window.__D("text/zohar-chadash/c003",{"p":[[9514012457,"<p>דְּאִית מַרְגְּלָאן וְאַבְנִין יַקִּירִין, דְּאִינוּן מִנִּשְׁמָתָא וְרוּחָא וְנַפְשָׁא, דְּכָרְסְיָיא יְקָרָא, וּמַלְאָכַיָא, וְד' סִטְרֵי עָלְמָא. נְהוֹרָא דְּאִלֵּין מַרְגְּלָאן אִית לֵיהּ שִׁיעוּרָא, וְאִית לֵיהּ רֵישָׁא וְסוֹפָא. אֲבָל לִנְהוֹרָא דְּנִשְׁמָתָא וְרוּחָא וְנַפְשָׁא דְּאִינוּן בְּאוֹרַח אֲצִילוּת, מִבִּינָה וְתִפְאֶרֶת וּמַלְכוּת, לֵית לֵיהּ שִׁיעוּרָא.</p>"],[9514012458,"<p>וְאִלֵּין אִינוּן בְּאוֹרַח אֲצִילוּת, אֲבָל אָחֳרָנִין, אִיתְּמָר בְּהוֹן סַפִּיר גִּיזְרָתָם, כְּמָה דְאוֹקְמוּהָ קַדְמָאֵי, כָּל הַנְּשָׁמוֹת גְּזוּרוֹת מִכִּסֵּא הַכָּבוֹד.</p>"],[9514012459,"<p>וְכָל אִלֵּין גְּוָונִין נְהִירִין בְּעַיְינִין דְּגוּפָא דְּגַּן עֵדֶן. וּבְהוֹן שַׁבָּחַת אוֹרַיְיתָא לִשְׁכִינְתָּא. וּמשֶׁה בְּגִין דְּאִתְלַבַּשׁ בְּהַהוּא גּוּפָא דְּגִנְתָּא דְעֵדֶן דִּלְתַתָּא, אִיתְּמָר בֵּיהּ (שמות ל״ד:ל׳) וַיִּירְאוּ מִגֶּשֶׁת אֵלָיו.</p>"],[9514012460,"<p>וּבְגַּן עֵדֶן דִּלְעֵילָא אִיתְּמָר בֵּיהּ, (שם לג) וּפָנַי לֹא יֵרָאוּ, דְּאַף עַל גַּב דִּבְכָל אֲתַר אִיהוּ קוּדְשָׁא בְּרִיךְ הוּא. אִית אֲתַר דְּאִתְגַּלְּיָיא בֵּיהּ, וַאֲתַר דְּלָא אִתְגַּלְיָיא בֵּיהּ כָּל כַּךְ. וְדָא אִיהוּ רָזָא דְּאַסְפַּקְלַרְיָא הַמְאִירָה, וְאַסְפַּקְלַרְיָא שֶׁאֵינָהּ מְאִירָה.</p>"],[9514012461,"<p>כְגַוְונָא דָא אִית בְּאוֹרַיְיתָא כַּמָּה לְבוּשִׁין, כַּמָּה אַנְפִּין, דְּאִתְקְרִיאוּ פָּנִים הַנִּרְאִים, וּפָנִים דְּאֵינָם נִרְאִים. וְקוּדְשָׁא בְּרִיךְ הוּא לָא אִתְגְּלֵי בְּאוֹרַיְיתָא, אֶלָא לְכָל חָדָא כְּפוּם עוֹבָדוֹי, וּכְפוּם נִשְׁמָתֵיהּ וְרוּחֵיהּ וְנַפְשֵׁיהּ מֵאֲתַר דְּאִתְגְּזָרוּ.</p>"],[9514012462,"<p>עַיְינִין אִינוּן כְּגַוְונָא דְּגַלְגַּל, דִּמְגַלְגַּל עִיגּוּלִין מִסִּטְרָא דְמַיִם. וְדָא אִיהוּ רָזָא דְּגַלְגַּלִּים. וְאָזְלִין בְּקַו הַמִּדָּה, בַּאֲרִיכוּ דִּילְּהוֹן, בַּעֲמִיקוּ דִּילְּהוֹן.</p>"],[9514012463,"<p>וְרָזָא דְמִלָּה (ישעיהו מ׳:י״ב) מִי מָדַד בְּשָׁעֳלוֹ מָיִם. וְאִינוּן ה' מְדוּדִים מָדַד בָּהּ, כְּגוֹן זֶה:: וְאִינוּן אָ אֵ אֹ ו אִ אֻ כֵיצַד, מִי מָדַד</p>"],[9514012464,"<p>בְּשָׁעֲלוֹ מַיִם ז אָ. וְשָׁמַיִם בַּזֶּרֶת תִּכֵּן אֵ. וְכָל בַּשָּׁלִישׁ עֲפַר הָאָרֶץ אֹ. וְשָׁקַל בַּפֶּלֶס הָרִים אִ. וּגְבָעוֹת בְּמֹאזְנַיִם אֻ.</p>"],[9514012465,"<p>וְאִינוּן ו', קַו דְנָפֵיק מִן הַמִּדָּה דְּאִיהִי י', וּמָדֵיד ה' מְדוֹדִין בָּהֶם, בְּחָמֵשׁ סְפִירָאן דִּכְלִילָן בְּה' תַּתָּאָה. וַדַּאי י' דִּילָהּ, אִיהִי מִדָּה דִּילָהּ.</p>"],[9514012466,"<p>וְאִינוּן ד' גְּוָונִין דְּעֵינָא, מָדַד בְּהוֹן לְד' סִטְרִין. וְקַו אִיהוּ ו', גַּלְגַּל דְּאִיהוּ י' עִם ו' אִתְעֲבֵיד גִּלְגּוּ\"ל. דְּסָלִיק לְחוּשְׁבַּן ע\"ב.</p>"],[9514012467,"<p>כַד גַּלְגַּל דְּעֵינָא אִתְהַפַּךְ בְּקַו דְּאִיהוּ ו', וּמִתְהַפֵּךְ עֵינָא בֵּיהּ לְחִוָּורָא, אִתְגַּלְּיָיא בֵּיהּ דְּאִיהוּ גִּלְגּוּל דִּילֵיהּ, מִזִּמְנָא קַדְמָאָה מִסִּטְרָא דְּחֶסֶד. וְאִם יִתְעַסֵּק בְּאוֹרַיְיתָא, חַכִּים יְהֵא, מִסִּטְרָא דְּיָמִינָא, בְּגִין דְּתַמָּן אִתְּמָר בָּהּ, הָרוֹצֶה לְהַחְכִּים יַדְרִים.</p>"],[9514012468,"<p>וְאִי לָא יִתְעַסַּק בְּאוֹרַיְיתָא, יְהֵא חַכִּים בְּמִלִּין, לְצַיֵּיר בִּידֵיהּ כַּמָּה צִיּוּרִין, דְּכַמָּה מְלָאכוֹת, אַף עַל גַּב דְּלָא אוֹלִיפוּ לֵיהּ בְּהַאי עָלְמָא. דְּמַאן דְּלָא עָבִיד מִלּוֹי מִלִּבּוֹי וּמִמַּחֲשַׁבְתֵּיהּ עַד דְּאוֹלִיפוּ לֵיהּ, הַאי לָאו אִיהוּ בְּגִלְגּוּלָא דָּא כְּלַל.</p>"],[9514012469,"<p>וְכַד גַּלְגַּל דְּעֵינָא אִתְהַפַּךְ לִשְׂמָאלָא בַּאֲדִימוּ, דְּשַׁלִּיט עַל גְּוָונִין אָחֳרָנִין, אִיהוּ מִזִּמְנָא תִּנְיָינָא גִּלְגּוּלָא דִילֵיהּ. וְהַאי יְהֵא עָתִיר בְּלָא טוֹרַח וּבְלָא מַזָּל וַעֲלֵיהּ אִיתְּמָר הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין. וְיִתְקָרֵב בַּר נָשׁ לְגַבֵּיהּ, דְּוַותְּרָן יְהֵא בְּמָמוֹנֵיהּ, בְּגִין דְלָא טָרַח בֵּיהּ, דְּהַהוּא דְּטָרַח בְּמָמוֹנֵיהּ לָא תִתְקְרֵיב לְגַבֵּיהּ, דְּקַמְצָן יְהֵא.</p>"],[9514012470,"<p>וְכַד גַּלְגַּל דְּעֵינָא אִתְהַפַּךְ לְיָרוֹקָא, דְּשַׁלִּיט עַל כָּל גְּוָונִין. דָּא אִיהוּ בְּגִלְגּוּלָא תְּלִיתָאָה. וִיהֵא חַכִּים בְּאוֹרַיְיתָא, וְעָתִיר בְּמָמוֹנָא דְּלָא טָרַח בֵּיהּ. דָּא אִיהוּ שְׁלִים מִכֹּלָא, מִסִּטְרָא דְיַעֲקֹב, דְּאִיתְּמָר בֵּיהּ (בראשית כ״ה:כ״ז) וְיַעֲקֹב אִישׁ תָּם. (איוב ל״ג:כ״ט) הֵן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלשׁ עִם גָּבֶר.</p>"],[9514012471,"<p>וּכְעָן צָרִיךְ לְפָרְשָׁא, מָאן אִיהוּ עַיִן דְּאִתְגַּלְגֵּל בְּגִלְגּוּלָא דִּתְלַת גְּוָונִין, אִלֵּין אָדָם קַדְמָאָה דְּסִטְרָא דַּכְיָיא, דְּאִית אָדָם אוֹחֲרָא מִסִּטְרָא דִּמְסָאֲבוּ. וְלָא עוֹד, אֶלָּא תְּלַת אָדָם אִינוּן: אָדָם דִּבְרִיאָה, אָדָם דִּיצִירָה, אָדָם דַּעֲשִׂיָּה, מִסִּטְרָא דְּדַכְיוּ. וְאִית אָחֳרָא מִסִּטְרָא דִּמְסָאֲבוּ, דְּאִיהוּ אָדָם בְּלִיַּעַל, אִישׁ אָוֶן, יֵצֶר הָרָע. אָדָם טוֹב, יֵצֶר הַטוֹב. דְּהָכֵי אוֹקְמוּהָ קַדְמָאִין, (קהלת ז׳:י״ד) גַּם אֶת זֶה לְעֻמַּת זֶה עָשָׂה הָאֱלֹהִים.</p>"],[9514012472,"<p>וּכְעָן צָרִיךְ לְפָרֵשׁ אָדָם דְּסִטְרָא דַּכְיָא. תָּא חֲזֵי, כַּד אִתְלַבַּשׁ אָדָם דְּדַכְיוּ, בְּאַבְרָהָם, אִתְלַבֵּן בֵּיהּ. וּבְיִצְחָק אִצְטָרֵיף. הֲדָא הוּא דִכְתִיב, (זכריה יג) וּצְרַפְתִּים כִּצְרֹף אֶת הַכֶּסֶף וּבְחַנְתִּים כִּבְחֹן אֶת הַזָּהָב. בְּיַעֲקֹב, אַחֲזֵי דְיוֹקְנֵיהּ, וְעָבִיד תּוֹלָדִין.</p>"],[9514012473,"<p>וְהַאי אַמַּאי. אֶלָּא לְיֵצֶר הַטוֹב וּלְיֵצֶר הָרָע, דְּאִינוּן אָדָם טוֹב אָדָם רָע, מַנֵּי קוּדְשָׁא בְּרִיךְ הוּא תְּלַת פִּקּוּדִין. עֲבוֹדָה זָרָה. גִּלּוּי עֲרָיוֹת. וּשְׁפִיכוּת דָּמִים. עֲבוֹדָה זָרָה, הֲדָא הוּא דִכְתִיב, (בראשית ב) וַיְצַו ה' אֱלֹהִים עַל הָאָדָם לֵאמֹר. וְאָמְרוּ מָארֵי מַתְנִיתִין, לֵית צַו אֶלָּא עֲבוֹדָה זָרָה. עַל הָאָדָם, זֶה שְׁפִיכוּת דָּמִים. לֵאמֹר, זֶה גִּלּוּי עֲרָיוֹת.</p>"],[9514012474,"<p>וּבְצִוּוּי דָּא הֲווֹ כַּחֲדָא יֵצֶר הַטוֹב וְיֵצֶר הָרָע. לְבָתַר דַּעֲבַר יֵצֶר הָרָע עַל צִוּוּי דְקוּדְשָׁא בְּרִיךְ הוּא, גָּזַר עֲלֵיהּ מִיתָה. אֲמַר, מָה אַעֲבֵד, אִם אֲנָא אֵימוּת אִיהוּ נָטֵיל עֶבֶד אָחֳרָא. דְּיֵצֶר הָרָע אִיהוּ עֶבֶד, וּבַת זוּגֵיהּ שִׁפְחָה, וְאַתְרֵיהּ יָרֵית לֵיהּ הַהוּא עֶבֶד.</p>"],[9514012475,"<p>מָה עֲבַד, אָזַל אִיהוּ וְאִתְּתֵיהּ, לְפַתָּאָה לְאָדָם וּלְאִתְּתֵיהּ דְּסִטְרָא טָבָא. בַּת זוּגֵיהּ דְּיֵצֶר הָרָע לִילִית, פַּתֵּי לְאָדָם דְּאִיהוּ יֵצֶר הַטוֹב, וּבְגִינָהּ אִיתְּמָר (שם ג) הָאִשָּׁה אֲשֶׁר נָתַתָּ עִמָּדִי הִיא נָתְנָה לִי מִן הָעֵץ. וְיֵצֶר הָרָע פַּתֵּי לְחַוָּה, וְגָרְמוּ לוֹן מָוֶת.</p>"],[9514012476,"<p>בְּגִין דָּא, קוּדְשָׁא בְּרִיךְ הוּא אַפְשֵׁיט לְאָדָם דְּאִיהוּ יֵצֶר הַטוֹב מִגּוּפֵיהּ בְּגַן עֵדֶן וּמִמַּלְבּוּשׁוֹי, לֵיהּ וּלְאִתְּתֵיהּ, הֲדָא הוּא דִכְתִיב, (שם) וַיֵּדְעוּ כִּי עֵרוּמִים הֵם. וְגֵירַשׁ לוֹן מִגַּן עֵדֶן, הֲדָא הוּא דִכְתִיב, (שם) וַיְגָרֶשׁ אֶת הָאָדָם. אֶת, בַּת זוּגֵיהּ עִמֵּיהּ.</p>"],[9514012477,"<p>וְנָחֵית לוֹן לְשֶׁבַע אַרְעִין, דְּאִינוּן: גֵּיא. נְשִׁיָה. צִיָּה. אַרְקָא. אֶרֶץ. אֲדָמָה. תֵּבֵל. עֲבַד תְּיוּבְתָּא, הֲוָה מְצַפְצֵף וְעוֹלֶה. וְעִם כָּל דָּא הֲוָה עָרוֹם בְּלֹא לְבוּשׁ הוּא וְאִתְּתֵיהּ.</p>"],[9514012478,"<p>מָה עֲבַד קוּדְשָׁא בְּרִיךְ הוּא. אַיְיתֵי לֵיהּ בְּגִלְגּוּלָא בְּאַבְרָהָם, וּלְאִנְתְּתֵיהּ בְּשָׂרָה. וְקוּדְשָׁא בְּרִיךְ הוּא הֲוָה מְלַבֵּן לֵיהּ בְּכוּרָא דְּכַסְפָּא, דְּאִיהוּ מְעוֹרָב בַּאֲבָרָא, דְּאִיהוּ עוֹפֶרֶת, מִיָּד דְּאַרְמֵי לֵיהּ בְּנוּרָא, אִתְלַבְּנָא כַּסְפָּא, וַאֲפֵיקַת זוּהֲמָא, דְּאִיהוּ עוֹפֶרֶת לְבַר, וּכְגַוְונָא דָא אִתְלַבֵּן אָדָם בְּאַבְרָהָם. וְאַפֵּיק מִנֵּיהּ זוּהֲמָא לְבַר, וְדָא יִשְׁמָעֵאל, דְּאִיהוּ זוּהֲמָא דְּהִטִיל חִיוָיָא בְּחַוָּה.</p>"],[9514012479,"<p>לְבָתַר אִתְגַּלְגַּל בְּיִצְחָק, בַּת זוּגֵיהּ דְּאָדָם, וְאִסְתַּמַּק בְּנוּרָא, וְאַפֵּיק זוּהֲמָא לְבַר, וְדָא עֵשָׂו. וְסוּמְקָא דִילֵיהּ כְּדָמָא דִשְׁחִיטָה. וּבְגִין דְּאִתְגַּלְגַּל נוּקְבָא בְּיִצְחָק, אִתְקְרֵי שְׂמֹאל נוּקְבָא.</p>"],[9514012480,"<p>לְבָתַר עָאלוּ תַּרְוַויְיהוּ בְּיַעֲקֹב וּבַת זוּגֵיהּ, וַאֲפִיקוּ מִנֵּיהּ זַרְעָא. וְגווָֹנָא דִילֵיהּ הוּא יְרוֹקָא דִילֵיהּ דְּסַחֲרָא. וְדָא אִיהוּ (איוב לג) הֵן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלשׁ עִם גָּבֶר.</p>"],[9514012481,"<p>עַיְינִין אוּכְמִין חֲשׁוֹכִין, תַּמָּן לִילִית, דְּאִיהִי חֲשׁוֹכָא אֲפֵילָה, פְּתַיָא אוּכְמָא. וְעַיְינִין אוּכְמִין עֲקִימִין, וַדַּאי תַּמָּן שַׁבְּתָאי, דַּעֲלֵיהּ אִתְּמָר (משלי ג) מְאֵרַת ה' בְּבֵית רָשָׁע. דְּהַהוּא גַּוָּון חָשׁוּךְ, שַׁלִּיט עַל גּווָֹנֵי אָחֳרָנִין.</p>"],[9514012482,"<p>וּלְמַאן דְּאִסְתַּכַּל בֵּיהּ לִילִית אוֹ שַׁבְּתָאי בְּאִילֵין עַיְינִין, מְאֵרָה וַעֲנִיּוּתָא וְכַפְנָא וּמוֹתָנָא יֵיתֵי. אִסְתַּמַּר מִנֵּיהּ, (שם ה) דְּרַגְלֶיהָ יֹרְדוֹת מָוֶת שְׁאוֹל צְעָדֶיהָ יִתְמֹכוּ. וְכָל מַשָּׂא וּמַתָּן דְּעָבִיד בַּר נָשׁ קָדָם מָארֵי דְּעַיְינִין אִלֵּין, אִתְאֲבֵיד.</p>"],[9514012483,"<p>וְצָרִיךָ בַּר נָשׁ דְּלָא יִשְׁתְּכַח בְּשָׂבְעָה קֳדָמֵיהּ בְּיוֹמִין דְּחוֹל, אֶלָּא בְּשַׁבָּת, דְּלֵית לֵיהּ שָׁלְטָנוּתָא עֲלֵיהּ וְאִם אִשְׁתְּכַח בְּיוֹמִין דְּחוֹל בְּשָׂבְעָה קֳדָמֵיהּ, וְאִסְתַּכַּל בֵּיהּ בְּעֵינָא בִּישָׁא, לָא אִשְׁתְּזֵיב מִנֵּיהּ מִמִּיתָה אוֹ מֵעוֹנִי. וְחוֹטְמָא וּפוּמָא וְאַנְפּוֹי דְּהַאי בַּר נָשׁ לָאו אִינוּן עַל קַו הַיּוֹשֶׁר.</p>"],[9514012484,"<p>עַיְינִין אוּכְמִין שַׁפִּירָן, עַל קַו הַיּוֹשֶׁר, אִיהוּ מִסִּטְרָא דְּשַׁבָּת, דְּאִיהִי בַּת עַיִן שַׁפִּירָא. עֲלָה אִיתְּמָר, (שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה. הַאי אִיהוּ בִּדְיוֹקְנָא דְּשַׁבָּת, דְּאִיהוּ שָׁקוּל לְאוֹרַיְיתָא כּוּלָהּ.</p>"],[9514012485,"<p>וּבְשַׁבָּת צָרִיךְ לְאַחֲזָאָה שׂוֹבְעָה, בְּהִפּוּכָא דְּשִׁפְחָה לִילִית. וְצָרִיךְ בַּאֲתַר דַּעֲצִיבוּ דְּשַׁבְּתָאי, לְאַחֲזָאָה חֶדְוָה, בַּאֲתַר דַּחֲשׁוֹכָא. שְׁרַגָּא. בַּאֲתַר דְּעִינּוּי, עֹנֶג. לְמֶעְבַּד תַּמָּן שִׁינּוּי בְּכֹלָּא.</p>"],[9514012486,"<p>דְּלִילִית מָרָה אוּכְמָא, צִמָּאוֹן דְּלֵית בֵּיהּ מַיִם, דְּאִיהוּ (בראשית ל״ז:כ״ד) הַבּוֹר רֵק אֵין בּוֹ מַיִם, אֲבָל נְחָשִׁים וְעַקְרַבִּים יֵשׁ בּוֹ. וּנְחָשִׁין וְעַקְרַבִּין דִּילָהּ אִינוּן עֵרַב רַב. יוֹסֵף דְּאִיהוּ בְּגוֹבָא, דָּא יִשְׂרָאֵל דְּאִינוּן בְּגָלוּתָא דִּילָהּ, בְּהַהוּא בּוֹר.</p>"],[9514012487,"<p>וּמַאן דְּאוֹקִיר שַׁבָּת, יִמָּלֵט מִמֶּנָּהּ. (קהלת ז׳:כ״ו) וְחוֹטֵא יִלָּכֶד בָּהּ. חוֹטֵא דִּמְחַלֵּל שַׁבָּת, יִלָּכֶד בָּהּ, דְּאִיהִי חִילּוּל שַׁבָּת וַדַּאי, חֲלָלָה זוֹנָה. דְּמַאן דְּנָטִיר אוֹת שַׁבָּת אוֹ אוֹת בְּרִית, מִלְּחַלֵּל לֵיהּ, בֵּיהּ אִתְקְרֵי צַדִּיק, וְאִשְׁתְּזֵיב מִינָהּ. וְלֹא עוֹד אֶלָּא דְּסָלֵיק לְמַלְכוּת, דְּאִיהִי שַׁבָּת וַדַּאי.</p>"],[9514012488,"<p>וְיוֹסֵף בְּגִין דְּנָטִיר בְּרִית, אִשְׁתְּזֵיב מִן גּוּבָא, וּמִן נְחָשִׁים וְעַקְרַבִּים דִּילֵיהּ. וְלֹא עוֹד אֶלָּא דְּזָכָה לְמַלְכוּת. וְיִשְׂרָאֵל דְּנָטְרִין שַׁבָּת וְאוֹת בְּרִית מִילָה, אִיתְּמָר בְּהוֹן כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים, וְאִלְמָלֵא נָטְרִין יִשְׂרָאֵל שַׁבָּת אֶחָד כְּהִלְכָתָהּ מִיָּד נִגְאָלִין.</p>"],[9514012489,"<p>וְכָל בַּר נָשׁ דְּאִיהוּ עַיְינִין אוּכְמִין עַל קַו הַיּוֹשֶׁר, דְּאִיהִי קַו הַמִּדָּה, עֹנֶג אִיהוּ וְחֶדְוָה וְשָׂבְעָא, וְוַתְּרָן, וְעַיְינָא טָבָא. וּבָעֵי לְאִתְפָּאֲרָא בִּלְבוּשִׁין שַׁפִּירִין. בְּגִין דְּאִיהוּ בֶּן דְּשַׁבָּת, בֶּן מַטְרוֹנִיתָא וַדַּאי. וּבְהִיפּוּכָא בֶּן לִילִית. עַד הָכָא רָזָא דְּעַיְינִין. וַדַּאי אִיהוּ רָזָא דְּאַנְשֵׁי חַיִל.</p>"],[9514012490,"<p>יִרְאֵי אֱלֹהִים בִּשְׁמִיעָה, דְּתַלְיָיא בְּאוּדְנִין, דְּתַמָּן יִרְאָה. הֲדָא הוּא דִכְתִיב, (חבקוק ג׳:ב׳) ה' שָׁמַעְתִּי שִׁמְעֲךָ יָרֵאתִי.</p>"],[9514012491,"<p>פּוּתְלַת צְלוֹתִין אִינוּן, חַד תַּלְיָיא בִּרְאִיָה. וְתִנְיָינָא בְּרֵיחָא. וּתְלִיתָאָה בִּשְׁמִיעָה. פֶּה, אִיהוּ שַׁבָּת, כְּלוּלָה מִכָּלְהוֹ. אִיהִי תְּפִלָּה לֶעָנִי, דְּאִיהוּ צַדִּיק, וְאִיהוּ יוֹם הַשַּׁבָּת. וּצְלוֹתָא דְפֶסַח, אִיהִי כּוּרְסְיָיא דְרַחֲמֵי. וּצְלוֹתָא דְרֹאשׁ הַשָּׁנָה, כּוּרְסְיָיא דְּדִין. וְתַמָּן קוּדְשָׁא בְּרִיךְ הוּא אִיהוּ דַיָין, וְכָל צְבָא הַשָּׁמַיִם קָיְימִין עֲלֵיהּ, מִיָּמִינָא וּמִשְׂמָאלָא. כְּגַוְונָא דְּשַׂעֲרָא, דְּתַלְיָיא בָּתַר אוּדְנִין, מִיָּמִינָא וּמִשְׂמָאלָא.</p>"],[9514012492,"<p>וְהָא אוֹקִימְנָא לְעֵיל, דְּצָרִיךְ לְבַעֲרָא לוֹן, אִם אִינוּן תְּחוֹת אוּדְנִין, לְאִתְגְּלָאָה אוּדְנִין, דְּאִינוּן תַּרְעִין דִּצְלוֹתָא. דְּכַמָּה מָארֵי דְדִינִין סָתְמִין תַּרְעִין, בְּחוֹבִין דְּיִשְׂרָאֵל. וּצְלוֹתָא לְבַר, דְּלָא מַנִּיחִין לָהּ לְאַעֲלָאָה בְּהֵיכָלָא דִילֵיהּ, דְּאִיהוּ אדני. וְאִיהִי קָרְאָה לְתַרְעִין דְּהֵיכָלָא דְּיִפְתְּחִין לָהּ. וּבְנָהָא לְתַתָּא קָרָאן בְּיִחוּדָא שְׁמַע יִשְׂרָאֵל, לְקָלָא דִּצְלוֹתָא דִילָךְ, דְּאִיהִי לְתַרְעָא דִילָךְ.</p>"],[9514012493,"<p>וְאִם מְבַעֲרִין שַׂעֲרִין דִּתְחוֹת אוּדְנִין, דְּאִינוּן מָארֵי דְדִינִין, מִיָּד קוּדְשָׁא בְּרִיךְ הוּא דְּאִיהוּ יִשְׂרָאֵל, דַּיָּין אֱמֶת, אַפְתַּח הֵיכָלָא דְּתֵיעוֹל צְלוֹתֵיהּ. וְדָא אִיהוּ אֲדֹנָי שְׂפָתַי תִּפְתָּח, פֶּתַח הֵיכָ\"ל דְּאִיהוּ אדנ\"י בְּחוּשְׁבַּן, וְיֵיעוֹל צְלוֹתָא.</p>"],[9514012494,"<p>וּצְלוֹתָא דְּיִשְׂרָאֵל לְעֵילָא, אִיהִי מַלְכוּת, וְאִיהוּ תִּפְאֶרֶת. וּצְרִיכִין יִשְׂרָאֵל דְּלָא יְסַלְקִין לְהוֹ לְעֵילָא, עַד דְּיִתְבַּעֲרוּן דִּינִין מִתַּרְעָא, וִיהוֹן צָוְוחִין בָּהּ לְגַבֵּיהּ, בַּעֲשָׂרָה מַלְכֻיּוֹת, וּבַעֲשָׂרָה זִכְרוֹנוֹת, וּבַעֲשָׂרָה שׁוֹפָרוֹת.</p>"],[9514012495,"<p>דִּצְלוֹתָא דְמִנְחָה, אִיהִי דִינָא דְרֹאשׁ הַשָּׁנָה. וּבְגִין דָּא תְּקִינוּ עֲשָׂרָה שׁוֹפָרוֹת, דְּאִינוּן: קשר\"ק, קש\"ק, קר\"ק. לְסַלְקָא לָהּ בַּעֲשָׂרָה, דְּלֵית שְׁכִינְתָּא שַׁרְיָיא בְּפָחוֹת מֵעֲשָׂרָה. וּבְגִינַיְיהוּ אִיתְּמָר (בראשית יח) לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה.</p>"],[9514012496,"<p>בִּשְׁבָרִים, (שמות כג) שַׁבֵּר תְּשַׁבֵּר מַצֵּבוֹתֵיהֶם, דְּקָיְימִין קֳדָם תַּרְעִין, דְּלָא מַנִּיחִין לַאֲעָלָא צְלוֹתָא. בִּתְרוּעָה, תָּפְסִין לוֹן בְּשַׁלְשְׁלָאִין. בִּתְקִיעָה, (במדבר כה) וְהוֹקַע אוֹתָם לַה' נֶגֶד הַשָּׁמֶשׁ. בְּגִין דְּלָא יָהֲבוּ יְקָרָא לְמַטְרוֹנִיתָא, לַאֲעָלָא בְּתַרְעִין דִּילָהּ.</p>"],[9514012497,"<p>וּבְשַׁעֲתָא דְּדִינִין פְּנוּיִן מִתַּרְעִין דְּהֵיכָלָא דְמַלְכָּא, סָלְקָא צְלוֹתָא בְּכַמָּה שִׁירִין וְתוּשְׁבָּחוֹת וְהוֹדָאוֹת דִּצְלוֹתָא. וְחֵיוָן כָּלְהוֹ פָּתְחִין גַּדְפַיְיהוּ, לְקַבְּלָא לָהּ בְּחֶדְוָה, הֲדָא הוּא דִכְתִיב, (יחזקאל א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת. כָּלְהוֹ פְּרוּדוֹת לְעֵילָא לְקַבְּלָא לָהּ.</p>"],[9514012498,"<p>וְאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם, בְּגִין דְּיִשְׁמַע מַלְכָּא, דְּמַטְרוֹנִיתָא קָא אַתְיָא, וְיִפְתַּח הֵיכָלָא לְגַבָּה. הֲדָא הוּא דִכְתִיב, (תהלים נא) אֲדֹנָי שְׂפָתַי תִּפְתָּח. מִיָּד אַפְתַּח מַלְכָּא הֵיכָלָא, וְקַבֵּיל לָהּ בְּחֶדְוָה, וְיֵיעוֹל עִמָּהּ בְּהֵיכָלֵיהּ. אֵימָתַי בִּצְלוֹתָא דַעֲמִידָה. מִיָּד אִיתְּמָר בְּחֵיוָן, בְּעָמְדָם תְּרַפֶּינָה כַּנְפֵיהֶם.</p>"],[9514012499,"<p>בְּהַהוּא זִמְנָא, אִיהוּ יהו\"ה בְּהֵיכָלֵיהּ, כְּגַוְונָא דָא יאהדונה\"י. בְּהַהוּא זִמְנָא, מַאן דְּבָעֵי לְמִישְׁאַל שְׁאֵלְתֵּיהּ, יִשְׁאַל. הֲדָא הוּא דִכְתִיב, (דברים לב) שְׁאַל אָבִיךָ וְיַגֵּדְךָ. (תהלים ב) שְׁאַל מִמֶּנִּי וְאֶתְּנָה גוֹיִם נַחֲלָתֶךָ. וְהַבֵּן שׁוֹאֵל מֵאָבִיו, בְּאֶמְצָעִיּוֹת דִּצְלוֹתָא. בְּהַהוּא זִימְנָא דְּאִיהוּ יהו\"ה בְּהֵיכָלֵיהּ, אָז תִּקְרָא וַה' יַעֲנֶה.</p>"],[9514012500,"<p>וְאִית נִימִין דְּשַׂעֲרָא, דְּהַהוּא דְּאִיתְּמָר בֵּיהּ (דניאל ז) וְעַתִּיק יוֹמִין יְתִיב לְבוּשֵׁיהּ כִּתְלַג חִיוָּר וּשְׂעַר רֵישֵׁיהּ כַּעֲמַר נְקֵי. וְכָלְהוֹ רַחֲמֵי. לֵית נִימָא דְּלָא אִית לֵיהּ מַבּוּעָא, וְדָא י'. נִימָא אֲרִיכָא דָא ו'. קְמִיטָא ה' זְעֵירָא. אֲרִיכָא וּקְמִיטָא לְתַתָּא, דָּא ה' עִילָּאָה, דְּאִית בָּהּ דִּינָא וְרַחֲמֵי. דִּקְמִיטָא וְלָא אֲרִיכָא, דָּא ה' תַּתָּאָה, דְּאִיהוּ כֹּלָּא דִּינָא.</p>"],[9514012501,"<p>וְכָל נִימָא וְנִימָא, אִיהוּ עָלְמָא שְׁלֵימָא, וַעֲלַיְיהוּ אִיתְּמָר (שיר השירים ו׳:ח׳) וַעֲלָמוֹת אֵין מִסְפָּר. בְּגִין דָּא אָמְרוּ מָארֵי מַתְנִיתִין כָּל צַדִּיק וְצַדִיק יֵשׁ לוֹ עוֹלָם בִּפְנֵי עַצְמוֹ. וְאִיהוּ נִימָא חָדָא דְקוּדְשָׁא בְּרִיךְ הוּא, עָלְמָא שְׁלֵימָא. וּבְגִינָהּ אִתְּמָר, דְּקוּדְשָׁא בְּרִיךְ הוּא מְדַקְדֵּק עִם הַצַּדִּיקִים אֲפִילּוּ כְּחוּט הַשַּׂעֲרָה.</p>"],[9514012502,"<p>וּצְלוֹתָא דְשַׁחֲרִית, כַּד סָלְקָא כָּל אִלֵּין מָארֵי דְדִינָא, כָּלְהוֹ רַחֲמֵי, וְלָא מְעַכְּבִין לָהּ לְאַעֳלָא. שַׂעֲרָא יְרוֹקָּא, לֵית תַּמָּן דִּינָא כְּלָל. נִימִין יְרוֹקִין שַׁפִּירִין, כְּלִילִין מֵחִוָּור וְסוּמָק, אִינוּן כָּלְהוֹ רַחֲמֵי. וְכַד סָלְקָא צְלוֹתָא בְּהוֹן, כָּלְהוֹ חַיָּילִין דְּנִימִין מְקַבְּלִין לָהּ בְּחֶדְוָה וּרְחִימוּ.</p>"],[9514012503,"<p>שַׂעֲרָא אוּכְמָא שַׁפִּירָא, כָּל נִימִין דִּילֵיהּ, אִתְקְרִיאוּ עוֹלָמוֹת דִּילֵיהּ. הֲדָא הוּא דִכְתִיב, וַעֲלָמוֹת אֵין מִסְפָּר, וְאִינוּן חַיָּילִין דְּשַׁבָּת. וּצְלוֹתָא דְשַׁבָּת, אִיהִי שְׁקִילָא לְאוֹרַיְיתָא. וְכַמָּה תִּלֵּי תִּלִּים דְּתַלְיָין מִינָהּ אִתְקְרִיאוּ קְוֻצּוֹתָיו תַּלְתַּלִּים.</p>"],[9514012504,"<p>שַׂעֲרָא חִוָּרָא מִסִּטְרָא דְּחֶסֶד. סוּמְקָא, מִסִּטְרָא דִּגְבוּרָה. שַׂעֲרָא יְרוֹקָא, מִסִּטְרָא דְּתִפְאֶרֶת. אוּכְמָא, מִסִּטְרָא דְּמַלְכוּת. דְּאִיתְּמָר בֵּהּ (שיר השירים א׳:ה׳) שְׁחוֹרָה אֲנִי וְנָאוָה. הֲרֵי אַרְבַּע תִּקּוּנִין דְּשַׂעֲרָא, דְּשַׁרְיָיא עֲלַיְיהוּ יהו\"ה.</p>"],[9514012505,"<p>י\"ג תִּיקּוּנִין אִינוּן דְּתַלְיָין מִשַּׂעֲרָא, ג' לְכָל סְטַר, לְד' סִטְרִין, וְאִינוּן וא\"ו. עֲלַיְיהוּ אִיתְּמָר (שם ה) קְוֻצּוֹתָיו תַּלְתַּלִּים. לְעֵילָא בְּרֵישָׁא, בְּפַלְגוּ דְרֵישָׁא, מִתְפַּלְּגִין אוֹרְחִין בְּשַׂעֲרָא, לִתְלָתִין וּתְרֵין שְׁבִילִין, בְּחוּשְׁבַּן יו\"ד ה\"א ה\"א. וְכָלְהוֹ שְׁבִילִין אִינוּן בְּיַמָּא, דְּאִיהוּ מוֹחָא. וְאִלֵּין תִּיקּוּנִין אִינוּן בְּרֵישָׁא דְּהַהוּא גוּפָא דְּגַּן עֵדֶן, וְכָלְהוֹ תִּיקוּנִין אִית בֵּיהּ, עַד הָכָא יִרְאֵי אֱלֹהִים.</p>"],[9514012506,"<p>אַנְשֵׁי אֱמֶת, בִּדְיוֹקְנָא דְּאַנְפִּין, בְּחוֹטְמָא, בְּשִׁרְטוּטִין דְּמִצְחָא, בְּדִיקְנָא דְּאַנְפִּין, בִּקְרִיצִין דְּעַל עַיְינִין.</p>"],[9514012507,"<p>תָּא חֲזֵי, תְּלַת שׁוּתָּפִין אִינוּן, אָדָם דִּבְרִיאָה, אָדָם דִּיצִירָה, אָדָם דַעֲשִׂיָּה. אָדָם דִּבְרִיאָה, אִיהִי נִשְׁמָתָא, בָּהּ חָשִׁיב בַּר נָשׁ, וְדָא עוֹלָם הַמַּחְשָׁבָה וַדַּאי אִתְקְרִיאַת. רוּחַ, אָדָם דִּיצִירָה, עוֹלָם הַדִּיבּוּר, כַּד אִתְלַבַּשׁ בֵּיהּ מַחְשָׁבָה, בָּהּ חָשִׁיב, וְצַיָּיר צִיּוּרִין דְּשִׁרְטוּטִין וּדְיוֹקְנִין. וְאַף עַל גַּב דְּחָשֵׁיב לוֹן, לֵית רְשׁוּ לַאֲפָקָא לוֹן מֵהַהוּא חֵילָא דְּאִיתְּמָר בֵּיהּ מֵהַכֹּחַ אֶל הַפּוֹעַל, עַד דְּאִתְלַבְּשׁוּ נִשְׁמָתָא וְרוּחָא בְּנַפְשָׁא, וּבָהּ אַפִּיקוּ כֹּלָּא לַפּוֹעַל. בְּגִין דְּנַפְשָׁא אִיהוּ עוֹלָם הַמַּעֲשֶׂה. וּבָהּ רוּחָא בָּטַשׁ בְּמִצְחָא וְעָבִיד שִׁרְטוּטִין. בָּטַשׁ בְּעַיְינִין, וְעָבִיד קְרִיצִין. בָּטַשׁ בְּעַיְינִין, וְעָבִיד גּווָֹנִין. בָּטַשׁ בְּאַנְפּוֹי, וְעָבִיד גּווָֹנִין וְתִיקּוּנִין. נָחֵית לְתַתָּא, בָּטַשׁ בִּידִין, וְעָבִיד שִׁרְטוּטִין. בָּטַשׁ בָּאֵבָרִים כָּלְהוֹ דְּגוּפָא, וְעָבִיד דְּיוֹקְנִין. וְלֵית חֵילָא לְמַחְשָׁבָה וְלָאו לְרוּחָא לַאֲפָקָא חֵילָא לְעוֹבָדָא, בְּלָא נַפְשָׁא.</p>"],[9514012508,"<p>וְעִם כָּל דָּא דִּתְלַת שׁוּתָּפִין אִלֵּין בְּבַּר נָשׁ, לֵית מַחְשָׁבָה דְּאִית לָהּ חֵילָא לַחֲשׁוֹב בְּלָא שְׁכִינְתָּא עִילָּאָה, דְּתַמָּן חָכְמָה. וְלָא רוּחָא דְּאִית לֵיהּ רְשׁוּ לְצַיָּירָא בְּלָא תִפְאֶרֶת, דְּאִיהוּ כָּלֵיל שִׁית סְפִירָן. וְנַפְשָׁא לֵית לָהּ חֵילָא לְמֵיעֱבַד עוֹבָדָא בְּלָא מַלְכוּת, דְּאִיהוּ מַעֲשֵׂה בְרֵאשִׁית, עֲלָה אִיתְּמָר (בראשית א) תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה.</p>"],[9514012509,"<p>אֲבָל בְּרִיאָה בֵּאלֹהִים דְּאִיהִי בִינָה, הֲדָא הוּא דִכְתִיב (בראשית א׳:כ״א) בְּרֵאשִׁית בָּרָא אֱלֹהִים. וַיִּבְרָא אֱלֹהִים אֶת שְׁנֵי הַמְאוֹרוֹת הַגְּדוֹלִים. (בראשית א׳:כ״ז) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ. הוי\"ה אִיהוּ בִּיצִירָה, הֲדָא הוּא דִכְתִיב, (שם) יְהִי אוֹר וַיְהִי אוֹר. יְהִי רָקִיעַ. בְּכָל אֲתַר וַיְהִי כֵן, אִיהוּ תִּפְאֶרֶת כָּלֵיל שִׁית סִטְרִין, הוּא טוֹב דְּכָל יוֹמֵי בְרֵאשִׁית, וְהוּא צַיָּיר יֵצֶר הַטוֹב, דְּאִיתְּמָר בֵּיהּ (שם) וַיִּיצֶר ה' אֱלֹהִים. בִּיצִירָה תִּשְׁכַּח יהו\"ה.</p>"],[9514012510,"<p>מַאן דְּבָעֵי לְמִיפְעַל עֲשִׂיָּה, מֵאִלֵּין מַלְאָכִין דִּמְמַנָּן עַל צְלוֹתִין, לֵית לֵיהּ רְשׁוּ לְמֵיעֱבַד עוֹבָדָא בִּצְלוֹתָא, אֶלָּא בְּעוֹבָדִין טָבִין דְּתַלְיָין בְּמַעֲשֶׂה, דִּבְהוֹן נָחֵית שְׁכִינְתָּא עֲלֵיהּ, דְּאִיהִי עוֹלָם הַמַּעֲשֶׂה, דְּאִיהוּ מַעֲשֵׂה בְרֵאשִׁית, דְּאִיהוּ פוֹעַל.</p>"],[9514012511,"<p>וּבִינָה כֹּחַ, כ\"ח אַתְוָון דִּקְרָא קַדְמָאָה דִבְרֵאשִׁית, כ\"ח מָ\"ה, דְּאִיהוּ חָכְמָה, מַחְשָׁבָה. יהו\"ה אֱלֹהֵינוּ יהו\"ה כוז\"ו במוכס\"ז כוז\"ו. פְּעוּלָה דְהַאי כֹּחַ לָאו אִיהִי, אֶלָּא בְּמַעֲשֶׂה, דְּאִיהִי פוֹעַל אדנ\"י וְדָא אִיהוּ מֵהַכֹּחַ אֶל הַפוֹעַל. וְהַפוֹעַל לֵית לֵיהּ חֵילָא לְמִיפְעַל בְּלָא דִיבּוּר, דְּאִיהוּ יהו\"ה תִּפְאֶרֶת, דְּכָלֵיל כֹּלָּא.</p>"],[9514012512,"<p>הָכָא לֵית קִיצוּץ וּפֵירוּד בְּמַחְשָׁבָה וְדִבּוּר וּמַעֲשֶׂה. תִּפְאֶרֶת כָּלֵיל כֹּלָּא, וְהָכֵי אִתְכְּלֵיל כֹּלָּא בְּבִינָה. וְהָכֵי אִתְכְּלֵיל כֹּלָּא בְּמַלְכוּת.</p>"],[9514012513,"<p>מַחְשָׁבָה מִבִּינָה וּלְעֵילָא עַד אֵין סוֹף, וּמִינָהּ לְתַתָּאָה עַד אֵין תַּכְלִית. דִּבּוּר בְּתִפְאֶרֶת, מֵעֵילָא לְתַתָּא וּמִתַּתָּא לְעֵילָא. עֲשִׂיָּיה בְּמַלְכוּת, מִתַּתָּא לְעֵילָא וּמֵעֵילָא לְתַתָּא.</p>"],[9514012514,"<p>מַחְשָׁבָה לְמֶהֱוֵי בָּהּ בַּר נָשׁ חָשִׁיב בְּבוֹרֵא עָלְמִין, לְיַחֲדָא שְׁמֵיהּ עַד אֵין סוֹף וְעַד אֵין תַּכְלִית, וְאִיהוּ בָּרָא בְּבִינָה. הֲדָא הוּא דִכְתִיב, (ישעיהו מ׳:כ״ו) וּרְאוּ מִי בָרָא אֵלֶּה. מִי וַדַּאי.</p>"],[9514012515,"<p>דִּבּוּר לְאִתְעַסְּקָא בֵּיהּ בְּאוֹרַיְיתָא, וּלְמִנְדַע מִנֵּיהּ יוֹצֵר הַכֹּל, דַּעֲלֵיהּ אִיתְּמָר יוֹצֵר אוֹר. וְלֵית אוֹר אֶלָּא תּוֹרָה. הֲדָא הוּא דִכְתִיב, (משלי ו׳:כ״ג) כִּי נֵר מִצְוָה וְתוֹרָה אוֹר. וְדָא אִיהוּ יוֹצֵר, דְּצַיָּיר בֵּיהּ בְּבַּר נָשׁ אַנְפִּין וְעַיְינִין וְאוּדְנִין וְחוֹטְמָא וּפוּמָא, לְאִתְעַסְּקָא בְּאוֹרַיְיתָא, וּלְמִנְדַע לֵיהּ מִינָהּ.</p>"],[9514012516,"<p>כְגַוְּונָא דָא צַיָּיר פּוּמָא, לְמַלָּלָא בְּאוֹרַיְיתָא. צַיָּיר עַיְינִין, לְאִסְתַּכָּלָא בִּנְהוֹרָא דְּאוֹרַיְיתָא. צַיָּיר בֵּיהּ אוּדְנִין, לְמִשְׁמַע בְּהוֹן פִּתְגָּמֵי אוֹרַיְיתָא. אִלֵּין אִינוּן שִׁית סִטְרִין דְּכָלֵיל תִּפְאֶרֶת, תְּרֵין עַיְינִין, תְּרֵין אוּדְנִין, פּוּמָא וְלָשׁוֹן.</p>"],[9514012517,"<p>צַיָּיר חוֹטְמָא, וּבָהּ (בראשית א) וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים, לְמֶהֱוֵי חָשִׁיב בָּהּ בְּיִיחוּדָא, כְּמָה דְאִיתְּמָר, (ישעיהו מ״ד:כ״ד) אָנֹכִי ה' עֹשֶׂה כֹּל, דָּא שְׁכִינְתָּא תַּתָּאָה. מִנֵּיהּ יְהֵיב בְּבַּר נָשׁ נֶפֶשׁ הַשִּׂכְלִית, לְמִנְדַע מִינָּהּ בְּכָל עוֹבָדִין דְּאוֹרַיְיתָא, דְּאִינוּן פִּיקּוּדִין דְּאוֹרַיְיתָא, לְהַהוּא דְּאִתְקְרֵי עוֹֹשֶׂה כֹּל.</p>"],[9514012518,"<p>וְאִינוּן תְּלַת קְטִירִין, דִּיהֵיב בְּבַּר נָשׁ. נְשָׁמָה הַשִּׂכְלִית, לְמִנְדַע בָּהּ לְעוֹשֶׂה כָּל עָלְמִין, דְּאִיהוּ אוֹמֵר וְעוֹשֶׂה, מְדַבֵּר וּמְקַיִּים, וְאִיהוּ בּוֹרֵא יוֹצֵר וְעוֹשֶׂה. כֹּלָּא חַד. אִיהוּ מִלְּגָיו, אִיהוּ אַפֵּיק כֹּלָּא מִכֹּחַ לַפּוֹעַל. וְאִיהוּ מְשַׁנֶּה עוֹבָדוֹי, וּבֵיהּ לֵית שִׁנּוּי.</p>"],[9514012519,"<p>וְאִיהוּ הוּא דִּמְסַדֵּר כָּל סְפִירָאן, וְאִית בִּסְפִירָן, מִנַּיְיהוּ, רַב וּבֵינוֹנִי וּזְעֵיר, כָּל חַד עַל סִדּוּרָא, וּבֵיהּ לֵית סֵדֶר. וְאִיהוּ בָּרָא כֹּלָּא בְּבִינָה, וְלֵית מַאן דְּבָרָא לֵיהּ. אִיהוּ צַיָּיר וְיָצַר כֹּלָּא בְּתִפְאֶרֶת, וְלֵיהּ, לֵית צִיּוּר וְצַיָּיר. אִיהוּ עָבִיד כֹּלָּא בְּמַלְכוּת, וְלֵית מַאן דַּעֲבֵיד לֵיהּ.</p>"],[9514012520,"<p>וּבְגִין דְּאִיהוּ בְּאִלֵּין עֶשֶׂר סְפִירָן מִלְּגַו, דִּבְהוֹן בְּרָא וְצַיָּיר וַעֲבַד כֹּלָּא, שַׁוֵּי תַּמָּן יִחוּדֵיהּ, לְאִשְׁתְּמוֹדְעָא לֵיהּ תַּמָּן. וְכָל מַאן דְּאַפְרִיד בְּשׁוּם סְפִירָה מֵחֲבֶרְתָּהּ מֵאִלֵּין עֶשֶׂר סְפִירָן, דְּאִתְקְרִיאוּ יו\"ד ה\"א וא\"ו ה\"א, כְּאִלּוּ אַפְרִיד בֵּיהּ.</p>"],[9514012521,"<p>וְאִיהוּ דִּמְיַיחֵד י' בְּה' ו' בְּה', וְלָא אִתְקְרִיאוּ יהו\"ה, אֶלָּא בֵּיהּ. וְכֵן אדנ\"י. וְכֵן אהי\"ה. וְכֵן אֱלֹהִי\"ם. וּמִיָּד דְּאִסְתַּלַּק מִתַּמָּן, לֵית לֵיהּ שֵׁם יְדִיעַ. וְאִיהוּ דְּקָשֵׁיר כָּל מֶרְכָּבוֹת דְּמַלְאָכַיָיא, וְקָשֵׁיר לוֹן כַּחֲדָא. וְסָבִיל עִילָּאִין וְתַתָּאִין. וְאִם הוּא אִסְתַּלַּק מִנַּיְיהוּ, לֵית לוֹן קִיּוּמָא, וְלָא יְדִיעָה, וְלָא חַיִּים. לֵית אֲתַר דְּלָאו אִיהוּ תַּמָּן, לְעֵילָא עַד אֵין סוֹף, וּלְתַתָּא עַד אֵין תַּכְלִית, וּלְכָל סִטְרָא לֵית אֱלוֹהַּ בַּר מִנֵּיהּ.</p>"],[9514012522,"<p>אֲבָל עִם כָּל דָּא דְּאִיהוּ בְּכָל אֲתַר, בְּרִיאָה יְצִירָה וַעֲשִׂיָּה דִילֵיהּ לָא שָׁוֵי, לָא בְּכוּרְסְיָיא, וְלָא בְּמַלְאָכַיָא, וְלָא בִּשְׁמַיָא, וְלָא בְּאַרְעָא וּבְיַמָּא, וְלָא בְּשׁוּם בְּרִיָּה בְּעָלְמָא. בְּגִין לְאִשְׁתְּמוֹדְעָא לֵיהּ כָּל בְּרִיָּין, אֶלָּא בִּסְפִירָן.</p>"],[9514012523,"<p>וְלֹא עוֹד, אֶלָּא כָּל בְּרִיָּין אִינוּן, מִנַּיְיהוּ עַל יְדֵי בְּרִיאָה, וּמִנַּיְיהוּ עַל יְדֵי יְצִירָה, וּמִנַּיְיהוּ עַל יְדֵי עֲשִׂיָּה. וּסְפִירָאן, אַף עַל גַּב דְּכֹלָּא בְּרָא וְיָצַר וַעֲבַד בְּהוֹן, לָא אִתְקְרֵי בְּהוּ בְּרִיאָה וִיצִירָה וַעֲשִׂיָּה כְּתַתָּאי, אֶלָּא אִינוּן בְּאוֹרַח אֲצִילוּת. וּבְגִין דָּא, כֶּתֶר וְחָכְמָה וּבִינָה וְדַעַת דִּשְׁאָר בְּרִיָּין, לָא דָמֵי לוֹן, הֲדָא הוּא דִכְתִיב, (שם מ) וְאֶל מִי תְדַמְּיוּנִי וְאֶשְׁוֶה יֹאמַר קָדוֹשׁ. כְּגַוְונָא דְאוֹרַיְיתָא דְּאִתְּמָר בָּהּ (משלי ג׳:ט״ו) יְקָרָה הִיא מִפְּנִינִים וְכָל חֲפָצֶיךָ לֹא יִשְׁווּ בָהּ, וּבוֹרֵא וְיוֹצֵר וְעוֹשֶׂה כֹּלָּא. אַף עַל גַּב דְּאִשְׁתְּמוֹדְעָא לִבְנֵי נָשָׁא בְּעֶשֶׂר סְפִירָאן, דְּאִינוּן כֶּתֶר עֶלְיוֹן חָכְמָה וּבִינָה וכו', אִתְּמָר בֵּיהּ, דְּאִיהוּ חַכִּים, וְלָא בְחָכְמָה יְדִיעָא. מֵבִין, וְלָא בְּבִינָה יְדִיעָא. חָסִיד, וְלָא בְּחֶסֶד יְדִיעָא. גִּבּוֹר, וְלָא בִּגְבוּרָה יְדִיעָא. אִיהוּ פְּאֵר בְּכָל אֲתַר, וְלָא בַּאֲתַר יְדִיעָא. אִיהוּ הוֹד וְהָדָר בְּכָל אֲתַר, וְלָא בַּאֲתַר יְדִיעָא. אִיהוּ צַדִּיק, וְלָאו בַּאֲתַר יְדִיעָא. אִיהוּ מֶלֶךְ, וְלָאו בְּמַלְכוּתָא יְדִיעָא.</p>"],[9514012524,"<p>אִיהוּ אֶחָד, וְלָא בְּחוּשְׁבָּן. כְּגוֹן אֶחָד, דְּסָלֵיק תְּלַת עֲשַׂר מְכִילָן. וְאַף עַל גַּב דְּלָאו אִיהוּ לְבַר מִכֹּלָּא, אִיהוּ סָבֵיל עִילָּאִין וְתַתָּאִין, וְסָבֵיל כָּל עָלְמִין, עַד דְּלֵית סוֹף וְלֵית תַּכְלִית, וְלֵית מַאן דְּסָבֵיל לֵיהּ.</p>"],[9514012525,"<p>כָל מַחְשַׁבְתִּין לָאָן לְמֶחֱשַׁב בֵּיהּ, וְלֵית חַד מִנַּיְיהוּ דְּיָדַע לְאַשָּׂגָא לֵיהּ. וַאֲפִילּוּ שְׁלֹמֹה דְּאִתְּמָר בֵּיהּ (מלכים א ה׳:י״א) וַיֶּחְכַּם מִכָּל הָאָדָם, בָּעָא לְאַשָּׂגָא לֵיהּ בְּמַחְשַׁבְתֵּיהּ, וְלָא יָכֵיל. וּבְגִין דָּא אֲמַר, (קהלת ז׳:כ״ג) אָמַרְתִּי אֶחְכְּמָה וְהִיא רְחוֹקָה מִמֶּנִּי.</p>"],[9514012526,"<p>לְמַאן דְּאִיהוּ מְחַיֶּה בְּיהו\"ה, לֵית מַאן דְּקָטֵיל לֵיהּ, וּלְמַאן דְּאִיהוּ מֵמִית בְּאדנ\"י, לֵית מַאן דִּמְחַיֶּה לֵיה. וְאִלֵּין אַתְוָון לֵית בְּהוּ חַיֵּי וּמִיתָה. בַּר מִנֵּיהּ. וְאַף עַל גַּב דִּבְהוֹן מִיתָה וְחַיֵּי, וְלֵית בְּהוֹן קְרִיבוּ וְיִיחוּדָא, בַּר מִינֵיהּ. שְׁמָא לָא אִתְקְרֵי שְׁלִים, אֶלָּא בֵּיהּ. וְלָא אַפֵּיק פְּעוּלָה לַפּוֹעַל אֶלָּא בֵּיהּ.</p>"],[9514012527,"<p>וְסִטְרִין אָחֳרָנִין דְּאִינוּן מִסִּטְרָא אָחֳרָא, כָּלְהוֹ בִּרְשׁוּתֵיהּ, לְמֶעְבַּד בְּהוֹן רְעוּתֵיהּ. וַעֲלַיְיהוּ אִתְּמָר, (דניאל ד׳:ל״ב) וְכָל דָּיְרֵי אַרְעָא כְּלָה חֲשִׁיבִין וּכְמִצְבְּיֵהּ עָבֵד בְּחֵיל שְׁמַיָא. וְלָא אִיתַי דִּי יְמַחֵא בִידֵהּ וְיֵאמַר לֵהּ מָה עֲבַדְתְּ. הוּא תָּפֵיס בְּכָל מַחֲשַׁבְתִּין, וְלֵית מַחֲשָׁבָה יְדִיעָא בֵיהּ.</p>"],[9514012528,"<p>וְלָא צָרִיךְ לְרָשְׁמָא אֲתַר לְמֶחֱשַׁב בֵּיהּ, וְלָא לְמִנְדַע בֵּיהּ. אֲבָל לְבְּרִיָין, בְּגִין דְּלָא יָכֵיל מַחֲשַׁבְתָּא דִּילְהוֹן לַאֲשָׂגָא לֵיהּ בְּכָל אֲתַר, בְּגִין דְּאִית לֵיהּ עָלְמִין אֲפִילּוּ לְעֵילָא מִן סְפִירָן. כְּנִימִין דְּשַׂעֲרָא דְּלֵית לוֹן חוּשְׁבְּנָא. וּבְגִין דְּיִנְדְעִין לְמִקְרֵי לֵיהּ בַּאֲתַר יְדִיעַ, רְשִׁים לוֹן סְפִירָן לְאִשְׁתְּמוֹדְעָא לֵיהּ בְּהוֹן, בְּגִין דְּאִינוּן קְשִׁירָן בְּעִילָּאִין וְתַתָּאִין, וּבְרָא בְהוֹן כָּל בְּרִיָין, לְאִשְׁתְּמוֹדְעָא לֵיהּ בְּהוֹן.</p>"],[9514012529,"<p>וְאִיהוּ דְּצַיָּיר שִׁרְטוּטִין, וְהַכָּרַת אַנְפִּין. בְּעַמּוּדָא דְּאֶמְצָעִיתָא צַּיָּיר תְּרֵי אַפִּין, בִּתְרֵין יוּדִין מִן וַיִּיצֶר. חוֹטְמָא בְּאוֹת ו' מִן וַיִּיצֶר, וְסָלֵיק בְּהוֹן חוּשְׁבַּן יהו\"ה. צַיָּיר לוֹן בְּהַאי שְׁמָא לְאִשְׁתְּמוֹדְעָא מִנֵּיהּ לְיוֹצֵר עָלְמִין.</p>"],[9514012530,"<p>יהו\"ה אִיהוּ תִּפְאֶרֶת, אִיהוּ נָהֵיר בְּאַנְפִּין. תְּרֵין גְּוָונִין דְּאַנְפִּין עָבֵד לֵיהּ, דְּאִינוּן חִוַּור וְסוּמָק, דְּאִינוּן חֶסֶד וּגְבוּרָה, דְּאִינוּן רָזָא ק (שמות ל״ד:ו׳) דְּוַיַּעֲבֹר ה' עַל פָּנָיו וַיִּקְרָא. וַעֲלַיְיהוּ אִתְּמָר לְגַבֵּי עֵילָא, (שם לג) וְדִבֶּר ה' אֶל משֶׁה פָּנִים אֶל פָּנִים. פּוּמָא דִּילֵיהּ מַלְכוּת. תְּרֵין שִׂפְוָון, נֶצַח וָהוֹד. יְסוֹד, לְשׁוֹן לִמּוּדִים, עֲלָה אִתְּמָר (במדבר י״ב:ח׳) פֶּה אֶל פֶּה אֲדַבֶּר בּוֹ.</p>"],[9514012531,"<p>שִׁרְטוּטִין דְּמִצְחָא, אִינוּן כְּגַוְונָא דָא, = - = מִינַּיְיהוּ חָמֵשׁ בְּפוּתְיָיא. בְּרָזָא דְּהַאי כּוֹכָבָא כְּגַוְונָא דָא;:: מִנַּיְּיהוּ כְּגַוְונָא דָא ו\"ו ו\"ו אַרְבָּעָה. בְּרָזָא דְּהַאי כּוֹכָבָא כְּגַוְונָא דָא;. וְאִינוּן בְּרָזָא דְאָת ד'. מִינַּיְיהוּ שִׁית כְּגַוָונָא דָא מַאן דְּרָשֵׁים כֹּלָּא י\"ו, דְּאִינוּן קַו הַמִּדָּה דִּלְהוֹן. וּבְהוֹן סָלְקִין לִתְלָתִין וּתְרֵין. וְכֹלָּא ד' כּוֹכְבַיָא. וְאִית בְּהוֹן תְּלָתִין פִּיקּוּדִין, בְּחוּשְׁבַּן תְּלַת יוּדִין, דְּאִינוּן י י י, וְאִלֵּין תְּלַת יוּדִין, אִינוּן תְּלַת יְרָחִין דְּסִיהֲרָא. וּבְהוֹן (שמות ב׳:ב׳) וַתַּהַר הָאִשָּׁה וַתֵּלֶד בֵּן וַתֵּרֶא אֹתוֹ כִּי טוֹב הוּא וַתִּצְפְּנֵהוּ שְׁלשָׁה יְרָחִים. וְאִינוּן תְּלַת יְרָחִין דְּסִיהֲרָא קַדִּישָׁא, תְּלַת אֲבָהָן אִינוּן.</p>"],[9514012532,"<p>יַעֲקֹב, עֲלֵיהּ אִתְּמָר (שם יט) בַּחֹדֶשׁ הַשְּׁלִישִׁי. בֵּיהּ הַהוּא טוֹב גָּנֵיז, וְהוּא אוֹרַיְיתָא, דְּאִתְּמָר בֵּיהּ, (תהילים קי״ט:ע״ב) טוֹב לִי תוֹרַת פִּיךָ. (מלאכי ג׳:כ״ב) זִכְרוּ תּוֹרַת משֶׁה עַבְדִּי.</p>"],[9514012533,"<p>וְעַל הַהוּא טוֹב, אִיתְּמָר לְגַבֵּי יַעֲקֹב, (בראשית ל״ב:ל״ב) וַיִּזְרַח לוֹ הַשֶּׁמֶשׁ. וַעֲלֵיהּ אִתְּמָר, (שמות י״ט:ט״ז) וַיְהִי בַּיּוֹם הַשְּׁלִישִׁי בִּהְיוֹת הַבֹּקֶר וַיְהִי קוֹלוֹת וּבְרָקִים.</p>"],[9514012534,"<p>וּבְזִמְנָא דְיֵיתֵי מַלְכָּא מְשִׁיחָא, בְּסוֹף גָּלוּתָא בַּתְרָאָה, דְּאִתְּמָר בֵּיהּ (בראשית כ״ט:ז׳) הֵן עוֹד הַיּוֹם גָּדוֹל, (שמות ב׳:ג׳) וְלֹא יָכְלָה עוֹד הַצְּפִינוֹ וַתִּקַּח לוֹ תֵּבַת גֹּמֶא. כְּגַוְונָא דְּאָרוֹן דְסֵפֶר תּוֹרָה. אוֹרַיְיתָא וַדַּאי יְהֵא גְּנִיזוּ דִילֵיהּ, בְּדָרָא בַתְרָאָה. וּבָהּ אִתְטַמַּר, כְּגַוְונָא דְּנֹחַ בַּתֵּיבָה, דְּהֲוָה אָזֵיל עַל מַיָיא. הָכֵי הַאי אָזֵיל בֵּין עֵרֶב רַב, דְּאִינוּן מַיִם הַזֵּדוֹנִים.</p>"],[9514012535,"<p>וּבְסוֹף גָּלוּתָא שַׁוֵּי קוּדְשָׁא בְּרִיךְ הוּא לְמשֶׁה בְּהַהִיא תֵּיבָה, וְאַיְיתֵי לֵיהּ בְּגָלוּתָא. וּמְנָא לָן דִּבְסוֹף גָּלוּתָא אַיְיתֵי לֵיהּ. הֲדָא הוּא דִכְתִיב, (שם) וַתָּשֶׂם בַּסּוּף. וְעַד הַהוּא סוֹף, כְּתִיב (דברים ד׳:ל׳) וְהָיָה בְּאַחֲרִית הַיָּמִים וְשַׁבְתָּ עַד ה' אֱלֹהֶיךָ. וְעוֹד, וַתָּשֶׂם בַּסּוּף, דָּא אִיהוּ רָזָא (קהלת י״ב:י״ג) דְּסוֹף דָּבָר הַכֹּל נִשְׁמָע.</p>"],[9514012536,"<p>וַתַּחְמְרָה בַחֵמָר וּבַזָּפֶת, חֵמָר מִבִּפְנִים חִוָּור, וְזֶפֶת מִבַּחוּץ אוּכָם. הָכֵי אוֹרַיְיתָא, חִוָּורָא מִלְּגָיו, וְאוּכְמָא מִלְּבַר. חִוָּורָא מִסִּטְרָא דְאוֹר, דְּאִיהוּ אוֹר דְאַבְרָהָם, דְּדַרְגֵּיהּ חֶסֶד. וְהַאי אִיהוּ אוֹר דְּאִתְּמָר בֵּיהּ, (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב. וְאִתְּמָר בֵּיהּ וַתֵּרֶא אֹתוֹ כִּי טוֹב הוּא. וְאֵין אוֹר אֶלָּא תּוֹרָה, דִּכְתִיב (משלי ו׳:כ״ג) וְתוֹרָה אוֹר. וְדָא אוֹר דְּאִתְיְיהֵיב מִיָמִינָא. אוּכְמָא מִלְּבַר, בְּהַהוּא חשֶׁךְ דְּיִצְחָק, דְּאִתְּמָר בֵּיהּ (בראשית כ״ז:א׳) וַתִּכְהֶיןָ עֵינָיו מֵרְאוֹת, וְאִתְּמָר (שם א) וְלַחשֶׁךְ קָרָא לָיְלָה.</p>"],[9514012537,"<p>וַתָּשֶׂם בַּסּוּף, דָּא יַעֲקֹב. דְּאִתְּמָר בֵּיהּ, (שם מט) וַיֶּאֱסֹף רַגְלָיו אֶל הַמִּטָה. עַל שְׂפַת הַיְאוֹר, דָּא אוֹרַיְיתָא דִּבְעַל פֶּה, בְּגִין דְּאִיהִי הֲלָכָה לְמשֶׁה מִסִּינַי, קַבָּלָה לְמשֶׁה.</p>"],[9514012538,"<p>כַד אָזְלָא לְגַבֵּיהּ, אִתְקְרִיאַת הֲלָכָה לְמשֶׁה. כַּד קַבֵּיל לָהּ בִּדְרוֹעוֹי, אִתְקְרִיאַת קַבָּלָה לְמשֶׁה. כַּד שַׁרְיָיא בְּפוּמֵיהּ, (במדבר י״ב:ח׳) פֶּה אֶל פֶּה אֲדַבֵּר בּוֹ. וַעֲתִידָא לְמֵיזַל לְגַבֵּיהּ בְּסוֹף יוֹמַיָיא, וִיקַבֵּל לָהּ בִּדְרוֹעוֹי. וּבָהּ בּוֹקֵעַ מַיָּא דְאוֹרַיְיתָא.</p>"],[9514012539,"<p>וְעוֹד וַתַּחְמְרָה, בְּקַלִּין וַחֲמוּרִין דְּאוֹרַיְיתָא. בַּחֵמָר וּבַזָּפֶת, בְּחוּמְרָא דְּפִיקּוּדִין דַּעֲשֵׂה, דְּאִינוּן מִצַּד אוֹר. וּמִפִּיקּוּדִין דְּלֹא תַעֲשֶׂה, דְּאִינוּן חשֶׁךְ.</p>"],[9514012540,"<p>וְרָזָא דְמִלָּה, (תהילים מ״ב:ט׳) יוֹמָם יְצַוֶּה ה' חַסְדּוֹ וּבַלַּיְלָה שִׁירֹה עִמִּי. בְּהַהוּא דְּאִתְּמָר בֵּיהּ וְלַחשֶׁךְ קָרָא לָיְלָה. וַיִּקְרָא אֱלֹהִים לָאוֹר יוֹם, לְקִבְלֵיהּ אָמַר, יוֹמָם יְצַוֶּה ה' חַסְדּוֹ. וְלַחשֶׁךְ קָרָא לַיְלָה, לְקִבְלֵיהּ אָמַר, וּבַלַּיְלָה שִׁירֹה עִמִּי.</p>"],[9514012541,"<p>וַתָּשֶׂם בַּסּוּף, בְּסוֹף מ' שְׁנִין בַּתְרָאִין דְּגָלוּתָא. לְקִבְלַיְיהוּ עָלוּ יִשְׂרָאֵל לְסוֹף מ' שְׁנִין דְּאָזְלוּ בַּמִּדְבָּר, לְאַרְעָא דְיִשְׂרָאֵל. בְּהַהוּא זִמְנָא, (תהלים מב) כִּי רָם ה' וְשָׁפָל יִרְאֶה.</p>"],[9514012542,"<p>וַתֵּתַצַּב אֲחֹתוֹ מֵרָחֹק, דָּא חָכְמָה דִילֵיהּ. הֲדָא הוּא דִכְתִיב, (משלי ז׳:ד׳) אֱמֹר לַחָכְמָה אֲחֹתִי אָתְּ. וַתֵּתַצַּב, בֵּיהּ (שמואל א ג׳:י׳) וַיָּבֹא ה' וַיִּתְיַצֵּב. מֵרָחוֹק, (משלי ל״א:י״ד) מִמֶּרְחָק תָּבִיא לַחְמָהּ.</p>"],[9514012543,"<p>וְעוֹד וַתֵּתַצַּב אֲחֹתוֹ, דָּא חָכְמָה. מֵרָחֹק בְּהַהוּא זִמְנָא דְּמִתְרַחֲקִין יִשְׂרָאֵל מֵחָכְמַת קַבָּלַת משֶׁה, וְאִתְרַחֲקָא אִיהִי מִנַּיְיהוּ. בְּהַהוּא זִמְנָא, (שמות ב׳:ה׳) וַתֵּרֶד בַּת פַּרְעֹה לִרְחֹץ עַל הַיְאֹר, נָחֲתָא מִדַּת הַדִּין לְקַטְרְגָא עֲלֵייהוֹן, וּלְאִתְרַחֲצָא מִדָּמָא דְיִשְׂרָאֵל, דְּאִינוּן דָּמִים דִּלְהוֹן, דְּאִינוּן חַיֵּיהוֹן. וְכֹלָּא עַל דְּהַהוּא אוֹר דְּאִתְּמָר בֵּיהּ (בראשית א׳:ד׳) וַיַּרְא אֱלֹהִים אֶת הָאוֹר כִּי טוֹב, עַל אוֹר דְאוֹרַיְיתָא, דַּהֲווֹ מִתְרַחֲקִין מִינָהּ, אוֹר דְּמשֶׁה וַדַּאי.</p>"],[9514012544,"<p>וְנַעֲרֹתֶיהָ הֹלְכֹת עַל יַד הַיְאֹר. אִלֵּין הָאוּמוֹת, דְּאִינוּן עֵרֶב רַב. וְכֵן כָּל אוּמִין דְּעָלְמָא, אִתְיָיעֲטִין עֲלַיְיהוּ דְיִשְׂרָאֵל, לְאַעֲקָרָא לוֹן מִן עָלְמָא, וְכוֹלָּא עַל סִיבָּה דְּהַהוּא אוֹר, וְזֶהוּ עַל יַד הַאי אוֹ\"ר.</p>"],[9514012545,"<p><Noneb>סִתְרֵי תוֹרָה </b></p>"],[9514012546,"<p>וּתְלַת דְּלָא עָבְרוֹן, הַאי אִיהוּ בְּאָת פ' וְאָת א', וְכֹלָּא פ\"א בְּאַשְׁלָמוּתֵיהּ. אָת ר' לֵית בֵּיהּ כְּלָל.</p>"],[9514012547,"<p>שַׂעֲרוֹי אוּכְמִין, תַּלְיָין וְלָא שְׁעִיעָן. דָּא אִיהוּ בַּר נָשׁ דְּשָׁתֵיק תָּדִיר. אֲבָל פְּקִיחָא אִיהוּ, מָארֵי דְלִישְׁנָא בִּישָׁא, מִלּוֹי בְּרוּגְזָא, פּוּם מְמַלֵּל רַבְרְבָן, אַצְלַח וְלָא אַצְלַח, מָארֵי קְטָטָא בְּבֵיתֵיהּ, לָא חַיֵּישׁ לִיקָרָא דְּבַּר נָשׁ, חַד בְּפוּמֵיהּ וְחַד בְּלִבֵּיהּ, הֲפַכְפָּךְ בְּלִישָׁנֵיהּ, גְּבִינִין דִּילֵיהּ סוּמְקִין זְעֵיר.</p>"],[9514012548,"<p>וְאִי קְמִיטָא תְּחוֹת עֵינֵיהּ רַב, וְאָזֵיל עַד חוֹטְמָא מִסְטַר יָמִינָא, וּתְרֵין תְּחוֹתֵיהּ, וְחַד מִנַּיְיהוּ זְעֵיר מֵאוֹחֲרָא, דָּא שָׁכֵיב בְּנִדָּה מִיּוֹמִין זְעִירִין, וְחוֹבֵיהּ רְשִׁים בֵּיהּ רְשִׁימִין אִלֵּין.</p>"],[9514012549,"<p>בֵּין כְּתֵפוֹי אִית לֵיהּ רוֹשֶׁם חַד, וְד' שַׂעֲרִין בֵּיהּ, חַד מִנַּיְהוּ בְּאֶמְצָעִיתָא רַב וְתָלֵי, וְג' אָחֳרָנִין זְעִירִין. וְעַד לָא הֲוָה עֲבֵירָה דָא, הֲווֹ תְּלַת זְעִירִין, וְחַד דְּאִתְרְשֵׁם בֵּיהּ דַּקִּיק וּזְעֵיר מִכָּלְהוֹ. הַהוּא רוֹשֶׁם הֲוָה בֵּיהּ מִקַּדְמַת דְּנָא אוּכָם, וְאִינוּן שַׂעֲרִין חִוְּורִין כָּלְהוֹ. הַשְׁתָּא לָאו הָכֵי, אֶלָּא רוֹשֶׁם אוּכָם, וְחַד סוּמְקָא כִּרְשִׁימוּ דְּטוּלְפְחָא בְּאֶמְצָעִיתָא. וְהוּא שַׂעֲרָא דְּאִתְרַבֵּי בֵּין אָחֳרָנִין, רֵישֵׁיהּ סוּמָק, וּדְאִשְׁתָּאַר חִיוָּר. אִי תָּב בִּתְיוּבְתָּא, תִּשְׁכַּח בְּעֵינֵיהּ יָמִינָא חַד חִיוָּרָא, חִיוָּר גּוֹ הַהוּא אוּכְמָא.</p>"],[9514012550,"<p>בְּמִצְחֵיהּ תְּלַת שִׁרְטוּטִין עָבְרִין, וּתְרֵין דְּלָא עָבְרִין. הַהוּא רוֹשֶׁם אוּכָם, וְסַחֲרָנֵיהּ חוּטָא סוּמְקָא, וּבְגוֹ הַהוּא חוּטָא, חַד שַׂעֲרָא דַקִּיק זְעֵיר, וּתְלַת שַׂעֲרִין בְּאִמְצָעִיתָא, כָּלְהוֹ כַּחֲדָא. זְעֵירָא יֶחְכַּם בְּאוֹרַיְיתָא, אִי יוֹלִיף, וְלָא יִצְלַח בְּעוֹבָדוֹי.</p>"],[9514012551,"<p>וְאִי יָרוֹקָא דְעֵינָא לָא אִצְטַבַּע כָּל כָּךְ, וְעֵינוֹי אֻכְמִין, וְחַד חוּטָא סוּמָק זְעֵיר, אַעֲבַר בֵּין אִינוּן גְּוָונִין. כְּדֵין אִיהוּ בְּאָת פ' בִּשְׁלִימוּ, וּבְאָת ר' בִּלְחוֹדוֹי.</p>"],[9514012552,"<p>בְּמִצְחֵיהּ תִּשְׁכַּח שִׁית שִׁרְטוּטִין, תְּלַת עָבְרִין, וּתְלַת לָא עָבְרִין. שַׂעֲרֵיהּ תַּקִּיף וְלָא כָּל כַּךְ, תָּלֵי וְלָא תָלֵי. הַאי אִיהוּ בִּשְׁלִימוּ לְכָל בַּר נָשׁ. קַמְצָן אִיהוּ, לֵית בֵּיהּ חֵידוּ, וַאֲפִילּוּ בְּחֶדְוָה לָא אִתְחַדֵּי. בִּדְווֹנָא אִתְחֲזֵי.</p>"],[9514012553,"<p>אָטִים אוּדְנֵיהּ שְׂמָאלֵיהּ. בְּשִׁינּוֹי אִית תְּלַת רַבְרְבִין מִלְּעֵילָא, וְיַהֲבוּן לוֹן דּוּכְתָּא אִינוּן דִּלְתַתָּא, מְהֵימְנָא אִיהוּ וְלָא כָּל כָּךְ.</p>"],[9514012554,"<p>אַנְפּוֹי אֲרִיכִין, וְלָא שַׁפִּירִין, קָלֵיהּ כְּאִיתְּתָא, וּמִלּוֹי כְּאִיתְּתָא, מְקַנַּח פּוּמֵיהּ בְּמִלּוֹי, אַפְתַּח אֶצְבְּעָאן דִּידוֹי בְּמִילּוּלֵיהּ. כַּד אָזַל, אַקְדִּים לֵיהּ בְּלִיתָא דְפַרְסָאי, דְּלָא יָחוֹב בַּר נָשׁ לְגַבֵּיהּ, עֲלֵיהּ כְּתִיב, (דברים כ״ד:ד׳) כִּי תוֹעֵבָה הִיא לִפְנֵי ה'.</p>"],[9514012555,"<p>עַיְינִין יָרוֹקִין, וְאִלֵּין סִימָנִין בֵּיהּ, וְאַנְפּוֹי אֲרִיכִין שַׁפִּירָן, שַׂעֲרוֹי אוּכְמִין וּמְרִיטִין מִלְּעֵילָא בְּרֵישֵׁיהּ. רֵישֵׁיהּ רַב, כַּד אָזֵיל כָּפֵיף רֵישֵׁיהּ, קְרִיצִין דְּעֵינוֹי כְּקַדְמָאָה, עֲלֵיהּ כְּתִיב (משלי א׳:ט״ו) מְנַע רַגְלְךָ מִנְּתִיבָתָם.</p>"],[9514012556,"<p>עַיְינִין רַבְרְבִין וִירוֹקִין, דָּא אִיהוּ בִּתְרֵין אַתְוָון, ר' פ\"א, חַד יְחִידָא, וְחַד בִּשְׁלִימוּ. בְּמִצְחוֹי שִׁרְטוּטָא חָדָא, דְּאָזֵיל וְעָבַר מִסְּטַר לִסְטַר, וּתְלַת אָחֳרָנִין אִית דְּלָא עָבְרִין. מִצְחֵיהּ רַב. קְרִיצִין דְּעַל עֵינוֹי לָאו רַבְרְבִין. בְּדִיקֵנֵיהּ שַׂעֲרָא טְפֵי. וְאַנְפּוֹי שַׁפִּירָן סוּמָק, שַׂעֲרֵיהּ שְׁעִיעַ וְלָא כָּל כָךְ.</p>"],[9514012557,"<p>דָּחִיל חַטָאָה אִיהוּ, רְחִים אוֹרַיְיתָא אִיהוּ, רְחִים לְאִינוּן דְּמִשְׁתַּדְּלִין בָּהּ, חָדֵי בְּכֹלָּא, עָבִיד טִיבוּ לְכֹלָּא, כְּדִיבָא לְתוֹעַלְתֵּיהּ, מְהֵימְנָא אִיהוּ לְרָזִין דְּאוֹרַיְיתָא, טַב אִיהוּ לְמִלִּין דְּעָלְמָא, מַאן דְּאִשְׁתַּתֵּף בַּהֲדֵיהּ לָא אַצְלַח, לֹא אִיהוּ, וְלָא אָחֳרָא. אַצְלַח אִיהוּ בִּלְחוֹדוֹהִי, דְּהָא אָת ר' גָּרִים.</p>"],[9514012558,"<p>פָּגִים אִיהוּ בְּרֵישֵׁיהּ לְעֵילָא, רְשִׁימָא דְחַד מַכְתְּשָׁא דְּהֲוָה לֵיהּ תַּמָּן, דְּעָבַד לֵיהּ חַד רַבְיָיא בְּאַבְנָא, בְּלָא רְעוּ וְכַוָּונָה, וְאִיכְסֵי בְּשַׂעֲרָא. וְהַהוּא רִישּׁוּמָא דְּמַכְתְּשָׁא, כְּגַוְונָא דְגִימְל יְוָנִי\"ת. מְהֵימְנָא אִיהוּ לְגַבֵּי בְּנֵי נְשָׁא, וְסָלֵיק לְמֶהֱוֵי רֵישָׁא דְעַמָּא, עַד הָכָא רָזָא דְעַיְינִין.</p>"],[9514012559,"<p>וְאִית רָזִין אָחֳרָנִין בְּעַיְינִין, דְּמִתְפָּרְשָׁן מִינַּיְיהוּ. עַיְינָן דִּמְעַמְקָן וְחָיְיכָן, דָּא אִיהוּ בִּשְׁלִימוּ דְּאַתְוָון, בַּר דְּקַדְמָאָה ר', וּלְבָתַר פ'. דָּא אִיהוּ בַּר נָשׁ דְּאַצְלַח בְּעוֹבָדוֹי.</p>"],[9514012560,"<p>תְּלַת שִׁרְטוּטִין בְּמִצְחֵיהּ, מִצְחֵיהּ עָגֵיל, עֵינוֹי נְהִירִין, מְרַקְמָן עוֹבַד צִיּוּר, דַּכְיָין, קַיְימִין עַל שְׁלִימוּ. שַׂנְאוֹי יִפְּלוּן תְּחוֹתֵיהּ, פְּקִיחָא אִיהוּ, אַצְלַח בְּכוֹלָּא, בָּהִיל בְּעוֹבָדוֹי, טַב אִיהוּ עִם בְּנֵי נְשָׁא, מִלּוֹי בְּקַשְׁיוּ בְּלָא דְחִילוּ, וַותְּרָן אִיהוּ, עָבִיד טִיבוּ, וְלֹא לִשְׁמָהּ.</p>"],[9514012561,"<p>שַׂעֲרֵיהּ שְׁעִיעַ וְתַלְיָא. וְלִישָׁנֵיהּ כְּחַרְבָּא. תְּחוֹת עֵינוֹי קְמִיטִין, תְּלַת רַבְרְבִין וּתְלַת זְעִירָן, וְאִי אִית ד' זְעִירִין וּתְלַת רַבְרְבִין, כְּדֵין תִּשְׁכַּח תְּרֵין שִׁרְטוּטִין בְּמִצְחֵיהּ, עָבְרִין מִסְטַר לִסְטַר, וּתְלַת דְּמָטוֹ וְלָא מָטוֹ.</p>"],[9514012562,"<p>תְּחוֹת טַבּוּרֵיהּ קָיְימָא רִישׁוּמָא חַד, צִיּוּרָא דְּרֵישָׁא דְּבַּר נָשׁ, אוּכָם וְחִיוָּור תְּרֵין שַׂעֲרִין תַּלְיָין בֵּיהּ. הַהוּא בַּר נָשׁ אִתְכְּשַׁל בְּאִיתַּת גְּבַר מִיּוֹמִין רְחִיקִין, וְלָא תָּב מֵהַהוּא חוֹבָא. מַרְעִין רָדְפִין אֲבַתְרֵיהּ. וְעַל דָּא חַד מֵאִינוּן מַרְעִין, דִּצְרִיךְ לְאוֹשְׁדָא שֶׁתֶּן וְלָא יָכִיל. דְּעַד כְּעָן הַהוּא חוֹבָא תַּלְיָיא בְּקַדְלֵיהּ דְּנָחָשׁ עֲקִימָא, וְשַׁלִּיט עֲלֵיהּ בְּדָא. וְדָא לְסוֹף יוֹמִין דְּסִיבוּ.</p>"],[9514012563,"<p>וְאִי תָּב בִּתְיוּבְתָּא, בְּזִמְנָא דְּאִיהוּ בְּחֵילֵיהּ, הַהוּא רִשּׁוּמָא אַזְעֵירַת דְּיוּקְנָאָה, וְשַׂעֲרִין לָא תַּלְיָין בֵּיהּ כְּלָל. וְאִי תָּב בִּתְיוּבְתָּא בְּסוֹף יוֹמוֹי, כַּד מַרְעִין רָדְפִין אֲבַתְרֵיהּ, כְּדֵין הַהוּא רְשִׁימָא קָמִיט, וְשַׂעֲרִין תַּלְיָין בֵּיהּ, וְהַהוּא מַרְעָא לָא אַעֲדֵי מִנֵּיהּ, מִגּוֹ דְּתַלְיָיא בְּקַדְלֵיהּ דְּנָחָשׁ.</p>"],[9514012564,"<p>בְּגִין דְהַהוּא נָחָשׁ, כֵּיוָן דְּאָחִיד הַהוּא חוֹבָא עַל קַדְלֵיהּ, לֵית מַאן דְּיַתִּיר קִשְׁרָא מִקַּדְלֵיהּ. בְּגִין דְּהַהוּא נָחָשׁ לֵית לֵיהּ רְשׁוּת בְּיוֹמֵי דְּעוּלֵימוּ דְּבַּר נָשׁ לְקָשְׁרָא הַהוּא חוֹבָא עַל קַדְלֵיהּ. וְקָשְׁרֵי לֵיהּ בְּקִשְׁרִין תַּקִּיפִין.</p>"],[9514012565,"<p>וְאִיהוּ רָדִיף אֲבַתְרֵיהּ דְּהַהוּא בַּר נָשׁ, וּמַלְקֵי לֵיהּ בְּהַהוּא בְּרִית דְּחָב בֵּיהּ. וְאַף עַל גַּב דְּתָב בִּתְיובְתָּא, יְצַוַּוח מִגּוֹ עָאקוּ דְּלָקוּתָא. הַהוּא חִוְּיָא דָּלִיג וְעָאל בְּהַהוּא קִשְׁרָא לְשִׁיפּוּלֵי דִּתְהוֹמָא רַבָּא, כְּדֵין רָוַוח לֵיהּ לְבַר נָשׁ, וְהַהוּא נָחָשׁ לְבָתַר יוֹמִין נָפִיק וְעָבִיד דָּא.</p>"],[9514012566,"<p>וּבְזִמְנָא דְּמִית הַהוּא בַּר נָשׁ, תְּלַת מְאָה שׁוֹטְרִין רָדְפִין אֲבַתְרֵיהּ דְּהַהוּא בַּר נָשׁ, וְתָפְסִין לֵיהּ וְעָיְילִין לֵיהּ קַמֵּי מַלְכָּא. וּמַלְכָּא קַדִּישָׁא מְתַבַּר אִינוּן קִשְׁרִין, וְנָחִית הַהוּא חוֹבָה מֵעַל קַדְלֵיהּ.</p>"],[9514012567,"<p>וְעַל רָזָא דָא כְּתִיב, (ישעיהו כ״ב:י״ד) אִם יְכֻפַּר הֶעָוֹן הַזֶּה לָכֶם עַד תְּמֻתוּן. כְּמָה דְאַתְּ אָמֵר (שם כח) וְכֻפַּר בְּרִיתְכֶם אֶת מָוֶת. תָּבַר הַהוּא קְיָימָא דִילְּכוֹן. אֶת מָוֶת, כְּמָה דְאַתְּ אָמֵר (בראשית ל״ב:כ״א) כִּי אָמַר אֲכַפְּרָה פָנָיו בַּמִּנְחָה, אֲבַטֵל רוּגְזֵיהּ. כְּדֵין הַהוּא בַּר נָשׁ אָזִיל לְהַהוּא עָלְמָא נָקִי מֵהַהוּא חוֹבָה, דְּהָא קַבֵּיל עָנְשֵׁיהּ בְּהַאי עָלְמָא.</p>"],[9514012568,"<p>וְכִי תֵימָא, הֵיכֵי מַשְׁמַע דִּבְהַאי עֲוֹן אֵשֶׁת אִישׁ מִשְׁתָּעֵי קְרָא. דִּכְתִיב הָכָא אִם יְכֻפַּר הֶעָוֹן הַזֶּה, וּכְתִיב הָתָם בְּאִיסּוּר אֵשֶׁת אִישׁ שֶׁזִּינְתָה, (במדבר ה׳:ל״א) וְנִקָּה הָאִישׁ מֵעָוֹן. וּכְתִיב גַּבֵּי אַבְנֵר וְאִישׁ בּשֶׁת, (שמואל ב ג׳:ח׳) וַתִּפְקֹד עָלַי עֲוֹן הָאִשָּׁה הַיּוֹם הַזֶּה. אִי נָמֵי, (ישעיהו כ״ב:י״ג) וְהִנֵּה שָׂשׂוֹן וְשִׂמְחָה הָרֹג בָּקָר וְשָׁחֹט צֹאן אָכוֹל וְשָׁתוֹ, וּכְתִיב (משלי ל׳:כ׳) הָתָם אָכְלָה וּמָחֲתָה פִיהָ, וּכְתִיב (בראשית ל״ט:ו׳) כִּי אִם הַלֶּחֶם אֲשֶׁר הוּא אוֹכֵל.</p>"],[9514012569,"<p>וּכְתִיב (משלי ט׳:ט״ז-י״ז) מִי פֶתִי יָסֻר הֵנָּה וַחֲסַר לֵב וְאָמְרָה לוֹ. מַיִם גְּנוּבִים יִמְתָּקוּ וְלֶחֶם סְתָרִים יִנְעָם. וְלֹא יָדַע כִּי רְפָאִים שָׁם בְּעִמְקֵי שְׁאוֹל קְרֻאֶיהָ. זֶהוּ כַּד לָא קַבֵּיל עָנְשֵׁיהּ בְּהַאי עָלְמָא.</p>"],[9514012570,"<p>וְאִי אִשְׁתְּכַח בֵּיהּ זְכוּת אָבוֹת, עוֹנְשֵׁיהּ בְּהַאי עָלְמָא בְּהַהוּא עָוֹן, כְּמָה דְאַתְּ אָמֵר (תהילים פ״ט:ל״ג) וּפָקַדְתִּי בְּשֵׁבֶט פִּשְׁעָם וּבִנְגָעִים עֲוֹנָם. וּפָקַדְתִּי זְעֵיר זְעֵיר, ק (איוב ל) אִם בְּפִידוֹ לָהֶן שׁוּעַ. (שמות כ) פּוֹקֵד עֲוֹן אָבוֹת עַל בָּנִים. מַזְעֵיר וְנוֹתֵן זְעֵיר עַל דָּא, וּזְעֵיר עַל דָּא, וְאִשְׁתְּזֵיב הוּא וַאֲבוֹי מֵעוֹנְשָׁא דְּהַהוּא עָלְמָא, דְּהָא בְּרָא מְזַכֵּי אַבָּא.</p>"],[9514012571,"<p>עַיְינִין עֲקִימִין, דְּלָא מִסְתַּכְּלִין בְּאוֹרַח קְשׁוֹט, דָּא הוּא בְּלָא אָת כְּלַל, פָּרְחִין מִנֵּיהּ כָּל אַתְוָון, בְּגִין דְּאִיהוּ מָארֵי דְּעֵינָא בִישָׁא, חֵיזוּ דִּילֵיהּ בְּהִיפּוּכָא, הַהוּא רַע עַיִן שַׁלִּיט עֲלֵיהּ.</p>"],[9514012572,"<p>וְאִי כָּשְׁרִין עוֹבָדוֹי דְּהַהוּא בַּר נָשׁ, לָא שַׁלִיט אֶלָּא עַל עֵינוֹי. וְאִיצְטְרִיךְ בַּר נָשׁ לְאִסְטַמְּרָא מֵעֵינוֹי. בְּגִין דְּסִטְרָא אָחֳרָא שָׁלְטָא עֲלַיְיהוּ. אִינוּן עַיְינִין חָמָאן כָּל בִּישׁ, וְאִתְעֲבִידִין סַרְסוּרִין לְגַבֵּיהּ, וְשַׁיְיפֵי גוּפָא נִצְחָן, אֲבָל שָׁלְטִין עֵינוֹי מִסְתַּכְּלִין.</p>"],[9514012573,"<p>מַאן דְּבָעֵי לְאִסְתַּמְּרָא מִנֵּיהּ, לִכְתּוֹב בִּידֵיהּ יָמִינָא יו\"ד, וּבִידֵיהּ שְׂמָאלָא זַי\"ן, וְיִפְתַּח קַמֵּיהּ וְלֵימָא, יו\"ד בַּאֲפָכָא בְּאַתְוֵוי, וְאִשְׁתְּזֵיב מִנַּיְיהוּ.</p>"],[9514012574,"<p>דָּא אִיהוּ דְּפָגִים לְשִׁימּוּשָׁא דִּקְדוּשָּׁה, בְּגִין כָּךְ לָא שַׁרְיָין בֵּיהּ אַתְוָון, וְהָא אִסְתַּלְּקוּ מִנֵּיהּ. דְּהָא אִיהוּ בְּרָזָא דְּהַהוּא קַו יָרוֹק דְּנָפֵיק מִתּוֹהוּ בִּמְדִידוּ דְּבוּצִינָא. וְאִית לְאִסְתַּכְּלָא גּוֹ שִׁרְטוּטִין דִּידָא, בְּיָמִינָא וּבִשְׂמָאלָא, וּבְרָזָא דְּאִינוּן שִׁרְטוּטִין דְּיָדִין תִּשְׁכַּח דָּא.</p>"],[9514012575,"<p>מַאן דְּעֵינָא חַד אָטִים וְלָא כָּל כַּךְ, וְעֵינָא אָחֳרָא פְּקִיחָא, מוּמָא חַד מֵאִינוּן מוּמִין אִית בֵּיהּ. דָּא אִיהוּ בְּאָת ר' בִּלְחוֹדוֹי בְּאַשְׁלָמוּתֵיהּ. וְאָת י' מָטֵי לְגַבֵּיהּ וְלָא מָטֵי.</p>"],[9514012576,"<p>בְּמִצְחֵיהּ תְּלַת שִׁרְטוּטִין עָבְרִין, וְחַד זְעֵירָא דְּאַעֲבַר, אוּף הָכֵי רְשִׁימָא חָדָא סָלִיק מֵעֵינֵיהּ לָקֳבֵיל אוּדְנֵיהּ שַׂעֲרֵי תָּלֵי וְתַקִּיף. קְרִיצוֹי רַבְרְבִין. אִיהוּ מוּמָא מִסְטַר אוֹחֲרָא. אִימָּא דִילֵיהּ אָזְלַת בְּחָרְשִׁין כַּד הֲוָה בִּמְעָהָא. וְנָפְקַת לְפָרָשָׁא דְּאוֹרְחִין בְּלֵילְיָיא, כַּד דָּא אִתְיְילֵיד. בְּגוֹ תְּרֵין שְׁנִין דִּילֵיהּ אִתְחַלָּשׁ עַד דְּאַזְעַר דְּיוֹקְנֵיהּ וְאִמֵּיהּ אָזְלָא בְּלֵילָא בַּהֲדֵיהּ, וְקָא עָבְדַת חַרְשִׁין עֲלֵיהּ.</p>"],[9514012577,"<p>הַאי חָדֵי בְּחֶדְוָא, לֵית בֵּיהּ מְהֵימְנוּתָא, מְשַׁבַּח גַּרְמֵיהּ בַּמֶּה דְלֵית בֵּיהּ, גַּס רוּחַ, מְמַלֵּל בִּישִׁין וַעֲתִיקִין. וַותְּרָן אִיהוּ, לֵית בֵּיהּ קַמְצָנוֹ כְּלָל. מָארֵי דְּגַיְיפָא הוּא. אַצְלַח וְלָא אַצְלַח, חֲדִידָא בְּלִישָׁנֵיהּ.</p>"],[9514012578,"<p>וְאִי חַד שִׁרְטוּטָא בְּמִצְחֵיהּ רַב וּתְרֵין זְעִירִין, דָּא אָזַל גּוֹ חָרְשִׁין, וְהָא אִימֵּיהּ עָבְדַת לְהוֹ. וּמִתְחַלְּפִין שִׁרְטוּטִין דְּקָא סָלְקִין מֵעֵינָא יָמִינָא לְעֵינָא שְׂמָאלָא. גַּס רוּחַ אִיהוּ, אֲבָל לֵית בֵּיהּ בִּישָׁא כְּלָל. קַמְצָאן אִיהוּ, לֵית בֵּיהּ קְצַת גִּיּוּפָא. חֲדִידָא בְּלִישָׁנֵיהּ אִיהוּ.</p>"],[9514012579,"<p>בְּשָׂפָה דִילֵיהּ אִית בֵּיהּ רוֹשֶׁם חַד סוּמָק טְפֵי, וְחַד שַׂעֲרָא בְּאֶמְצָעוּתָא. אֶצְבְּעָן דִּי בְרַגְלֵיהּ שְׂמָאלָא, קְמִיטִין זְקִיפִין מִתְפַּשְּׁטִין, עַיְינִין זְבַּלְגָנִין, יָרוֹקִין, נָחֲתִין דִּמְעִין תָּדִיר. הַאי אִתְדַּבַּק בְּאָת פ', וְאָת ר' לָא אִתְיְישַׁב בֵּיהּ, הַאי אִית לֵיהּ אַרְבַּע שִׁרְטוּטִין בְּמִצְחֵיהּ, וְעָבְרִין כָּלְהוֹ, וּתְרֵין זְעִירִין מֵעֵינֵיהּ וְעַד שַׂעֲרֵיהּ. תְּרֵין רְשִׁימִין, וּתְלַת זְעִירִין בֵּין קְרִיצֵי עֵינוֹי.</p>"],[9514012580,"<p>הַאי אִיהוּ בַּר נָשׁ, דְּאָזַל כָּפִיף רֵישָׁא. זִינָא חַד, מִתְּלַת מָארֵי רְשׁוּמִין דְּתוֹלְדוֹת מָארֵי צָרַעַת, אִית בֵּיהּ בְּזִינֵיהּ. הַאי לָאו מְסָאֲבָא הֲוָה לְמִסְגַּר. חָדֵי אִיהוּ בְּכֹלָּא, וְחַיֵּיךְ תָּדִיר, כָּל מִלּוֹי חָיְיכִין בְּהוּ בְּנֵי נָשָׁא. קַמְצָן אִיהוּ בְּבֵיתֵיהּ, בְּאָחֳרָנִין לָאו הָכֵי. לֵית לֵיהּ כִּסּוּפָא בְּמִלּוֹי, בְּגִין דְּחָמֵי דְּכֹלָּא חָיְיכִין בֵּיהּ. גַּיְיפָא אִיהוּ, שַׂעֲרוֹי סוּמְקִין זְעֵיר, לָא שְׁעִיעִין וְלָא קְמִיטִין.</p>"],[9514012581,"<p>וְאִי בְּמִצְחוֹי תְּלַת שִׁרְטוּטִין דְּעָבְרִין, וּתְלַת זְעִירִין דְּלָא עָבְרִין, וְכָל שְׁאָר סִימָנִין בֵּיהּ. הַאי אִית לֵיהּ פְּגִימוּ, וְרוֹשֶׁם חַד בְּעֵינָא. דְּבַּר נָשׁ דְּהֲוָה צָד צִפֳּרִין עָבַד לֵיהּ, בְּלָא כַּוָּונָה, בְּאָעָא דְּהֲוָה אוֹשִׁיט לַצִּפֳּרִין. וְאִיהוּ אִתְרְשֵׁים עַל עֵינֵיהּ שְׂמָאלָא, לְעֵילָא מִקַּרְצוֹי בְּאוֹרְכָּא.</p>"],[9514012582,"<p>הַהוּא דְּהֲוָה צָד צִפֳּרִין, אַגְזִים לֵיהּ בְּהַהוּא אָעָא, בְּגִין דְּהֲוָה אַפְרַח צִפֳּרִים, וּמָחָא לֵיהּ בְּלָא כַוָּונָה. הַאי אַצְלַח לִמְזוֹנֵיהּ וּלְבֵיתֵיהּ, וְלָא לְמִכְנַשׁ מָמוֹנָא סַגֵּי. מְהֵימְנָא אִיהוּ, וְלָא כָּל כַּךְ. וְהַאי מְהֵימְנוּתָא בְּמִלִּין זְעִירִין, אֲבָל בְּרַבְרְבִין לָאו אִיהוּ מְהֵימְנָא. מָארֵי דְלִישְׁנָא בִּישָׁא. וְכֹלָּא חָיְיכִין בְּמִלּוֹי.</p>"],[9514012583,"<p>פּוּמֵיהּ רַב, שִׂפְוָותֵיהּ רַבְרְבִין. מַאן דְּאִשְׁתַּתַּף בַּהֲדֵיהּ, אַצְלַח בְּכוֹלָּא. וְאִיהוּ אַצְלַח אוּף הָכֵי. טַב אִיהוּ לְכָל שִׁתּוּפָא.</p>"],[9514012584,"<p>רְשִׁימָא דְּהַהוּא מַכְתְּשָׁא עִמֵּיהּ, עֵינוֹהִי זְבָלְגִין, יָרוֹקִין, וְחַד רְשִׁימוּ אוּכָם סַחֲרָא לוֹן. הַאי אִיהוּ בְּאָת פ\"א בִּשְׁלִימוּ דִּתְרֵין אַתְוָון, וְאָת ר' בִּלְחוֹדוֹי.</p>"],[9514012585,"<p>דָּא רֵישֵׁיהּ רַב, וְד' שִׁרְטוּטִין רַבְרְבִין בְּמִצְחֵיהּ. וּתְלַת זְעִירִין בֵּין קְרִיצוֹי. וְחַד לְעֵילָא קְרִיעָא זְעֵיר. עַל חוֹטְמֵיהּ שַׂעֲרוֹי רַבְרְבִין. רֵישֵׁיהּ עָגֵיל. הוּא גִּיבַּר חֵילָא, מָארֵי זְדוֹנָא בְּמִלִּין.</p>"],[9514012586,"<p>שַׂעֲרֵיהּ קָמִיט, גַּיְיפָא אִיהוּ. וּבְלֵילְיָא אִשְׁתַּתַּף אִיהוּ לְגִיּוּפָא. לְזִמְנִין אִתְכְּשַׁל אִיהוּ בְּאִינְתּוּ אֲסוּרָה. דִּיקְנֵיהּ מַלְיָא בְּשַׂעֲרִין, הַאי אִית לֵיהּ בִּדְרוֹעָא שְׂמָאלָא חַד רְשִׁימוּ דְּחַרְבָּא, דְּמָחָא לֵיהּ חַד גְּבַר, אִטַר יָמִינָא, בְּיוֹמָא רְבִיעָאָה דְשַׁבַּתָּא, כַּד בָּעָא שִׁמְשָׁא לְאִתְכַּנְּשָׁא. דְּהָא בְּהַהוּא יוֹמָא אִיתְעַר עֲלֵיהּ חַד חוּטָא דְּמַאְדִּים. הַהוּא חוּטָא דְּבִסְטַר שְׂמָאלָא, וְהַהוּא רְשִׁימוּ עֲקִימָא בְּבִשְׂרֵיהּ בְּעִיגּוּלָא.</p>"],[9514012587,"<p>כַד מָטָא לְיוֹמִין דְּסִיבוּ, נָפַל מֵאֲתַר דְּרָכִיב בֵּיהּ, אוֹ סוּסְיָיא, אוֹ חַמְרָא, אוֹ נָפִיל מִן כּוֹתְלָא, וּמִנֵּיהּ יִתְחַלַּשׁ וִימוּת. דְּהָא חוֹבָא דְּחָב בְּעוּלֵימוֹי בַּהֶבֶל רָדִיף אֲבַתְרֵיהּ. וְאִי הַהוּא גַבְרָא תָּב בִּתְיוּבְתָּא בְּאֶמְצַע יוֹמוֹי, נָפִיל מִגּוֹ חוּלְשָׁא דְּבֵיהּ, וִימוּת.</p>"],[9514012588,"<p>וְאִי תָּב בְּעוּלֵימוֹי, כְּדֵין תִּשְׁכַּח שִׁרְטוּטִין דְּמִצְחֵיהּ, תְּלַת רַבְרְבִין וְאַרְבָּעָה זְעִירִין. וּתְרֵין תְּרֵין מִגּוֹ עֵינוֹי דְּסָלְקִין לְעֵילָא. הַאי בְּאוֹרַח כָּל אַרְעָא יְהֵא מַרְעֵיהּ. וְיִפּוֹל מֵעַרְסֵיהּ, וִימוּת. דְּהָא לְעָלְמִין אִית בֵּיהּ נְפִילָה לְבַסּוֹף.</p>"],[9514012589,"<p>עַיְינִין זְעִירִין דַּקִּיקִין, דְּלָא אִתְחַזְיָין גְּוָונִין דִּילְהוֹן לְפוּם שַׁעֲתָא, וְכַד מִסְתַּכְּלִין בְּהוֹן, אִינוּן יָרוֹקִין וְאוּכְמִין. הַאי אִיהוּ שִׂפְוָון חַדִּין, וְאַפִּין אֲרִיכִין בַּחֲדִידוּ, כְּדֵין תִּשְׁכַּח בְּמִצְחֵיהּ תְּרֵין שִׁרְטוּטִין, וְחַד זְעֵירָא בֵּינַיְיהוּ, הַאי אִיהוּ בְּאָת פ' בִּלְחוֹדוֹי, וּבְאָת ר' בִּלְחוֹדוֹי.</p>"],[9514012590,"<p>הַאי אִיהוּ, שַׂעֲרֵיהּ תַּלְיָא, וְלָא שְׁעִיעַ. אַצְלַח בְּעוֹבָדֵי יְדוֹי, וּבְאוֹרַיְיתָא אִי אִשְׁתַּדַּל. אוּף הָכֵי זְעִירָא אִיהוּ בְּשַׁיְיפוֹי, וְגַס בִּשְׂרָא לֵית בֵּיהּ. רוּחָא, מְמַלֵּל מִגּוֹ חוֹטְמוֹי, בְּגִין דִּנְקָבִין דִּלְהוֹן דְּחִיקִין, וּבְגִין כָּךְ נָפֵיק רוּחָא בִּדְחִיקוּ לִסְטַר שְׂמָאלָא.</p>"],[9514012591,"<p>בְּיַרְכָא דִילֵיהּ לְעֵילָא מֵאַרְכּוּבָא, רְשִׁימָא חַד חַבּוּרָה, דְּעָבַד לֵיהּ רַבְיָיא חַד בְּסַכִּין, בְּיוֹמֵי עוּלֵימוֹי, וְאִסְתַּכֵּן בֵּיהּ. מְקַנֵּא הוּא לְאִתְּתֵיהּ, עַד דְּבַּר נָשׁ חָיְיכִין מִנֵּיהּ. בָּעֵי לְאִתְתַּקְּנָא בְּגוּבְרִין אָחֳרָנִין, וְלָא אִתְתַּקַּן, וְחָיְיכִין בֵּיהּ. הַאי לָא יִשְׁתַּתֵּף בַּר נָשׁ בַּהֲדֵיהּ, דְּלָא יִצְלַח. חַמְדָן אִיהוּ, אִשְׁתַּדַּל בַּמֶּה דְּלָא אִית לֵיהּ, חָשִׁיב גַּרְמֵיהּ דְּאִיהוּ גַּבְרָא רַבָּא, וְלָאו הָכֵי. זָכֵי לְבָנוֹת, וְלָא לְבָנִים.</p>"],[9514012592,"<p>וְאִי מִתְחַלְּפָן שִׁרְטוּטִין, תְּרֵין זְעִירִין וְחַד רַבְרְבָא בְּמִצְחֵיהּ, וְאַנְפּוֹי סוּמְקִין. זָכֵי לִבְנִין, וְלִבְרַתָּא חָדָא, אוֹ דִּיְלֵדַת בַּר וְאִסְתַּלְּקַת מֵעָלְמָא.</p>"],[9514012593,"<p>אָת חַד אִית לֵיהּ בָּתַר אוּדְנֵיהּ יָמִינָא, רוֹשֶׁם דְּטוּלְפְּחָא, וְחַד שַׂעֲרָא דְּתָלֵי בְּרֵישׁ אוּדְנֵיהּ. וְאֶצְבְּעָא זְעִירָא דִּי בִּידָא שְׂמָאלָא כָּפֵיף כְּדֵין תִּתְקַיֵּים וְתוֹלִיד בְּנִין וּבְנָן. אִי סִימָנִין אִלֵּין תֶּהֱוְיָן לָהּ. בֵּין רַגְלָהָא יִכְרַע וְיִפּוֹל חַד בְּרָא, בֵּין אִינוּן דִּיהֵא מַבּוּעָא דִּנְבִיעַ בְּאוֹרַיְיתָא. הוּא מְקָרֵב וּמַפִּיק מַבּוּעִין וְנַחֲלִין דְּאוֹרַיְיתָא, וּבִשְׁנִין זְעִירִין יִתְכְּנֵשׁ מֵעָלְמָא.</p>"],[9514012594,"<p>הַאי אִיהוּ מֵאִינוּן אֶלֶף, דְּמִתְכַּנְשִׁין מֵעָלְמָא מֵרֵישׁ שַׁתָּא וְעַד רֵישׁ שַׁתָּא. בְּיוֹמִין קַדְמָאִין. מִדְּאִתְחְרַב בֵּי מַקְדְּשָׁא, לָא אַשְׁכַּח בַּר שִׁתִּין חָסֵר חַד, וְאִלֵּין אִינוּן דְּמִסְתַּלְּקֵי מֵעָלְמָא, כַּד יַהֲבֵי רֵיחָא, עַד לָא מָטָא זִמְנַיְיהוּ.</p>"],[9514012595,"<p>בְּגִין דְּכַד קוּדְשָׁא בְּרִיךְ הוּא עָאל לְאוֹלִיף אוֹרַיְיתָא, לְאִינוּן יְנוּקִין דְּאִסְתַּלְּקוּ מֵעָלְמָא, כַּד יַהֲבוּ רֵיחָא, עַד לָא מָטָא זִמְנַיְיהוּ, אִינוּן קַדְמָאֵי בְּאִינוּן מִלִּין. וְקוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ לְהַהוּא מְמָנָא יופיאָמַר לֵיהּ שְׁמֵיהּ, דְּקָאִים וְקָשִׁיר קִשְׁרִין דְּאוֹרַיְיתָא, מַאן הוּא דֵּין דְּאַקְדִים לִי, הֲדָא הוּא דִכְתִיב, (איוב מ״א:ג׳) מִי הִקְדִּימַנִי וַאֲשַׁלֵּם, וַאֲשַׁלֵּם וַדַּאי.</p>"],[9514012596,"<p>כְדֵין קָרָא קוּדְשָׁא בְּרִיךְ הוּא לְמטטרו\"ן, דְּאִיהוּ קָיְימָא גוֹ פְּרוֹכְתָּא דְּפָרְסָא, וְשִׁשִּׁים אֶלֶף רִבּוֹא מָארֵי דְאוּלְפְנָא דְאוֹרַיְיתָא סוֹחֲרָנֵיהּ, וְאִיהוּ מְקַשֵּׁר קְשָׁרִים לְמָארֵיהּ. אָמַר לֵיהּ מַאן הַאי דְּאַקְדִּים לִי, מִי הִקְדִּימַנִי וַאֲשַׁלֵּם. אִיהוּ רְשִׁים גּוֹ מְתִיבְתָּךְ. אוֹ לֹא. אָמַר לֵיהּ מָארֵי דְעָלְמָא, לָאו אִיהוּ בִּמְתִיבְתָּא דִילִי, גּוֹ מְתִיבְתָּךְ אִיהוּ. וְכָל אִינוּן דְּקָדָמָי, תְּחוֹת כָּל שְׁמַיָא הוּא, הֲדָא הוּא דִכְתִיב, (שם) תַּחַת כָּל הַשָּׁמַיִם לִי הוּא.</p>"],[9514012597,"<p>בְּגִין דִּתְרֵין מְתִיבְתִּין אִית לְעֵילָא. מְתִיבְתָּא דְּהַהוּא נַעַר מטטרו\"ן. וּמְתִיבְתָּא עִילָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא. וּבְכָל אֲתַר דְּתָנִינָן מְתִיבְתָּא עִילָּאָה, דָּא הוּא דְקוּדְשָׁא בְּרִיךְ הוּא. מְתִיבְתָּא דִּרְקִיעַ, דָּא דְּמטטרו\"ן.</p>"],[9514012598,"<p>כְדֵין אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, אִי הָכֵי, לְקוֹט לֵיהּ גַּבָּאי. לָקִיט לֵיהּ, וְאָרַח לֵיהּ, הֲדָא הוּא דִכְתִיב, (שיר השירים ו׳:ב׳) דּוֹדִי יָרַד לְגַנּוֹ לַעֲרוּגַת הַבֹּשֶׂם. דּוֹדִי, דָּא קוּדְשָׁא בְּרִיךְ הוּא, כְּמָה דְאַתְּ אָמֵר (שם ב) דּוֹדִי לִי וַאֲנִי לוֹ הָרוֹעֶה בַּשּׁוֹשַׁנִּים. יָרַד לְגַנּוֹ, דָּא גּוֹרֶן דְּרָקִיעַ, דְּקָיְימֵי כְּגוֹרֶן. לַעֲרוּגַת הַבּוֹשֶׂם, דָּא מְתִיבְתָּא דְּמטטרו\"ן. לִרְעוֹת בַּגַּנִּים וְלִלְקֹט שׁוֹשַׁנִּים, לְעַיְינָא וּלְאִסְתַּכָּלָא בְּאִינוּן מְתִיבְתָּאן דִּילֵיהּ. מַאי וְלִלְקֹט שׁוֹשַׁנִּים, אַל תִּקְרֵי שׁוֹשַׁנִּים אֶלָּא שֶׁשּׁוֹנִים. אִלֵּין אִינוּן דִּמְקַדְּמֵי רֵיחָא בְּהַאי עָלְמָא, דְּמִתְלַקְּטֵי וּמִסְתַּלְּקֵי מֵהַאי עָלְמָא, עַד דְּלָא מָטָא זִמְנַיְיהוּ.</p>"],[9514012599,"<p>כְדֵין קָארֵי הַהוּא נַעַר מטטרו\"ן לְגַבְרִיאֵל, דִּי קֶסֶת הַסּוֹפֵר בְּחַרְצוֹי, וַאֲמַר לֵיהּ, כְּתוֹב פִּתְקָא וְהַב לְמַלְאַךְ הַמָּוֶת עַל פְּלוֹנִי, דְּיִלְקוֹט לֵיהּ מֵעָלְמָא. וְאִתְלְקֵיט מִיָּד. וְסָלְקִין לֵיהּ בְּקַדְמִיתָא לִמְתִיבְתָּא דְּמטטרו\"ן, וְתַמָּן אֲמַר תַּלְמוּדֵיהּ דְּאַיְיתֵי בִּידֵיהּ. וְאוֹלִיף תַּמָּן מַה דְּאוֹלִיף. לְבָתַר סָלְקִין לֵיהּ לִמְתִיבְתָּא עִילָּאָה דְּקוּדְשָׁא בְּרִיךְ הוּא. וּזְמִינָא לִמְתִיבְתָּא דִילֵיהּ. וְתַמָּן אִשְׁתַּעֲשַׁע בְּהוּ, בְּאִינוּן דִּילֵיהּ, וּבְרָזִין עִילָּאִין, וְטַעֲמֵי דְאוֹרַיְיתָא, דַּהֲווֹ סְתִימִין מִנֵּיהּ בְּהַאי עָלְמָא.</p>"],[9514012600,"<p>וְיופיאָמַר לֵיהּ רַב מְמַנָּא, אָזִיל מִגּוֹ מְתִיבְתָּא עִילָּאָה, וְחָתִים סִתְרִין וְרָזִין דְּאוֹרַיְיתָא, מִגּוֹ תְּרֵין מְתִיבְתִּין. כָּל מַה דְּאַקְשׁוּ בִּמְתִיבְתָּא דִּרְקִיעָא, אִינוּן דִּמְתִיבְתָּא עִילָּאָה מְתַרְצִין. בִּמְתִיבְתָּא עִילָּאָה, לֵית תַּמָּן פִּרְכֵי וְקוּשְׁיָין, אֶלָּא בִּמְתִיבְתָּא דִּרְקִיעָא. וְחָתִים מִתְּרֵי מְתִיבְתֵּי מִלִּין דְּאוֹרַיְיתָא כִּדְקָא יָאוֹת. וְעַל דָּא כְּתִיב, (תהילים פ״ד:ח׳) יֵלְכוּ מֵחַיִל אֶל חָיִל.</p>"],[9514012601,"<p>וּלְזִמְנָא דְאָתֵי יִסְתַּלְּקוּן פִּרְכֵי וְקוּשְׁיָין מִגּוֹ מְתִיבְתָּא דִּרְקִיעָא. כְּמָא דְּאַתְּ אָמֵר, יֵלְכוּ מֵחַיִל אֶל חָיִל, וּכְתִיב (שם קכב) יְהִי שָׁלוֹם בְּחֵילֵךְ שַׁלְוָה בְּאַרְמְנוֹתָיִךְ. עַד הָכָא רָזִין דְּעַיְינִין, בְּגוֹ גְּוָונִין לְאִסְתַּכָּלָא.</p>"],[9514012602,"<p>דְּיוֹקְנִין דְּחוֹטְמָא, חוֹטְמָא אִיהוּ חוֹתָמָא וּפַרְצוּפָא דְּבַּר נָשׁ לְאִשְׁתְּמוֹדְעָא. חוֹטְמָא זְעֵירָא עֲקִימָא, דְּלָא אִתְיַישְׁבַת כָּרָאוּי בְּאוֹרַח מֵישָׁר, דָּא אִיהוּ דְּאָבֵיד פַּרְצוּפָא דְּבַּר נָשׁ, וְדָא אִיהוּ בְּאָת ה' בִּלְחוֹדוֹי, בְּלָא שְׁלִימוּ. דָּא אִיהוּ דְּאוֹרַח עִנְוְתָנוּתָא וּשְׁלֵימָתָא אִתְעֲבַר מִינֵּיהּ, חֲצִיפָא אִיהוּ. שַׂעֲרֵיהּ בֵּין סוּמָק לְחִיוָּר.</p>"],[9514012603,"<p>תְּלַת רְשִׁימִין רַבְרְבִין עַל מִצְחֵיהּ, וּתְלַת אָחֳרָנִין דְּלָא אִתְחַזְיָין כָּל כַּךְ. תְּלַת שִׁרְטוּטִין אָחֳרָנִין מִסִּטְרָא דָּא לְסִטְרָא דָא, שִׂפְוָון דִּילֵיהּ רַבְרְבָן. בַּחֲצִיפוּתֵיהּ מְמַלֵּל בְּקַשְׁיוּ כָּל מַה דְּבָעֵי. דְּאוֹרַח עִנְוְתָנוּתָא אִתְעֲבַר מֵחוֹטְמֵיהּ, וּמֵעַל אַנְפּוֹי, דְּהָא כִּיסּוּפָא וְעִנְוְתָנוּתָא מְיַישֵׁר חוֹטְמָא עַל אַנְפִּין. וְהַאי לֵית בֵּיהּ כְּלַל. וּבְגִין דְּאִיהוּ חֲצִיפָא, כָּדִיב וְחַיֵּיךְ בְּמִלּוֹי.</p>"],[9514012604,"<p>וְאִי מִתְעַבְרִין שִׁרְטוּטִין מֵעַל מִצְחֵיהּ, וְאִינוּן ג' רַבְרְבָן וְג' זְעִירִין, וְשַׂעֲרֵיהּ אוּכָם, הָא אִיהוּ בֵּין תְּרֵין אַתְוָון בְּמַתְקְלָא. דָּא נָמִיךְ רֵישָׁא, וְחַיִּיךְ בְּמִלּוֹי. שַׂעֲרֵיהּ שְׁעִיעַ וְלָא כָּל כַּךְ, צַעֲרִין רַבְרְבִין מִתְעָרִין עֲלוֹי, וְאִשְׁתְּזֵיב מִכָּלְהוֹ.</p>"],[9514012605,"<p>דָּא, זְכוּ זְעֵירָא מֵאֲבוֹי מֵגִין עֲלֵיהּ. וְהַהוּא זְכוּ אִתְרְשִׁים גּוֹ עַמּוּדָא דְּקָאִים בֵּיהּ הַהוּא נַעַר. וְאִיהוּ זָכֵי בְּחַד יַתְמָא. בְּגִין דְּכָל יְתָם וְאַרְמַלְתָּא, קָיְימִין בְּפִקְדוֹנֵיהּ דְּמטטרו\"ן, דְּקָיְימָא לְדַיְינָא בְּאִינוּן שִׁבְעִין סַנְהֶדְּרִין.</p>"],[9514012606,"<p>בְּהֵיכָלָא דִזְכוּתָא, דָּיְינִין כָּל דִּינִין דְּעָלְמָא, בַּר מִתְּלַת, בָּנֵי חַיֵּי וּמְזוֹנֵי. וְכָלְהוֹ בִּקְרָאֵי כְּתִיבֵי. בָּנֵי, דִּכְתִיב (שמואל א א) וַתִּתְפַּלֵּל עַל ה', עַל דַּיְיקָא, לְעֵילָא לְעֵילָא. אַתְרָא דְּמַזָּלָא עִילָּאָה. חַיֵּי, דִּכְתִיב (ישעיהו ל״ח:ה׳) הִנְנִי יוֹסִיף עַל יָמֶיךָ חֲמֵשׁ עֶשְׂרֵה שָׁנָה, יוֹסִיף דַּיְיקָא. מְזוֹנֵי, דִּכְתִיב (תהילים נ״ה:כ״ג) הַשְׁלֵךְ עַל ה' יְהָבְךָ וְהוּא יְכַלְכְּלֶךָ, עַל דַּיְיקָא. וְתַמָּן דָּיְינִין בְּנֵי עָלְמָא.</p>"],[9514012607,"<p>וְיָהֲבִין פִּתְקָא לְמַלְאָךְ הַמָּוֶת לְקָטְלָא לוֹן, וּלְנַטְלָא רוּחֵיהוֹן, וְהוֹאִיל וּמַשְׁכּוֹנִין עִילָּאִין, וְטָבִין דִּבְנֵי נָשָׁא בִּידוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, פַּקֵּיד לְמטטרו\"ן, דִּיהוֹן בְּנוֹי דְּהַהוּא בַּר נָשׁ וְאִתְּתֵיהּ בְּפִקְדוֹנָא דִּילֵיהּ. וּבְגִין דְּאָסוּר לְמַשְׁכְּנָא לוֹן, מַשְׁכּוֹנִין עַל מַשְׁכּוֹנִין, לָא יְמִיתוּן.</p>"],[9514012608,"<p>וְעַל דָּא, מַאן יְשֵׁיזֵיב לוֹן מֵעִינּוּיָא, הַהוּא זְכוּ אַגֵּין עַל בְּנוֹי. וְהוּא, חַד מִנַּיְיהוּ דְּהַהוּא זְכוּ אַגֵּין עֲלֵיהּ, בְּעִידָן עַקְתֵיהּ.</p>"],[9514012609,"<p>לְהָא אִית לֵיהּ רוֹשֶׁם בְּמִצְחֵיהּ. חַיָיבָא, אוֹ גַּיָּיפָא אִיהוּ. וְלָא אִתְחֲזֵי קַמֵּי בְּנֵי נָשָׁא, דְּלָא יָדְעִין בֵּיהּ. דָּא אַצְלַח. וּמַאן דְּאִתְחַבַּר בַּהֲדֵיהּ, יַצְלַח יַתִּיר מִנֵּיהּ.</p>"],[9514012610,"<p>חוּטְמָא עֲקִימָא, וּתְרֵין נוּקְבִין דִּילֵיהּ רַבְרְבִין, וְסָלְקִין לְבַר אִינוּן פָּתְחִין דִּנְחִירוֹי, וְחוֹטְמָא לָא סָלֵיק. דָּא אִיהוּ בְּאָת ה' בִּשְׁלִימוּ.</p>"],[9514012611,"<p>ה' שִׁרְטוּטִין בְּמִצְחֵיהּ רַבְרְבָן, וְשִׁית זְעִירִין. אוּדְנוֹי רַבְרְבָן. עֵינוֹי רַבְרְבָן. וּתְרֵין רְשִׁימִין אוּכְמִין דַּקִּיקִין בְּעֵינֵיהּ דְּיָמִינָא. שַׂעֲרֵיהּ, לָא אִתְתַּקַּן בְּמַזְיֵיהּ, בְּגִין דְּאִיהוּ רַב וְתַקִּיף. רוֹשֶׁם מַכְתְּשָׁא בְּמִצְחֵיהּ.</p>"],[9514012612,"<p>דָּא שַׂרְפָא, בְּכָל יוֹמָא זַמִּין כַּד אִתְרְעֵם. בְּרוּגְזֵיהּ, קָרִיר חוּטְמֵיהּ, וְאִתְחֲזֵי חִוָּור. תָּב מֵרוּגְזֵיהּ לִזְמַן רַב. מְהֵימְנָא אִיהוּ בְּמִלִּין רַבְרְבִין. וּבִזְעִירִין לָאו הָכֵי. חַמְדָן אִיהוּ. גּוּפֵיהּ מָלֵי מַכְתְּשִׁין וַאֲבַעְבּוּעִין בְּכָל יוֹמֵי שַׁתָּא, וּבַר זִמְנָא חַד זְעֵיר בְּיוֹמֵי דְּסִתְוָוא, אִתְנַהֵיג בְּעִנְוְתָנוּתָא בְּבֵיתֵיהּ. תִּיאוּבְתֵּיא לְמֵיכַל בְּכָל אֲתַר, אַף עַל גַּב דְּלָא יְזַמְּנוּן לֵיהּ. אִי זָכֵי בְּאוֹרַיְיתָא, וְאוֹלִיף יְנוֹקִין, זָכֵי בְּהוּ בְּשי\"ן תי\"ו.</p>"],[9514012613,"<p>בִּיהֵיהּ יָמִינָא, רוֹשֶׁם עֲמִיקָא מִתּוֹלָדָה דְּאִתְיַלֵּד בֵּיהּ. תַּרְתֵּי נָשִׁין אִזְדַּמְּנוּ לֵיהּ, קַדְמַיְיתָא תָּמִית עַל מַשְׁבְּרָא. תִּנְיָינָא תִּזְכֵּי לִתְרֵין בְּנִין, חַד יְמִית זְעֵיר בַּחֲלָבָא דְאִימֵּיהּ, וְחַד יְקוּם בְּעָלְמָא גְּיָיפָא, יַתִּיר מִבְּנֵי נָשָׁא אָחֳרָנִין, וְחַיִּין קָיְימִין בֵּיהּ, אֲבָל לֹא כָּל כָּךְ.</p>"],[9514012614,"<p>חוֹטְמָא דְּאָזֵיל בְּאוֹרַח מֵישָׁר, וּמִתְתַּקְּנָא עַל גַּבֵּי אַנְפִּין. הַאי אִיהוּ בְּאָת ה' בִּשְׁלִימוּ. דָּא אִתְגְּלֵי בְּמִצְחֵיהּ תְּרֵין שִׁרְטוּטִין רַבְרְבִין, וְה' זְעִירִין, וּתְרֵין מִסִּטְרָא דְּיָמִינָא לְגַבֵּי שַׂעֲרֵיהּ. מֵישַׁר מִתַּתָּא לְעֵילָא. שַׂעֲרֵיהּ בֵּין אוּכָם לְסוּמָק, תַּלְיָא עַל אוּדְנוֹי. עֵינוֹי רַבְרְבִין יָרוֹקִין, וְחוּטָא סוּמְקָא סַחֲרָא לְגוֹ. אַנְפּוֹי אֲרִיכִין.</p>"],[9514012615,"<p>דָּא, אִיקְרֵי אַנְפֵּי נֶשֶׁר. דָּא, מִבְּנוֹי דְּסִיהֲרָא בְּאַשְׁלָמוּתָא. כַּד בָּעֵי לְאַזְעָרָא גַרְמֵיהּ, טַב אִיהוּ לְגַבֵּי מָארֵיהּ. דָּחִיל חַטָאָה אִיהוּ. בִּימֵי עוּלֵימוֹי אִיהוּ בְּלָא מַרְעִין, אָזִיל בִּבְרִיאוּתֵיהּ, כְּגִיבָּר בְּלָא דְחִילוּ. בְּיוֹמִין דְּסִיבוּ נָחֵית כִּנְחִיתוּ דְּסִיהֲרָא, חֲלָשָׁא לֶהֱוֵי. מַרְעִין רָדְפִין אֲבַתְרֵיהּ, דָּא זַכָּאָה בְּמַרְעִין יִתְכַּפְּרוּן.</p>"],[9514012616,"<p>וְאִי מִתְחַלְּפִין סִימָנִין, בְּיוֹמֵי עוּלֵימוֹי לֶהֱוֵי בְּמַרְעִין. בְּגִין דְּאִיהוּ כְּסִיהֲרָא דְּבַעְיָא לְאַנְהָרָא. וִיהֵא הַהוּא גַּבְרָא בְּמִסְכְּנוּ. וּבְיוֹמִין דְּסִיבוֹ, יֶהֱוֵי בְּלָא מַרְעִין, וּבְעוֹתְרָא וִיקָר סַגְיָא. דְּהָא כְּדֵין אַנְהֵירַת סִיהֲרָא וְקָיְימָא בְּאַשְׁלָמוּתָא. וְדָא אִיהוּ צַדִּיק וְטוֹב לוֹ. וְדָא עִנְוְתָנוּתָא בֵּיהּ, רְחִים הוּא לְמָארֵיהּ בְּכֹלָּא.</p>"],[9514012617,"<p>חוֹטְמָא אֲרִיכָא וְחַד, חִדּוּדָא כְּרֵישָׁא דְּחוֹטְמָא דְּנִשְׁרָא. הַאי אִיהוּ בְּלָא אָת כְּלָל. שַׂעֲרֵיהּ קָמִיט. שִׁרְטוּטִין דְּמִצְחֵיהּ תְּלַת. אַנְפּוֹי חֲדִידָן. עֵינוֹי זְעִירִין. הָא אִיהוּ חַמְדָן בַּמֶּה דְּאִית לְהוֹ לְאַחֲרָנִין. כָּל עוֹבָדוֹי לָאו בִּדְחִילוּ דִּשְׁמַיָא. סָאנֵי אוֹרַיְיתָא, סָאנֵי לְמַאן דְּלָעָאן בָּהּ. רְחִים לְפוּם שַׁעֲתָא לְמִשְׁמַע מִלִּין דְּאוֹרַיְיתָא, וּלְפוּם שַׁעֲתָא פָּרְחִין מִנֵּיהּ.</p>"],[9514012618,"<p>בְּרַגְלֵיהּ שְׂמָאלָא תְּרֵין אֶצְבְּעָן קְמִיטִין דְּלָא מִתְפַּשְּׁטִין וּבְרַגְלֵיהּ יָמִינָא חַד. הַאי אִיהוּ בְּחַטָאָה דְּגַנָּבָא, וְלָא יְתוּב מֵהַהוּא חוֹבָא לְעָלְמִין.</p>"],[9514012619,"<p>בֵּין כְּתֵפוֹי תַּלְיָין תְּרֵין שַׂעֲרִין רַבְרְבִין. בְּחָדוֹי אִית תְּלַת שַׂעֲרִין דְּתַלְיָין. אוֹמֵי אוֹמָאָה בְּכָל רִגְעָא וְשַׁעֲתָא, וְלָא אִתְהַנֵּי. זִמְנִין תְּרֵין בְּשַׁתָּא יִשְׁתַּתֵּף בַּר נָשׁ בַּהֲדֵיהּ. וְלָא יַתִּיר, וְיַצְלַח, וְהוּא מֵאֲדָר עַד רֵישׁ נִיסָן. וּמֵאֱלוּל, עַד שִׁית יוֹמִין דְּמַרְחֶשְׁוָון, וְלָא יַתִּיר, וּבְיוֹמִין אִלֵּין, יִצְלַח מַאן דְּיִשְׁתַּתֵּף בַּהֲדֵיהּ, דְּהָא יוֹמִין אִלֵּין יוֹמִין דְּאַתְוָון אִינוּן, וּמַאן דְּלֵית לֵיהּ אַתְוָון, אִתְאֲחַד בְּהוּ.</p>"],[9514012620,"<p>בְּיוֹמִין אִלֵּין נָפְקִין נִשְׁמָתִין עַרְטִלָאִין, וְאִינוּן מִתְהַדְּרָן כְּמִלְּקַדְמִין, וְלֵית לוֹן זִוּוּגִין. וּבְיוֹמִין אִלֵּין נָפְקִין אַתְוָון כ\"ב וְשָׁרָאן בְּהוּ, וּמִתְעַטְרָן בְּהוּ, וּבְרַחֲמֵי יִשְׁתַּכְּחוּן זִוּוּגִין. וּבְיַרְחִין אָחֳרָנִין, וּבְיוֹמִין אָחֳרָנִין, לָאו.</p>"],[9514012621,"<p>דְּהָא מִז' בַּאֲדַר בָּטַשׁ בּוּצִינָא, וְאַפֵּיק אַתְוָון זְעִירִין, וּבָקְעִין רְקִיעִין וְנָפְקִין לְעָלְמָא. בְּזִמְנָא דְּאִינוּן נָפְקִין, כָּל אִינוּן נִשְׁמָתִין עַרְטְלָאִין, דַּהֲווֹ זְמִינִין לְאִתְהַדְּרָא, נָפְקִין בַּהֲדַיְיהוּ, וְאִתְאַחֲדָן בְּאִינוּן אַתְוָון.</p>"],[9514012622,"<p>וְנָפְקִין עַל יְדֵי דְּפַרְוַונְקָא. בְּגִין דְּכָל בְּנֵי עָלְמָא, כַּד אִתְבְּנִין לְאִתְצַיְירָא בְּהַאי עָלְמָא, כָּל צִיּוּרִין דְּאַתְוָון מִתְצַיְירִין בְּהוּ, עַל יְדָא דְּאִינוּן תְּלַת שׁוּתָּפִין, דְּקָא מִזְדַּוַּוג בִּנְיָינָא. וְהַשְׁתָּא אִלֵּין דְּקָא מִתְהַדְּרָן, כָּל אִינוּן אַתְוָון קָא אִתְצַיְירוּ בְּהוּ. אָחֳרָנִין לָא מִתְצַיְירֵי בְּהוּ. דְּהָא אִינוּן פַּרְוַונְקִין, לָא מְצַיְירִין לוֹן בְּאַתְוָון, כְּמָה דְּאִתְצַיְירוּ בְּקַדְמִיתָא, מִסִּטְרָא דְּאַבָּא וְאִימָּא.</p>"],[9514012623,"<p>וְאִלֵּין אַתְוָון אָזְלִין וּמְשָׁטְטִין בְּעָלְמָא, וְאִתְאַחֲדָאן בְּהוּ כָּל אִינוּן דְּלֵית לְהוֹ אַתְוָון, עַד רֵישׁ יַרְחָא דְסִיוָן. דְּהָא כְּדֵין אִתְטַמְּרָן אִלֵּין, וְאַתְוָון עִילָּאִין בָּעְיָין לְאִתְגַּלָּאָה.</p>"],[9514012624,"<p>וּמֵאֱלוּל אִתְטַמְּרוּ אִלֵּין עִילָּאִין. עַד ו' יוֹמִין בְּמַרְחֶשְׁוָון. עַד דִּיהַדְּרוּן בְּנֵי נָשָׁא מֵחוֹבַיְיהוּ, וְיִתְכַּפֶּר לוֹן, וּמִתְהַדְּרָן אַתְוָון כְּמִלְּקַדְּמִין. וּבֵין כָּךְ וּבֵין כָּךְ, אִינּוּן זְעִירִין נָפְקָן לְקָיְימָא עָלְמָא, וְאִלֵּין אִתְאַחֲדִין בְּהוּ, בְּגִין דְּלֵית לוֹן אַתְוָון כְּלָל.</p>"],[9514012625,"<p>דְּהָא מֵאֱלוּל קָיְימָא תְּשׁוּבָה, וְאַתְוָון סָלְקִין לְגַבָּהּ, וּבְנֵי עָלְמָא מִתְהַדְּרָן מֵחוֹבַיְיהוּ, וּמִתְהַדְּרָן לְאַתְוָון, וְקָיְימִין עַל עָלְמָא תְּרֵין יְרָחִין, וּמִסְתַּלְּקִין טֵבֵת וּשְׁבָט.</p>"],[9514012626,"<p>מֵז' בַּאֲדָר נָפְקִין אִלֵּין אָחֳרָנִין, כְּמָא דְּאִתְּמָר. וְאִלֵּין דְּמִתְאַחֲדָן בְּהוּ, מְקַדְּמֵי רַחֲמֵי בְּאִלֵּין יוֹמִין. וּתְרֵין יְרָחִין אָחֳרָנִין אִתְטַמְּרָן כָּלְהוֹ, וְאִלֵּין תַּמּוּז וְאָב. וְנָפְקִין יְמֵי הָרָעָה בְּאַתְוָותַיְיהוּ וְשָׁלְטִין אִלֵּין עַל עָלְמָא, וְאָחֳרָנִין אִתְטַמָּרוּ. וּבְגִין כָּךְ, בְּאִינוּן יוֹמִין, זַכָּאָה אִיהוּ מַאן דְּאִשְׁתְּזֵיב מִנַּיְיהוּ.</p>"],[9514012627,"<p>וְכַד חוֹטְמָא אֲרִיכָא, רַב בְּפוּתְיָיא לְגַבֵּי רֵישָׁא. דָּא אִיהוּ בְּאָת ה', וּלְזִמְנִין אָת י' אִתְחַבַּר בַּהֲדֵיהּ. דָּא אִיהוּ בַּר נַשׁ דְּאַצְלַח.</p>"],[9514012628,"<p>אַנְפּוֹי קְמִיטִין, בְּתוֹלְדוֹת דַּאֲבַעְבּוּעִין. עֵינוֹי סוּמְקִין. דָּא אִיהוּ בֵּין אִינוּן תּוֹלָדִין דִּסְגִירוּ. דְּעֵינוֹי לְזִמְנִין זָלְגִין דִּמְעִין.</p>"],[9514012629,"<p>קְמִיטִין דְּמִצְחֵיהּ ד' וּב' עֲבָרִין רְשִׁימִין, כְּאָרִיחַ עַל גַּבֵּי לְבֵנָה. שַׂעֲרֵיהּ רַב. הַאי אַצְלַח, וּדְחִיל חַטָאָה, שֶׁבַח גַּרְמֵיהּ בְּכֹלָּא, יַתִּיר מִמַּה דְּאִית בֵּיהּ. וּבְזִמְנָא דְּאִתְנַעֲנַע, עֵינוֹי זָלְגִין דִּמְעִין. וּכְאֵבָא בְּחוּטְמֵיהּ, עַד דְאוֹשִׁיד לֵיחָה יָרוֹקָה. וְדָא קַשְׁיָא מֵאִינוּן זִינֵי דִסְגִּירוּ. מַאן דְּאִשְׁתַּתַּף בַּהֲדֵיהּ אַצְלַח. מְהֵימְנָא אִיהוּ בְּכֹלָּא.</p>"],[9514012630,"<p>עַל כִּתְפֵיהּ שְׂמָאלָא, אִית תְּלַת רְשִׁימִין. ב' סוּמְקִין, וְחַד אוּכָם. בְּרַם אוּכָם אִית לֵיהּ תּוֹעַלְתָּא. הַאי מָשִׁיךְ לְאִתְקְרָבָא בִּבְנֵי נָשָׁא, וְאָחִיד בְּהוּ, דְּלָא יַחְשְׁבוּן לֵיהּ כִּסְגִירָא.</p>"],[9514012631,"<p>מוּמָא אִתְיְילֵיד בֵּיהּ בְּלֵילָא, בְּחַד יוֹמָא דְסִתְוָוא, בְּיוֹמֵי דְּעוּלֵימוֹי, דְּאָכַל נוּנָא וְשָׁתָה מַיָא, וּנְפַק לְבַר. וּבְהַהוּא שַׁעֲתָא הֲוָה שַׁלִּיט כּוֹכָב שַׁבְּתָאי בְּעָלְמָא, וְחַד עֲנָפָא דִילֵיהּ הֲוָה מָשִׁיךְ לְאִתְפַּשְּׁטָא לְתַתָּא, וּנְפַק אִיהוּ בְּגִילוּיָיא דְּרֵישָׁא, וּמְחָה בֵיהּ עַל יְדָא דְּקורקפנ\"י וְשׁמרירו\"ן תְּרֵין רוּחִין דְּשָׁלְטִין בְּהַהוּא עֲנָפָא. וְכָךְ אִתְמְחֵי הַאי בַּר נָשׁ, רָשְׁמוּ בֵיהּ תְּרֵין רְשִׁימִין סוּמְקִין. וְהַהוּא עֲנָפָא רְשִׁים בֵּיהּ הַהוּא רְשִׁימוּ אוּכְמָא. דְּהָא מִילּוֹי דְּשַׁבְּתָאי בְּאוּכָם אִשְׁתַּמַּשׁ.</p>"],[9514012632,"<p>וְרָזָא דָּא שַׁלִּיט בְּעַמָּא דְּשַׁבְּתָאי וְלָא בְּעַמָּא קַדִּישָׁא. בְּגִין דְּעַמָּא קַדִּישָׁא לֵית לוֹן חוּלָקָא וְאַחְסַנְתָּא בְּכוֹכָבַיְיא וּמַזָּלֵי, אֶלָּא בְּקוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי. וְאִצְטְרִיךְ לוֹן לְאַחֲזָאָה חֶדְוָה, וּמֵיכְלָא וּמִשְׁתְּיָיא, וּלְבוּשִׁין חִיוָּרִין, אוֹ דִּגְוָונִין שַׁפִּירִין, וּלְתַקְנָא בֵּיתָא וּפְתוֹרָא בְּיוֹמָא דָא.</p>"],[9514012633,"<p>דְּלָאו הָכֵי אִינוּן דַּאֲחִידָן בְּכוֹכָבַיָיא דְּשַׁבְּתָאי, דְּאִצְטְרִיךְ לוֹן לְאִתְעַנָּאָה, וּלְאַחֲזָאָה עֲצִיבוּ וּדְאָגָה, וּלְמִלְבַּשׁ שְׁחוֹרִין, וּלְכַסָּאָה שְׁחוֹרִין, וְלָא לְמֵיכַל בִּשְׂרָא וְחַמְרָא וּמִשְׁחָא. וְלָא לְאִתְעַנְּגָא בְּעִינּוּגִין דְּעָלְמָא. אֶלָּא לְמֵיתַב בְּדִיּוּרָא עֲצִיב, וּלְאִתְפְּרָשָׁא מִן בְּנֵי נָשָׁא. וּכְדֵין אִלֵּין רוּחִין קרקפונ\"י וְשמרירו\"ן אִתְמַשְׁכִין עֲלֵיהּ, וְאוֹדְעִין לֵיהּ מִלִּין דְּעָלְמָא בְּאַמְשָׁכוּתָא דְּשַׁבְּתָאי.</p>"],[9514012634,"<p>חָזֵינָא בְּסִפְרָא דִּשְׁלֹמֹה מַלְכָּא, דְּאִית בַּר נָשׁ דְּאִתְיְילִידוּ כַּד שָׁלְטָא עֲנָפָא דָא, וְאִינוּן עֲצִיבִין תָּדִיר דְּלָא חָדָאן לְעָלְמִין. בַּר אִי לָעָאן בְּאוֹרַיְיתָא, וְקָא אִתְאַחֲדָאן בְּקוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514012635,"<p>וְעִם כָּל דָּא, אִי אִית בֵּיהּ בְּהַהוּא בַּר נָשׁ יְסוֹדִין וְשָׁרָשִׁין מִזְּכוּ דַּאֲבָהָן, עֲנָפָא דָא דְּנָפֵיק מִשַּׁבְּתָאי, לְזִמְנִין נָצַח לֵיהּ, וְאָחִיד לֵיהּ, וְאִינוּן תְּרֵין רוּחִין מִתְפַּשְּׁטִין, וְאָזְלִין לְנוּקְבָא דְּטִינָרָא, דְּתַמָּן מִתְכַּנְּשִׁין כָּל רוּחִין עַרְטְלָאִין, דְּלָא עָאלָן לְגוֹ פַּרְגּוֹדָא דְּמַלְכָּא.</p>"],[9514012636,"<p>וְאִינוּן עַרְטְלָאִין בְּהַאי עָלְמָא, וְכַד נָפְקֵי מֵהַאי עָלְמָא, מְשָׁטְטֵי לְאָעֳלָא בְּהַהוּא עָלְמָא, וְנָעֲלִין תַּרְעָא בְּאַנְפַּיְיהוּ, בְּכָל סִטְרִין דְּעָלְמָא. וְלָא אַשְׁכְּחוּ נַיְיחָא, עַד דְּאִינוּן נָפְקִין וּמְשָׁטְטֵי בְּעָלְמָא, וְאִלֵּין אִיקְרוּן בִּשְׁמָהָן שכנות.</p>"],[9514012637,"<p>וּבְיוֹמָא דְשַׁבַּתָּא, כַּד אִתְקַדַּשׁ יוֹמָא, וְאִינוּן לְאָן עָאלִין. לְגוֹ נוּקְבָא דְּחַד טִינָרָא, דְּאִיהוּ לְבַר מֵחוֹמוֹת גִּנְתָּא, בְּטוּרִין דִּלְבַר, וּמִשְׁתַּכְּחֵי תַּמָּן כָּל יוֹמָא דְשַׁבַּתָּא. וּלְבָתַר נָפְקִין וּמְשָׁטְטִין בְּעָלְמָא, וּמוֹדִיעִין בְּחֵיזוּ דְלֵילְיָא, מִלִּין לִבְנֵי נָשָׁא.</p>"],[9514012638,"<p>וְכָה נָצַח עֲנָפָא דָא לְהַהוּא בַּר נָשׁ. אִינוּן תְּרֵין רוּחִין אָזְלִין לְהַהוּא נוּקְבָא, וּמִתְעַכְּבִין תַּמָּן עַד דְּנָפֵיק שַׁבַּתָּא. כֵּיוָן דְּנָפֵיק שַׁבַּתָּא, נָפְקִין אִינוּן נִשְׁמָתִין וְאִינוּן רוּחִין בַּהֲדַיְיהוּ, וּמִתְחַבְּרָן כַּחֲדָא.</p>"],[9514012639,"<p>וְאַתְיָין אִינוּן תְּרֵין רוּחִין, וְחַד נִשְׁמָתָא דְּגִזְעָא דְּהַהוּא בַּר נָשׁ, ע' דַּרְגִּין לַאֲחוֹרָא, וְשָׁארָן עַל הַהוּא בַּר נָשׁ, רוּחָא בָּתַר רוּחָא, וְאוֹדְעֵי לֵיהּ מִלִּין בְּעָלְמָא, מִנַּיְיהוּ קְשׁוֹט וּמִנַּיְיהוּ לָאו קְשׁוֹט. מִנַּיְיהוּ קְשׁוֹט, מִסִּטְרָא דְּנִשְׁמְתָא עַרְטִילָאָה. דְּהָא אַשְׁכְּחָא תַּמָּן נַיְיחָא. וּמִנַיְיהוּ לָאו קְשׁוֹט, מִסִּטְרָא דְּאִינוּן רוּחִין. וּלְזִמְנִין, אִינוּן רוּחִין אוֹדְעִין לֵיהּ מִילֵי קְשׁוֹט, לִזְמַן קָרִיב.</p>"],[9514012640,"<p>וְהָא אִיהִי נִשְׁמָתָא דְּלָא אַשְׁכְּחַת פֵּירוּקָא, מֵע' דַּרְגִּין לַאֲחוֹרָא. כְּדֵין, כּוֹכָב שַׁבְּתָאי מָשִׁיךְ לְהַאי עָלְמָא, אִינוּן רוּחִין. וּבְגִינָהּ לָא דָּחִיל הַהוּא בַּר נָשׁ, כַּד שָׁרָאן עֲלוֹהִי, וְלָא אִזְדַּעְזַע. זַכָּאָה חוּלָקֵיהּ דְּמַאן דְּאִית לֵיהּ זְכוּ דַּאֲבָהָן, לְסַיְיעָא בְּכָל אִינוּן עוֹבָדִין.</p>"],[9514012641,"<p>חוֹטְמָא עָקִים, וְהַהוּא עֲקִימוּ סָטָא לִסְטַר יָמִינָא. דָּא אִיהוּ בַּר נָשׁ דִּרְשִׁים בְּאָת ה' וּלְזִמְנִין בְּאָת ר'. וְלָא מִתְחַבְּרִין כַּחֲדָא. דָּא אִיהוּ בַּר נָשׁ מְמַלֵּל רְכִיכִין.</p>"],[9514012642,"<p>בְּמִצְחֵיהּ שִׁרְטוּטָא חָדָא רַבְרְבָא, וְד' זְעִירִין, וְאִינוּן דְּקִיקִין וְלָא כָּל כַּךְ, וְאִינוּן מִתְהַפְּכָן לְסוּמְקָא. שַׂעֲרוֹי תַּלְיָין שְׁעִיעִין זְעֵיר, שַׁלְשְׁלָאָה רַבְרְבָא הֲוָה לֵיהּ, וְתַלְיָיא מִנֵּיהּ. סִיּוּעָא אִית לֵיהּ, מְהֵימְנָא אִיהוּ. אַצְלַח בְּעוֹבָדוֹי. דָּא אִית לֵיהּ פְּגִימוּ דְּמוּמָא, דְּאִיהוּ סְרִיס חַמָּה, אוֹ תַּלְיָיא בְּכִיסָא דְּבֵעוֹי חַד מִמֵּעוֹי, וְלָא אַפֵּיק זַרְעָא כִּדְקָא יָאוֹת. בִּידָא דִשְׂמָאלָא אִית לֵיהּ אֶצְבַּע זְעֵירָא, קָמִיט וְלָא אִתְפַּשַּׁט .</p>"],[9514012643,"<p>אֲמַר אָדָם קַדְמָאָה, לֹא נִכְחַד עָצְמִי מִמֶּךָּ אֲשֶׁר עֻשֵּׂיתִי בַּסֵּתֶר רֻקַּמְתִּי (תהלים קלט) בְּתַחְתִּיּוֹת אָרֶץ. מִכָּאן דְּמִזִּוּוּגָא דִּדְכַר וְנוּקְבָא, אַתְיָא נִשְׁמָתָא קַדִּישָׁא. מִזִּיווּגָא דְּמַלְכָּא בְּמַטְרוֹנִיתָא. מַאי טַעְמָא. תַּחְתִּיּוֹת אָרֶץ. תְּרֵין תְּחוּמִין אִית לְהַהִיא דְּאִיתְקְרֵי אֶרֶץ חֵפֶץ. אַתְרָא דְּאִתְצַיְירָא נִשְׁמָתָא דִּדְכוּרָא לְיָמִינָא. וְאַתְרָא דְנִשְׁמָתָא דְּנוּקְבָא לִשְׂמָאלָא.</p>"],[9514012644,"<p>וְעַל דָּא בָּעֵי אִתְעֲרוּתָא מִסִּטְרָא דְנוּקְבָא. הֲדָא הוּא דִכְתִיב, (ישעיהו מ״א:כ״ה) הַעִירוֹתִי מִצָּפוֹן וַיַּאת. וּכְדֵין מִמִּזְרַח שֶׁמֶשׁ קוֹרֵא בִשְׁמִי. זִוּוגָא דְשִׁמְשָׁא בְּסִיהֲרָא, יַעֲקֹב בְּרָחֵל וְיָבֹא סְגָנִים כְּמוֹ חֹמֶר. אִלֵּין חַיָּילִין דְּעָלְמָא, דְּנָפְקוּ מֵאָדָ\"ם קַדְמָאָה.</p>"],[9514012645,"<p>בָּתַר הָכֵי, (תהלים קלט) גָּלְמִי רָאוּ עֵינֶיךָ, כְּשֶׁהָיִיתִי מוּטָל גּוֹלֶם בְּלֹא צוּרָה, מִמִּזְרָח לַמַּעֲרָב. רָאוּ עֵינֶיךָ, הַדּוֹרוֹת הָעֲתִידוֹת לָצֵאת מִמֶּנִּי. כִּי אַתָּה הוּא הַקּוֹרֵא הַדּוֹרוֹת מֵרֹאשׁ.</p>"],[9514012646,"<p>וְעַל סִפְרְךָ כּוּלָּם יִכָּתֵבוּ. זֶה סֵפֶר תּוֹלְדוֹת אָדָם לִדְיוֹקְנִין. דִּבְהַאי סִפְרָן שֶׁל צַדִּיקִים, הֲווֹ אִתְחַקְּקָן כָּל דְּיוֹקְנִין בְּעָלְמָא. בְּצֵירוּפָא דְאַתְוָון, זר\"ה פס\"ץ.</p>"],[9514012647,"<p>וְתַמָּן כֻּלָּם יִכָּתֵבוּ, בְּצִיּוּרִין דִּקְמָטִין, בְּמִשְׁכָא דְאָדָם, כְּגַוְּונָא דִּרְקִיעַ הַשָּׁמַיִם, דְּתַמָּן כּוֹכָבִים, (ישעיה מ) הַמּוֹצִיא בְמִסְפָּר צְבָאָם לְכֻלָּם בְּשֵׁם יִקְרָא. לְזַרְעָא דְּיִשְׂרָאֵל עַבְדִּי, יַעֲקֹב אֲשֶׁר בְּחַרְתִּיךָ. דְּאִינוּן אִיקְּרוּן אָדָם, דִּכְתִיב (יחזקאל לד) וְאַתֵּן צֹאנִי צֹאן מַרְעִיתִי אָדָם אַתֶּם. וּבְגִינֵהוֹן אִתְבְּרֵי עָלְמָא. הֲדָא הוּא דִכְתִיב, (ירמיה ב) קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה. דְּאִינוּן עָאלוּ בַּמַּחֲשָׁבָה, עַד לָא אִתְבְּרֵי עָלְמָא. וְכָלְהוֹ וְעַל סִפְרְךָ כֻּלָּם יִכָּתֵבוּ.</p>"],[9514012648,"<p>יָמִים יוּצָרוּ, לְכָלְהוֹ יוֹמִין עִילָּאִין, כְּמִנְיַן מִשְׁכ\"וּ וּקְחוּ לָכֶם. מִשְׁכוּ יוֹמִין עִילָּאִין, לְאַנְהָרָא לְיוֹמִין תַּתָּאִין. שס\"ה וּרְבִיעַ יוֹם. וּמִקְצַת יוֹמָא כְּכוּלֵי יוֹמָא, לְחוּשְׁבַּן מִשְׁכוּ. וּמַאן דְּמָשִׁיךְ מִתַּמָּן מָשִׁיךְ נְהִירוּ לְסִיהֲרָא לְקַדְּשָׁא לָהּ.</p>"],[9514012649,"<p>וְלֹא אֶחָד בָּהֶם, דָּא דָוִד מְשִׁיחָא. דְּלָא הֲווֹ לֵיהּ יוֹמִין לְאִתְנַהֲרָא, וְאִיהוּ מָשִׁיךְ לֵיהּ שִׁבְעִין שְׁנִין. כְּמָה דְאַתְּ אָמֵר, (תהלים לט) הִנֵּה טְפָחוֹת נָתַתָּ יָמַי. מַאי טְפָחוֹת, ט' פָּחוֹת. טַב הָכָא דְּפָחֵית לוֹן מִיּוֹמוֹי דְּאָדָם, לְמֵיהַב לְדָוִד, דְּהֲוָה טוֹב רוֹאִי. טוֹב דִּילֵיהּ, מֵאָדָם קַדְמָאָה, דְּעָבַד עִמֵּיהּ צְדָקָה, בְּגִין דִּיהֵא מוּכָן דָּוִד, לַעֲשׂוֹת צְדָקָה לְיִשְׂרָאֵל. כְּגַוְונָא דְּקַבֵּיל דָּוִד דְּהֲוָה עָנִי וְאֶבְיוֹן, הָכֵי יָהֵיב לְמִסְכְּנֵי. וְכֹלָּא בְּמִשְׁפָּט, כְּמָה דְאַתְּ אָמֵר (שמואל ב ח) וַיְהִי דָוִד עוֹשֶׂה מִשְׁפָּט וּצְדָקָה לְכָל עַמּוֹ.</p>"],[9514012650,"<p>וְאִתְעָרוּ, שׁוּפְרֵיהּ דְּיַעֲקֹב אָבִינוּ, מֵעֵין שׁוּפְרֵיהּ דְּאָדָם קַדְמָאָה. בְּגִין דְּיַעֲקֹב יוֹשֵׁב אוֹהָלִים, וְאוֹלִיף תַּמָּן, בְּבֵית שֵׁם וְעֵבֶר וְאַבְרָהָם וְיִצְחָק, לְמִפְלַח לְקוּדְשָׁא בְּרִיךְ הוּא. בְּגִין דְּאִיהוּ בְּכוֹר, דִּכְתִיב (שמות ד) בְּנִי בְּכוֹרִי יִשְׂרָאֵל, וַעֲבוֹדָה בִּבְכוֹרוֹת הֲוָה.</p>"],[9514012651,"<p>וַדַּאי, סִפְרָא דְּאָדָם קַדְמָאָה, הֲוָה לֵיהּ לְיַעֲקֹב. וְסִפְרָא דַּחֲנוֹךְ. וְסֵפֶר יְצִירָה דְּאַבְרָהָם אָבִינוּ. וְהָא אִיתְרְעוּ, מַסֶּכֶת עֲבוֹדָה זָרָה דְּאַבְרָהָם אָבִינוּ, ד' מְאָה פִּרְקֵי הַוְיָין. וּמִכָּל אִינוּן סִפְרִין, אוֹלִיף יַעֲקֹב אָבִינוּ אִישׁ תַּם יוֹשֵׁב אֹהָלִים, חָכְמָתָא סַגִּיאָה, וַהֲוָה שׁוּפְרֵיהּ וְשִׁרְטוּטִין דְּיַעֲקֹב, כְּגַוְונָא דְּשִׁרְטוּטִין דְּאָדָם קַדְמָאָה.</p>"],[9514012652,"<p>וְהוּא כְּגַוְונָא דְּאָדָם קַדְמָאָה, דְּאִיהוּ קֳדָם לִיצִירָה, יְצִיר כַּפָּיו שֶׁל הַקָּדוֹשׁ בָּרוּךְ הוּא. אוּף יַעֲקֹב רִאשׁוֹן. רִאשׁוֹן לִשְׁלִימוּ, קֹדֶשׁ יִשְׂרָאֵל לַה' רֵאשִׁית תְּבוּאָתֹה, דְּהֲוָה עַרְסֵיהּ שְׁלִים.</p>"],[9514012653,"<p>מַה דְּלֵית הָכֵי בְּאַבְרָהָם, דְּנָפֵיק מִנֵּיהּ יִשְׁמָעֵאל וּבְנֵי קְטוּרָה, דְּאִינוּן סִיגֵי הַכֶּסֶף. וְאָדָם, דְּנָפַק מִנֵּיהּ קַיִן. וְנֹחַ, דְּנָפַק מִנֵּיהּ חָם. וְיִצְחָק, דְּנָפַק מִנֵּיהּ עֵשָׂו, סִיגֵי דַהֲבָא. אֲבָל יַעֲקֹב עַרְסֵיהּ שְׁלֵימָא אִיהוּ. וְעַל דָּא בֵּיהּ בָּחַר ה' מִכָּל הָעַמִּים. דִּכְתִיב, (תהילים קל״ה:ד׳-ה׳) כִּי יַעֲקֹב בָּחַר לוֹ יָהּ יִשְׂרָאֵל לִסְגֻלָּתוֹ, וּכְתִיב (דברים ל״ב:ט׳) כִּי חֵלֶק ה' עַמּוֹ יַעֲקֹב חֶבֶל נַחֲלָתוֹ. עַד כָּאן סִתְרֵי תּוֹרָה.</p>"],[9514012654,"<p>(שמות כ׳:א׳) וַיְדַבֵּר אֱלֹהִים אֶת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר. רַבִּי שִׁמְעוֹן וְר' אֶלְעָזָר, וְר' אַבָּא, הֲווֹ יָתְבֵי. אָמַר רִבִּי אֶלְעָזָר, אִי נִיחָא לֵיהּ לְאַבָּא, לֵימָא חַד מִלָּה בְּמַעֲשֵׂה מֶרְכָּבָה. אָמַר לֵיהּ, וְהָא תְּנַן, וְלֹא בַּמֶּרְכָּבָה בְּיָחִיד. אָמַר לֵיהּ, דַּעְתֵּיהּ דְּאַבָּא דְּאֵימָא מִלָּה דְּאוֹלִיפְנָא מִנֵּיהּ. נָפַק ר' אַבָּא. אָמַר לֵיהּ רַבִּי שִׁמְעוֹן לְר' אַבָּא, אַנְתְּ בִּלְחוֹדָךְ תְּתַקֵּן פְּתוֹרָא, וְאֶלְעָזָר בַּהֲדָי.</p>"],[9514012655,"<p>פָּתַח רַבִּי אֶלְעָזָר וְאָמַר, (יחזקאל א׳:א׳) וַיְהִי בִּשְׁלשִׁים שָׁנָה בָּרְבִיעִי בַּחֲמִשָּׁה לַחֹדֶשׁ וַאֲנִי בְּתוֹךְ הַגּוֹלָה עַל נְהַר כְּבָר נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאוֹת אֱלֹהִים. הַאי קְרָא לָא אִתְּמָר מַאן אֲמָרָהּ, אִי יְחֶזְקֵאל, הָא כְתִיב אֲבַתְרֵיהּ, (שם) הָיֹה הָיָה דְבַר ה' אֶל יְחֶזְקֵאל בֶּן בּוּזִי הַכֹּהֵן. וְהַאי קְרָא אִצְטְרִיךְ לְמִיכְתַּב בְּקַדְמִיתָא, דְּהָא בִּרְשׁוּתָא קָאֲמַר, וּלְבָתַר וַיְהִי בִּשְׁלשִׁים.</p>"],[9514012656,"<p>אֶלָּא יְחֶזְקֵאל קָאֲמַר לֵיהּ, וּבִרְשׁוּתָא דְּקוּדְשָׁא בְּרִיךְ הוּא, קָאֲמַר כָּל מַה דְּקָאֲמַר, וְגַלֵּי כָּל מַה דְּגַלֵּי. וְהַאי קְרָא אוֹקְמוּהָ חַבְרַיָיא. אֲבָל נְבוּאָה דָא הֲוַות, בְּזִמְנָא דְּנָחֲתַת שְׁכִינְתָּא עִמְּהוֹן דְּיִשְׂרָאֵל בְּגָלוּתָא, וִיקָרָא עִילָּאָה מְנַצְצָא, סְתִימָא אִסְתַּכְּלוּתָא דְּהַהוּא דְּאִיקְּרֵי זֹהַר שְׁכִינְתָּא, דְּמֵהַהוּא זוֹהֲרָא אִתְּזָנַת, לָא אִזְדַּהֲרָא. וּשְׁכִינְתָּא עִילָּאָה אִסְתַּלְקַת מֵעַל בְּנִין, וְאִתְיְיהַב רְשׁוּ לְשִׁבְעִין שְׁנִין אָחֳרָנִין דְּמַלְכוּת בָּבֶל לְשַׁלְּטָאָה.</p>"],[9514012657,"<p>אַדְהָכֵי, נָחֲתַת אֶשָּׁא מִלְּעֵילָא, וְסָחֲרָא לוֹן, וַהֲווּ שָׁמְעִין קָל מַשִּׁרְיָין עִילָּאִין, מִגּוֹ אֶשָּׁא. חָדֵי רַבִּי שִׁמְעוֹן, אֲמַר לֵיהּ פְּתַח פּוּמָךְ וִינַהֲרוּן מִלִּין.</p>"],[9514012658,"<p>פְּתַח וַאֲמַר, בָּרְבִיעִי: דָּא דָּוִד מַלְכָּא דְּאִיהוּ סָמְכָא רְבִיעָאָה לְכוּרְסְיָיא עִילָּאָה, בַּהֲדֵי אִינוּן תְּלַת סַמְכִין עִילָּאִין, דְּאִינוּן רָזָא דִּשְׁלשִׁים שָׁנָה, וְהַאי סָמְכָא רְבִיעָאָה, אִיהוּ בְּחִיבּוּרָא חָדָא עִמְּהוֹן. וּבְגִין דְּאִיהוּ עִמְּהוֹן בְּלָא פֵּירוּדָא, אִתְּמָר בָּרְבִיעִי. בַּחֲמִשָּׁה לַחֹדֶשׁ, אִלֵּין דַּרְגִּין לְתַתָּא, דְאִינוּן תִּיקּוּנָא דְּסִיהֲרָא, לְאִתְחַבְּרָא בְּהוּ.</p>"],[9514012659,"<p>וְלֵית לְכָלְהוֹ דַּרְגִּין בְּאִסְתַּלְּקוּת שְׁכִינְתָּא עִילָּאָה מֵעַל בְּנִין, נַיְיחָא וּנְהוֹרָא. וּכְדֵין לָבְשׁוּ שָׁמַיִם קַדְרוּת וְשַׂק הוּשַׂם כְּסוּתָם. וּכְדֵין כְּתִיב, וַאֲנִי בְּתוֹךְ הַגּוֹלָה, דְּהָא נָחֲתַת שְׁכִינְתָּא בְּגָלוּתָא, וְאִתְגַּלְּיָיא יְקָרָא עִילָּאָה, וְשִׁמְשָׁא אִתְחֲשַׁךְ.</p>"],[9514012660,"<p>וּכְמָּה דִּבְזִמְנָא דָא, הַאי קְרָא דַּרְשִׁינָן לֵיהּ בְּצַעַר, הָכֵי בְּזִמְנָא אוֹחֲרָא, כָּל זִימְנָא דְּקַיְימָא הַהוּא נְהוֹרָא לְאַנְהָרָא, וְכָרְסְוָון אִשְׁתַּלִּימוּ בִּנְהוֹרָא, דָּא בְדָא. כּוּרְסְיָיא עִילָּאָה קַדִּישָׁא, אַנְהֵיר נְהִירוּ בַּאֲבָהָן בְּקַדְמִיתָא, וְכַד אִינוּן נָהֲרִין מִגּוֹ הַהוּא נְהוֹרָא עִילָּאָה, כֹּלָּא נָהֵיר. הֲדָא הוּא דִכְתִיב, וַיְהִי בִּשְׁלשִׁים וְגו' וַיְהִי מִקַּדְמַת דְּנָא.</p>"],[9514012661,"<p>וְהָכֵי תַּנְיָא, וַיְהִי אוֹר, וְהָיָה אוֹר לֹא נֶאֱמַר, אֶלָּא וַיְהִי אוֹר, שֶׁכְּבָר הֲוָה. אוּף הָכָא וַיְהִי בִּשְׁלשִׁים שָׁנָה, וְהָיָה לֹא נֶאֱמַר, אֶלָּא וַיְהִי, דְּהָא כְּבָר הֲוָה. וְרָזָא דָא דִּכְתִיב, עַל נְהַר כְּבָר, עַל נְהוֹרָא דִּכְבָר הֲוָה. בָּרְבִיעִי: דָּא דָוִד מַלְכָּא, כְּמָא דְּאִתְּמָר. וְאִיהוּ קָיְימָא בְּאַרְבַּע סְרֵי, לְאַנְהָרָא. אִיהוּ רְבִיעָאָה וַדַּאי. בַּחֲמִשָּׁה: דָּא שְׁלֹמֹה מַלְכָּא, דְּאִיהוּ אַשְׁלֵים לְכוּרְסְיָיא, דִּכְתִיב (דברי הימים א כ״ט:כ״ג) וַיֵּשֶׁב שְׁלֹמֹה עַל כִּסֵּא ה' לְמֶלֶךְ.</p>"],[9514012662,"<p>עֲה כָּאן אִתְנְהֵיר נְהִירוּ בְּכֹלָּא, מִכָּאן וְאֵילָךְ, שָׁארֵי נְהִירוּ לְאִתְכַּסְיָיא, דִּכְתִיב וַאֲנִי בְּתוֹךְ הַגּוֹלָה. רָזָא וַאֲנִי, קְרִיבַת לְאִתְחַשְּׁכָא. דִּכְתִיב בְּתוֹךְ הַגּוֹלָה, וְלָא כְתִיב בַּגּוֹלָה, אֶלָּא דְּהֲוָה קָרֵיב לַגּוֹלָה, וְאִתְחַשְּׁכָא וְאָזֵיל עַד דְּאִתְחַשַּׁךְ, וְאִתְכַּסֵּי נְהוֹרָא.</p>"],[9514012663,"<p>אַמַּאי אִתְכַּסֵּי נְהוֹרָא, אַהֲדַר וַאֲמַר עַל נְהַר כְּבָר. עַל נְהוֹרָא דִּכְבָר הֲוָה, דְּאִסְתְּלַק הַשְׁתָּא וְאִתְפְּרַשׁ מִינָּהּ, וּבְגִין דְּאִתְפְּרַשׁ מִינָּהּ הַהוּא נְהוֹרָא דִּכְבָר הֲוָה, דְּאִיהוּ נְהוֹרָא קַדְמָאָה, נִפְתְּחוּ הַשָּׁמַיִם, בְּגִין כָּךְ נִפְתְּחוּ וַדַּאי.</p>"],[9514012664,"<p>דְּהָא בְּקַדְמִיתָא אִשְׁתְּכַח חִיבּוּרָא חָדָא בִּכְלָלָא חַד, דְּאִתְכְּלִילָא יָמִינָא בִּשְׂמָאלָא, וּשְׂמָאלָא בְּיָמִינָא, וְאִתְעֲבֵיד מִנֵּיהּ שָׁמַיִם דְּכָלֵיל תַּרְוַויְיהוּ. כֵּיוָן דְּיָמִינָא אִתְהַדַּר לַאֲחוֹרָא, כְּמָא דִכְתִיב, (איכה ב׳:ג׳) הֵשִׁיב אָחוֹר יְמִינוֹ, כְּדֵין וַדַּאי נִפְתְּחוּ הַשָּׁמַיִם, נִפְתְּחוּ מֵהַהוּא שְׁלִימוּ דְּחִבּוּרָא דְּהֲוָה בְּקַדְמִיתָא, וְאִתְכַּסֵּי קַדְרוּתָא בְּהַהוּא אֲתַר, דִּכְתִיב (ישעיהו נ׳:ג׳) אַלְבִּישׁ שָׁמַיִם קַדְרוּת, דַּחֲסַר מִנַּיְיהוּ נְהַר כְּבָר, הַהוּא נְהוֹרָא אוֹר קַדְמָאָה, דִּכְבָר הֲוָה. כִּבְיָכוֹל אִשְׁתְּכַח פֵּירוּדָא.</p>"],[9514012665,"<p>וְרָזָא (שם סג) כִּי אַבְרָהָם לֹא יְדָעָנוּ, וְכֵיוָן דְּאַבְרָהָם לֹא יְדָעָנוּ וְלָא נָהֵיר לָן, וּכְדֵין וְיִשְׂרָאֵל לֹא יַכִּירֶנוּ, דְּהָא נִפְתְּחוּ הַשָּׁמַיִם, וְחִבּוּרָא לָא אִשְׁתְּכַח, וּנְהוֹרָא אִתְאֲבַד.</p>"],[9514012666,"<p>וָאֶרְאֶה מַרְאוֹת אֱלֹהִים, מַה דַּהֲווֹ מִתְכַּסְיָין בְּקַדְמִיתָא בְּגוֹ נְהִירוּ עִילָּאָה, וְלָא אִתְגַּלְיָין, הַשְׁתָּא חָמֵינָא לוֹן בְּקַדְרוּ, צָוְוחִין לְבַר. כְּמָה דְאַתְּ אָמֵר, (שם לג) הֵן אֶרְאֶלָם וְגו', חָמֵינָא לוֹן דְּיִצְעֲקוּ חוּצָה, וְנָחֲתוּ לְגָלוּתָא דְּאִיהוּ חוּצָה, לְבַר מֵאַרְעָא קַדִּישָׁא, לְבַר מִתְּחוּמָא דִּילְּהוֹן.</p>"],[9514012667,"<p>וְצָוְוחִין תְּרֵין בְּכִיָּין, חַד, עַל דְּנָחֲתֵי בְגָלוּתָא, לְבַר מִתְּחוּמָא דִּילְּהוֹן. וְחַד, עַל דְּנִפְתְּחוּ הַשָּׁמַיִם, וְשָׁלוֹם לָא אִשְׁתְּכַח, וְאִינוּן תְּרֵין בְּכִיָּין, הֲדָא הוּא דִכְתִיב צָעֲקוּ חוּצָה, הָא בְּכִיָּיה חַד. מַלְאֲכֵי שָׁלוֹם, אִינוּן דַּהֲווֹ מִסִּטְרָא דְּשָׁלוֹם, יִבְכּוּ עַל הַהוּא שָׁלוֹם, בְּגִין דְּחַסְרֵי נְהַר כְּבָר.</p>"],[9514012668,"<p>בַּחֲמִשָּׁה לַחֹדֶשׁ הִיא הַשָּׁנָה הַחֲמִישִׁית לְגָלוּת הַמֶּלֶךְ יְהוֹיָכִין, (יחזקאל א׳:ב׳) בַּחֲמִשָּׁה לַחֹדֶשׁ, הָא אוֹקְמוּהָ. אֲבָל יוֹמָא דָּא, יוֹמֵי דְּשָׁבוּעוֹת, הַהוּא יוֹמָא דְּקַבִּילוּ יִשְׂרָאֵל אוֹרַיְיתָא עַל טוּרָא דְסִינַי, וְשָׁמְעוּ אָנֹכִי. וּכְדֵין אִתְקַיֵּים, (ישעיהו מ״ט:ט״ו) וְאָנֹכִי לֹא אֶשְׁכָּחֵךְ. וְאִדְכַּר לוֹן הַהוּא יוֹמָא, וְנָחֲתַת שְׁכִינְתָּא לְגָלוּתָא לְדָיְירָא עִמְּהוֹן דְּיִשְׂרָאֵל.</p>"],[9514012669,"<p>בְּהַהוּא יוֹמָא דְּאִיהוּ חֲמִשָּׁ\"ה לַחֹדֶשׁ, יוֹמָא דְּחַמְשִׁין תַּרְעִין, הֲוָה כַּד קַּבִּילוּ יִשְׂרָאֵל אוֹרַיְיתָא עַל טוּרָא דְסִינַי, וְנָחֲתֵי כַּמָּה רְתִיכִין, כַּמָּה מַשִּׁרְיָין דְּסָחֲרִין כּוֹרְסֵי יְקָרָא עִילָּאָה, וְקוּדְשָׁא בְּרִיךְ הוּא יָתִיב עַל כּוֹרְסְיָיא, גּוֹ יְקָרָא עִילָּאָה דְמַלְכָּא שַׁלִּיטָא בְּהִידּוּרָא. וְרָפֵיד שְׁמַיָא וּשְׁמֵי שְׁמַיָא עַל טוּרָא דְסִינַי, וִיהֵיב אוֹרַיְיתָא.</p>"],[9514012670,"<p>וּכְדֵין אִשְׁתְּכַח חֶדְוָה קַמֵּיהּ, יוֹתֵר מִיּוֹמָא דְּאִתְבְּרוּן שְׁמַיָא וְאַרְעָא. דְּהָא שָׁמַיִם וָאָרֶץ עַל תְּנַאי אִתְבְּרִיאוּ, וְלָא אִתְקַיְימוּ בְּקִיּוּמַיְיהוּ, עַד הַהוּא יוֹמָא דְּאִתְיְהֵיב אוֹרַיְיתָא לְיִשְׂרָאֵל. כֵּיוָן דְּקַבִּילוּ יִשְׂרָאֵל אוֹרַיְיתָא עַל טוּרָא דְסִינַי, כְּדֵין אִתְבַּסָּם עָלְמָא, וְאִתְקַיְימוּ שְׁמַיָא וְאַרְעָא.</p>"],[9514012671,"<p>וּכְמָא דְהַהוּא יוֹמָא הֲוָה חֶדְוָה קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, הָכִי נָמֵי הָכָא יוֹמָא דְּעִרְבּוּבְיָא וַעֲצִיבוּ הֲוָה, לְאִתְתָּרְכָא שְׁכִינְתָּא מִתְּחוּמָא קַדִּישָׁא, וְהוֹאִיל וְאִתְגַּלְּיָיא נְבוּאָה דָא, לָא אִתְגַלְּיָיא אֶלָּא בְּיוֹמָא דָא, יוֹמָא דְּאִדְכַּר קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל הַהִיא קִיּוּמָא דְּטוּרָא דְסִינַי, וְקַבִּילוּ אוֹרַיְיתָא.</p>"],[9514012672,"<p>(יחזקאל א) הָיֹה הָיָה דְּבַר ה' אֶל יְחֶזְקֵאל בֶּן בּוּזִי הַכֹּהֵן בְּאֶרֶץ כַּשְׂדִים עַל נְהַר כְּבָר וַתְּהִי עָלָיו שָׁם יַד ה'. מִכָּאן, דְּבִרְשׁוּתָא גַּלֵּי יְחֶזְקֵאל, וְאִתְיְהֵיב לֵיהּ רְשׁוּ עִילָּאָה, לְגַלָּאָה כָּל מַה דְּגַלֵּי.</p>"],[9514012673,"<p>הָיֹה הָיָה: קִיּוּם עַל קִיּוּם, הֲוָה בְּקִיּוּמָא דְּהַהוּא מִלָּה, וְהַהוּא נְבוּאָה. שְׁמָא דְּקוּדְשָׁא בְּרִיךְ הוּא דְּאִתְמְסַר לְמשֶׁה, הֲוֵי שְׁמָא קַדִּישָׁא עִילָּאָה, וּשְׁמָא דָא אִיהוּ לְאַגָּנָא עַל גָּלוּתָא, וְאִלְמָלֵי הֲוָה שְׁלָם בְּרָזָא דִּשְׁלִימוּ, לָא יִתְעַכְּבוּן כְּלַל בְּגָלוּתָא. אֲבָל אִסְתְּלַק מִשְׁמָא דָא א', וְאִשְׁתָּאַר הָיֹה. וּבְגִין דְּאִסְתְּלַק א'. אִתְכְּפַל הָיָה תְּרֵי זִמְנֵי, לְאַגָּנָא עֲלַיְיהוּ, וְאִיהוּ רָזָא חָדָא. דְּהָא בִּשְׁמָא דָא נָחֲתָא שְׁכִינְתָּא לְגָלוּתָא, אֲבָל בְּאִסְתַּלָּקוּת אוֹר אָת א'.</p>"],[9514012674,"<p>וְאִתְגְּלֵי נְבוּאָה דָא לִיחֶזְקֵאל בְּאֶרֶץ כַּשְׂדִים, בְּחֶסְרוֹן אוֹת אָלֶ\"ף מֵרָזָא דִשְׁמָא קַדִּישָׁא. לְאַחֲזָאָה, דְּלָא הֲוָה אֶלָּא עַל נְהַר כְּבָר, עַל נָהָר דִּכְבָר הֲוָה, דְּאִסְתְּלַק מִשְׁמָא דָא.</p>"],[9514012675,"<p>וּבְגִין כָּךְ, וַתְּהִי עָלָיו שָׁם יַד ה'. בְּקַדְמִיתָא דְּבַר ה', וּלְבָתַר יַד ה', וְכֹלָּא חַד, וְרָזָא חַד. אֶלָּא בְּקַדְמִיתָא לָאו בְּדִינָא, דְּהָא לָאו אַתְרֵיהּ אִיהוּ לְאִתְגַּלָּאָה עֲלוֹי שְׁכִינְתָּא. וְהַאי קְרָא, רוּחַ קוּדְשָׁא אֲמָרָהּ. דְּאַסְהֵיד עֲלֵיהּ דִּיחֶזְקֵאל, דְּאִתְיְיהֵיב לֵיהּ רְשׁוּ, וּבְרוּחַ נְבוּאָה אֲמַר כָּל מַה דַּאֲמַר. עֲד כָּאן אִשְׁתָּעֵי קְרָא רָזָא דְּעוֹבָדָא, מִכָּאן וּלְהָלְאָה שֵׁירוּתָא דְּרָזִין עִילָּאִין.</p>"],[9514012676,"<p>(שם) וָאֵרֶא וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן וְגו'. מִכָּאן שֵׁירוּתָא לְגַלָּאָה רָזִין, וְלָא אִצְטְרִיכוּ לְגַלָּאָה, בַּר לְחַכִּימֵי לִיבָּא, דְּיָדְעִין לְמִדְרַשׁ בְּהוּ. וָאֵרֶא, וְלָא כְתִיב וְאֶרְאֶה. אֶלָּא ה' עִילָּאָה אִסְתַּלַּק, וְלָא חָמָא, בַּמֶּה דְּלָא אִתְיְהֵיב לֵיהּ רְשׁוּ, וְלָא לְאֳחָרָא לְגַלָּאָה.</p>"],[9514012677,"<p>וְהוּא אִסְתַּכֵּל לְתַתָּא, בְּאִינוּן מַרְאוֹת דְּאִתְגַּלְיָין יַתִּיר, וְתַמָּן כְּתִיב וָאֶרְאֶה. אֲבָל הָכָא, אַף עַל גַּב דְּקָא רָמִיז מִלִּין עִילָּאִין, כְּמַאן דְּאִסְתַּכֵּל בָּתַר כּוֹתְלָא הֲוָה, בְּגִין כָּךְ אִסְתַּלַּק ה' מִתֵּיבָה דָא.</p>"],[9514012678,"<p>וְהִנֵּה רוּחַ סְעָרָה בָּאָה מִן הַצָּפוֹן, הַאי אִיהוּ רָזָא דְּקָאֲמָרָן, דְּאָתָא לְמִיתְבַּר קַמֵּי נְבוּכַדְנֶצַּר חַיָּיבָא, רֵישׁ מַלְכְּוָון. רוּחַ סְעָרָה, דְּקָא מַסְעַר כּוֹלָּא.</p>"],[9514012679,"<p>וְהַיְינוּ רָזָא דְקָא גַּלֵּי קוּדְשָׁא בְּרִיךְ הוּא לְאֵלִיָּהוּ, דִּכְתִיב, (מלכים א י״ט:י״א) וְרוּחַ גְּדוֹלָה וְחָזָק מְפָרֵק הָרִים וּמְשַׁבֵּר סְלָעִים כו', לֹא בָּרוּחַ ה' וַדַּאי. וְאַחַר הָרוּחַ רַעַשׁ לֹא בָּרַעַשׁ ה'. וְהַיְינוּ עָנָן גָּדוֹל. דְּהַהוּא עֲנָנָא קָא מַרְעִישׁ וְאָזֵיל, דְּאִיהוּ גָדוֹל. וְאַחַר הָרַעַשׁ אֵשׁ לֹא בָאֵשׁ ה' וַדַּאי. וְהַיְינוּ אֵשׁ מִתְלַקַּחַת.</p>"],[9514012680,"<p>וְכָל אִינוּן קְלִיפִּין לְמוֹחָא דְּסָחֲרָן, דָּא לְגוֹ מִן דָּא, וְדָא לְגוֹ מִן דָּא. וְהַהוּא אֵשׁ, אִיהוּ דְּקָא אָחֵיד בְּגַוֵּיהּ הַהוּא נֹגַהּ, דִּכְתִיב וְנֹגַהּ לוֹ סָבִיב. הַאי אִיהוּ לְגוֹ מִן כּוֹלָּא, וְדָא אִיהוּ דְקָא מִתְאַחֵד בְּמוֹחָא.</p>"],[9514012681,"<p>הָכָא אִיהוּ רָזָא דְאַרְבַּע מַלְכְּוָון, דְּסָחֲרָן כּוֹלָּא. רוּחַ סְעָרָה, דָּא מַלְכוּת בָּבֶל. עָנָן גָּדוֹל, דָּא אִיהוּ מַלְכוּת מָדַי. וְאֵשׁ מִתְלַקַּחַת, דָּא אִיהוּ מַלְכוּת אֱדוֹם. וְנֹגַהּ לוֹ סָבִיב, דָּא אִיהוּ מַלְכוּת יָוָן, דְּסָחֲרָא לוֹן נֹגַהּ, וְלָא בְּהוּ נֹגַהּ, דִּכְתִיב בְּהוּ סָבִיב. בְּגִין דְּלֵית בְּכָל מַלְכְּוָון, דְּאִינוּן קְרֵבִין לְאוֹרַח מְהֵימְנוּתָא, כַּוָּותַיְיהוּ. אוּף הָכָא בְּאִינוּן קְלִיפִּין, לָאו מַאן דְּקָרֵיב לְמוֹחָא, כְּהַאי. וְהַאי סַחֲרָא לֵיהּ נוֹגַהּ, וְלָאו בֵּיהּ נֹגַהּ, אֶלָא נַפְקָא מִגּוֹ מוֹחָא, וְנָהֵיר סְחוֹר סְחוֹר.</p>"],[9514012682,"<p>וְאִלֵּין ד' מַלְכְּוָון מִתְחַלְּפִין, כַּד שָׁלְטָא הַאי עַל אִינוּן אָחֳרָנִין, אִתְדַּחְיָין כָּל אִלֵין, וְעָאל הַהוּא דְּשָׁלְטָא לְקַבְּלָא מֵהַאי נוֹגַהּ, וּבֵיהּ שָׁלְטָא לְמֶהֱוֵי קָרֵיב.</p>"],[9514012683,"<p>(יחזקאל א׳:ד׳) וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל, הָא אוֹקְמוּהָ, דְּאִינוּן חֵיוָן אֶשָׁא מְמַלְּלָן, וְאִינוּן זוֹהֲרָא דְּזָהֵיר, סָלְקָא וְנָחֲתָא, אֶשָׁא דְּלָהִיט, קָאִים וְלָא קָאִים, דְּלֵית מַאן דְּיָכוֹל לְמֵיקַם בֵּיהּ בְּדוּכְתָּא חָדָא. וְעַיְינִין וְחֶזְווֹהִי לָא יָכְלִין לְשַׁלְּטָאָה עֲלֵיהּ. הָא אִיהוּ, וְהָא לָא אִיהוּ. הָא בְּדוּכְתָּא חָדָא, וְהָא בְּדוּכְתָּא אָחֳרָא. הָא סָלֵיק, וְהָא נָחֵית. וּבְחֵיזוּ דָא, אִתְטַמַּר מַה דְּאִתְטַמַּר, וְאִתְגְּנֵיז מַה דְּאִתְגְּנִיז.</p>"],[9514012684,"<p>וְהָא אִיהוּ רָזָא, דְּאִקְרֵי חַשְׁמַל. דִּנְבִיאָה לְמִגּוֹ מִן דָּא אִצְטְרִיךְ לְמֵיחֱזֵי וּלְמִנְדַע, וּלְאִסְתַּכָּלָא בְּצָחוּתָא דְלִיבָּא, וְעֵינָא אִיהוּ סְגִיר יַתִּיר מִכּוֹלָּא, וּלְוַאי דְּיָכֵיל לְקָיְימָא בֵּיהּ.</p>"],[9514012685,"<p>וְכָל מַה דְּאִסְתַּכֵּל לְמֶחֱמֵי וּלְמִנְדַע, כָּל דָּא בְּאַסְפַּקְלַרְיָא דְּלָא נָהֲרָא. אֲבָל בְּאַסְפַּקְלַרְיָא דְּנָהֲרָא, לָא זָכָה נְבִיאָה לְאִסְתַּכָּלָא בַּר משֶׁה נְבִיאָה מְהֵימְנָא, דְּכָל מַפְתְּחָן דְּבֵיתָא בִּידֵיהּ. שְׁאָר נְבִיאִים, כַּד הֲווֹ מָטָאן לְהַאי חַשְׁמַל לְאִסְתַּכָּלָא לְגָיו רַעֲיוֹנִין אִתְבְּהִילוּ, וְלִבָּא לָא שָׁכֵיךְ, וְנָפְקוּ בֵּיהּ מִכָּל רַעֲיוֹנֵי גּוּפָא, כְּדֵין חָמוֹ לְגוֹ מַה דְּחָמוֹ בִּלְחִישׁוּ.</p>"],[9514012686,"<p>הַאי חַשְׁמַל, גַּוָּון אֶשָׁא מְלַהֲטָא מְנַצְּצָא, סָלְקָא וְנָחֲתָא, נָצֵיץ וְלָהֵיט. מֵהַאי סִטְרָא, נָפְקָא נְצִיצוּ חַד, חֵיזוּ מְנַצְצָא מְלַהֲטָא, הֲוֵי וְלָא הֲוֵי, קָאִים וְלָא קָאִים. וְחַד כְּגַוְונָא דָּא מֵהַאי סִטְרָא, וְדָא מֵהַאי סִטְרָא, וְכֵן לד' סִטְרִין.</p>"],[9514012687,"<p>מְמַלֵּל דָּא אֶל דָּא, וְדָא מְמַלֵּל אֶל דָּא, וְכֵן כָּלְהוֹ, עַד דְּאִינוּן חַד. כְּדֵין נָצְצָן נִיצִיצִין בִּנְצִיצוּ חַד. סָלְקָא וְנַחֲתָא, אָזְלָא וְקָיְימָא. אִתְחֲזֵי וְלָא אִתְחֲזֵי. הָא אִיהוּ, וְהָא לָאו אִיהוּ. לֵית מַאן דְּקָיְימָא בֵּיהּ. אִתְהַדְּרָן נְצִיצוּ בְּחֵיזוּ דְּחֵיוָן כְּמִלְּקַדְּמִין. מְמַלְּלָא. רַעֲיוֹנִין מִתְבַּהֲלִין בֵּיהּ, וְלִבָּא לָא שָׁכֵיךְ וְדָא אִיהוּ רָזָא דְּחַשְׁמַל.</p>"],[9514012688,"<p>לְגוֹ מִן דָּא אִיהוּ רָזָא בִּלְחִישׁוּ, רָזָא דְּקָיְימִין לְגוֹ בְּמוֹחָא. וְדָא אִיהוּ דִּכְתִיב, (שם) וּמִתּוֹכָהּ דְּמוּת ד' חַיּוֹת וְזֶה מַרְאֵיהֶן, וּמִתּוֹכָהּ וְגו', הַאי אִיהוּ רָזָא פְּנִימָאָה, בְּמוֹחָא קָיְימָא, גּוֹ רָזִין עִילָּאִין, בִּדְיוֹקְנָא עִילָּאָה, מִגּוֹ כָּל אִינוּן קְלִיפִּין דְּסָחֲרִין לְמוֹחָא כִּדְקָאֲמָרָן.</p>"],[9514012689,"<p>וּמִתּוֹכָהּ, מִתּוֹכָהּ דְּמַאן. מִתּוֹךְ הַהוּא דְּאִקְרֵי חַשְׁמַל. וְאִי תֵימָא, הָא כְתִיב חַשְׁמַל, וְהָא כְתִיב חַשְׁמְלָה, דְּמַשְׁמַע דְּחַשְׁמַל אִיהוּ דְּכַר, וְחַשְׁמְלָה אִיהִי נוּקְבָא, וְהָכָא כְּתִיב חַשְׁמַל, אַמַּאי כְּתִיב וּמִתּוֹכָהּ.</p>"],[9514012690,"<p>אֶלָּא כָּלְהוֹ לְתַתָּא, נוּקְבֵי אִינוּן. וְכָל מַאן דְשַׁלִּיט דָא עַל דָּא, הַאי דְּאִיהוּ לְתַתָּא, אִיקְּרֵי נוּקְבָא, וְכָל אִינוּן דִּלְעֵילָא דּוּכְרִין אִינוּן, וְדָא לְגוֹ מִן דָּא.</p>"],[9514012691,"<p>דְּמוּת ד' חַיּוֹת, דְּמוּת דְּמַאן. דְּמוּת דְּאִינוּן חֵיוָן עִילָּאִין, דְּהָא מֵאִלֵּין אִתְחַזּוּן אִינוּן גְּנִיזִין דְּלָא אִתְחַזּוּן. הָכָא אִיקְּרֵי דְּמוּת, וְאִיקְּרֵי צֶלֶם, דִּכְתִיב (בראשית א׳:כ״ו) בְּצַלְמֵנוּ כִּדְמוּתֵנוּ וּכְתִיב (שם ט) בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם, וּכְתִיב (שם ה) בִּדְמוּת אֱלֹהִים עָשָׂה אֹתוֹ.</p>"],[9514012692,"<p>בְּגִין דְּהָכָא רָזָא עִילָּאָה אִיהוּ, דְּכַד הַהוּא נָהָר דְּנָפֵיק מֵעֵדֶן, פָּרְחִין מִנֵּיהּ כָּל אִינוּן נִשְׁמָתִין, דְּאִינוּן אִיבָּא דְּקוּדְשָׁא בְּרִיךְ הוּא, וְנָטְלָא לוֹן מַאן דְּנָטְלָא, בְּשַׁעֲתָא דְּנָפְקָא מִקַּמֵּי קוּדְשָׁא בְּרִיךְ הוּא. כָּלְהוֹ כָּל חַד עָאל בִּדְיוֹקְנָא לְאִצְטַיְירָא, בְּהַהוּא אֲתַר דְּאִיקְּרֵי דְּמוּת, וְאִינוּן ד' חֵיוָון.</p>"],[9514012693,"<p>וְתַמָּן מִצְטַיְירָא כָּל חַד וְחַד, בְּהַהוּא דְּיוּקְנָא דְּאִתְחֲזֵי לֵיהּ. וּמִתַּמָּן נָפְקֵי כָּל אִינוּן דִּיוּקְנִין, מִצְטַיְירִין בִּדְיוּקְנַיְיהוּ כָּל חַד בִּדְיוּקְנֵיהּ, כְּמַאן דְּאָעֵיל בִּדְפוּס לְאִצְטַיְירָא. דְּמוּת דָּא, אַפֵּיק דְּמוּת. וְצֶלֶם, אַפֵּיק צֶלֶם. חַיּוֹת דְּנָפְקֵי מֵחֵילָא דְחַיָּה דְּאִיהוּ דְּכַר.</p>"],[9514012694,"<p>וּבְגִין דְּאִינוּן נוּקְבֵי, אִיקְּרוּן חַיּוֹת ד', דְּאִינוּן בְּד' סִטְרִין דְּעָלְמָא, וּבְהוֹן כְּלִילָן כָּל אִינוּן חֵילִין וּמַשִּׁרְיָין. דְּמוּת בְּרָזָא דִלְעֵילָא בְּרָזָא דִלְתַתָּא, נָטְלֵי דִּיוּקְנִין לְעֵילָא, נָטְלֵי דִּיוּקְנִין לְתַתָּא, וְאִינוּן דְּיוּקְנָא מַמָּשׁ דְּכָל סִטְרִין. וַאֲפִיקוּ דִּיוּקְנִין דְּכָל סִטְרִין דִּלְעֵילָא וְתַתָּא.</p>"],[9514012695,"<p>כֵיוָן דַּאֲמַר דְּמוּת, אַמַּאי לְבָתַר כְּתִיב וְזֶה מַרְאֵיהֶן. אֶלָּא דְּאָחֵית קַמֵּיהּ, וְאַחְזְיֵיהּ מִלָּה דְּלָא יְדִיעַ. כְּמָה דְאַתְּ אָמֵר, (במדבר ח׳:ד׳) וְזֶה מַעֲשֵׂה הַמְנוֹרָה. (בראשית ו) וְזֶה אֲשֶׁר תַּעֲשֶׂה וְגו', אוּף הָכָא וְזֶה מַרְאֵיהֶן.</p>"],[9514012696,"<p>וְאִי תֵימָא כָּל אִינוּן נְבִיאִים בַּר משֶׁה נְבִיאָה מְהֵימְנָא, כָּלְהוֹ מִתְעַרְבְּבֵי דַּעְתַּיְיהוּ כַּד מָטֵי לְגוֹ חַשְׁמַל, וְהוּא יָכֵיל לְמֵיקַם עַל דָּא. אֶלָּא בְּגִין רוּחַ נְבוּאָה הֲוָה קָאֲמַר מִלִּין, וּבְגִין רְחִימוּ דְיִשְׂרָאֵל אִיתְגְּלֵי כָּל חֶזְוָון דִּלְבַר. כָּלְהוֹ מִתְעַרְבְּבֵי, וְכָלְהוֹ בְּעִרְבּוּבְיָא.</p>"],[9514012697,"<p>וְחֵיזוּ פְּנִימָאָה אִיהוּ חֵיזוּ בִּלְחִישׁוּ, כְּמָא דַּאֲמַר (מלכים א י״ט:י״ב) וְאַחַר הָאֵשׁ קוֹל דְּמָמָה דַקָּה. וְדָא אִיהוּ רָזָא, דִּדְיוּקְנָא דְּכָלֵיל כָּל דִּיוּקְנִין בְּחֵיזוּ דִלְעֵילָא, קוֹל עִילָּאָה, בִּלְחִישׁוּ דִּלְעֵילָא, דְּמִנֵּיהּ נָפְקֵי כָּל דִּיוּקְנִין. קוֹל לְתַתָּא, כְּהַהוּא קוֹל עִילָּאָה דְּנָקֵיט בְּגַוֵּיהּ כָּל דְּיוֹקְנִין. וּבְגִין דְּדָא אִיהוּ בִּלְחִישׁוּ, כַּד נְבִיאָה מָטֵי לְגַבֵּיהּ, נָהֵיר בֵּיהּ עַיְינִין, וְנָהֲרִין רַעֲיוֹנִין.</p>"],[9514012698,"<p>וְזֶה מַרְאֵיהֶן, דְּהָא לֵית לוֹן חֵיזוּ, אֶלָּא מִגּוֹ רָזָא דְּאַסְפַּקְלַרְיָא דְּנָהֲרָא לְעֵילָא, דְּאִיהוּ חֵיזוּ דִּילְהוֹן, וְחֶזְוָוא דְּכֹלָּא, וְכֹלָּא נָהֲרִין בְּהַהוּא נְהוֹרָא.</p>"],[9514012699,"<p>חַשְׁמַל, אִינוּן אַרְבַּע נְצִיצִין, דְּלָהֲטִין וְנָצְצֵי וְעָאלִין דָּא בְּדָא, אִתְעֲבֵיד מִנַּיְיהוּ חַד גּוּפָא, וְאִיקְּרֵי חַשְׁמַל. אוּף הָכָא אִלֵּין ד' חַיּוֹת, כְּלִילָן דָּא בְּדָא.</p>"],[9514012700,"<p>בְּגִין דְּאִינוּן לְד' סִטְרִין. הַהוּא דְּלִסְטַר מִזְרָח, אִתְכְּלֵיל בִּסְטַר מַעֲרָב. וְהַהוּא דְּלִסְטַר מַעֲרָב, אִתְכְּלֵיל בִּסְטַר מִזְרָח. וְהַהוּא דְּלִסְטַר צָפוֹן, אִתְכְּלֵיל בִּסְטַר דָּרוֹם, וְהַהוּא דְּלִסְטַר דָּרוֹם, אִתְכְּלֵיל בִּסְטַר צָפוֹן. וְכֵיוָן דְּאִתְכְּלִילוּ כּוּלְהוּ דָּא בְדָא, אִתְעֲבֵיד מִנַּיְיהוּ חַד גּוּפָא, וְאִיהוּ רָזָא דְאִקְרֵי אָדָם. וְאַף עַל גַּב דְּכָל אַנְפִּין מִשְׁתַּנִּין בְּסִטְרַיְיהוּ.</p>"],[9514012701,"<p>וּמִגּוֹ אִלֵּין דְּאִינוּן רָזָא פְּנִימָאָה, לְגַבֵּי נְקוּדָה דְּקָיְימָא עֲלַיְיהוּ, נָפְקֵי כַּמָּה מַשִּׁרְיָין לְזִינַיְיהוּ.</p>"],[9514012702,"<p>אָדָם דְּכַר וְנוּקְבָא. אָת דְּאִיהוּ רָזָא, דְּכַר אִיהוּ אָת ן'. רָזָא דְאָדָם בִּשְׁלִימוּ. וְאָת דָּא שָׁלְטָא בִּנְקוּדָה דָא דְּאִיהוּ ד', עַל ד' חֵיוָן.</p>"],[9514012703,"<p>וּבְרָזָא דָא דְּאִיהוּ רָזָא פְּנִימָאָה דְּכֹלָּא, כָּל אִינוּן מַשִּׁרְיָין אָחֳרָנִין וְכָל אִינוּן חֵילִין אִקְרוּן בִּשְׁמָא דָא, דִּכְתִיב, (תהילים ס״ח:י״ח) אַלְפֵי שִׁנְאָן. וְאַף עַל גַּב דְּאוֹקְמוּהָ, אֲבָל רָזָא דָא, בְּגִין דְּנָפְקֵי מִגּוֹ רָזָא דְמוֹחָא פְּנִימָאָה, בִּכְלָלָא דְּכֹלָּא, שִׁנְאָ\"ן, רָזָא דְּמוֹחָא, שׁוֹר נֶשֶׁר אַרְיֵה, אָדָם כָּלֵיל לוֹן, אַכְלֵיל עַלַיְיהוּ ן'. אִתְחַבֵּר מוֹחָא כֹּלָּא כַּחֲדָא, בְּרָזָא פְּנִימָאָה, וְאִינוּן רָזָא שִׁנְאָ\"ן, וְעַל דָּא אִקְרוּן אַלְפֵי שִׁנְאָן.</p>"],[9514012704,"<p>וְכַד לְפוּם שַׁעֲתָא מִסְתַּכְּלִין, כְּתִיב, וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם. וּלְבָתַר מִתְפַּרְשׁוֹ דִּיוּקְנִין, כָּל חַד וְחַד לְסִטְרֵיהּ. וְכַד אִתְחַפְיָין כָּלְהוֹ, דְּלָא מִסְתַּכְּלִין לְעֵילָא, לְגוֹ רָזָא דַּעֲלַיְיהוּ, לָא אִתְחֲזֵי דְּיוּקְנָא כְּלָל, בַּר דְּיוּקְנָא דְּאָדָם, דְּדָא אִיהוּ דְּיוּקְנָא דְּכָלֵיל כָּל דִּיוּקְנִין. וְכָלְהוֹ סְתִימִין קַמֵּי הַאי דְּיוּקְנָא. בְּגִין כָּךְ, כָּל דִּיוּקְנִין דְּעָלְמָא כַּד מִסְתַּכְּלָן לִדְיוּקְנָא דְּאָדָם, כָּלְהוּ דַּחֲלֵי וְזָעאִין מִקַּמֵּי הַאי דְיוּקְנָא.</p>"],[9514012705,"<p>דְּיוּקְנָא עִילָּאָה דִּנְפַק מִגוֹ רָזָא עִילָּאָה, בְּגוֹ אַתְוָון רְשִׁימָן, אִיהִי רָזָא דְּאָדָם, וְכֹלָא כָּלֵיל בֵּיהּ. אָדָם כְּלָלָא דְכֹלָּא, בְּרָזָא דְּמִקְצֵה הַשָּׁמַיִם עַד קְצֵה הַשָּׁמַיִם, וְאִיהוּ אֶמְצָעִיתָא, וְתַתָּא, וְעֵילָא, כֹּלָּא בִּכְלָלָא חָדָא. ם סְתִימָא, לְעֵילָא, דְּכָלֵיל כֹּלָּא לְתַתָּא. ד' לְתַתָּא, דְּכָלֵיל כַּמָּה רְתִיכִין וּמַשִּׁרְיָין כַּחֲדָא. א רָזָא דְּכֹלָּא, בְּאֶמְצָעִיתָא, דְּנָטֵיל לְכָל סִטְרִין, בְּגִין כָּךְ, אָדָם, רָזָא דְּכֹלָּא, מִסִּטְרָא חָד לְסִטְרָא חָד. בַּר רָזָא עִילָּאָה, דְּקָיְימָא בְּמַחֲשָׁבָה וּרְעוּ, עַד דְּסָלְקָא לְאֵין סוֹף.</p>"],[9514012706,"<p>(יחזקאל א׳:ז׳) וְרַגְלֵיהֶם רֶגֶל יְשָׁרָה וְגו' דָּא אִיהוּ רָזָא, לְבָתַר דְּקָאֲמַר רָזִין דְּגוּפָא, אַהֲדַר וְנָחֵית לְתַתָּא בְּרַגְלִין, וּטְלָפִין.</p>"],[9514012707,"<p>אִלֵּין מָטוֹ עַד נִיצוֹצֵי דְּחַשְׁמַל, הַאי אִיהוּ חַשְׁמַל דִּלְבַר. בְּגִין דִּמְהַאי חַשְׁמַל, נָפְקִין אָחֳרָנִין דְּאִיקְּרוּן עַל שְׁמָא דָא, וְכָלְהוֹ נָפְקֵי, בְּשַׁעֲתָא דְּחַיּוֹת מְכַוְּונֵי רַגְלַיְיהוּ. וּמָטוֹ לְאִינוּן נִיצוֹצִין דְּחַשְׁמַל, כְּדֵין מְלַהֲטִים אִינוּן נִיצוֹצִין, סָלְקֵי וְנַחֲתֵי וְנָפְקֵי כָּל אִינוּן דְּאִקְּרוּן עַל שְׁמָא דָא.</p>"],[9514012708,"<p>חַשְׁמַל דָּא, מַקִּיף סְחוֹר סְחוֹר. נִצּוֹצִין דִּילֵיהּ נָחֲתִין לְתַתָּא, עַד הַהוּא אֲתַר דְּאִקְרֵי קַרְקַע זְעֵירָא. וְתַמָּן בְּהַהוּא קַרְקַע, רָהֲטֵי כָּל זִינֵי אַבְנִין דִּבְדוֹלְחָא, וּמַרְגְּלָאן נְצִיצִין, וְאַבְנִין דְּבָרֶקֶת.</p>"],[9514012709,"<p>וְכַד נָצֵיץ וְלָהֵיט נְהִירוּ דְּחַשְׁמַל, וְסָלֵיק וְנָחֵית, וּמִתְגַּפְּפָן אִינוּן ד' סִטְרִין דָּא עִם דָּא, נָהֵיר הַהוּא קַרְקַע זְעֵירָא, וְרָהֲטֵי אַבְנִין, וּמַרְגְּלָאן סָלְקִין, עַד דְּמָטָן לְגַבֵּי תַּרְעָא דְדָרוֹם. וְתַמָּן אוֹצְרִין סְתִימִין, וּפִיתְחָאן ד' מְאָה וְשִׁבְעִין, כְּחוּשְׁבַּן קַרְקַ\"ע. וּגְלִיצוּ\"ר מְמוּנֶה בְּהוּ.</p>"],[9514012710,"<p>בְּזִמְנָא דְהַאי חַשְׁמַל אַנְהֵיר נִצוֹצִין לְד' סִטְרִין, קָל חַד נָפֵיק מִלְּעֵילָא, וְאִיתְעַר מִבֵּין גַּדְפִין, כַּד אַקִישׁוּ דָּא עִם דָּא אִינוּן גַּדְפִין דְּאַשְׁמִיעוּ קָלָא, כְּמָה דְאַתְּ אָמֵר (שם) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם כְּקוֹל מַיִם רַבִּים. וּכְדֵין הַאי קָלָא כְּלִילָא בְּד' קָלִין, כַּד נָפַק פָּגַע בְּאִינוּן נִצוֹצִין, וְאִתְפְּלֵיג לְד' קָלִין.</p>"],[9514012711,"<p>קָל חַד אָזְלָא לִגְלִיצוּ\"ר, וְאִיתְעַר בְּהַהוּא קָלָא נְהִירוּ דְּחַשְׁמַל, וְאִתְעֲבֵיד מִנֵּיהּ דִּבּוּר חַד. וּבְהַהוּא דִּבּוּר אִיתְעַר דִּיבּוּרָא אָחֳרָא סְתִימוּ, בִּלְחִישׁוּ. וְכַד מָטֵי הַאי לִגְלִיצוּ\"ר, כְּדֵין אִתְגַּלְּיָין לֵיהּ, מָאתָן וְאַרְבַּע סְרֵי רָזִין עִילָּאִין דְּאִתְגַּלְיָאן.</p>"],[9514012712,"<p>קָלָא תִּנְיָנָא, אָזְלָא לַעֲנָאֵ\"ל, רַב מְמַנָּא עַל תְּמַנְסְרֵי אֶלֶף רִבּוֹא מַשִּׁרְיָין, מְשַׁמְשִׁין גּוֹ קַרְקַע אָחֳרָא, דְּאִיהוּ בִּנְהִירוּ דְּכָל גְּוָונִין, הַאי אִקְרֵי קַרְקַע דְּאַרְגְּוָונָא, נָהֵיר בְּכָל זִינֵי נְהוֹרִין דְּנָפְקֵי מֵהַאי חַשְׁמַל. וְתַמָּן בְּהַהוּא קַרְקַע, שְׁקִיעָן תְּרֵיסַר אֶלֶף רִבּוֹא מַרְגְּלָאן עִילָּאִין.</p>"],[9514012713,"<p>וְכַד סָלְקִין נְצִיצִין דְּחַשְׁמַל, וְעָאלִין דָּא בְּדָא, סָלְקִין כָּל אִינוּן מַרְגְּלָאן דְּאִינוּן שְׁקִיעָן בְּהַהוּא קַרְקַע, וּמָטוֹ לְגַבֵּי תַּרְעָא דְמִזְרָח. וְתַמָּן שִׁית אֶלֶף אַלְפִין תַּרְעִין פְּתִיחָן, וַעֲנָאֵ\"ל רַב מְמַנָּא בְּהוּ.</p>"],[9514012714,"<p>קָלָא כַּד אִיתְעַר מִלְּעֵילָא, בָּטַשׁ נְהִירוּ דְּהַאי חַשְׁמַל בֵּיהּ, וְאִתְעֲבֵיד מִנֵּיהּ דִּבּוּר, וּבְהַהוּא דִּבּוּר אִתְעַר דִּבּוּר אָחֳרָא סְתִימָא.</p>"],[9514012715,"<p>וְכַד מָטֵי הַאי לַעֲנָאֵ\"ל מְמַנָּא, כְּדֵין אִתְגַּלְּיָין תְּלַת מְאָה וְשִׁתִּין וְחָמֵשׁ רָזִין עִילָּאִין, דְּאִינוּן שְׁקִיעִים בְּגוּשְׁפַּנְקָא חוֹתָם אֱמֶת. כְּדֵין בְּאֵימְתָא בְּחִיל בְּרֶתֶת בְּזִיעַ, סָלְקִין שִׁירִין וְתוּשְׁבְּחָן לְמָארֵי כֹּלָּא. וּנְהִירוּ דְּרָשִׁים בְּשֵׁם הַמְּפוֹרָשׁ, בְּמ\"ב אַתְוָון מְחַקְּקָן, נַפְקָא מֵהַהוּא רַב סְגָנִין עַל כָּל שְׁאָר מַשִּׁרְיָין, וְסַנְדַּלְפוֹ\"ן אִקְרֵי, וְהַהוּא נְהִירוּ חַפְיָיא עַל אִינוּן ב' קַרְקָעֵי, מִקַּרְקַע זְעֵירָא וְעַד קַרְקַע דְּאַרְגְּוָונָא.</p>"],[9514012716,"<p>וְרָזָא דָא (מלכים א ז׳:ז׳) וְסָפוּן בָּאֶרֶז מֵהַקַּרְקַע וְעַד הַקַּרְקַע, סַנְדַּלְפוֹן אִקְרֵי הָכֵי, בְּגִין דְּתַמָּן עָאלִין כָּל רָזֵי פָּנִים עִילָּאִין, וְאַנְעִילוּ בֵיהּ, כְּהַאי סַנְדְלָא, דְּאִיהוּ אָעֵיל בְּגַוֵּיהּ כָּל יְסוֹדָא וְשָׁרְשָׁא דְגוּפָא.</p>"],[9514012717,"<p>דָּא רַב מְמַנָּא, מְשַׁמְשָׁא לְאִינוּן פָּנִים לְגוֹ. בְּהַאי חֲקִיקִין רָזִין דְּאַתְוָון רְשִׁימִין גְּלִיפִין, בָּלְטִין בְּהַהוּא נְהִירוּ דְּחַפְיָיאן עַל אִינוּן קַרְקָעֵי. כַּד הַאי קָשִׁיר כִּתְרִין לְמָארֵיהּ, אִינוּן אַתְוָון סָלְקִין בְּהַהוּא נְהִירוּ, וּמִתְעַטְרָן בְּאִינוּן כִּתְרִין וְהַדְּרָא הַהוּא נְהוֹרָא חַפְיָיא בְּאַתְרֵיהּ, וְאַתְוָון סָלְקִין בְּאִינוּן כִּתְרִין, בְּרָזָא דִשְׁמָא קַדִּישָׁא.</p>"],[9514012718,"<p>(יחזקאל א׳:ז׳) וְרַגְלֵיהֶם רֶגֶל יְשָׁרָה, מִתְחַבְּרָאן כַּחֲדָא, דְּאִינוּן כַּחֲדָא, לְמֵהַךְ בְּאוֹרַח מֵישָׁר, בְּרִגְּשַׁת חֲבוּרָתָא בְּמֵישַׁר כַּחֲדָא, וְרַגְלֵיהֶן בְּמֵישַׁר. וְעַל דָּא, לְחֵיזוּ נְבִיאָה בְּדַרְגִּין יְדִיעָאן.</p>"],[9514012719,"<p>וְכָלְהוֹ דַּרְגִין אִיקְּרוּן רַגְלֵי הַחַיּוֹת אַרַע מִנַּיְיהוּ. וּלְהוֹ כְּחֵיזוּ רַגְלִין בְּגוּפָא, בְּסִדְּרָא דְּקָא מְסַדְּרָא, וְאִיהוּ כֹּלָּא בְּשִׁיעוּרָא.</p>"],[9514012720,"<p>וְכַף רַגְלֵיהֶם כְּכַף רֶגֶל עֵגֶל, בְּחִיבּוּרָא דְּהַאי סִטְרָא. וְלֵית לוֹן אֶצְבְּעָן לְתַתָּא, בְּגִין דְּאֶצְבְּעָן לְתַתָּא אַחְזְיָין חֵילִין אָחֳרָנִין, בִּדְיוּקְנָא אוֹחֲרָא. וְעַל דָּא בַּר נָשׁ אַחֲזֵי בְּאֶצְבְּעָן חֵילִין אָחֳרָנִין לְעֵילָא בְּיָדִין, וְחֵילִין אָחֳרָנִין לְתַתָּא בְּרַגְלִין. וְאִלֵּין לָא רְשִׁימִין בְּגַוַּיְיהוּ חֵילִין אָחֳרָנִין דִּסְטַר אָחֳרָא, וְעַל דָּא אִקְרוּ רֶגֶל יְשָׁרָה, דְּסָתִים לְסִטְרָא דָא, וְאִינוּן כַּף אַחַת.</p>"],[9514012721,"<p>וְאַף עַל גַּב דְּלָא מִתְפָּרְשִׁין בִּפְרִישׁוּ דְּאֶצְבְּעָן בְּחֵילִין אָחֳרָנִין דִּסְטַר אוֹחֲרָא, אִית בְּהוּ רְשִׁימוּ חַד, לְמֵיהַב דּוּכְתָּא לִסְטַר אָחֳרָא, וְאִתְחַזְּיָין לְתַתָּא כְּכַף רֶגֶל עֵגֶל, אֲבָל לָא כַּף לְאַסְטָאָה, אַף עַל גַּב דְּאִינוּן רֶגֶל עֵגֶל, יְשָׁרָה אִיהוּ, דְּלָא אַסְטֵי לְעָלְמִין.</p>"],[9514012722,"<p>בְּהַהוּא רִגְּשָׁא, נְפַק נְצִיצוּ וְשַׁלְהוֹבָא לְסִטְרָא דָא לִשְׂמָאלָא, וְאִינוּן נְצִיצוּ וְשַׁלְּהוֹבָא מִתְחַבְּרָן כַּחֲדָא, וְנָצְצִין לְכָל עִיבַר, וְאִתְעֲבֵיד מִנַּיְיהוּ חֵיילִין וּמַשִּׁרְיָין, וְכָלְהוֹ אִיקְּרוּן רַגְלֵי הַחַיּוֹת, בְּגִין דְּנָפְקֵי מֵאִינוּן רַגְלִין. וְכָלְהוֹ אָזְלִין וְשָׁאטָן בִּשְׁלִיחוּתָא בְּעָלְמָא, לְאִתְלַבְּשָׁא בְּגוּפָא לְתַתָּא. וְאִתְחֲזוּן כְּאִינוּן אָחֳרָנִין דְּאִיתְחֲזוּן וְעָבְדֵי שְׁלִיחוּתָא בְּעָלְמָא, וּמְהַדְּרָן בְּרַמְשָׁא וּבְפַנְיָא, וּמַקְדְּשֵׁי שְׁמָא דְּמָארֵיהוֹן.</p>"],[9514012723,"<p>(שם) וּדְמוּת פְּנֵיהֶם פְּנֵי אָדָם, דְּמוּת הַהוּא דְּיוּקְנָא לְעֵילָא, לְאִצְטַיְירָא בְּצִיּוּרָא גְנִיזָא. פָּנִים קְלִיטִין בְּקוֹלְפִין דַּקִּיקִין. דְּמוּת אַנְפִּין דִּלְגוֹ צִיּוּרָא דְּיוּקְנָא דְּאָדָם, נָצֵיץ נְצִיצוּ דְּהַהוּא נְצִיצָא מְלַהֲטָא דִּלְגוֹ דְּחַשְׁמַל פְּנִימָאָה, דְּטָמִיר וְגָנִיז, הֲוֵי וְלָא הֲוֵי.</p>"],[9514012724,"<p>אוֹר נָצִיץ, אֶשָׁא לָהִיט, מְלַהֲטָא בְּשַׁלְהוֹבֵי דְּנוּרָא. רוּחָא מְנַצְצָא אָחִיד בְּגווָֹנֵי, קוּלְפָא בְּסוּטְרָא, גּוֹ כְּלִילָא חָדָא. אָחִיד לְעֵילָא, אָחִיד לְתַתָּא. גְּוָונוֹי אֲחִידוּ לְכַמָּה סִטְרִין.</p>"],[9514012725,"<p>גַּוָּון אוֹר גָּנִיז, אָחִיד נָהִיר וְנָצִיץ בִּנְצִיצוּ, וְהַאי אוֹר אָחִיד וְתָפִיס וְאָעֵיל לְגַבֵּיהּ נְהִירוּ דְּאֶשָׁא מְלַהֲטָא, וְשַׁלְהוֹבֵי נוּרָא, אִלֵּין תְּרֵין לָא מִתְיַשְּׁבָן כַּחֲדָא. וּמִגּוֹ מַרְגְּלָא דְּלָא אִתְגַּלְיָיא כְּלַל, נָפְקָא רוּחָא דְּבוּסְמָא, כְּלִילָא בִּתְרֵיסַר בּוּסְמִין עִילָּאִין, וּמִגּוֹ הַהוּא סְלִיקוּ דְּאִינוּן תְּרֵין דְּלָא מִתְיַשְּׁבָן כַּחֲדָא, אָחִיד בְּהוּ הַהוּא רוּחָא, וּמִתְיַשְּׁבָן בְּדוּכְתַּיְיהוּ.</p>"],[9514012726,"<p>וּכְדֵין, אִצְטַבַּע הַהוּא רוּחָא, מִגּוֹ הַהוּא נְהִירוּ דְּאוֹר גָּנִיז, וּנְהִירוּ דְּאֶשָׁא מְלַהֲטָא, וְאִתְיַשְּׁבָן וְקָיְימָא בֵּיהּ, כְּדֵין אִצְטַיְירוּ בֵּיהּ, צִיּוּרָא דִּפְנֵי אָדָם, דְּכָלֵיל כָּל דִּיוּקְנִין, וְהַאי אִיהוּ גַּוָּון דְּכָלֵיל כָּל גְּוָונִין. אַנְפִּין דְּכָלֵיל כָּל אַנְפִּין.</p>"],[9514012727,"<p>וְכַד אִינוּן מִתְתַּקְנָן כִּדְקָא יָאוֹת, לְגוֹ כָּרְסְיָיא, כָּלְהוֹ בִּדְיוּקְנָא חָדָא דְּאָדָם. וְרָזָא דָא, כַּד מִסְתַּכְּלִין לִסְטַר מִזְרָח, כָּלְהוֹ אִינוּן בִּדְיוּקְנָא חָדָא דְּאָדָם, בְּגִין דְּמִתַּמָּן אִיהוּ תְּקִיפוּ דְּרָזָא דְאָדָם.</p>"],[9514012728,"<p>וְכַד מִסְתַּכְּלִין לִסְטַר דָּרוֹם, כָּל אַנְפִּין אִינוּן בִּדְיוּקְנָא חָדָא, דְּיוּקְנָא דְּאַרְיֵה, דְּתַמָּן אִיהוּ חֵילָא וְתוּקְפָא דְּכֹלָּא. וְכַד מִסְתַּכְּלִין לִסְטַר צָפוֹן, כָּל אַנְפִּין אִינוּן בִּדְיוּקְנָא חָדָא, דְּיוּקְנָא דְשׁוֹר, דְּתַמָּן אִיהוּ נְגִיחוּ דְּדִינָא תַּקִּיפָא.</p>"],[9514012729,"<p>וְכַד מִסְתַּכְּלִין לִסְטַר מַעֲרָב, כָּל אַנְפִּין אִינוּן בִּדְיוּקְנָא חָדָא, בִּדְיוּקְנָא דְנֶשֶׁר. כְּמָה דְאַתְּ אָמֵר, (משלי ל׳:י״ט) דֶּרֶךְ הַנֶּשֶׁר בַּשָּׁמַיִם. בְּגִין דְּתַמָּן (דברים ל״ב:י״א) נֶשֶׁר יָעִיר קִנּוֹ עַל גּוֹזָלָיו יְרַחֵף. וְאוֹרַח דְּנֶשֶׁר, לְאִתְדַּבְּקָא תָּדִיר בַּשָּׁמַיִם, דְּתַמָּן אִיהוּ תֵּיאוֹבְתֵּיהּ לְאִסְתַּלָּקָא וּלְאִתְדַּבְּקָא. וּבְגִין כָּךְ אִיהוּ לִסְטַר מַעֲרָב.</p>"],[9514012730,"<p>וּבְגִין דְּכָל אַנְפִּין מִשְׁתַּנִּין, כְּפוּם הַהוּא אֲתַר דְּהַהוּא סִטְרָא דְּמִסְתַּכְּלָאן בֵּיהּ, כְּתִיב בְּכָלְהוֹ בְּכָל דְּיוּקְנָא וּדְיוּקְנָא, לְאַרְבַּעְתָּם. פְּנֵי אָדָם וּפְנֵי אַרְיֵה לְאַרְבַּעְתָּם פְּנֵי שׁוֹר לְאַרְבַּעְתָּן וּפְנֵי נְשֶׁר לְאַרְבַּעְתָּן.</p>"],[9514012731,"<p>הַאי כַּד מִתְתַּקְנָן בְּכָרְסְיָיא, כְּמָא דְּכָרְסְיָיא פָּנִי לְמֵיזַל, הָכֵי אִינוּן אִתְחַזְּיָין דְּיוּקְנַיְיהוּ, כְּפוּם הַהוּא סִטְרָא דְּאָזַל, כְּדִכְתִיב (יחזקאל א׳:י״ב) אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלְכוּ.</p>"],[9514012732,"<p>וְכַד לָא אָזְלִין וְלָא מִתְתַּקְנִין גּוֹ כָּרְסְיָיא, כְּדֵין כָּל חַד וְחַד אִתְפְּרַשׁ בִּדְיוּקְנֵיהּ דְּאִתְחֲזֵי לֵיהּ. וְעִם כָּל דָּא, כָּל חַד וְחַד אִתְדַּבַּק בִּדְיוּקְּנָא דְחַבְרֵיהּ, וְכָלְהוֹ אִתְחַזְּיָין דְּיוּקְנַיְיהוּ מִתְדַּבְּקוּ דָּא בְּדָא, וְדָא כָּלֵיל בְּדָא, כָּל חַד כָּלֵיל בְּחַבְרֵיהּ, וְחַבְרֵיהּ בֵּיהּ.</p>"],[9514012733,"<p>סִטְרָא חַד אוֹמֵר קָדוֹשׁ, וְסִטְרָא חַד אוֹמֵר קָדוֹשׁ, וְסִטְרָא חַד אוֹמֵר קָדוֹשׁ, וְסִטְרָא אוֹחֲרָא אוֹמֵר ה' צְבָאוֹת מְלֹא כָל הָאָרֶץ כְּבוֹדוֹ.</p>"],[9514012734,"<p>וִיהֵי אָדָם מִתַּחַת כַּנְפֵיהֶם, הַאי לְקַבְּלָא מָארֵיהוֹן דִּתְיוּבְתָּא לְגַבַּיְיהוּ, דְּהָא יָמִינָא דְקוּדְשָׁא בְּרִיךְ הוּא, פְּרִישָׂא לְקַבְּלָא כָּל אִינוּן דְּתָיְיבִין לְגַבֵּיהּ. מִתַּחַת כַּנְפֵיהֶם, אַמַּאי, בְּגִין צְנִיעוּ, דְּהָא מָארֵיהוֹן דִּתְיוּבְתָּא צְנִיעוּ אִצְטְרִיךְ, דְּלָא לְמִנְדַע בְּהוּ אַחֲרָא, כְּמָא דְאַתְּ אָמֵר (תהלים לב) כְּסוּי חֲטָאָה.</p>"],[9514012735,"<p>רָזָא דָא, דְּלָא סָלְקִין יְדַיְיהוּ לְעֵילָא, כְּמָא דִּבְנֵי נְשָׁא דְּיָדַיְיהוּ סָלְקִין לְעֵילָא עַל רֵישַׁיְיהוּ, וְהַנֵּי לָאו הָכֵי, דְּהָא מִתְּחוֹת גַּדְפַיְיהוּ לָא נָפְקֵי לְבַר, דְּהָא גַּדְפַיְיהוּ וְאַנְפַּיְיהוּ פְּרִידָן אִינוּן לְעֵילָא. כְּמָא דְאָמַר (יחזקאל א׳:י״א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרֻדוֹת מִלְמָעְלָה. דְּאִתְפָּרְשָׁן כַּד לָא מִתְתַּקְנָן גּוֹ כּוּרְסַיָיא כִּדְקָא אֲמָרָן. וְאִלֵּין יָדַיִן לָא אִתְחַזְּיָין כְּלַל לְסָלְקָא לְעֵילָא, מִגּוֹ דְּאִתְגַּלְּיָין, וְעַל דָּא מִתַּחַת כַּנְפֵיהֶם כְּתִיב.</p>"],[9514012736,"<p>וְכַד אִלֵּין נָטְלִין, גַּדְפַיְיהוּ מִתְחַבְּרָן כַּחֲדָא, לְמֶהֱוֵי בְּאֹרַח מֵישָׁר, לְנַטְלָא דָּא עִם דָּא כַּחֲדָא, בְּשַׁעֲתָא חָדָא, בְּזִמְנָא חָדָא, וְכָלְהוֹ כַּחֲדָא סָלְקִין לְכָרְסְיָיא לְעֵילָא.</p>"],[9514012737,"<p>וְאִינוּן דְּלָא יָדְעֵי לְאָן אֲתַר אָזְלִין וְלָא חָמָאן וְלָא מִסְתַּכְּלִין, זָעָאן, וּמֵהַהוּא זֵיעָא דִּלְהוֹן כַּד אִינוּן נָטְלִין, וְסָלְקִין לְכוּרְסְיָיא קַדִּישָׁא, אִתְעֲבֵיד מֵהַהוּא זֵיעָא נְהַר דִּינוּר, נָגִיד וְנָפֵיק.</p>"],[9514012738,"<p>וְהַהוּא זֵיעָא כִּנְטִילוּ דְּנָטְלֵי אִיהוּ. טִפִּין מְנַטְפִין מִד' גְּוָונֵי אֶשִׁין. אֶשָׁא חִוָּורָא, מְנַטְפָא אֶשָׁא סוּמְקָא, אֶשָׁא יְרוּקָא. אֶשָׁא סוּמְקָא, מְנַטְפָא אֶשָׁא אוּכְמָא, אֶשָׁא יְרוּקָא. אֶשָׁא יְרוּקָא מְנַטְפָא אֶשָׁא סוּמְקָא, אֶשָׁא חִוָּורָא. אֶשָׁא אוּכְמָא, מְנַטְפָא הַהוּא אֶשָׁא סוּמְקָא.</p>"],[9514012739,"<p>חִיוָּורָא תִּנְיָינָא, לָאו אִיהוּ הַהוּא חִיוָּורָא קַדְמָאָה. וְהַהִיא אֶשָׁא אוּכְמָא, לָאו אִיהִי הַהִיא אֶשָׁא אוּכְמָא קַדְמָאָה. וְכֵן כָּל גְּוָונִין, לָאו אִלֵּין כְּאִלֵּין, קַדְמָאָה, וְתִנְיָינָא, וּתְלִיתָאָה, וְכֵן כָּלְהוֹ.</p>"],[9514012740,"<p>בְּשַׁעֲתָא דְּנָטְפִין אִלֵּין אֶשִׁין, וְאִתְכְּלִילוּ לְאִתְחַבְּרָא כַּחֲדָא, סָלְקִין שַׁלְהוֹבִין מְלַהֲטָן, וּבָטְשֵׁי דָּא בְּדָא, וּמֵהַהוּא בְּטִישׁוּ דְּבָטְשׁוּ כַּחֲדָא, אִתְעֲבִידוּ כָּל אִינוּן מַלְאֲכֵי חַבָּלָה, דְּטָרְדֵי חַיָּיבַיָא בַּגֵּיהִנֹּם. מֵאִינִין שַׁלְהוֹבִין אִתְעֲבֵיד נוּרָא דְּגֵיהִנֹּם לְתַתָּא, דְּאִינוּן שְׁלִיחָן דְּחַבָּלָה, אִתְמַנּוּן בְּאִינוּן שַׁלְהוֹבִין, לְאוֹקְדָא חַיָּיבַיָא תַּמָּן, דְּרָזָא דִילְהוֹן תַּמָּן. דִּכְתִיב, (יחזקאל ט״ו:ז׳) מֵהָאֵשׁ יָצָאוּ וְהָאֵשׁ תֹּאכְלֵם.</p>"],[9514012741,"<p>כַד נָטְלִין, כָּלְהוֹן נָטְלִין לָקֳבֵל אַנְפּוֹי, דְּהַהוּא דְּאִתְמְנָא לְהַהוּא סִטְרָא. כַּד רוּחָא אִיתְעַר לְמֵיהַךְ לְסִטְרָא דְמִזְרָח, בָּטֵישׁ הַהוּא רוּחָא לְגַבֵּי אַנְפִּין דְּהַהוּא דְּקָיְימָא לְהַהוּא סִטְרָא, וְאִיהוּ נָטֵיל בְּקַדְמִיתָא, וְכָלְהוֹ עִמֵּיהּ כַּחֲדָא, דִּכְתִיב (שם א) וְאִישׁ אֶל עֵבֶר פָּנָיו יֵלֵכוּ אֶל אֲשֶׁר יִהְיֶה שָּׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ.</p>"],[9514012742,"<p>הַאי רוּחַ, אִיהוּ רוּחַ מְמַלְּלָא. רוּחַ דְּכָלֵיל כָּל רוּחִין בְּגַוֵּיהּ. רוּחַ טָמִיר וְגָנִיז בְּגַוַּויְיהוּ. רוּחַ דָּא, אִיהוּ רוּחַ דְּכָלֵיל בְּרָזָא דִּלְתַתָּא, לָקֳבֵל תְּלַת קִידּוּשִׁין דְּאִתְקַדַּשׁ בְּהוֹן כַּחֲדָא. וְאִינוּן קָדוֹשׁ קָדוֹשׁ קָדוֹשׁ, לָקֳבֵל תְּלַת זִימְנִין רוּחַ דִּכְתִיב הָכָא. אֶל אֲשֶׁר יִהְיֶה שָׁמָּה הָרוּחַ, חַד. עַל אֲשֶׁר יִהְיֶה שָׁם הָרוּחַ, תְּרֵי. שָׁמָּה הָרוּחַ לָלֶכֶת, תְּלַת. בְּגִין, דְּרוּחַ דָּא כָּלֵיל מִתְּלַת רוּחִין, רָזָא דְּחַיּוֹת הַקֹּדֶשׁ עִילָּאִין, דְּאִינוּן רָזָא דִּתְלַת קְדוּשָׁאן, דְּנָחֲתָא מֵהַהוּא קֹדֶשׁ עִילָּאָה, רוּחַ סְתִימָא, דְּכָל קְדוּשָׁאן מִנֵּיהּ תַּלְיָין.</p>"],[9514012743,"<p>(שם) וּדְמוּת הַחַיּוֹת מַרְאֵיהֶם כְּגַחֲלֵי אֵשׁ בֹּעֲרוֹת וְגו'. וּדְמוּת, דְּיוּקְנָא דְּמִתְלַבְּשָׁן בְּחַד מִנַּיְיהוּ, דְּאִתְלַבַּשׁ בְּנוּרָא. וְאִיהוּ לָא חָזָא, אֶלָּא דְּיוּקְנָא חֵיזוּ שַׁמָּשֵׁי דְּגַחֲלֵי דְנוּרָא.</p>"],[9514012744,"<p>גַּחֲלֵי אֵשׁ, אִלֵּין אִינוּן דְּאִיקְּרוּן מַרְאֵיהֶם, חֵיזוּ דְּחֵיוָן, דִּבְהוֹ אִסְתַּכְּלָן לְמֶיחֱמֵי בְּחֵיזוּ. כְּמַרְאֵה דְּאַחֲזֵי כָּל גְּוָונִין, הָכֵי שְׂרָפִים, אִינוּן כְּמַרְאֵה לְאַחֲזָאָה בְּהוֹן דִּיוּקְנִין דְּחֵיוָן. בְּגִין דְּכוֹלָא אִתְלַבַּשׁ דָּא בְּדָא, וְדָא מַרְאֶה דְּדָא.</p>"],[9514012745,"<p>אֲבָל וּדְמוּת הַחַיּוֹת, לֹא אָמַר דְּיוּקְנָא דִּילְּהוֹן, וְלָא אִיצְטְרִיךְ, דְּהָא בְּקַדְמִיתָא קָאָמַר כָּל דִּיוּקְנִין דִּילְּהוֹן. וְהָכָא אָמַר מֵאִינוּן דְּמוּת דִּלְּהוֹן דְּאִינוּן מַרְאוֹת דִּילְּהוֹן.</p>"],[9514012746,"<p>כְגַחֲלֵי אֵשׁ, מַאן גַּחֲלֵי אֵשׁ. אִלֵּין שְׂרָפִים. מַרְאֵיהֶם, אִינוּן אוֹפַנִּים, דִּבְהוֹן אִתְלַבְּשָׁן, לְאַחֲזָאָה דִּיוּקְנִין, וְחֵיזוּ דִּילְּהוֹן.</p>"],[9514012747,"<p>נְצִיצוּ דִּילְּהוֹן, בְּאִינוּן דְּאִיקְּרוּן לַפִּידִים. וּמַאן אִינוּן חַשְׁמַלִּים תַּתָּאִין, דְּנָפְקֵי מֵהַהוּא חַשְׁמַל תַּתָּאָה. רָזָא דָא, כְּרָזָא עִילָּאָה לְעֵילָא, בְּהַהוּא חַשְׁמַל פְּנִימָאָה, בְּגִין דְּכֹלָּא גּוָֹונָא חָדָא, מִתַּתָּא וְעֵילָא. עַד הָכָא רָזָא דְחַשְׁמַל, בִּגְוָונִין דְּלָא אִתְחַזּוֹן, אֶלָּא בְּחֵיזוּ. חֵיזוּ לְגוֹ מִן חֵיזוּ, חֵיזוּ דָּא לְגוֹ מִן דָּא. כְּמָא דִכְתִיב, מִמַּרְאֶה מָתְנָיו וּלְמַעְלָה וּמִמַּרְאֶה מָתְנָיו וּלְמַטָה.</p>"],[9514012748,"<p>הִיא מִתְהַלֶּכֶת בֵּין הַחַיּוֹת, דְּאִתְיְיהִיבַת בֵּין תְּרֵין סִטְרִין, וְאִתְחֲקָקַת תַּמָּן בְּגִלּוּפָא וּדְיוּקְנָהָא. דִּכְתִיב (שיר השירים ח׳:ו׳) שִׂימֵנִי כַּחוֹתָם עַל לִבֶּךָ וְגו'. וּמִגּוֹ דְּהַאי אֶבֶן טָבָא מַרְגָּלִיתָא, אָזְלָא בֵּין תְּרֵין סִטְרִין, אִית לָהּ נְהִירוּ לְאַנְהָרָא, וּלְסַלְקָא נְהוֹרָא. עַל כָּל שְׁאָר אַבְנִין מְנַצְּצָן.</p>"],[9514012749,"<p>וְנוֹגַהּ לָאֵשׁ, הַאי נוֹגַהּ אִיהוּ מִסִּטְרָא דְּיָמִינָא, וְאִתְכְּלֵיל בִּשְׂמָאלָא, וּשְׂמָאלָא בְּיָמִינָא, וְאֶשָׁא מְלַהֲטָא מְנַצְּצָא. מֵהַהוּא נוֹגַהּ נָהֵיר הַהוּא אַבְנָא, וְאִתְיְיהֵיב בָּהּ חֵיזוּ, לְאִסְתַּכְּלָא בְּשׁוּפְרָהָא.</p>"],[9514012750,"<p>וְהַאי נוֹגַהּ אִיהוּ נְצִיצוּ דִּנְצִיצָן כְּאֶשָׁא, וְנָהֵיר סוּמְקָא דִילֵיהּ. וּמִגּוֹ דָּא, בְּשַׁעֲתָא דְּעָאל וְנָקֵיב גּוֹ הַהוּא אַבְנָא, אִיהִי שַׁפִּירָא בְּחֵיזוּ.</p>"],[9514012751,"<p>בִּתְרֵין גְּוָונִין, אִתְחַזְּיָיא הַאי אַבְנָא וְאִצְטַבַּע, בְּגִין דְּאִיהוּ גַּוָּון חָשׁוּךְ בְּקַדְמִיתָא, כֵּיוָן דְּאִתְתַּקְנַת לְקַבְּלָא נְהוֹרָא, אִתְעַר נְהִירוּ מִסִּטְרָא דְיָמִינָא, וְאִתְנְהֵירַת בְּחִוָּורוֹ. כֵּיוָן דְאַנְהִירַת בְּחִוָּורוֹ כְּאַבְנָא בְּדוֹלְחָא, עַד כְּעָן לֵית לָהּ חֵיזוּ בְּשַׁפִּירוּ לְאִסְתַּכְּלָא, עַד דְּאָתָא סִטְרָא דִשְׂמָאלָא דְּהַהוּא נוֹגַהּ, דְּסוּמְקָא, וְעָאל בְּגַוֵּיהּ הַהוּא סוּמְקָא בְּהַהוּא נוֹגַהּ, כְּדֵין אִיהִי שַׁפִּירָא בְּחֵיזוּ, שַׁפִּירָא בְּרֵיוָא, לְאִסְתַּכָּלָא.</p>"],[9514012752,"<p>אִיהִי אַבְנָא יַקִּירָא בִּשְׁלֵימוּ בִּגְוָונִין. כְּאִתְּתָא שַׁפִּירָא בְּחֵיזוּ, חִוָּור וְסוּמָק. וּכְדֵין אַתְוָון מְנַצְּצָן בְּגַוָּהּ, וְנָפֵיק בְּגוֹ הַהוּא נְצִיצוּ בָּרָק מִבָּרֶקֶת, נָהֵיר לְפוּם שַׁעֲתָא, חִיוָּר וְסוּמָק, סוּמָק וְחִיוָּר.</p>"],[9514012753,"<p>רָזָא קַדִּישָׁא, לְאִצְטַבַּע שְׁאָר אַבְנִין מֵהַהוּא אַבְנָא טָבָא דְּאִקְרֵי בָּרֶקֶת. בְּגִין דְּאִצְטַבַּע מֵהַהוּא נְהִירוּ דְּבָרָק, אִיקְּרֵי עַל שְׁמֵיהּ בָּרֶקֶת. בְּגִין דְּהַאי אַבְנָא טָבָא, מַרְגָּלִיתָא עִילָּאָה, אִצְטַבַּע בִּתְרֵיסַר גְּוָונִין, מְנַהֲרִין גּוֹ אִינוּן תְּרֵין. מִגּוֹ נְצִיצוּ דְּנָצִיץ וְאַפֵּיק, אִצְטַבְּעָן תְּרֵיסַר אַבְנִין דִּילָהּ, וְאִינוּן תְּלַת סִדְרִין. וּכְפוּם דְּאִצְטַבְּעוּ מִינָהּ, הָכֵי אִקְּרוּן עַל הַהוּא שְׁמָא מַמָּשׁ.</p>"],[9514012754,"<p>(יחזקאל א׳:י״ד) וְהַחַיּוֹת רָצוֹא וָשׁוֹב, נְהִירִין גְּנִיזִין גַּלְיָין, וּסְתָרִין קָיְימִין וְלָא קָיְימִין, נָהֲרִין וְלָא נָהֲרִין. זִמְנִין נָהֲרִין בְּהַאי גָּוָון, וּלְפוּם שַׁעֲתָא גָּוָון אָחֳרָא. הַשְׁתָּא שְׁמָא דָא, וּלְפוּם שַׁעֲתָא שְׁמָא אָחֳרָא. לֵית מַאן דְּיָכֵיל לְקָיְימָא בְּאִלֵּין נְהוֹרִין.</p>"],[9514012755,"<p>יהו\"ה, נְהִירוּ דְּאִסְתַּלַּק בִּשְׁמָא דָא, דְּכָלֵיל כָּל נְהוֹרִין בִּשְׁלִימוּ. וּלְפוּם שַׁעֲתָא, נָחֵית וְאִתְהַדַּר נְהִירוּ בְּגָוָון אוֹחֲרָא, וְאִסְתַּלַּק בִּשְׁמָא אָחֳרָא, אֱלֹהִי\"ם. וּלְפוּם שַׁעֲתָא, אֵ\"ל. וּלְפוּם שַׁעֲתָא, צְבָאוֹ\"ת. וּלְפוּם שַׁעֲתָא שַׁדַּ\"י. וְהָכֵי בְּכָל אִינוּן שְׁמָהָן דְּאִיקְּרֵי בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא.</p>"],[9514012756,"<p>וּבְגִין דְּאִית אֲתַר גָּנִיז דְּנַפְקֵי מִנַּיְיהוּ, וּכְפוּם דְּאִיהוּ נְבִיעַ מִגּוֹ מַבּוּעָא גָּנִיז דְּאִתְגְּנִיז בֵּיהּ, הָכֵי אִתְחֲזֵי כָּל חַד. וְלֵית מַאן דְּיָקוּם בְּהוּ. וְרָזָא דָא מָנָא דְמַיָיא וְשִׁמְשָׁא, בְּכוֹתְלָא.</p>"],[9514012757,"<p>וּכְמָא דְּאִינוּן רָצוֹא וָשׁוֹב, אוּף הָכֵי בְּלִבָּא וְדַעְתָּא. בַּר נְבִיאֵי מְהֵימְנֵי, דְּמִסְתַּכְּלֵי מִגּוֹ אִינוּן דִּלְתַתָּא, דְּאִינוּן בְּרָזָא דְּאַסְפַּקְלַרְיָא דְּלָא נָהֲרָא, וּמִגּוֹ אִלֵּין הֲווֹ מִסְתַּכְּלִין כְּבָתַר כּוֹתְלָא. עַד הָכָא דְּמוּת מֵאִינוּן רָזִין לְעֵילָא וְהַשְׁתָּא לְתַתָּא.</p>"],[9514012758,"<p>כְתִיב (שם) וָאֵרֶא הַחַיּוֹת וְהִנֵּה אוֹפַן אֶחָד בָּאָרֶץ וְגו'. וָאֵרֶא הַחַיּוֹת, דָּא אִיהוּ אִסְתַּכְּלוּתָא בְּאַסְפַּקְלַרְיָא דְּלָא נָהֲרָא. וּמִגּוֹ דְּחָמָא אִלֵּין, אִסְתַּכֵּל בַּמֶּה דְּגָנִיז וְסָתִים.</p>"],[9514012759,"<p>וְהִנֵּה אוֹפַן אֶחָד בָּאָרֶץ, דָּא מטטרו\"ן, דְּאִיהוּ עִילָּאָה מִנַיְיהוּ ת\"ק שְׁנִין. מטטרו\"ן, מיטטרו\"ן, זְבוּל, עבד, זבוְאָמַר לֵיהּ, הָא חָמֵשׁ. וּכְפוּם שְׁלִיחוּ דְּמָארֵיהּ, הָכֵי אַסְגִּיאוּ שְׁמוֹי לְד' סִטְרוֹי, כְּד' סִטְרִין דְּעָלְמָא.</p>"],[9514012760,"<p>קָשִׁיר קְשָׁרִין לְמָארֵיהּ, שַׁלִּיט בְּרָזִין דְּאַרְבַּע אֶלֶף וַחֲמֵשׁ מְאָה נַהֲרֵי אֲפַרְסְמוֹנָא, דְּנָגְדִין וְנָפְקִין מִגּוֹ תְּלֵיסַר אָחֳרָנִין גְּנִיזִין. וְאַרְבָּעָה אֶלֶף וְת\"ק רִבּוֹא הֵיכָלִין, דְּאִינוּן טְמִירִין בְּגוֹ אִינוּן נְהִירִין, קָיְימִין קַמֵּיהּ, וְאִיהוּ מְמַנָא עֲלַיְיהוּ.</p>"],[9514012761,"<p>כָל זִמְנָא דְּעָאל וְנָפֵיק, אֶלֶף וְת\"ק רְקִיעִין זָעאִין קַמֵּיהּ. תְּרֵיסַר אַלְפֵי רִבּוֹא מִיָּמִינֵיהּ, וּתְרֵיסַר אַלְפֵי רִבּוֹא מִשְׂמָאלֵיהּ. תְּרֵיסַר אַלְפֵי רִבּוֹא קַמֵּיהּ, תְּרֵיסַר אַלְפֵי רִבּוֹא מֵאֲחוֹרֵיהּ. כָּל הַנֵּי מַשִּׁרְיָין נָהֲרִין, מִגּוֹ שַׁלְּהוֹבָא חַד מְנַצְּצָא. דְּנָפְקָא מִנֵּיהּ. וּבְהַהוּא שַׁלְּהוֹבָא חֲקִיקָן אַתְוָון דְּשֵׁם הַמְפוֹרָשׁ, נְצִיצִין מְלַהֲטִין מִגּוֹ הַהוּא שַׁלְּהוֹבָא. וְכָלְהוֹ כַּד מִסְתַּכְּלָאן בִּנְהִירוּ דְּאַתְוָון מְחַקְּקָן גְּלִיפָן, כָּלְהוֹ זָעאִין וְדָחֲלִין, וְנָטְלִין לְגַבֵּי הַהוּא נְצִיצוּ דְּאַתְוָון.</p>"],[9514012762,"<p>וּמִגּוֹ שַׁלְהוֹבָא דָא, נָהֲרִין אוֹפַנִּים אוֹחֲרָנִין, דְּנָטְלֵי בִּרְתִיכִין אָחֳרָנִין לְתַתָּא, גּוֹ אִינוּן הֵיכָלִין, דְּאִינוּן מְשַׁלְּבָן דָּא בְּדָא, כְּמָה דְאַתְּ אָמֵר כַּאֲשֶׁר יִהְיֶה הָאוֹפָן בְּתוֹךְ הָאוֹפָן, כְּלֵיל דָּא בְּדָא, וְעָאל דָּא בְּדָא, רֵישִׁין בְּרֵישִׁין, אִלֵּין בְּאִלֵּין. וְאַנְפִּין פְּרִישָׂן בְּסִטְרַיְיהוּ.</p>"],[9514012763,"<p>וְכָלְהוֹ נָטְלִין לְגַבֵּי אַנְפִּין, בְּגוֹ נְהִירוּ דְּמִסְתַּכְּלָאן לְגַבֵּי אִינוּן אַנְפִּין. כַּד מִסְתַּכְּלָאן לְמֵהַךְ, חָמָאן הַהוּא נְהִירוּ דְּנָהֵיר, לְהַהוּא אֲתַר דְּנָהֵיר, אָזְלִין וְנָטְלִין כָּלְהוֹ. וְאַתְוָון דִּשְׁמָא קַדִּישָׁא מְחַקְּקָא, נָהֵיר עַל כֹּלָּא. וְאִיהוּ נָטֵיל כָּלְהוֹ, גּוֹ הַהוּא רוּחָא עִילָּאָה, דְּנָטֵיל כָּל מַשִּׁרְיָין.</p>"],[9514012764,"<p>וּמטטרו\"ן רַב מְמַנָּא, קָאִים בְּקִיּוּמָא דְּהַהוּא שְׁמָא קַדִּישָׁא, וְנָטֵיל לְכָל מַשִּׁרְיָין בְּרָזָא דִילֵיהּ, לְד' פָּנָיו, בְּד' דִּיוּקְנִין, גּוֹ ד' סִטְרִין דְּעָלְמָא. וְאִיהוּ כָּלֵיל שְׁמָא דְאִקְרֵי שַׁדַּ\"י. וְכָלְהוֹ קָרָאן שְׁמָא דָא, גַּבֵּי שְׁמָא עִילָּאָה קַדִּישָׁא.</p>"],[9514012765,"<p>בִּיהָא דְּמטטרו\"ן אִתְמַסְרוּ תְּרֵיסַר מַפְתְּחִין עִילָּאִין, בְּרָזָא דִּשְׁמָא קַדִּישָׁא. וְד' מַפְתְּחָן מִנַּיְיהוּ, אִינוּן ד' רָזִין נְהוֹרִין דְּמִתְפָּרְשָׁן. מַפְתְּחָא חָדָא, אִיקְּרֵי אוֹר נָצֵיץ, טָמִיר וְגָנִיז, לֵית לֵיהּ גָּוָון. וְהַהוּא נְצִיצוּ לָא קָיְימָא לְאִסְתַּכְּלָא, וְלָא אִתְחֲזֵי גָוָון, אֶלָּא נָצֵיץ נְצִיצוּ לְעַיְינִין, וְאִגְנִיז וְלָא אִתְיְידַע. מַפְתְּחָא תִּנְיָינָא, אוֹר נְהִירוּ חֵידוּ לְאִסְתַּכְּלָא. לְזִמְנִין אִיהוּ חִיוַּר, לְזִמְנִין יָרוֹק, לְזִמְנִין לָא דָא וְלָא דָא.</p>"],[9514012766,"<p>מַפְתְּחָא תְּלִיתָאָה, אִיקְּרֵי אוֹר זוֹהֵר, דְּזָהֵיר וְנָהֵיר, אִיהוּ זוֹהַר דְּנָהֵיר לְכָל שְׁאָר נְהוֹרִין. הַאי מְרַקְמָא בְּכָל גְּוָונִין. הַאי אוֹר אִיהוּ מֵהַהוּא זוֹהַר דְּהוּא רָקִיעַ דְּעַל גַּבֵּי חֵיוָן, דִּכְתִיב (דניאל י״ב:ג׳) כְּזֹהַר הָרָקִיעַ. כָּלֵיל גּוֹ עֶשֶׂר שְׁבִילִין, דְּנָפְקֵי מֵאִינוּן ל\"ב שְׁבִילִין גְּנִיזִין.</p>"],[9514012767,"<p>מַפְתְּחָא רְבִיעָאָה, אִיקְּרֵי אוֹר דְּסוּכְלְתָנוֹ, דִּיהַב סוּכְלְתָנוֹ בְּלִבָּא לְמִינְדַע וּלְאִסְתַּכָּלָא וּלְקָיְימָא עַל רָזִין עִילָּאִין. וְהַאי אוֹר דְּחָדֵי לִבָּא, יָהֵיב נְהִירוּ דְּחָכְמְתָא וְסוּכְלְתָנוֹ, לְמִינְדַּע וּלְאִסְתַּכְּלָא.</p>"],[9514012768,"<p>וְאִלֵּין אִינוּן ד' מַפְתְּחָן עִילָּאִין, דְּכָל שְׁאָר מַפְתְּחָן כְּלִילָן בְּהוּ. וְכָלְהוֹ אִתְמָסְרוּ בִּידָא דְּהַאי רַב מְמַנָּא, מטטרו\"ן. מָארֵי רַב כָּלְהוֹ רָזִין דְּמָארֵיהּ, בְּגִילּוּפִין דְּרָזִין דִּשְׁמָא קַדִּישָׁא מְפוֹרָשָׁא.</p>"],[9514012769,"<p>עַל אַרְבַּעַת רִבְעֵיהֶן בְּלֶכְתָּם יֵלֵכוּ וְגו', עַל אַרְבַּעַת דְּאִינוּן ד' דִּתְחוֹתַיְיהוּ, וְאִינוּן דִּתְחוֹתַיְיהוּ, אִיקְּרוּן רִבְעֵיהֶן. כְּמָה דְאַתְּ אָמֵר, רְבִיעַ תְּחוֹת טוֹעֲנֵיהּ, וְעַל אִינוּן דִּרְבִיעִין תְּחוֹתַיְיהוּ, כַּד אִינוּן בָּעָאן לְמֵיזַל אָזְלִין. דְּכָל חַד אִית לֵיהּ ד' גַּלְגַּלֵּי אוֹפַנִּים, רְבִיעִין תְּחוֹתַיְיהוּ. וְעַל אִלֵּין רִבְעֵיהֶן אָמַר, בְּלֶכְתָּם יֵלֵכוּ.</p>"],[9514012770,"<p>וְהַיְינוּ דִכְתִיב, (יחזקאל א׳:י״ט) וּבְלֶכֶת הַחַיּוֹת יֵלְכוּ הָאוֹפַנִּים אֶצְלָם, וּבְהִנָּשֵׂא הַחַיּוֹת כו' יִנָּשְׂאוּ הָאוֹפַנִּים. וְאִי אוֹפַנִּים רִבְעֵיהֶם דְּחַיּוֹת, אִצְטְרִיךְ לְמֵימַר וּבְלֶכֶת הָאוֹפַנִּים. אֶלָּא מִכָּאן דְּחַיּוֹת נָטְלִין לִדְנָטְלִין לוֹן, כְּגַוְונָא דָא אָרוֹן, נָטֵיל לְמַאן דְּנָטֵיל לֵיהּ.</p>"],[9514012771,"<p>כָרְסְיָיא קַדִּישָׁא נְטָלַת לַחַיּוֹת. וְאִי אִיהִי נְטֵילַת לוֹן, זֵיעָא דְחַיּוֹת מִמָּה אִתְעֲבֵיד. אֶלָּא זֵיעָא דִילְּהוֹן, בְּאִסְתַּכְּלוּתָא לְמִינְדַע וּלְאִסְתַּכְּלָא וּלְאַדְבְּקָא, בַּמֶּה דְּטָמִיר וְגָנִיז, וְלָא יָכְלִין לְמֵיקַם בֵּיהּ. וְעַל דָּא אִיהוּ זֵיעָא דִּילְּהוֹן. אֲבָל כָּל אִינוּן דְּמִתְדַּבְּקָאן בִּקְדוּשָּׁה עִילָּאָה, אִינוּן נָטְלִין לְאִינוּן דְּנָטְלִין לוֹן. וְרָזָא דָא, עַל אַרְבַּעַת רִבְעֵיהֶן בְּלֶכְתָּם יֵלֵכוּ.</p>"],[9514012772,"<p>(שם) וְגַבֵּיהֶן וְגֹבַהּ לָהֶם. וְגַבֵּיהֶם, רָזָא דִּגְוָונִין דְּגוּפָא, אִתְנְהֵיר וְסָלְקָא בְּשִׁיעוּרָא מֵרֵישָׁא דְּבוּצִינָא לְרֵישָׁא דְּבוּצִינָא כְּשִׁיעוּרָא דִלְתַתָּא. וְאִסְתַּחֲרָא בְּאַרְבַּע גְּוָונִין נְצִיצִין. גָּוָון נָהֵיר בִּנְהִירוּ, בְּרָזָא דְּחַשְׁמַל לְעֵילָא, כַּד נָהֵיר וְאִתְגְּנֵיז גוֹ גְּוָונוֹי. גָּוָון נָצֵיץ, דְּנָצֵיץ בִּנְצִיצֵי. גָּוָון זָהֵיר, בְּזָהֲרָא דִרְקִימוּ דִּרְקִיעָא דְּקָיְימָא עֲלַיְיהוּ. גָּוָון מְרַקְמָא מִכָּל גְּוָונִין, וְאִתְכְּלֵיל בְּכָלְהוֹ, וְדָא אִיהוּ גּוּפָא מְצַיְירָא בְּצִיּוּרָא, לְאִתְכַּלְּלָא בִּכְלָלָא חָדָא.</p>"],[9514012773,"<p>וְגוֹבַהּ לָהֶם, מִסִּטְרָא דִלְעֵילָא. וְיִרְאָה לָהֶם, מִסִּטְרָא דִלְתַתָּא. וְגוֹבַהּ לָהֶם, גוֹבַהּ שָׁמַיִם. וְיִרְאָה לָהֶם, דְּחִילוּ דְּדָחֵיל וּמַבְעֵית וְאַרְעֵישׁ כּוֹלָּא. דְּחִילוּ דְּסָחֲרָא דְּלָא לְקָרְבָא לְקוּדְשָׁא. וְאִיהוּ דְּסָחֲרָא לוֹן מִסִּטְרָא דִלְתַתָּא.</p>"],[9514012774,"<p>וְגוֹבַהּ לָהֶם, בִּסְלִיקוּ דְּחֵיזוּ דְּגַוְונֵי שָׁמַיִם. בְּגִין דְּגַוְונֵי שָׁמַיִם, הַהוּא רָזָא דִכְתִיב, גוֹבַהּ שָׁמַיִם. וּמַאן אִיהוּ. דְּנָטֵיל כָּל גְּוָונִין, מִיָּמִינָא וּמִשְׂמָאלָא, וְכַד נָטֵיל לוֹן לְגַבֵּיהּ, אִיקְּרֵי גּוֹבַהּ שָׁמַיִם.</p>"],[9514012775,"<p>וְיִרְאָה לָהֶם, בְּחֵיזוּ דְּהַהוּא יִרְאָה לְתַתָּא, בְּסִדּוּרָא דְּאִינוּן גְּוָונִין לָהֲטִין וּמְהַפְּכִין חֵיזוּ דְּאֶשָׁא דְּלָא דַּקִּיק, כְּאֶשָׁא דַּקִּיק לְעֵילָא. וְהַאי אִיהוּ דְּקָא מַבְעִית לְכֹלָּא. וּבְגִין כָּךְ, וְגוֹבַהּ לָהֶם, מִלְּעֵילָא. וְיִרְאָה לָהֶם, מִתַּתָּא.</p>"],[9514012776,"<p>וְגַבּוֹתָם מְלֵאוֹת עֵינַיִם, לְאִסְתַּכְּלָא בְּכָל סִטְרִין. וְאַף עַל גַּב דְּאִית מָארֵי דְעֵינַיִם בְּחֵיזוּ לְאִסְתַּכָּלָא אָחֳרָנִין לְתַתָּא, אִלֵּין בְּאִינוּן עַיְינִין לְאִסְתַּכָּלָא אִלֵּין בְּאִלֵּין בְּסַחֲרָנוֹ, לְקַמַּיְיהוּ וּבַאֲחוֹרָא, דְּעַיְינִין סָחֲרִין לְכָל סִטְרִין.</p>"],[9514012777,"<p>וּבְּגִין כָּךְ חָמָאן הָכָא וְהָכָא, בְּסִטְרָא דָא וּבְסִטְרָא דָא, חָמָאן מַה דַּהֲוֵי, וּמַה דְּזַמִּין לְמֶהֱוֵי מִסִּטְרָא דַּאֲחוֹרָא. וְהַיְינוּ דִכְתִיב סָבִיב. וְחָמָאן מִיָּמִינָא וְחָמָאן מִשְׂמָאלָא. חָמָאן מִיָּמִינָא, בְּכָל אֹרַח זְכוּ וּקְשׁוֹט. חָמָאן מִשְּׂמָאלָא, בְּכָל אוֹרַח דְּלָא קְשׁוֹט וְלָא קָיְימָא בִּזְכוּ. וְעַל דָּא מִסְתַּכְּלָן בְּכָל סִטְרִין, וּבְדָא אִית לוֹן שׁוּלְטָנֵי וְסוּכְלְתָנוֹ עַל כּוֹלָּא, לְאִסְתַּכָּלָא בְּכָל הַנֵּי סִטְרִין, מַה דְּלָא מִסְתַּכְּלִין הָכֵי כָּל אִינוּן אָחֳרָנִין.</p>"],[9514012778,"<p>וְעִם כָּל דָּא לָא יָכְלִין לְאִסְתַּכְּלָא לְעֵילָא, וְלָא אִתְיְיהֵיב לוֹן רְשׁוּ לְאִסְתַּכָּלָא. וְכַד בָּעָאן לְאִסְתַּכָּלָא, כָּלְהוֹ מְרַתְּתֵי בִּדְחִילוּ בְּאֵימְתָא בְּזִיעַ, וְכָלְהוֹ קָרָאן בִּדְחִילוּ סַגֵּי, בְּקָל רַב, (שם ג) בָּרוּךְ כְּבוֹד ה' מִמְּקוֹמוֹ.</p>"],[9514012779,"<p>וְגַבֵּיהֶם, וְלָא כְתִיב מַהוּ, כְּמָא דִכְתִיב לְבָתַר, וְגַבֹּתָם מְלֵאֹת עֵינַיִם. אֶלָּא גּוּפָא דְסִטְרָא דְּמִסְתַּכְּלָא לְגוֹ, לְגַבֵּי נְקוּדָה סְתִימָא. מֵהַהִיא סִטְרָא אִית לוֹן גּוֹבַהּ. וְכָלְהוֹ מִסְתַּכְּלִין לְגוֹ, כְּמָה דְאַתְּ אָמֵר (מלכים א ז׳:כ״ה) וְכָל אֲחֹרֵיהֶם בָּיְתָה.</p>"],[9514012780,"<p>אַבְרָהָם אִתְקְרֵיב לְגַבֵּי רָזָא דְקָיְימָא, עַד דְּסָלֵיק בְּרָזָא עִילָּאָה לְעֵילָא. וְעִם כָּל דָּא לָא זָכָה כְּיַעֲקֹב, דְּיַעֲקֹב אִיקְּרֵי אִישׁ תָּם. מַהוּ אִישׁ תָּם, רָזָא דָא כְּמָא דְּאִתְּמָר, אִישׁ הָאֱלֹהִים, מָארֵיהּ דְּבֵיתָא. משֶׁה אִקְּרֵי אִישׁ הָאֱלֹהִים, יַעֲקֹב אִקְּרֵי אִישׁ תָּם, וְכֹלָּא רָזָא חָדָא.</p>"],[9514012781,"<p>אוּף הָכֵי וְגַבּוֹתָם, הַהוּא דְּקָיְימָא לְגוֹ. כָּלְהוֹ מָלְיָין עַיְינִין לְאִסְתַּכָּלָא לְבַר. וְאַף עַל גַּב דְּלָא מִסְתַּכְּלָא לְגוֹ, גּוֹבַהּ לָהֶם, וְגַבּוֹתָם מְלֵאוֹת עֵינַיִם.</p>"],[9514012782,"<p>(יחזקאל א׳:י״ט) וּבְלֶכֶת הַחַיּוֹת יֵלְכוּ הָאוֹפַנִּים אֶצְלָם וּבְהִנָּשֵׂא הַחַיּוֹת מֵעַל הָאָרֶץ יִנָּשְׂאוּ הָאוֹפַנִּים, וְכָלְהוֹ כְּפוּם הַהוּא רוּחָא, דְּאָזִיל וְשָׁלֵיט עֲלַיְיהוּ.</p>"],[9514012783,"<p>(שם) עַל אֲשֶׁר יִהְיֶה שָׁם הָרוּחַ לָלֶכֶת, כְּתִיב (שם) אֶל אֲשֶׁר, וּכְתִיב עַל אֲשֶׁר. אֶלָּא רוּחַ דָּא דְּנָפֵיק מִגּוֹ רוּחָא סְתִימָאָה, וְדָא אִיהוּ רוּחַ קַדִישָׁא, כַּד נָפֵיק מִגּוֹ הַהוּא טְמִירָא דְּכוּרְסְיָיא, וּבָטֵישׁ בְּהַהוּא דְּשָׁרֵי עֲלוֹי, כְּדֵין כָּלְהוֹ נָטְלִין כַּחֲדָא לְגַבֵּיהּ, וְהַיְינוּ עַל אֲשֶׁר. אֶל אֲשֶׁר, דְּבָטֵישׁ בֵּיהּ הַהוּא רוּחָא, וְלָא שָׁארֵי, אֶלָּא דְּנָטֵיל לְגַבֵּיהּ, וְנָטְלֵי כָּלְהוֹ לְגַבֵּי הַהוּא סִטְרָא.</p>"],[9514012784,"<p>עַל אֲשֶׁר יִהְיֶה שָׁם הָרוּחַ לָלֶכֶת, עַל: הַהוּא אֲתַר טָמִיר וְגָנִיז. דְּהַהוּא רוּחָא עִילָּאָה שַׁרְיָא עֲלוֹי, כָּלְהוֹ מִסְתַּכְּלָן לְגַבֵּיהּ, לְאִתּוֹסְפָא זִיוָא. וּמֵהַהוּא זִיוָא, אִתּוֹסַף זִיוָא אִינוּן קַרְנֵי הַחַיּוֹת. וְאִינוּן זִיוָא דְּלָהֵיט וְנָצֵיץ, לְפוּם אִסְתַּכְּלוּתָא דִּיְקָרָא, דְּהַהוּא רוּחַ אָחֳרָא, דְּנָפֵיק מֵהַאי רוּחַ קַדְמָאָה, דְּאִיהוּ טָמִיר וְגָנִיז בִּגְנִיזוּ יְקָרָא.</p>"],[9514012785,"<p>דָּא אִיהוּ בְּרָזָא דִשְׁמָא קַדִּישָׁא, דְּכָלֵיל בֵּיהּ שֵׁם אהי\"ה, שְׁמָא רַבָּה וְשַׁלִּיטָא. מֵהַאי שְׁמָא, זָעאִין וְדָחֲלִין, וְנָטְלִין בְּאֵימְתָא בְּזִיעַ. וְדָא אִיהוּ שְׁמָא דְּשַׁלִּיט עַל רְתִיכָא דָּא, בִּרְשִׁימוּ דִּתְלַת שְׁמָהָן דִּכְלִילָן בֵּיהּ. בְּרָזָא דָא אִית שִׁבְעִין שְׁמָהָן מְפוֹרָשִׁין, שַׁלִּיטִין עַל כָּל רָזִין וּגְנִיזִין עִילָּאִין, דִּי כָּל חֵילִין וּמַשִּׁרְיָין זָעָאן מִנַּיְיהוּ, וְנָטְלֵי בְּגִינַיְיהוּ. בְּרָזָא דָא, כְּלִילָן כ\"ב אַתְוָון, וְכָלְהוֹ שְׁבִילִין.</p>"],[9514012786,"<p>רוּחַ אָחֳרָא דְּנָפֵיק מֵהַאי רוּחָא קַדְמָאָה, אִיהוּ דְּמִתַּמָּן רָזָא דִּמְהֵימְנוּתָא בְּכָל סִטְרִין. וְדָא אִיהוּ בְּרָזָא דִּשְׁמָא קַדִּישָׁא, דְּכָלִיל וְרָשִׁים עֲלֵיהּ, שְׁמָא דְּאִקְרֵי יהו\"ה, דְּנָפֵיק וְאִתְרְשֵׁים מִגּוֹ שֵׁם אהי\"ה. וְאַף עַל גַּב דְּכֹלָּא בְּרָזָא חָדָא, אֲבָל שֵׁם יהו\"ה בִּנְיַן אָב, דְּאִתְבְּנֵי מִשְּׁמָא טְמִירָא אהי\"ה. וְדָא אִיהוּ רָזָא, דְּנָפֵיק מֵרוּחָא קַדְמָאָה.</p>"],[9514012787,"<p>רוּחָא אָחֳרָא תַּתָּאָה, דְּנָפֵיק מִגּוֹ רוּחָא דָא, דָּא אִיהוּ בְּרָזָא דִשְׁמָא קַדִּישָׁא כָּלִיל בֵּיהּ שֵׁם אדנ\"י. שְׁמָא דָא שַׁלִּיט, עַל חַיּוֹת וְאוֹפַנִּים לְתַתָּא.</p>"],[9514012788,"<p>וְהָכֵי אִיהוּ רָזָא עִילָּאָה וְתַתָּאָה. עִילָּאָה שֵׁם אהי\"ה, שַׁלִּיט עַל אִינוּן חֵיוָון עִילָּאִין, בְּרָזָא דִשְׁמָא קַדִּישָׁא דְּקָאֲמָרָן. תַּתָּאָה שֵׁם אדנ\"י, שַׁלִּיט עַל אִלֵּין חֵיוָון תַּתָּאִין לְתַתָּא.</p>"],[9514012789,"<p>וְאִינוּן חַיּוֹת עִילָּאִין וְאוֹפַנִּים עִילָּאִין, וְחַיּוֹת תַּתָּאִין וְאוֹפַנִּים תַּתָּאִין. חַיּוֹת עִילָּאִין, דְּקָאֲמָרָן. אוֹפַנִּים עִילָּאִין, אִינוּן רָזָא דִּכְתִיב (שיר השירים ה׳:ט״ו) שׁוֹקָיו עַמּוּדֵי שֵׁשׁ, וְאוֹפַנִּים תַּתָּאִין בְּרָזָא דִלְתַתָּא, כְּמָה דְּחַיּוֹת בְּרָזָא דִלְתַתָּא.</p>"],[9514012790,"<p>חַיּוֹת עִילָּאִין ד'. אוֹפַנִּים ד'. כַּד מִתְחַבְּרָא חַד בְּאִינוּן רָזָא דְחַיּוֹת, כְּדֵין אִינוּן וְאוֹפַנִּים בְּחִיבּוּרָא דְּהַהוּא חַד, אִינוּן ד'. וְכֵן כְּגַוְונָא דָא לְתַתָּא, כָּלְהוֹ בְּרָזָא דָּא דְּד'. חַיּוֹת ד'. אוֹפַנִּים ד'. וְאִתְפָּרְשָׁן לְתַתָּא בְּרָזָא דָא. וְהָכָא בְּכָלְהוֹ מִתְפָּרְשָׁאן רָזִין עֵילָא וְתַתָּא, וְעַל דָּא אִיקְּרֵי מֶרְכָּבָה. וְאַף עַל גַּב דְּלָא חָמָא יְחֶזְקֵאל, אֶלָּא מִגּוֹ רָזָא דִּלְתַתָּא אִסְתְּכֵי בְּרָזָא עִילָּאָה.</p>"],[9514012791,"<p>עַל אֲשֶׁר יִהְיֶה שָׁם הָרוּחַ לָלֶכֶת יֵלֵכוּ, רָזָא אהי\"ה, כְּלָלָא דְּכֹלָּא, שַׁלִּיט עַל חַיּוֹת עִילָּאִין סְתִימִין. וּבְגִין כָּךְ אֶל אֲשֶׁר יִהְיֶה שָׁמָּה הָרוּחַ לָלֶכֶת, רָזָא הוי\"ה בִּנְיַן אָב. כִּי רוּחַ הַחַיָּה רָזָא אדנ\"י, לְמֶהֱוֵי סְתִימִין רָזִין גּוֹ סְתִימִין דִּרְתִיכָא דָא, לְמֶהֱוֵי כֹּלָּא כַּחֲדָא בְּרָזָא חָדָא.</p>"],[9514012792,"<p>(יחזקאל א׳:י״ז) בְּלֶכְתָּם יֵלֵכוּ, בְּלֶכְתָּם דְּמַאן. אִי תֵימָא דְחַיּוֹת, לָאו. אֶלָּא בְּרָזָא דְּאִלֵּין תְּלַת רוּחִין, תְּלַת שְׁמָהָן, כַּד נָצְצֵי, נָהֲרִין וְנָפְקִין אָזְלִין חֵיוָן עִילָּאִין וְתַתָּאִין. וּבְעָמְדָם יַעֲמוֹדוּ, כַּד אִינוּן בְּחִבּוּרָא חַד, בִּלְחִישׁוּ כָּלְהוֹ קָיְימִין. כְּדֵין אִתְעֲבִידוּ תְּלַת רוּחִין חַד, תְּלַת שְׁמָהָן חַד, וְקוּדְשָׁא בְּרִיךְ הוּא אִיתְגָּאֵי בְּגֵיאוּתָא עַל כֹּלָּא.</p>"],[9514012793,"<p>וּבְהִנָּשְּׂאָם מֵעַל הָאָרֶץ יִנָּשְׂאוּ הָאוֹפַנִּים, בְּהִסְתַּלְּקוּת חַיּוֹת, בְּרָזָא דְּרוּחִין עִילָּאִין, מֵעַל הָאָרֶץ, מִלְּשַׁמָּשָׁא עַל רוּחָא תַּתָּאָה, אִינוּן אוֹפַנִּים מִסְתַּלְּקִין עִמְּהוֹן, לְאַחֲזָאָה, דְּכָלְהוֹ גּוּפָא חָדָא, וְרָזָא חָדָא, בְּלָא פֵּירוּדָא מֵעִמְּהוֹן.</p>"],[9514012794,"<p>כִי רוּחַ הַחַיָּה בָּאוֹפַנִּים, רְעוּתָא דְהַהִיא חַיָּה בָּאוֹפַנִּים. דְּאַף עַל גַּב דִּרְעוּתָא בְּאִינוּן חַיּוֹת עִילָּאִין, רְעוּתָא יַתִּיר בְּאִינוּן אוֹפַנִּים. תְּלָתָא, תְּרֵין גַּלְיָין. וְחַד גָּנִיז. וְאִלֵּין עָבְדִין עוֹבָדָא דִּרְעוּ בְּהַהִיא חַיָּה. וְהַיְינוּ דִּכְתִיב וּמַעֲשֵׂיהֶם כְּעֵין תַּרְשִׁישׁ, כְּעֵין תְּרֵי שֵׁשׁ דָּא יָמִינָא וּשְׂמָאלָא, דְּאִלֵּין תְּרֵין מֵאִינוּן שִׁית. וְעַל דָּא כְּעֵין: כְּגַוְונָא דִּילְהוֹן.</p>"],[9514012795,"<p>עַד הָכָא רָזָא דְחַיּוֹת בְּרָזָא עִילָּאָה, כְּגַוְונָא דָא לְתַתָּא, וּדְמוּת עַל רָאשֵׁי הַחַיָּה רָקִיעַ. וּדְמוּת, דְּיוּקְנָא לְתַתָּא, כְּגַוְּונָא דִּלְעֵילָא. דְּעַד הָכָא אִית רְשׁוּ לְפָרְשָׁא, מִכָּאן וּלְהָלְאָה, מַאן דְּחָמֵי חָמֵי, דְּלָא אִית רְשׁוּ לְאִסְתַּכָּלָא. מֵהַאי רָקִיעַ וּלְתַתָּא, אִית רְשׁוּ לְמֵיחֱמָא, וּמֵהַאי רָקִיעַ וּלְתַתָּא, אִית רְשׁוּ לְאִסְתַּכָּלָא. מֵאֲתַר דְּאִסְתַּכְּלוּתָא וּלְעֵילָא, אִתְכַּסְיָין שְׁבִילִין וְאוֹרְחִין, לֵית עֵינָא דְּאִסְתַּכַּל בֵּיהּ, דְּכוֹלָּא אִתְכַּסְּיָיא.</p>"],[9514012796,"<p>רָאשֵׁי הַחַיָּה, אִינוּן רְתִיכִין. ד' רֵישֵׁי נְהוֹרִין לְד' זִיוְויָן. וְאִינוּן תְּרֵיסַר יַרְחִין. וְאִינוּן תְּרֵיסַר מְכִילָן, וְחַד דְּשָׁלְטָא עֲלַיְיהוּ, לְמֶהֱוֵי תְּלֵיסַר. וְאִלֵּין אִיקְּרוּן רָאשֵׁי שִׁלְטוֹנִין, שַׁלִּיטִין נְהִירִין לְכָלְהוֹ.</p>"],[9514012797,"<p>ב' רְקִיעִין בְּחַד, אִית רָזָא דִּדְיוּקְנִין דְּלָא אִתְחַזּוֹן. וּבְחַד, לֵית בֵּיהּ דִּיוּקְנִין, וְלָא גְוָונִין, וְלָא לְמִנְדַע, וְלָא לְאִסְתַּכָּלָא, וְלֵית מַאן דְּיָקוּם בֵּיהּ. דָּא אִיהוּ רָקִיעַ עִילָּאָה טְמִירָא, דְּגָנִיז מַה דְּגָנִיז, וִיהַב חֵידוּ וּקְיָימָא לְכֹלָּא.</p>"],[9514012798,"<p>בְּרָזָא דְּשֵׁם אהי\"ה, שְׁלִימוּ דְּכָל שְׁמָהָן. רָזָא דִרְתִיכָא קַדִּישָׁא, בְּרָזָא דְּד' זִיוָון דְּעָלְמָא עִילָּאָה. רָזָא דְד' שְׁמָהָן דִּכְלִילָן בְּחַד. תְּלַת שְׁמָהָן עִילָּאִין, וְחַד דְּאִתְחַבַּר עִמְּהוֹן בִּכְלָלָא חַד.</p>"],[9514012799,"<p>י\"ה, רָזָא טְמִירָא עִילָּאָה. כְּלָלָא דְּכֹלָּא, רָקִיעַ עִילָּאָה טָמִיר דְּקָיְימָא בִּגְנִיזוּ. וְחַד סְפִירָא גְּנִיזָא טְמִירָא דְּכֹלָּא עֲלֵיהּ. הַאי אִיתְאֲחַד וְלָא אִתְאֲחַד בַּמֶּה דְלָא אִתְיְידַע, וְלָא קָיְימָא בְּסוּכְלְתָנוּ. רָזָא דִּכְלָלָא. כְּלָלָא דְּכֹלָּא. בְּרִיךְ הוּא וּבְרִיךְ שְׁמֵיהּ לְעָלַם וּלְעָלְמֵי עָלְמִין. לְתַתָּא כַּד אִתְפַּשַּׁט שְׁמָא דָא, אִיהוּ ו' בְּאַתְרֵיהּ דְּאַלְפָא, בְּרָזָא חָדָא. כְּדֵין אִיהוּ רָקִיעַ לְתַתָּא, כְּגַוְונָא דִלְעֵילָא, וְחַד אֶבֶן סַפִּירָא לְעֵילָא עַל גַּבֵּי הַהוּא רְקִיעָא וְדָא אִיהוּ רָזָא ה' דְּאִתְפָּרְשָׁא שְׁמָא לְתַתָּא, בְּרָזָא יהו\"ה.</p>"],[9514012800,"<p>וּלְזִמְנִין דְּאִתְחַבַּר בִּשְׁמָא דָא אָת ו'. וְאִיהוּ כְּלָלָא חָדָא, הוּא וּבֵית דִּינוֹ וְכֹלָּא חַד, רָזָא דְרָזִין גּוֹ שְׁמָהָן קַדִּישִׁין.</p>"],[9514012801,"<p>(שם) נָטוּי עַל רָאשֵׁיהֶם מִלְּמָעְלָה, רָקִיעַ פָּרִישׂ לְעֵילָא, דְּלָא יְכִילִין חַיּוֹת לְמִנְדַע וּלְאִסְתַּכָּלָא, דְּכֹלָּא אָחִיד דָּא בְּדָא, רָזָא דָא סִימָנָא בְּעָלְמָא, בַּר נָשׁ לָא יָכֵיל לְמֶחֱמֵי לְרֵאשֵׁיהּ, וְאַף עַל גַּב דְּאִיהוּ הוּא, כָּל שֶׁכֵּן מַאן דְּסָתִים בֵּיהּ.</p>"],[9514012802,"<p>הַאי רְקִיעָא עִילָּאָה, לֵית בֵּיהּ דְּיוּקְנָא כְּלַל. לֵית מַאן דְּאִסְתַּכַּל מִתַּמָּן וּלְהָלְאָה, כּוֹלָּא סָתִים וְחָתִים בְּגוּשְׁפַּנְקָא. רָקִיעַ פָּרֵישׂ עַל גַּבֵּי רֵישֵׁי דְחֵיוָן לְעֵילָא, מְזוֹנָא דִילְּהוֹן נָטֵיף מֵהַהוּא רְקִיעָא. וּלְתַתָּא כָּלְהוֹ קָיְימִין בְּקִיּוּמָא, מִתְּחוֹת הַאי רָקִיעַ.</p>"],[9514012803,"<p>רָקִיעַ דָּא תַּלְיָין בֵּיהּ תְּלַת שְׁמָהָן לְעֵילָא, כְּמָא דְּמִתְפָּרְשָׁא לְתַתָּא, קָדוֹשׁ, רַחוּם, חַנּוּן, כִּנּוּי שְׁמָהָן קַדִּישִׁין. סְתִימִין לְעֵילָא בְּרָזָא דִלְתַתָּא, כֹּלָּא כְּגַוְּונָא דָּא מִן דָּא.</p>"],[9514012804,"<p>אִלֵּין שְׁמָהָן, גּוֹ רָזֵי מְהֵימְנוּתָא רָזָא דִילְּהוֹן. כָּל אִינוּן כִּנּוּי שְׁמָהָן, תַּלְיָין בְּרָזָא דִשְׁמָהָן קַדִּישִׁין אִלֵּין, דְּאִיקְּרוֹן חֵיוָן ו טְמִירִין, מְחַפְיָין עַל שְׁמָהָן דִּלְגָאו, וּמְעַפְפָן בְּאִלֵּין, וְאִתְחַפְיָין בְּאִלֵּין. קוּדְשָׁא בְּרִיךְ הוּא אִיקְּרֵי בְּהוּ. וְדָא אִיהוּ דִכְתִיב, (שיר השירים ה׳:ג׳) פָּשַׁטְתִּי אֶת כֻּתָּנְתִּי, לְאִתְתַּקְנָא לְגַבָּה.</p>"],[9514012805,"<p>מֵהַאי רָקִיעַ וּלְתַתָּא, תַּלְיָין אִינוּן כִּינּוּיִין, לְאִתְחַפְיָא בְּהוּ רָזָא דִּשְׁמָא קַדִּישָׁא. מֵהַאי רָקִיעַ וּלְעֵילָא, לָא תַּלְיָין כִּינּוּיִין. הֲדָא הוּא דִכְתִיב, (יחזקאל א׳:כ״ג) וְתַחַת הָרָקִיעַ כַּנְפֵיהֶם יְשָׁרוֹת אִשָּׁה אֶל אֲחוֹתָהּ. בְּגִין לְאִתְחַפְיָיא בְּהוּ אִינוּן טְמִירִין עִילָּאִין בְּרָזֵי שְׁמָהָן קַדִּישִׁין.</p>"],[9514012806,"<p>כְנָפַיִם, כִּסּוּיִין לְאִתְכַּסָּאָה שְׁמָהָן בִּטְמִירוּ. וּלְזִמְנָא דְאָתֵי, לָא יִתְכַּסֶּה רָזָא דִשְׁמָא קַדִּישָׁא, דְּכָלְהוֹ זַכָּאָה קְשׁוֹט יִנְדְּעוּן בְּאִתְגַּלְּיָיא, וְלָא מִגּוֹ כִּינּוּיִין. וְרָזָא דָא כְּתִיב (ישעיהו ל׳:כ׳) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךָ וְהָיוּ עֵינֶיךָ רֹאוֹת אֶת מוֹרֶיךָ.</p>"],[9514012807,"<p>לְאִישׁ שְׁתַּיִם מְכַסּוֹת לָהֵנָּה. תְּרֵין אִינוּן לְכָל חַד וְחַד לְאִתְכַּסְּיָא בְּהוּ. הַהוּא דְּיָמִינָא, אִית לֵיהּ חַד דְּיָמִינָא וְחַד דִּשְׂמָאלָא. וְהַאי דִשְׂמָאלָא אִית לֵיהּ חַד דִּשְׂמָאלָא. וְחַד דְּיָמִינָא. וְכֵן כָּלְהוֹ כְּלִילָן אִלֵּין בְּאִלֵּין לְאִתְחַפְיָא בְּהוּ.</p>"],[9514012808,"<p>גְּוִיֹּתֵיהֶם, רָזִין דִּלְגָאו, בִּשְׁמָהָן קַדִּישִׁין. דְּמִנַּיְיהוּ רָזָא דְגוּפָא דִילְּהוֹן. וְעִם כָּל דָּא, אִלֵּין כְּגַוְּונָא דְּאִלֵּין. הֲדָא הוּא דִכְתִיב, (יחזקאל א׳:כ״ד) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם כְּקוֹל: אֵל, אֱלֹהִים, ה'. דְּכַנְפֵיהֶם: גָּדוֹל, גִּבּוֹר, וְנוֹרָא. הַאי בְּרָזָא דְרָזִין לְעֵילָא, לְאִטַמְרָא כֹּלָּא בִּגְנִיזוּ. לְתַתָּא קָיְימִין בְּחֵיזוּ גַדְפִין, גּוֹ שִׁעוּרָא, בְּת\"ק פַּרְסֵי דְשִׁיעוּרָא. וְאִינוּן גַּדְפִין בְּחֵיזְוָוא.</p>"],[9514012809,"<p>הָכָא אִית חָמֵשׁ קוֹלוֹת, לָקֳבֵל חָמֵשׁ עִילָּאִין סְתִימִין. דִּכְתִיב, (שם) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם כְּקוֹל מַיִם רַבִּים כְּקוֹל שַׁדַּי בְּלֶכְתָּם קוֹל הֲמֻלָּה כְּקוֹל מַחֲנֶה. קוֹל כַּנְפֵיהֶם, דְּהָא בְּאִינוּן כִּינּוּיִין אִית שְׁמָא חַד, מֵהַהוּא שְׁמָא דְּאִיהוּ מֵאִינוּן שְׁמָהָן דִּלְגוֹ. וּמַאן אִיהוּ. אָמַר לֵיהּ. דְּהָא שְׁמָא דָא אָזַל בְּאִינוּן כִּינּוּיִין וְדָא אִיהוּ שְׁמָא, כִּשְׁמָא דְמַיִם רַבִּים. וּמֵהָכָא אִתְפְּרַשׁ שְׁמָא דָא לְתַתָּאי.</p>"],[9514012810,"<p>כְקוֹל שַׁדַּי, אֱלֹהִים. דִּשְׁמָא אִתְכַּנֵּי בְּתַתָּאי, וְאִתְחַתֵּים בְּתַתָּאי, אלק\"י. קוֹל הֲמֻלָּ\"ה, דָּא שְׁמָא דְּאִקְרֵי אלו\"ה, וּשְׁמָא דָא אִתְבְּנֵי בְּבֵי דִינָא לְתַתָּא, בַּאֲתַר דִּזְכוּתָא שַׁרְיָא. כְּקוֹל מַחֲנֶה, דָּא שְׁמָא דְיַעֲקֹב שַׁרְיָא בֵּיהּ. דִּכְתִיב, (בראשית ל״ב:ג׳) מַחֲנֵה אֱלֹהִים זֶה.</p>"],[9514012811,"<p>תּוּ, קוֹל דָּא, מְחַפְיָין חַד גּוּפָא, לְאַפְרָשָׁא דָא מִן דָּא, לְאִשְׁתְּמוֹדְעָא, וּלְאִתְחַבְּרָא גּוּפָא חַד הָכָא, וְגוּפָא חַד הָכָא. כְּמָה דְאַתְּ אָמֵר (יחזקאל א׳:י״א) לְאִישׁ שְׁתַּיִם חוֹבְרוֹת אִישׁ. מְחַבְּרָן אִישׁ, לְאִשְׁתְּמוֹדְעָא וּלְאַפְרָשָׁא דָּא מִן דָּא.</p>"],[9514012812,"<p>וּתְרֵין אָחֳרָנִין מְחַפְיָין לַגּוּף, וּשְׁתַּיִם מְכַסּוֹת אֶת גְּוִיּוֹתֵיהֶנָה. וְכָלְהוֹ גְּלִיפִין מְחַקְּקָן, בְּאַתְוָון דְּרָזָא דִשְׁמָא קַדִּישָׁא, בְּאַרְבְּעִין וּתְרֵין אַתְוָון. תְּחוֹת תְּרֵין אַבְנִין עֵילָא וְתַתָּא, לְאִשְׁתְּמוֹדְעָא קוּדְשָׁא בְּרִיךְ הוּא בִּשְׁמֵיהּ בִּיקָרֵיהּ לְמֶהֱוֵי חַד.</p>"],[9514012813,"<p>אַרְבָּעִין וּתְמַנְיָיא רְתִיכִין טְמִירִין בְּגַרְמַיְיהוּ, טְמִירִין בְּסִטְרָא דְּהַהוּא אָדָם דְּשָׁרְיָיא עַל כָּרְסְיָיא, בְּרָזָא דְּאַרְבְּעִין וּתְמַנְיָא אַתְוָון. וּמָאתָן אָחֳרָנִין גְּלִיפָן בְּגַרְמַיְיהוּ, לָקֳבֵל שַׁיְיפִין דְּגוּפָּא, וְכוֹלְהוֹן שָׁלְטִין עַל כּוּרְסְיָיא לְתַתָּא, כְּחוּשְׁבַּן פִּקּוּדֵי אוֹרַיְיתָא, בְּרָזָא דְּזָכוֹר.</p>"],[9514012814,"<p>הַהוּא אָדָם נָטֵיל לְכָל הַנֵּי פִּקּוּדֵי, וּלְכָל הַנֵּי רָזִין דְּשַׁיְיפִין דְּגוּפָא, וְאוֹתִיב בְּרָזָא דִילְּהוֹן לְגוֹ כָּרְסְיָיא קַדִּישָׁא. וּבְהוֹ אִסְתַּלְקַת כָּרְסְיָיא, בִּתְלַת מְאָה וְשִׁתִּין וְה' פְּקוּדִין אָחֳרָנִין בְּרָזָא דְשָׁמוֹר.</p>"],[9514012815,"<p>כָרְסְיָיא עִילָּאָה, אַפֵּיק כָּל אִינוּן, מִגּוֹ חַד מַבּוּעָא טְמִירָא גְּנִיזָא דְּאִתְגְּנִיז דְּשָׁלְטָא עֲלֵיהּ. הַהוּא מַבּוּעָא לֵית מַאן דְּיָדַע לֵיהּ וְלֵית מַאן דְּאִסְתַּכַּל בֵּיהּ. עֲלֵיהּ כְּתִיב (איוב כח) וְנֶעֶלְמָה מֵעֵינֵי כָל חָי וּמֵעוֹף הַשָּׁמַיִם נִסְתָּרָה.</p>"],[9514012816,"<p>וּכְתִיב שֵׁשׁ מַעֲלוֹת לַכִּסֵּא, אִלֵּין שִׁית סִיטְרִין לְתַתָּא, כְּגַוְּונָא דְּשִׁית סִטְרִין לְעֵילָא. שֵׁשׁ מַעֲלוֹת לְכָרְסְיָיא עִילָּאָה. שֵׁשׁ מַעֲלוֹת לְכוּרְסְיָיא תַּתָּאָה. אִלֵּין וְאִלֵּין, לָא יָכְלִין לְאִסְתַּכָּלָא וּלְמִנְדַע, לִיקָרָא דְּכָרְסְיָיא דַּעֲלַיְיהוּ. כָּל שֶׁכֵּן לְמַאן דְּשָׁרֵי עַל כָּרְסְיָיא. כָּלְהוֹ בְּאֵימְתָא בִּדְחִילוּ, תְּחוֹת כָּרְסְיָיא קָיְימִין. נָטְלִין כָּרְסְיָיא עֲלַיְיהוּ, וְלָא יָדְעוּ, לְאָן אֲתַר מִתְחַבְּרָאן גּוּפִין, כְּמָה דְאַתְּ אָמֵר, (יחזקאל א) חוֹבְרוֹת אִשָּׁה אֶל אֲחוֹתָהּ כַּנְפֵיהֶם, בְּגִין לְסָלְקָא לָהּ. וּכְדֵין כָּל אִינוּן כִּינּוּיִין דִּמְכַסְיָין לִשְׁמָהָן קַדִּישִׁין, שָׁלְטִין בִּשְׁמַיְיהוּ, וְאִקְרֵי קוּדְשָׁא בְּרִיךְ הוּא בְּכִנּוּיָיא.</p>"],[9514012817,"<p>וְכַד קָיְימָא כָּרְסְיָיא בְּכִינּוּיָיא דְּחֶדְוָה, בַּאֲתַר דְּאִצְטְרִיךְ, כְּדֵין אִינוּן חֵיוָן תְּרַפֶּינָה כַּנְפֵיהֶם, וְלָא שָׁלְטִין בְּאִינוּן כִּינּוּיִין, וְחֶדְוָה דִילְּהוֹן בְּהַהוּא זִמְנָא, דְּאִינוּן כִּינּוּיִין תְּרַפֶּינָה כַּנְפֵיהֶם. דְּהָא כְּדֵין קוּדְשָׁא בְּרִיךְ הוּא אִקְּרֵי בְּהוֹן בִּשְׁמָהָן אָחֳרָנִין קַדִּישִׁין עִילָּאִין.</p>"],[9514012818,"<p>הֲדָא הוּא דִכְתִיב, בְּעָמְדָם, עַל קִיּוּמַיְיהוּ. בְּעָמְדָם, דְּלָא נָטְלִין. אֶלָּא דְּחָדָאן מֵחֶדְוָה דְּקִדּוּשָׁא. וְנָהֲרִין, מִגּוֹ נְהִירוּ דְּנָטְלִין מִכּוּרְסְיָא. וְעַל דָּא כְּתִיב, (שם) תְּרַפֶּינָה כַּנְפֵיהֶן. וְשָׁלְטִין שְׁמָהָן אָחֳרָנִין עִילָּאִין קַדִּישִׁין, דְּקוּדְשָׁא בְּרִיךְ הוּא אִיקְּרֵי בְּהוּ.</p>"],[9514012819,"<p>(שם) וָאֵרֶא כְּעֵין חַשְׁמַל כְּמַרְאֵה אֵשׁ בֵּית לָהּ סָבִיב וְגו'. וָאֵרֶא, דְּהָא אִסְתַּלַּק מִנֵּיהּ הַהוּא חֵיזוּ, דְּחָמֵי לְפוּם שַׁעֲתָא. בְּגִין כָּךְ אָמַר וָאֵרֶא, וְלֹא כְתִיב וָאֶרְאֶה.</p>"],[9514012820,"<p>כְעֵין חַשְׁמַל, וְלָא חַשְׁמַל. כְּעֵין: כְּגַוָּון מְלַהֲטָא מְנַצְּצָא, סָלְקָא בִּגְוָונוֹי. כְּעֵין: כְּגווָֹנָא דְּעֵינָא דְּלָא יָכֵיל לְאִסְתַּכְּלָא בְּאִסְתַּכְּלוּתָא, אֶלָּא סְתִים וּפְקִיחָא פְּקִיחָא וּסְתִים, הָכֵי אִיהוּ חַשְׁמַל.</p>"],[9514012821,"<p>וְאִית חַשְׁמַל סָתִים, דְּלָא אִתְחֲזֵי כְּלַל, אֶלָּא מִגּוֹ מַרְאֶה סְתִימָא, דְּלֵית מַאן דְּיָכֵיל לְקָיְימָא בֵּיהּ, וּלְאִשְׁתְּמוֹדְעָא בֵּיהּ כְּלַל. וְאִית חַשְׁמַל דְּקָיְימָא בִּגְוָונִין, גּוֹ נְצִיצוּ לְאַנְהָרָא וּלְאִסְתַּכָּלָא לְפוּם שַׁעֲתָא. וְדָא אִיהוּ לְתַתָּא, דְּהָא לְעֵילָא לָא כְתִיב וָאֵרֶא, אֶלָּא וָאֶרְאֶה. וְדָא חַשְׁמַל דְּאִתְחֲזֵי בִּגְוָונִין, גָּוַון אַרְגְּוָונָא, יָרוֹק, אָדֹם, לָבָן. סָלְקָא דָא, וְנָחֲתָא דָא. נָצֵיץ וְלָהֵיט, סָלְקָא וְנָחֲתָא.</p>"],[9514012822,"<p>וּבְגִין כָּךְ כְּתִיב, כְּעֵין חַשְׁמַל, וְלָא כְתִיב וָאֵרֶא חַשְׁמַל, וְלָא וָאֵרֶא הַחַשְׁמַל, דְּלָאו אִיהוּ חַשְׁמַל, אֶלָּא כְּגווָֹנָא דִילֵיהּ. כְּגַוָון דְּאִתְחֲזֵי, הָכֵי גְּוָונוֹי. חַשְׁמַל דָּא אִיהוּ נְהִירוּ, דְּנָקִיט נְהִירוּ בְּגַוֵּיהּ, הַהוּא נְהִירוּ דְּאִתְחֲזֵי בְּאִינוּן נְצִיצִין, נְהִירוּ אָחֳרָא דַּקִּיק, זָהֵיר וְנָצֵיץ יַתִּיר אִית בְּגַוֵּיהּ, וְהַאי דְּקָאֲמַר הָכָא, לָאו אִיהוּ חַשְׁמַל, אֶלָּא כְּעֵין חַשְׁמַל.</p>"],[9514012823,"<p>בְּחֵיזוּ דְּקַדְמָאָה מַה כְּתִיב. וְאֵשׁ מִתְלַקַּחַת וְנוֹגַהּ לוֹ סָבִיב, וּלְבָתַר, וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל. וְהָכָא בְּקַדְמִיתָא כְּעֵין חַשְׁמַל, וּלְבָתַר כְּמַרְאֵה אֵשׁ בֵּית לָהּ סָבִיב, מֵאֶמְצָעִיתָא דְגוּפָא לְעֵילָא, וּמֵאֶמְצָעִיתָא דְגוּפָא לְתַתָּא.</p>"],[9514012824,"<p>וּתְלַת גְּוָונִין הָכָא, חַשְׁמַל בְּקַדְמִיתָא. וּלְבָתַר אֵשׁ לְגוֹ מִינָּהּ. וּלְבָתַר נוֹגַּהּ. וְאִינִין רָזִין גְּלִיפִין גּוֹ שְׁמָא קַדִּישָׁא. אדנ\"י בְּקַדְמִיתָא, כְּעֵין חַשְׁמַל. אֱלֹהִים לְבָתַר, כְּמַרְאֵה אֵשׁ בַּיִת לָהּ. ידו\"ד לְגוֹ מִכּוֹלָּא, וְנוֹגַּהּ לוֹ. וְכוֹלְהוֹ תְּלַת גְּלִיפָאן, גּוֹ הַאי רָזָא, כְּלִילָן בְּחַד, לְמֶהֱוֵי כּוֹלָּא חַד דָּא בְּדָא. וְעַל דָּא יְחֶזְקֵאל אִסְתַּכַּל לְעֵילָא, וְאִסְתַּכַּל לְתַתָּא, גּוֹ מְהֵימְנוּתָא, בְּרָזִין עִילָּאִין. מִמַּרְאֵה מָתְנָיו כו'.</p>"],[9514012825,"<p>(שמות כ׳:א׳) וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר. אִיהוּ בִּלְחוֹדוֹי בְּדִיבּוּרָא חָדָא וְהָא אוֹקִימְנָא, אָנֹכִי וְלֹא יִהְיֶה לְךָ בְּדִיבּוּרָא חָדָא אִתְאֲמָרוֹ.</p>"],[9514012826,"<p>וְכִי הַנִּי, וְתוּ לָא, אֶלָּא הַנֵּי כְּלָלָא דְּכֹלָּא, הַנֵּי כְּלָלָא דְּכָל אוֹרַיְיתָא וְהָכֵי נָמֵי זָכוֹר וְשָׁמוֹר. וּבְגִין דְּזָכוֹר וְשָׁמוֹר אִינוּן כְּלָלָא דְּכֹלָּא, נָקַט הַנֵּי דְּאִינוּן כְּלָלָא. זָכוֹר וְשָׁמוֹר. אָנֹכִי, זָכוֹר. לֹא יִהְיֶה לְךָ, שָׁמוֹר. וְכֹלָּא בְּדִיבּוּרָא חָדָא.</p>"],[9514012827,"<p>מַאי בְּדִבּוּרָא חָדָא. הָכֵי הוּא וַדַּאי, בְּדִיבּוּרָא חָדָא וְלָא בִּתְרֵין. בְּגִין דְּהַאי דִבּוּר, אִיהוּ אִתְכְּלֵיל מִכָּלְהוֹ קָלֵי. וְאִיהוּ דַהֲוָה אֲמַר בְּתוֹקְפָא וְחֵילָא דְּכָלְהוֹ, דְּכָל חַד וְחַד הוּא בָּטַשׁ בֵּיהּ בִּלְחִישׁוּ, וְאִיהוּ הֲוָה אֲמַר.</p>"],[9514012828,"<p>וּבְגִין דְּכָלְהוֹ הֲווֹ בִּלְחִישׁוּ וְלָא אִשְׁתְּמָעוּ, כְּתִיב (שם) וְכָל הָעָם רוֹאִים, וְלָא כְתִיב וְכָל הָעָם שׁוֹמְעִים, בְּגִין דְּלָא אִשְׁתְּמָעוּ כְּלָל, אֶלָּא כָּלְהוֹ הֲווֹ אַתְיָין, וְכָל חַד וְחַד נָשִׁיק לְהַאי דִבּוּר בִּלְחִישׁוּ, כְּמַאן דְּנָשִׁיק בַּחֲבִיבוּ דִּרְחִימוּתָא, וּלְבָתַר הַאי דִּבּוּר פָּרֵישׁ, וַאֲמַר מִלָּה, וְאַכְרֵיז לָהּ.</p>"],[9514012829,"<p>וְעַל דָּא כְּתִיב וַיְדַבֵּר אֱלֹהִים אֵת כָּל הַדְּבָרִים הָאֵלֶּה, דְּאִינוּן כְּלָלָא דְּזָכוֹר וְשָׁמוֹר אָנֹכִי וְלֹא יִהְיֶה לְךָ. אָנֹכִי כְּלָלָא דְּכָל פִּיקּוּדֵי אוֹרַיְיתָא, דְּאִינוּן בִּכְלַל זָכוֹר, וְאִיקְּרוּן מִצְוֹת עֲשֵׂה. אָנֹכִי כְּלָלָא דִּדְכַר וְנוּקְבָא כַּחֲדָא.</p>"],[9514012830,"<p>וּמַאן דַּאֲמַר דְּאִיהוּ רָזָא דְּכוּרְסְיָא, לָאו אִיהוּ כּוּרְסְיָא בִּלְחוֹדוֹהִי, וְלָאו הָכֵי, דְּהָא רָזָא דְּזָכוֹר אִיהוּ, וְאִיהוּ דְּכוּרָא. אֲבָל אַף עַל גַּב דְּאִיהוּ דְכוּרָא, כְּלָלָא דִּדְכַר וְנוּקְבָא כַּחֲדָא אִיהוּ.</p>"],[9514012831,"<p>וְאַף עַל גַּב דְּכֹלָּא שַׁפִּיר, אֲבָל אֲנִי, דָּא רָזָא דִּבְרִית קַדִּישָׁא, יְסוֹדָא דְּעָלְמָא. כ' אִתְכְּלֵיל בְּגַוֵּיהּ, דָּא אִיהוּ רָזָא דְנוּקְבָא. וּבְכָל אֲתַר כ', דָּא אִיהִי נוּקְבָא דְאִקְרֵי כֶּתֶר.</p>"],[9514012832,"<p>וּבְגִין כָּךְ כֹּלָּא אִיהוּ כַּחֲדָא, רָזָא דִדְכַר וְנוּקְבָא כַּחֲדָא, וְכֹלָּא אִקְרֵי זָכוֹר, דְּהָא דְּכַר לָאו אִיהוּ בִּלְחוֹדוֹי, וְנוּקְבָא אוּף הָכֵי לָאו אִיהִי בִּלְחוֹדָהָא, וּלְעָלְמִין לָא אִתְפַּרְשָׁן דָּא מִן דָּא. זָכוֹר אַתְיָא בְּנוּקְבֵיהּ, שָׁמוֹר אַתְיָא אוּף הָכֵי בְּרָזָא דְּוא\"ו, דְּאִיהוּ דְּכוּרִבִּי אֶלְעָזָר. בְּגִין דְּלָא מִתְפָּרְשָׁן דָּא מִן דָּא.</p>"],[9514012833,"<p>אָנֹכִי כְּלָלָא דִּדְכַר וְנוּקְבָא כַּחֲדָא, וְכֹלָּא אִיקְרֵי זָכוֹר. מַאי טַעְמָא, בְּגִין דְּאִיהוּ נָטֵיל לְנוּקְבָא, וְאַכְלֵיל לָהּ בְּגַוֵּויהּ. וְעַל דָּא לָא אִידְכַּר אֶלָּא אִיהוּ בִּלְחוֹדוֹי. וְכַד אִיהִי אַמְשִׁיכַת לְבַעֲלָהּ בַּהֲדָהּ, וְאָתֵי אִיהוּ לְגַבָּה, כְּמָה דְאַתְּ אָמֵר (שיר השירים ג׳:ד׳) עַד שֶׁהֲבֵאתִיו אֶל בֵּית אִמִּי, כְּדֵין אִיהִי נָטְלָא שְׁמָא, וְכֹלָּא אִיקְּרֵי שָׁמוֹר. מַאי טַעְמָא. בְּגִין דְּאִיהִי אַמְשִׁיכַת לֵיהּ לְגַבָּהּ, וְנָטְלַת לֵיהּ. כְּדֵין כָּל בֵּיתָא קָיְימָא בִּרְשׁוּתָהָא, וְלָא אִדְכַּר אֶלָּא אִיהִי בִּלְחוֹדָהָא, וּלְעָלְמִין לָא מִתְפָּרְשִׁין דָּא מִן דָּא.</p>"],[9514012834,"<p>אָנֹכִי, רָזָא דְרָזִין לְיָדְעֵי חָכְמְתָא. בְּהַהוּא שַׁעֲתָא דְּאִלֵּין אַתְוָון נָפְקוּ בְּרָזָא דְּכָלֵיל כַּחֲדָא, נָפְקָא בּוּצִינָא לְגָלְפָא מִשְׁחָתָא. מָדֵיד בְּסִטְרָא דָּא עֶשֶׂר אַמִּין, וּנְפָקוֹ זִיקִין, בְּזִיקִין שִׁבְעִין וּתְרֵין. וְאִתְלַהֲטָן שְׁבִיבִין, נְצִיצִין סָלְקִין וְנָחֲתִין. לְבָתַר, אִשְׁתְּכָכוּ, וְקָאִימוּ בִּסְלִיקוּ לְעֵילָא לְעֵילָא. מָדִיד בְּסִטְרָא אָחֳרָא עֶשֶׂר אַמִין, וּנְפָקוּ אוּף הָכֵי זִיקִין, בְּהַהוּא גּווָֹנָא קַדְמָאָה, וְכֵן לְכָל סִטְרִין.</p>"],[9514012835,"<p>אִתְפַּשְׁטָא בּוּצִינָא וְסָחֲרָא סְחוֹר סְחוֹר, וְאִתְלְהִיטוּ שְׁבִיבִין נְצִיצִין, וּסְלִיקוּ לְעֵילָא לְעֵילָא, וְאִתְלְהִיטוּ שְׁמַיָא. וְכָל חֵיְילִין עִילָּאִין כָּלְהוֹ, אִתְלְהִיטוּ וְאִתְנְצִיצוּ כַּחֲדָא.</p>"],[9514012836,"<p>סַחֲרָא בּוּצִינָא לְבָתַר מִסִּטְרָא דְדָרוֹם וּמָדִיד וְסָחֲרָא מִתַּמָּן לְמִזְרָח, וּמִמִּזְרָח לְצָפוֹן, עַד דְּאַסְחַר וְתָב לְסִטְרָא דְדָרוֹם כִּדְבְקַדְמֵיתָא.</p>"],[9514012837,"<p>לְבָתַר מִתְגַּלְגְּלָא בּוּצִינָא לְאִסְתַּלָּקָא, וְזִיקִין וּשְׁבִיבִין אִשְׁתַּכָּכוּ, וּכְדֵין נָפְקוֹ אִלֵּין אַתְוָון מְחָקְקָן מִתְלַהֲטָן נָצְצִין, כְּדַהֲבָא כַּד אִתְלַהֵיט בִּנְצִיצוֹ. כְּהַאי אוּמָנָא כַּד מְצָרֵף כַּסְפָּא וְדַהֲבָא, וְאַפֵּיק לוֹן מִגּוֹ אֶשָׁא מְלַהֲטָא, בָּרֵיר וְצָרֵיף כּוֹלָּא. הָכֵי נָמֵי נָפְקֵי אַתְוָון, צְרִיפָן בְּרִירָן מִגּוֹ מִשְׁחָתָא דְּבוּצִינָא. וְעַל דָּא כְּתִיב (תהילים י״ח:ל״א) אִמְרַת ה' צְרוּפָה. כְּמַאן דִּמְצָרֵף כַּסְפָּא וְדַהֲבָא.</p>"],[9514012838,"<p>כַד נָפְקוֹ אִלֵּין אַתְוָון, נָפְקוֹ כָּלְהוֹ צְרִיפִין, מְחַקְּקָן, בְּרִירָן, נְצִיצִין, מְלַהֲטָן. וְיִשְׂרָאֵל כָּלְהוֹ הֲווֹ חָמָאן לוֹן דַּהֲווֹ פָּרְחֵי בַּאֲוִירָא, וְאָזְלִין לְכָל סִטְרִין, וְאָתוֹ וּמִתְחַקְּקָן עַל לוּחֵי אַבְנַיָיא.</p>"],[9514012839,"<p>וְתָּא חֲזֵי כַּד הֲווֹ נָפְקֵי אִלֵּין אַתְוָון בְּרָזָא דִּכְלָלָא דִּדְכַר וְנוּקְבָא, בְּרִירָן מְחַקְּקָן. חַד אָת הֲוָה סָלֵיק עֲלַיְיהוּ, דְּהֲוָה רָשֵׁים וְגָלֵיף לְהַנֵּי אַתְוָון, וּמְעַטֵר לוֹן, וְהַהוּא אָת אָזֵיל בְּכוּלְּהוּ, מֵרָזָא דְּבוּצִינָא אִתְגְּלֵיף. וְהַהוּא אָת אִיהוּ אוֹת ו', דְּהוּא סָלֵיק עַל כָּל אַתְוָון אָחֳרָנִין, וְגָלֵיף לוֹן עַל כֹּלָּא.</p>"],[9514012840,"<p>וְרָזָא דָא, (שמות כ׳:ט״ו) וְכָל הָעָם רוֹאִים אֶ\"ת הַ\"קּוֹלוֹת וְאֶ\"ת הַ\"לַּפִּידִים וְאֵת קוֹל הַשּׁוֹפָר. אֶת הַקּוֹלוֹת, אִלֵּין אִינוּן אַתְוָון אָחֳרָנִין, דַּהֲווֹ נָפְקִין מֵאִינוּן קוֹלוֹת כִּדְקָאֲמָרָן, וְאִתְחַזּוֹן בַּאֲוִירָא לְעֵינֵיהוֹן דְּכֹלָּא.</p>"],[9514012841,"<p>דִּכְתִיב אֶת הַקּוֹלוֹת, וְלָא כְתִיב וְכָל הָעָם רוֹאִים הַקּוֹלוֹת, אֶלָּא אֶת הַקּוֹלוֹת, אִלֵּין אִינוּן אַתְוָון דַּהֲווֹ נָפְקֵי מִנַּיְיהוּ. וְאֶת קוֹל הַשּׁוֹפָר, דָּא אָת ו', דְּהֲוָה סָלֵיק עַל כָּל אַתְוָון, וְגָלֵיף לוֹן, כְּמָא דְּאִיתְּמָר. בְּגִין דְּרָזָא דְאָת ו' אִיקְּרֵי קוֹל הַשּׁוֹפָר, וּבְגִין כָּךְ כְּתִיב רוֹאִים. וְכַד שְׁמָעוֹ לָא שְׁמָעוֹ אֶלָּא קוֹל מִילּוּלָא חָדָא, דִּכְתִיב (דברים ד׳:י״ב) קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים, הַהוּא קוֹל דְּאִיקְּרֵי דְּבָרִים, דְּהוּא הֲוָה אָמַר מִלָּה בִּלְחוֹדוֹי.</p>"],[9514012842,"<p>וְאַף עַל גַּב דְּכָל יִשְׂרָאֵל חָמוֹ יְקָרֵיהּ דְּקוּדְשָׁא בְּרִיךְ הוּא, לָא הֲווֹ חָמָאן, אֶלָּא כְּמַאן דְּחָמֵי מִגּוֹ עֲשָׁשִׁיתָא, וַהֲווּ מִסְתַּכְּלָן לְמִנְדַע חָכְמְתָא בְּאִינוּן אַתְוָון דַּהֲווֹ נָפְקֵי. וַהֲווּ חָמָאן נְהִירוּ דְּנָהֵיר מִגּוֹ נְהִירוּ אָחֳרָא. וְעַל דָּא כְּתִיב, (שם) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה.</p>"],[9514012843,"<p>אָנֹכִי רָזָא דְזָכוֹר, רָזָא דִּדְכוּרָא, דְּבָטַשׁ וְאַנְהֵיר לְדִבּוּר, וְנָפְקֵי אִלֵּין אַתְוָון לְאִתְעַטְרָא, וּבְאִלֵּין אַתְוָון הֲווֹ חָמָאן, וַהֲווּ שָׁמְעִין מִלָּה דְּאִקְּרֵי אָנֹכִי, דְּאִיהוּ אִסְתַּכְּלוּתָא הֲווֹ חָמָאן מִנַּיְיהוּ. שְׁמִיעָה דְּתֵיבוּתָא דִילְּהוֹן, הֲווֹ שָׁמְעִין.</p>"],[9514012844,"<p>דִּכְתִיב קוֹל דְּבָרִים אַתֶּם שׁוֹמְעִים. הוּא שְׁמִיעָה, לְמֶעְבַּד דְּבָרִים, מֵאִינוּן אַתְוָון דַּהֲווֹ חָמָאן. וְאַף עַל גַּב דְּקוֹל דְּבָרִים אִיהוּ, וְאִיהוּ הֲוָה מְמַלֵּל, וְלָא הֲוָה מְמַלֵּל אֶלָּא מִלָּה, דְּאִינוּן אַתְוָון, כְּמָא דְּאִיתְּמָר.</p>"],[9514012845,"<p>אָנֹכִי הָכָא אִיהוּ רָזָא כְּלַל. וּפְרַט, יהו\"ה אֱלֹהֶיךָ. ה', רָזָא דְזָכוֹר. אֱלֹהֶיךָ, רָזָא דְשָׁמוֹר. וְעַל דָּא הָכָא כְּלַל וּפְרַט, וְאוֹרַיְיתָא בְּרָזָא דָא מִתְעַטְרָא. בִּכְלַל וּפְרַט, כְּלָלָא דְכָל אוֹרַיְיתָא. וְכָל פִּקּוּדֵי אוֹרַיְיתָא. בְּגִין דְּאִיהוּ כְּלָלָא דְּזָכוֹר וְשָׁמוֹר כַּחֲדָא.</p>"],[9514012846,"<p>כְמָא דְּאוֹקִימְנָא בְּסִפְרָא דִשְׁלֹמֹה, בְּגִילּוּפָא דְּעִיטוּרָא דְּאַתְוָון. אָנֹכִי: א\"י דְּכַר. נ\"כ נוּקְבָא. וְשַׁפִּיר אִיהוּ, וְהָכֵי קָאָמַר, אֲנִי דְּכַר וְנוּקְבָא כַּחֲדָא, דְּהָא נוּ\"ן כְּפוּפָה אִיהוּ נוּקְבָא בְּכָל אֲתַר. אוּף הָכָא אָנֹכִי כֹּלָּא כַּחֲדָא.</p>"],[9514012847,"<p>אַמַּאי נָקַט אָנֹכִי, וְלֹא אֲנִי. אֶלָּא נ\"כ תְּרֵי נוּקְבֵי אִינוּן, וּתְנִינָן, כְּגַוְונָא דִּשְׁכִינָה לְתַתָּא, אוּף הָכֵי שְׁכִינָה לְעֵילָא. וְכֹלָּא אִשְׁתְּכַח בְּמִלַּת אָנֹכִי, בְּחִיבּוּרָא חָדָא. אָנֹכִי כְּלָלָא דְּזָכוֹר, רָזָא דְּכָל מְהֵימְנוּתָא, כְּלָלָא דְּעֵילָא וְתַתָּא. יוּ\"ד: לְעֵילָא לְעֵילָא, רֵאשִׁיתָא דְּכָל מְהֵימְנוּתָא. נ\"כ: תְּרֵין נוּקְבֵי, עִילָּאָה וְתַתָּאָה, תְּרֵין עָלְמִין עֵילָא וְתַתָּא. א: רָזָא דְּקַו אֶמְצָעִיתָא, דְּנָטֵיל מִכָּל סִטְרִין, מֵעֵילָא וּמִסִּטְרוֹי. וְעַל דָּא הָכָא אִשְׁתְּכַח כָּל רָזָא דִּמְהֵימְנוּתָא.</p>"],[9514012848,"<p>וּבְגִין דְּהָכָא תַּלְיָא כֹּלָּא, בְּחִיבּוּרָא חָדָא, בִּכְלָלָא חָדָא, שָׁארֵי בְּהַאי מִלָּה, לְאַעֲטָרָא רָזָא דְאוֹרַיְיתָא בְּמִלָּה דָא אָנֹכִי, כְּלָלָא דְּכֹלָּא. ה' אֱלֹהֶיךָ, פְּרָטָא דְּכֹלָּא, שְׁמָא שְׁלִים, דְּאִתְגְּלֵיף עֲלַיְיהוּ דְּיִשְׂרָאֵל תָּדִיר.</p>"],[9514012849,"<p>תָּא חֲזֵי (בראשית ב) ה' אֱלֹהִים, שֵׁם מָלֵא, עַל עוֹלָם מָלֵא. דְּקָיְימָא אִיהוּ בִּלְחוֹדוֹי, וְאִתְעַטֵיר בְּגַוֵּיהּ. בְּגִין דְּלָא אִשְׁתְּכַח בְּהַהוּא זִימְנָא עַמָּא וְלִישָׁן, עַל מַה דְּאִתְעַטַר. וּבְגִין כָּךְ הֲוָה מִתְעַטֵר בְּגַוֵּיהּ, וְאִקְּרֵי ה' אֱלֹהִים.</p>"],[9514012850,"<p>כֵיוָן דְּאָתוֹ יִשְׂרָאֵל, וְקָיְימוּ עַל טוּרָא דְסִינַי, וְקַבִּילוּ אוֹרַיְיתָא, כְּדֵין אִתְעַטַר שְׁמָא שְׁלִים עֲלַיְיהוּ דְּיִשְׂרָאֵל, וְאִיקְּרֵי אֱלֹהֶיךָ. וְכַד אֲמַר משֶׁה ה' אֱלֹהֵינוּ, בְּגִין דְּאִיהוּ שִׁבְחָא דְיִשְׂרָאֵל, וְעִמֵּיהּ אַהֲרֹן כַּהֲנָא רַבָּא, וּבְנוֹי דְמשֶׁה מִסִּטְרָא אוֹחֲרָא. בֵּיהּ הֲוָה מִתְעַטַר שְׁמָא שְׁלִים יַתִּיר מִיִּשְׂרָאֵל, וְעַל דָּא הֲוָה אֲמַר ה' אֱלֹהֵינוּ.</p>"],[9514012851,"<p>וְעִם כָּל דָּא אַכְלֵיל עִמֵּיהּ לְכָל יִשְׂרָאֵל, דְּלָא כְּתִיב ה' אֱלֹהִים, אֶלָּא ה' אֱלֹהֵינוּ, כֹּלָּא כַּחֲדָא, לְאִתְעַטְרָא עֲלַיְיהוּ. וְעַל דָּא אִתְעַטְרָן יִשְׂרָאֵל עַל טוּרָא דְסִינַי, לְמֶהֱוֵי שְׁמָא שְׁלִים מִתְעַטְרָא עֲלַיְיהוּ כַּחֲדָא, דְּהָא מִקַּדְמַת דְּנָא לָא אִקְּרֵי ה' אֱלֹהֶיךָ, אֶלָּא ה' אֱלֹהִים.</p>"],[9514012852,"<p>כֵיוָן דְּקַבִּילוּ יִשְׂרָאֵל אוֹרַיְיתָא, ם סְתִימָא דְּהֲוָה אַסְתֵּים בְּגַוֵּיהּ, בְּהַהִיא שַׁעֲתָא אִתְפַּתַּח, וְאִתְמַשַּׁךְ לְאַנְהָרָא לְתַתָּא, וּלְאִתְעַטְרָא עֲלַיְיהוּ דְיִשְׂרָאֵל. וּמִן אוֹת ם אִתְפַּתַּח וְאִתְמַשַּׁךְ לְאַנְהָרָא לְתַתָּא, וְאִתְעֲבֵיד ך.</p>"],[9514012853,"<p>וְעַל דָּא תָּנִינָן בְּרָזָא דְּאַתְוָון, שִׁיעוּרָא דְּאָת ך, כְּשִׁיעוּרָא דִּסְתִימוּ דְּם' סְתִימָא. וּמְשִׁיכוּ דְּאָת נו\"ן לְתַתָּא, כְּשִׁיעוּרָא דְּכָפֵלְתָּא דְּנוּ\"ן כְּפוּפָה. דְּהָא כֹּלָּא בְּרָזָא חָדָא. וְכֹלָּא הֲוָה נָפֵיק מֵהַהוּא קוֹל דְּבָרִים דְּקָאֲמָרָן, דִּכְתִיב וַיְדַבֵּר אֱלֹהִים אֶת כָּל הַדְּבָרִים הָאֵלֶּה לֵאמֹר.</p>"],[9514012854,"<p>אָמַר רִבִּי שִׁמְעוֹן בֶּן יוֹחָאי, בְּשַׁעֲתָא דְּבַּר נָשׁ אַקְדִּים בְּצַפְרָא, וְאַנַּח תְּפִילִּין בְּרֵישֵׁיהּ, וּתְפִילִּין בִּרְשִׁימָא קַדִּישָׁא, בִּדְרוֹעָא, וְאִתְעַטַף בְּעִיטוּפָא דְמִצְוָה, וְאָתֵי לְנָפְקָא מִתַּרְעָא דְבֵיתֵיהּ. ד' מַלְאָכִין קַדִּישִׁין מִזְדַּוְּוגִין עִמֵּיהּ. וְנָפְקֵי עִמֵּיהּ מִן תַּרְעָא דְבֵיתֵיהּ, וְאוֹזִיפוּ לֵיהּ לְבֵי כְּנִישְׁתָּא, וּמַכְרִיזוּ קַמֵּיהּ, הָבוּ יְקָרָא לִדְיוּקְנָא דְמַלְכָּא קַדִּישָׁא, הָבוּ יְקָרָא לִבְרֵיהּ דְּמַלְכָּא, לְפַרְצוּפָא יַקִּירָא דְמַלְכָּא. רוּחָא קַדִּישָׁא שַׁרְיָא עֲלֵיהּ, אַכְרִיז וַאֲמַר, (ישעיהו מ״ט:ג׳) יִשְׂרָאֵל אֲשֶׁר בְּךָ אֶתְפָּאֵר.</p>"],[9514012855,"<p>בָּתַר הָכֵי, אִית לֵיהּ לְמִקְרֵי פַּרְשָׁתָא דִבְרֵאשִׁית עַד יוֹם אֶחָד, דְּאִיהוּ עִילּוּיָיא וְתוּשְׁבַּחְתָּא דְּכֹלָּא. לְבָתַר יִתְעַסַּק בְּפָרָשַׁת קָרְבָּנוֹת, לְכַפָּרָא עֲלוֹי. וְכָל אִינוּן קָרְבָּנִין. וְיֵימָא (ויקרא ו׳:ב׳) צַו אֶת אַהֲרֹן וְאֶת בָּנָיו לֵאמֹר זֹאת תּוֹרַת הָעוֹלָה, בְּגִין לְכַפָּרָא עַל כָּל אִינוּן הִרְהוּרִין וּמַחְשָׁבִין דְּלֵילְיָא. לְבָתַר יְשַׁבַּח בְּתוּשְׁבְּחָן דְּדָוִד מַלְכָּא. וּבְגִין כָּךְ עָאל בַּר נָשׁ, בְּתַרְעִין דְּבֵי כֹלָּה. וְאִיהִי אִתְתְּקָנַת, וּמִתְתַּקְּנִין דַּרְגִּין בַּהֲדָהּ.</p>"],[9514012856,"<p>כֵיוָן דְּמָטֵי לְיוֹצֵר אוֹר, דְּאִיהוּ שֵׁירוּתָא דִצְלוֹתָא דִּמְיוּשָׁב, כְּדֵין כָּל אִינוּן דַּרְגִּין פָּתְחִין תַּרְעִין, וּכְדֵין כְּתִמְרוֹת עָשָׁן כְּתִיב, (שיר השירים ג׳:ו׳) מַה תִּמְרוֹת עָשָׁן דִּקְטוֹרֶת סָלְקָא, וּמִתְחַבְּרִין דַּרְגִּין אִלֵּין בְּאִלֵּין, אוּף הָכָא אִיהִי צְלוֹתָא כְּתִמְרַת עָשָׁן דִּקְטֹרֶת, סָלְקָא, וּמִתְחַבְּרָן דַּרְגִּין, וּמִתְקַשְּׁרָן אִלֵּין בְּאִלֵּין דְּהָא אִיהוּ מְקַשֵּׁר לוֹן.</p>"],[9514012857,"<p>וְאוֹמֵר כֻּלָּם אֲהוּבִים כֻּלָּם בְּרוּרִים כֻּלָּם גִּבּוֹרִים. לְבָתַר אַהֲבָה רַבָּה, לְסָלְקָא וּלְאִתְקַשְּׁרָא בְּיָמִינָא. וְיִחוּדָא דִשְׁמַע, וְאִינוּן פָּרְשְׁיָין. וּכְדֵין אִיקְּרֵי מְקֻטֶרֶת מֹר. לְבָתַר אֱמֶת וְיַצִּיב, דְּאִיהוּ וּלְבוֹנָה. וְאַף עַל גַּב דְּאִיהוּ דִידָהּ, כְּלָלָא אִיהוּ.</p>"],[9514012858,"<p>כֵיוָן דַּאֲמַר אֱמֶת, אַמַּאי וְיַצִּיב, דְּאִיהוּ תַּרְגּוּם, וּמַה אִצְטְרִיכָא הָכָא, אֶלָּא וַדַּאי, כָּל אֱמֶת, דָּא יַעֲקֹב. וְיַצִּיב, דָּא יוֹסֵף. וְאִצְטְרִיךְ לְאִתְדַּבְּקָא בְּתַרְוַויְיהוּ. וּבְגִין דְּפָרָשַׁת צִיצִית רָזָא דְּכֹלָּה, אִצְטְרִיכַת לוֹן, מִיָּד אֲנַן אָמְרֵי תַּרְוַויְיהוּ, אֱמֶת וְיַצִּיב. וְעַל דָּא אֱמֶת דָּא יַעֲקֹב, וְיַצִיב דָּא יוֹסֵף. אִי הָכֵי, אַמַּאי תַּרְגּוּם. אֶלָּא בְּגִין דֶּאֱמֶת אֱמֶת לָא אַמְרִינָן, בְּגִין פְּגִימוּ. וְעַל דָּא אִיהוּ תַּרְגּוּם, וְלֵית פְּגִימוּ בְּתַרְוַויְיהוּ.</p>"],[9514012859,"<p>מִכֹל אַבְקַת רוֹכֵל, דָּא צְלוֹתָא דִמְעוּמָד. ג' קַדְמָאי, דְּאִינוּן מָגֵן, וּמְחַיֶּה, וְאַתָּה קָדוֹשׁ. מָגֵן, אִית בֵּיהּ מ\"ב תֵּיבִין. בְּרָזָא דִשְׁמָא קַדִּישָׁא, דְּמ\"ב אַתְוָון. וְאִית לְאַכְלָלָא לֵיהּ בְּלִבָּא, וּלְאִתְקַשְּׁרָא בֵּיהּ בְּרָזָא דָא, כְּשַׁלְּהוֹבָא בְּגַחֶלֶת, בִּרְחִימוּ דְּמָארֵיהּ. וְדָא אִיהִי בִּרְכְּתָא יָמִינָא.</p>"],[9514012860,"<p>מְחַיֶּה, אִית בֵּיהּ מ\"ט תֵּיבִין, בְּרָזָא דְּחַמְשִׁין תַּרְעִין חָסֵר חַד. וְאִית בֵּיהּ שְׁמָא, רָזָא דִגְבוּרוֹת ה'. וְאִיהוּ אַתָּ\"ה גִּבּוֹ\"ר לְעוֹלָ\"ם אֲדֹנָ\"י. וְרָזָא דִילֵיהּ, אגל\"א. וּבְרָזָא אָחֳרָא יגל\"א. וְכוֹלָּא רָזָא חָדָא, מִן גְּבוּרְתָּא דְּבִרְכָאן, (בראשית מ״ט:י׳) \"יְהוּדָה אַתָּה יוֹדוּךָ. \"גּוּר אַרְיֵה יְהוּדָה. \"לֹא יָסוּר שֵׁבֶט מִיהוּדָה. \"אוֹסְרִי לַגֶּפֶן עִירֹה. בְּדָא אִיתְעַר יְהוּדָה בִּגְבוּרְתָּא קַדִּישָׁא, וְדָא אִיהִי בִּרְכְּתָא שְׂמָאלָא.</p>"],[9514012861,"<p>קְדוּשָׁה, אִית בֵּיהּ י\"ד תֵּיבִין. עֶשֶׂר אֲמִירָן, וְד' אַתְוָון. וְדָא כָּלֵיל לְכָל סִטְרִין, וְאָחֵיד מִסְּיָיפֵי עָלְמָא עַד סְיָיפֵי עָלְמָא.</p>"],[9514012862,"<p>תְּלַת בַּתְרָאי, לָאו אִינוּן בְּחוּשְׁבַּן דָּא בְּתֵיבִין, וְאִינוּן רְצֵה וּמוֹדִים תָּמְכֵי אוֹרַיְיתָא, תְּרֵין עַמּוּדִים. שִׂים שָׁלוֹם, אִילָנָא דְחַיֵּי, דְּאִיהוּ שְׁלָמָא דְבֵיתָא, שְׁלָמָא דְכוֹלָּא. בֵּין כָּךְ וּבֵין כָּךְ בְּאֶמְצָעִיתָא, אִינוּן בִּרְכָאן דִּתְקִינוּ קַדְמָאי, וְהָא אוֹקְמוּהָ. לְבָתַר דִּמְסַיֵּם צְלוֹתָא וְאוֹדֵי עַל חוֹבֵיהּ, נְפִילַת אַפַּיִם.</p>"],[9514012863,"<p>נְפִילַת אַנְפִּין מָה הִיא. הָא אוֹקְמוּהָ, דְּקָא עָבִיד כָּל מַה דַּעֲבֵיד משֶׁה, צְלוֹתָא וְתַחֲנוּנִים וּבָעוּתִין וּנְפִילַת אַפַּיִם, דִּכְתִיב (דברים ט׳:י״ח) וָאֶתְנַפַּל לִפְנֵי ה'. אֲבָל בָּתַר דִּמְסַיֵּים צְלוֹתֵיהּ, וְעָאל בְכָל אִינוּן דַּרְגִּין עִילָּאִין, וְאִתְקַשְּׁרַת כַּלָּה בְּכָלְהוֹ, אִית לְנָחֲתָא לְתַתָּא, וְהוֹאִיל וְנָחֵית לְתַתָּא, אִצְטְרִיךְ נְפִילַת אַנְפִּין, בְּאַלְפָא בֵּיתָא.</p>"],[9514012864,"<p>מַאי טַעְמָא. בְּגִין דְּכֵיוָן דְּצַלֵּי צְלוֹתֵיהּ, וְאוֹדֵי עַל חוֹבוֹי, מִכָּאן וּלְהָלְאָה, אַחֲזֵי גַרְמֵיהּ, דְּמָסַר נַפְשֵׁיהּ לְמָארֵיהּ בִּרְחִימוּ. (תהילים כ״ה:א׳-ב׳) לְדָוִד אֵלֶיךָ ה' נַפְשִׁי אֶשָּׂא. וְנִיחָא לֵיהּ לְהַהוּא סִטְרָא דְּשַׁרְיָיא בֵיהּ מוֹתָא, וְעָבִיד לֵיהּ נַיְיחָא בְדָא.</p>"],[9514012865,"<p>וְעִם כָּל דָּא, בְּאַלְפָא בֵיתָא, אִית רָזָא דְרָזִין לְחַכִּימִין. בְּאַלְפָא בֵּיתָא דָא לֵית בֵּיהּ וא\"ו, וְאִית בֵּיהּ פ\"א בְּאַתְרֵיהּ, וְהַיְינוּ, (שם) פְּדֵה אֱלֹהִים אֶת יִשְׂרָאֵל. לְבָתַר ר' תְּרֵי זִמְנֵי נִינְהוּ. וְלֵית בֵּיהּ קו\"ף.</p>"],[9514012866,"<p>מַאי טַעְמָא. בְּגִין דִּנְפִילָה דָּא, דְּאִתְמְסַר בַּר נָשׁ לְמוֹתָא, אִצְטְרִיךְ לְכַוְּונָא רְעוּתֵיהּ, וּלְמֶעְבַּד נַחַת רוּחַ לְהַהוּא סִטְרָא דְּשַׁרְיָיא בֵּיהּ מוֹתָא, כְּמָה דְּעָבִיד קוֹף בְּחֻרְבוֹת וּבֶהָרִים, אַחֲזֵי גַרְמֵיהּ דְּמִית, וְאִתְחֲזֵי דְּמִית קַמֵּי חֵיוָתָא חָדָא דְּדָחֵיל מִינָּהּ. כֵּיוָן דְּהַהִיא חֵיוָותָא קָרֵיב לְגַבֵּיהּ, וְחָשֵׁיב לְקָטְלָא לֵיהּ, וּלְנַשְׁכָא לֵיהּ, חָמָא לֵיהּ נְפִיל לְאַרְעָא כְּמֵת, וְחָשֵׁיב דְּאִיהוּ מֵת, כְּדֵין תָּב לַאֲחוֹרָא, וְלָא מְקַטְרֵג לֵיהּ. וְעַל דָּא אִסְתַּלְּקוּ אִלֵּין ב' אַתְוָון, דְּלָא יְדַע בְּהוּ בַּר קוּדְשָׁא בְּרִיךְ הוּא בִּלְחוֹדוֹי.</p>"],[9514012867,"<p>וְעִם כָּל דָּא, בִּרְעוּתָא דְלִבָּא יַשְׁוֵי גַרְמֵיהּ לְקוּדְשָׁא בְּרִיךְ הוּא, דִּמְסַר לֵיהּ נַפְשֵׁיהּ בִּרְחִימוּ. וְקוּדְשָׁא בְּרִיךְ הוּא חָשִׁיב עֲלוֹי, כְּאִלּוּ נָטֵיל נִשְׁמָתֵיהּ מִנֵּיהּ. וְעַל דָּא צָרִיךְ לְמִנְפַּל בְּאַרְעָא כְּמֵת, בְּשַׁעֲתָא דְּיֵימַר נְפִילַת אַנְפִּין, בְּגִין דְּאִית חוֹבִין דְּעָבִיד בַּר נָשׁ, דְּלָא מִתְכַּפְּרִין אֶלָּא בְּמוֹתָא. כְּדִכְתִיב, (ישעיהו כ״ב:י״ד) אִם יְכֻפַּר הֶעָוֹן הַזֶּה וְגו'. וְהַשְׁתָּא דְּאִתְחֲשֵׁיב לֵיהּ דְּנָטַל קוּדְשָׁא בְּרִיךְ הוּא נִשְׁמָתֵיהּ, וְאִיהוּ יָהֵיב לָהּ בִּרְעוּתָא. הַהִיא שַׁעֲתָא קָיְימָא לְכַפָּרָא עַל חוֹבוֹי, וְאַשְׁלֵים לְכָל סִטְרִין, וּלְהַהוּא סִטְרָא דְּאִתְּמָר.</p>"],[9514012868,"<p>וְעַל כָּל דָּא, צְלוֹתָא עוֹלָה, וְאִסְתַּלְּקָא בֵּין ב' דְּרוֹעִין, בְּחִבּוּק דִּרְחִימוּ כִּדְקָא יָאוֹת. וְאִיהוּ מְקוּטֶרֶת מוֹר וּלְבוֹנָה מִכֹּל אַבְקַת רוֹכֵל.</p>"],[9514012869,"<p>הוּצְרַךָ משֶׁה אַרְבָּעִים יוֹם לַתּוֹרָה שֶׁבְּעַל פֶּה לְלָמְדָהּ, בְּגִין דְּהַהוּא דַרְגָּא אַרְבְּעִין אִקְּרֵי. וּלְכָךְ אָמַר, (שמות ל״ד:כ״ח) וַיְהִי שָׁם עִם ה' אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה, דְּאִתְחַבְּרוּ תּוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה. וּלְכָךְ הוּצְרַךְ לְהַזְכִּיר וּלְפָרֵט אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה, דְּהָא בְּאַרְבָּעִים יוֹם הֲוָה סַגֵּי.</p>"],[9514012870,"<p>וּבְמ' יוֹם אֲפֵיקַת הַהִיא הוֹרָתָ\"ם, בְּתוֹרָה וּמִצְוָה. דְּכוּרָא לְתוֹרָה וּמִצְוָה, לָקֳבֵל מ' יוֹם דִּיצִירַת הַוְּלַד. דְּנָפֵיק מִן הַכֹּחַ אֶל הַפּוֹעַל. וְאִתְרְשִׁימוּ אֵיבָרוֹי דְּהַהוּא דְכוּרָא, בְּאִינוּן אַרְבְּעִין יוֹמִין, לְאַכְלָלָא בֵּיהּ נְהִירוּ דִּלְעֵילָא, וּלְאִתְבְּנָאָה תַּמָּן גּוּפֵיהּ מִנְּהִירוּ דִּלְעֵילָא. בְּגִין דְּיִתְחֲזֵי לְשַׁמָּשָׁא קַמֵּי מַלְכָּא, וּלְאַמְשָׁכָא עֲלֵיהּ רוּחַ נְבוּאָה לְתַתָּא.</p>"],[9514012871,"<p>כְגַוְּונָא דְּאִשְׁתְּלֵים בְּמ' יוֹם בִּמְעֵי אִמֵּיהּ גּוּפָא דִלְתַתָּא, הָכֵי אִשְׁתְּלֵים לְעֵילָא. וְעַל דָּא (במדבר י״ב:ז׳) בְּכָל בֵּיתִי נֶאֱמָן הוּא. דְּאִשְׁתַּכְלֵל לְעֵילָא בְּבֵיתָא דִילִי, כְּגַוְּונָא דְבֵיתָא דִלְתַתָּא.</p>"],[9514012872,"<p>וְעַל דָּא קָרַן עוֹר פְּנֵי משֶׁה, דְּהָא אִתְנְהֵיר מִקֶּרֶן עִילָּאָה, וּמָשִׁיךְ שֶׁמֶן הַטוֹב עַל רֵאשֵׁיהּ, וְאִשְׁתְּלֵים כָּל חַד מֵאַרְבַּע יְסוֹדִין דִּילֵיהּ בְּעֶשֶׂר, הָא אַרְבְּעִין יוֹמִין וְאַרְבָּעִין לֵילָוָון, וְאַמְשֵׁיךְ שֶׁמֶן הַטוֹב עַל רֵאשֵׁיהּ, וּכְדֵין אִתְנְהֵיר.</p>"],[9514012873,"<p>וּלְבָתַר בָּא אַהֲרֹן, וְשָׁנָה לוֹ פִּרְקוֹ, דְּאָחֵית לֵיהּ הַהוּא נְהִירוּ עַל דִּיקְנֵיהּ, וְהַיְינוּ שְׁנֵי טִפֵּי מַרְגָּלִיּוֹת, דְּנָחֲתֵי עַל דִּיקְנָא דְאַהֲרֹן. וּנְהִירִין נְהִירוּ סַגֵּי, וְאִינוּן רֶמֶז לְתוֹרָה שֶׁבִּכְתָב וְתוֹרָה שֶׁבְּעַל פֶּה, דְּאִתְחַבָּרוּ בְּדִיקְנָא דְאַהֲרֹן, וְחִיבּוּרָא דִּילְהוֹן בְּמַזָּלָא עִילָּאָה תָּלֵי.</p>"],[9514012874,"<p>וּכְדֵין מַה טוֹב וּמַה נָּעִים. טוֹב: דָּא תּוֹרָה שֶׁבִּכְתָב, וְדָא צַדִּיק. נָעִים: דָּא זְמִירוֹת יִשְׂרָאֵל, דְּאִיקְּרֵי נָעִים, כַּד שָׁרָא עֲלֵיהּ נוֹעַם דִּלְעֵילָא, דְּעָלְמָא דְּאָתֵי. וְכוֹלָּא עַל יְדָא דְאַהֲרֹן, דְּחִבֵּר לוֹן כַּחֲדָא בְּקָרְבָּנָא.</p>"],[9514012875,"<p>וְעַל דָּא (מלאכי ב׳:ה׳) בְּרִיתִי הָיְתָה אִתּוֹ וְגו', דָּא מַטְרוֹנִיתָא דִילִי, דַּהֲוַות עִמֵּיהּ. הַחַיִּים וְהַשָּׁלוֹם, חַיִּים, דְּאִימָּא עִילָּאָה. וְשָׁלוֹם, דָּא שַׂר שָׁלוֹם.</p>"],[9514012876,"<p>וָאֶתְּנֵם לוֹ מוֹרָא וַיִּירָאֵנִי. יַהֲבִית לֵיהּ הַנְהוּ דַרְגִּין, לְחַבָּרָא לוֹן אִינוּן שְׁתֵּי טִפּוֹת מַרְגָּלִיּוֹת יַהֲבִית לֵיהּ. וְכַד אַעֲבַר מוֹרָה עַל דִּקְנֵיהּ, דְּהַיְינוּ כַּד הֲוָה מִסְתַּפֵּר, כְּמדָּבָר אַחֵר (שופטים י״ג:ה׳) וּמוֹרָה לֹא יַעֲלֶה עַל רֹאשׁוֹ. וְיִרָאֵנִי, דִּלְמָא מָעַל בְּהַהוּא שֶׁמֶן דְּנָגֵיד לֵיהּ מִשְׁמֵי עִילָּאָה, דְּאִיקְּרֵי שֵׁם, דְּנָגֵיד מִנֵּיהּ שֶׁמֶן הַטוֹב. וְעַל דָּא, (מלאכי ב׳:ה׳) וּמִפְּנֵי שְׁמִי נִחַת הוּא.</p>"],[9514012877,"<p>וְהוּא מַה עָבִיד. (שם) בְּשָׁלוֹם וּבְמִישׁוֹר הָלַךְ אִתִּי. דְּחִבֵּר שָׁלוֹם בְּמִישׁוֹר. מַאן מִישׁוֹר. כְּמָה דְאַתְּ אָמֵר, צַדִּיק וְיָשָׁר הוּא. וּכְדֵין, וְרַבִּים הֵשִׁיב מֵעָוֹן, עַל יְדֵי דְּקָרְבָּנוֹי דְּקָרֵיב לוֹן קַמֵּי מַלְכָּא. וּכְדֵין אִתְיְהֵב שָׁלוֹם בְּמִישׁוֹר. וְהָכָא תָּלֵי רָזֵי דְקָרְבָּנָא, דִּמְסַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְאַהֲרֹן. וּמִישׁוֹר אִיקְּרֵי, עַל דְּאַמְשֵׁיךְ אוֹרַיְיתָא וּנְהִירוּ לְעָלְמָא תַּתָּאָה.</p>"],[9514012878,"<p>וּמִזְרָח אַנְהֵיר לְדָרוֹם בְּקַדְמִיתָא, דִּכְתִיב הוֹלֵךְ אֶל דָּרוֹם. בְּגִין כָּךְ (שמות ל״ד:ל״א) וַיָּשׁוּבוּ אֵלָיו אַהֲרֹן וְכָל הַנְּשִׂיאִים בָּעֵדָה. אַהֲרֹן, דָּא רָזָא דְאַהֲרֹן דְּאִתְנְהֵיר מִמּשֶׁה. וְכָל הַנְּשִׂיאִים, דָּא נַחְשׁוֹן, דְּאִיהוּ רֵישָׁא דְּכָל הַנְּשִׂיאִים. וְכָלְהוֹ אִתְמָשְׁכוֹ אֲבַתְרֵיהּ, וְקָיְימֵי לִשְׂמָאלָא דְמשֶׁה.</p>"],[9514012879,"<p>וְהָא אִיתְעָרוּ, אֶת גָּדְלְךָ: דָּא אַהֲרֹן, מִיָּמִינָא. וְאֶת יָדְךָ הַחֲזָקָה: דָּא נַחְשׁוֹן, מִשְּׂמָאלָא. דִּלְבָתַר דְּאִתְנְהֵיר דָּרוֹם מֵאַסְפַּקְלַרְיָא דְּנָהֲרָא, יִתְנְהֵיר צָפוֹן. דִּכְתִיב, (קהלת א) הוֹלֵךְ אֶל דָּרוֹם וְסוֹבֵב אֶל צָפוֹן. דְּאַקִּיף לֵיהּ נְהִירוּ דְּרַחֲמֵי מִכָּל סִטְרִין, דְּלָא יִפּוֹק בְּשַׁלְהוֹבוֹי לְאוֹקְדָא עָלְמָא, וְיִתְבַּסֵּם דִּינָא בְּרַחֲמֵי. מַאן רַחֲמֵי, דָּא שִׁמְשָׁא, וְהַיְינוּ רוּחַ, דִּכְתִיב (שם) סוֹבֵב הוֹלֵךְ הָרוּחַ, דְּרַחֲמֵי אַקֵּיף כֹּלָּא.</p>"],[9514012880,"<p>וְעַל סְבִיבוֹתָיו שָׁב הָרוּחַ, סְבִיבוֹתָיו דְּמַאן. סְבִיבוֹתָיו דְּהַהוּא מָקוֹם דִּכְתִיב לְעֵילָא, וְאֶל מְקוֹמוֹ שׁוֹאֵף, וְדָא מַעֲרָב. וְעַד תַּמָּן שָׁב הָרוּחַ, לְאַנְהָרָא בְּאִינוּן ע' שְׁנִין, דְּאִתְכְּלֵיל מְקוֹמוֹ לְאַנְהָרָא לְעָלְמִין, וּלְאַנְהָרָא לְע' רַבְרְבִין מְמַנָּן דְּקָיְימִין סָחֳרָנֵיהּ דְּהַהוּא מְקוֹמוֹ דְּשִׁמְשָׁא דַּאֲמָרָן.</p>"],[9514012881,"<p>תָּא חֲזֵי, כְּגַוְּונָא דָא משֶׁה לְתַתָּא, אַנְהֵיר לְאַהֲרֹן, סִטְרָא דְדָרוֹם. וּלְבָתַר לַנְּשִׂיאִים, סִטְרָא דְצָפוֹן. דִּכְתִיב, וְסוֹבֵב אֶל צָפוֹן, וְאַקֵּיף לוֹן סַחֲרָנֵי מַדְבְּחָא. לְבָתַר וְאָצַלְתִּי מִן הָרוּחַ אֲשֶׁר עָלֶיךָ וְשַׂמְתִּי עֲלֵיהֶם, וְדָא הִיא וְעַל סְבִיבוֹתָיו שָׁב הָרוּחַ.</p>"],[9514012882,"<p>תָּא חֲזֵי, בְּקַדְמִיתָא אִינוּן שִׁבְעִים זְקֵנִים יָנְקִין מִמּשֶׁה, וְאִינוּן דְּבִקְצֵה הַמַּחֲנֶה אִתְאֲכָלוּ בְּנוּרָא דְּדָלֵיק. וְהָא אִיתְעָרוּ, מַאן גָּרֵים לוֹן. כֵּיוָן דְּחָזָא משֶׁה דְּלָא יָכְלִין לְאִתְקַיָּימָא בְּלָא זְקֵנִים, בָּעָא סִיַּעְתָּא לְאַנְהָרָא לְיִשְׂרָאֵל, וְקוּדְשָׁא בְּרִיךְ הוּא אָמַר לֵיהּ, (במדבר י״א:י״ז) אֶסְפָה לִי שִׁבְעִים אִישׁ כו', וְאָצַלְתִּי מִן הָרוּחַ אֲשֶׁר עָלֶיךָ, דָּא רוּחַ דְּאַסְפַּקְלַרְיָא דְּנַהֲרָא בְּמשֶׁה שַׁרְיָא וְלָא בְּאָחֳרָא. בְּגִין כָּךְ אִצְטְרִיכוּ לְאִתְנַהֲרָא מִנֵּיהּ, וְדָא הוּא וְעַל סְבִיבוֹתָיו שָׁב הָרוּחַ, לְאַנְהָרָא כִּדְבְקַדְמֵיתָא.</p>"],[9514012883,"<p>כֵיוָן דְּחָמָא שְׁלֹמֹה מַלְכָּא דָא, אֲמַר (קהלת א׳:ב׳) הֲבֵל הֲבָלִים כו', וְזָרַח הַשֶּׁמֶשׁ. בְּיוֹמוֹי דְמשֶׁה, דְּנָהֵיר שִׁמְשָׁא לְיִשְׂרָאֵל אַרְבְּעִין שְׁנִין, לָקֳבֵל נְהִירוּ דִּלְעֵילָא, דְּקַבֵּיל בְּאִינוּן אַרְבְּעִין יוֹמִין דְּהֲוָה בְהוֹ, וּמִקְצַת שָׁנָה רִאשׁוֹנָה כְּכוּלָּם, דִּבְהוֹ קַבֵּל נְהִירוּ דְּאַנְהֵיר לְתַתָּא. וּבָא הַשֶּׁמֶשׁ, כַּד אִסְתַּלַּק מֵעָלְמָא. וְאֶל מְקוֹמוֹ שׁוֹאֵף, כְּמָא דְאַתְּ אָמֵר (יחזקאל ג׳:י״ב) בָּרוּךְ כְּבוֹד ה' מִמְקוֹמוֹ. וְדָא מָקוֹם עִילָּאָה, דְּנָהֵיר לְמָקוֹם תַּתָּאָה.</p>"],[9514012884,"<p>דָּבָר אַחֵר, מְקוֹמוֹ תַּתָּאָה מַמָּשׁ. שׁוֹאֵף נְהִירוּ מִלְּעֵילָא, וְזוֹרֵחַ הוּא שָׁם, דְּנָהֵיר תַּמָּן לְסִיהֲרָא, וְדָא יְהוֹשֻׁעַ, דְּאִתְנְהֵיר מִנֵּיהּ, דִּכְתִיב וְנָתַתָּ מֵהוֹדְךָ עָלָיו. וְאִתְעָרוּ, פְּנֵי משֶׁה כִּפְנֵי חַמָּה וכו'. הוֹלֵךְ אֶל דָּרוֹם, בְּקַדְמִיתָא כַּד הֲוָה בְּעָלְמָא, כָּל סִטְרִין אִתְנְהִירוּ כִּדְאֲמָרָן. אֲבָל הַשְׁתָּא כַּד אִסְתַּלַּק, בִּמְקוֹמוֹ זוֹרֵחַ וְלָא יַתִּיר.</p>"],[9514012885,"<p>וּשְׁמָא דִילֵיהּ אִיקְּרֵי זָהָב יְרַקְרַק, וְרָזָא דָא אוֹקְמוּהָ חַבְרַיָיא, אֶסְתֵּר יְרַקְרֹקֶת הָיְתָה. גַּוָּון אֶתְרוֹג, וְכוֹלָּא חַד. זָהָב דָא, אִיהוּ רֵישָׁא בִּסְתִימוּ, אַף עַל גַּב דְּאִיהוּ בְּאִתְגַּלְּיָא לְגַבֵּי זָהָב עִילָּאָה. עַד דְּאִתְמַשְּׁכָא וְשַׁרְיָא לְרֵישָׁא דְגַבְרִיאֵל, כְּמָה דְּאוֹקִימְנָא. וּבְגִין כָּךְ כֹּלָּא אִיהוּ בְּרָזָא עִילָּאָה, וְאִתְמַשְּׁכָא הַהוּא רָזָא לְתַתָּא, כֹּלָּא כְּגַוְונָא חַד.</p>"],[9514012886,"<p>(שמות כ״ה:י״ז) וְעָשִׂיתָ כַּפֹּרֶת זָהָב טָהוֹר, רַבִּי שִׁמְעוֹן אָמַר, בְּכָל פָּרְשָׁתָא דָא אַשְׁכַּחְנָא דְּאִתְמְסַר עֲבִידְתָּא בִּידָא דְמשֶׁה, בַּר תְּרֵין. בְּכָלְהוֹ כְּתִיב, וְעָשִׂיתָ. וּבָאָרוֹן וּבָאֵפוֹד כְּתִיב (שם) וְעָשׂוּ אָרוֹן, (שם כח) וְעָשׂוּ אֶת הָאֵפוֹד, וְלָא כְתִיב וְעָשִׂיתָ. מַאי טַעְמָא בָּאָרוֹן לָא כְתִיב וְעָשִׂיתָ, בְּגִין דְּאָרוֹן כָּלֵיל לֵיהּ לְמשֶׁה בְּגַוֵּיהּ, לְאִתְנַהֲרָא מִנֵּיהּ. וְאִצְטְרִיכוּ אָחֳרָנִין לְתַקָּנָא תִּיקּוּנָא וְשַׁפִּירוּ דִילֵיהּ, לְמֵיעַל לֵיהּ לְגַבֵּיהּ.</p>"],[9514012887,"<p>בָּאֵפוֹה, לָאו דִּילֵיהּ הוּא, וְלָא לְאִשְׁתַּמָּשָׁא בֵּיהּ, וְלָא אִצְטְרִיךְ לֵיהּ לְמשֶׁה לְמֶעְבַּד פּוּלְחָנָא דְאָחוֹי, דְּהָא משֶׁה אִיהוּ מַלְכָּא, וְאַהֲרֹן שׁוֹשְׁבִינָא דְמַלְכָּא.</p>"],[9514012888,"<p>וְאִי תֵימָא, וְהָא כְתִיב (שם כט) וְהִלְבַּשְׁתָּ אֶת אַהֲרֹן כו', וְאָפַדְתָּ לוֹ. וְשַׂמְתָּ הַמִּצְנֶפֶת עַל רֹאשׁוֹ וְגו'. הָא כּוּלֵי הַאי פּוּלְחָנָא דְמשֶׁה, וִיקָרָא דְאַהֲרֹן אִיהוּ. לָאו הָכֵי אֶלָּא יְקָרָא דְמשֶׁה אִיהוּ, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא לָא בָּעָא פּוּלְחָנָא דְאַהֲרֹן, אֶלָּא עַל יְדָא דְמשֶׁה. וְאַהֲרֹן לָא יָכֵיל לְאִתְקַדָּשָׁא אֶלָּא עַל יְדָא דְמשֶׁה. וּבְכֹלָּא אִצְטְרִיךְ אַהֲרֹן לְמשֶׁה, וְכָל הַאי יְקָרָא דְמשֶׁה אִיהוּ.</p>"],[9514012889,"<p>וְעָשִׂיתָ כַּפֹּרֶת, תָּא חֲזֵי, כְּתִיב בְּפָרְשָׁתָא דָא עוֹבָדָא דְשָׁמַיִם וָאָרֶץ, וְכָל אִינוּן חַיָילִין דְּתַמָּן, דְּהָא קוּדְשָׁא בְּרִיךְ הוּא לָא פַקֵּיד לְמֶעְבַּד מַשְׁכְּנָא, אֶלָּא כְּגַוְונָא דְּעוֹבָדֵי שְׁמַיָא וְאַרְעָא, לְמֶהֱוֵי דִּיּוּרָא דִלְתַתָּא, כְּגַוְונָא דְדִיּוּרָא דִלְעֵילָא, וּלְאִתְחַבָּרָא דָא בְּדָא כְּגַוְונָא דְנִשְׁמָתָא וְגוּפָא, לְמֶהֱוֵי כֹּלָּא חַד.</p>"],[9514012890,"<p>כְתִיב (בראשית א׳:א׳) בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ. בְּרֵאשִׁית, הָא אוֹקְמוּהָ. אֲבָל רָזָא דְעוֹבָדָא דְּכַפּוּרְתָּא, הָכָא בִּרְמִיזוּ דִלְעֵילָא, שַׁלְשְׁלָא דְמטטרו\"ן, גְּנִיזָא דְּמַשְׁכְּנָא, לַאֲרָמָא אֲרָמוּת קוּדְשָׁא לְעֵילָא וְתַתָּא.</p>"],[9514012891,"<p>בְּרֵאשִׁית, רֵאשִׁיתָא עִילָּאָה י' כַּפּוּרְתָּא גְּנִיזָא טְמִירָא, דְּאִשְׁתַּכְּחָא מֵרָזָא דִּנְקוּדָא טְמִירוּ עִילָּאָה, וְאִתְפָּרַשׂ פְּרִישׂוּ, לְאִתְנְהָרָא גּוֹ נְהִירוּ, לְאִתְטַמְּרָא גּוֹ טְמִירוּ. טְמִירָא גוֹ הַאי כַּפּוּרְתָּא, מיטטרו\"ן מטטרו\"ן, דְּאִתְאַחֲדָא מִתַּתָּא לְעֵילָא.</p>"],[9514012892,"<p>מִגּוֹ דְחִילוּ דְּאָזַל בְּקוּשְׁטָא בְּגוֹ אַרְעָא, הֲוָה מַשְׁכַּח נְהִירוּ דְּאָבֵיד אָדָם קַדְמָאָה, דְּאִיטַמַּר הַהוּא נְהִירוּ בְּגִנְתָא דְעֵדֶן. סָלְקָא לְעֵילָא, לָא אִתְיַישְׁבָא בְּדוּכְתֵּיהּ, דְּהָא לָא הֲוָה אִשְׁתְּלֵים מִכָּל סִטְרִין, דְּהָא שְׁלִימוּ דִּלְתַתָּא הֲוָה גָרַע, דְּהָא אִתְאֲבֵיד בְּחוֹבָא דְאָדָם קַדְמָאָה נָחַת לְתַתָּא, וְאִתְטַמַּר גּוֹ אִילָנֵי גִנְתָּא, אִתְפַּשְּׁטָא תַּמָּן בְּכָל סִטְרֵי גִנְתָּא, עַד דְּאִתְיְילִיד חֲנוֹךְ בֶּן יָרֶד.</p>"],[9514012893,"<p>כֵיוָן דְּאִתְיְילִיד הֲוָה אִשְׁתְּכַח סָמוּךְ לְגִנְתָּא, שָׁרִיאַת הַהִיא נְהִירוּ לְאַנְהָרָא בְּגַוֵּויהּ, אִתְרַבֵּי בִּרְבוּ קוּדְשָׁא, וְשַׁרְיָא עֲלֵיהּ נְהִירוּ דָא מְנַצְּצָא. עָאל לְגִנְתָּא דְעֵדֶן, אַשְׁכַּח תַּמָּן אִילָנָא דְחַיֵּי, עַנְפּוֹי וְאִנְבֵּי דְאִילָנָא, אָרַח בְּהוּ, וְאִתְיַישַׁב בְּגַוֵּיהּ הַהוּא רוּחָא דִּנְהִירוּ דְחַיֵּי.</p>"],[9514012894,"<p>אָתוֹ שְׁלִיחָן מַלְאֲכֵי עִילָּאֵי, וְאוֹלִיפוּ לֵיהּ חָכְמְתָא עִילָּאָה, יַהֲבוּ לֵיהּ סֵפֶר דְּהֲוָה טָמִיר גּוֹ אִילָנָא דְחַיֵּי, וְאוֹלִיף מִנֵּיהּ, וְיָדַע אוֹרְחוֹי דְּקוּדְשָׁא בְּרִיךְ הוּא, וְאִשְׁתַּדֵּל אֲבַתְרֵיהּ. הֲדָא הוּא דִכְתִיב, (שם ה) וַיִּתְהַלֶּךְ חֲנוֹךְ אֶת הָאֱלֹהִים. עַד דְּהַהוּא נְהִירוּ, אִשְׁתְּלֵים בְּגַוֵּיהּ.</p>"],[9514012895,"<p>כֵיוָן דְּהַהוּא נְהִירוּ אִשְׁתְּלֵים לְתַתָּא, בָּעָא לְסַלְקָא לְדוּכְתֵּיהּ. וּבְגִין לְאַחֲזָאָה הַהוּא שְׁלִימוּ בְּרָזָא דַּחֲנוֹךְ. יוֹמָא חַד עָאל גּוֹ גִּנְתָּא דְעֵדֶן, וְאַחְמוּ לֵיהּ טְמִירִין דְּגִנְתָּא, וַאֲנַח הַהוּא סֵפֶר, וְכָל מַה דְּחָמָא, לְבַר, וְאִיהוּ צָנִיעַ בְּגוֹ חַבְרַיְיא.</p>"],[9514012896,"<p>לְבָתַר אִתְלַבַּשׁ הַהוּא נְהִירוּ, גּוֹ הַהוּא לְבוּשָׁא, לְאַחֲזָאָה לְעֵילָא, וּלְמֶהֱוֵי כִּיסּוּפָא בַּהֲדֵיהּ, לְכָל אִינוּן דְּעָבְדוּ קִטְרוּגָא בְּמָארֵיהוֹן, דְּלָא יִתְבְּרֵי בַּר נָשׁ בְּעָלְמָא.</p>"],[9514012897,"<p>הֲדָא הוּא דִכְתִיב, (שם) וְאֵינֶנּוּ כִּי לָקַח אֹתוֹ אֱלֹהִים. וְאֵינֶנּוּ: בְּהַאי עָלְמָא. וְאֵינֶנּוּ: כִּדְקָא הֲוָה בְּהַאי עָלְמָא. כִּי לָקַח אֹתוֹ אֱלֹהִים. לִדְיוּקְנָא אָחֳרָא. בְּהַאי, אִיהוּ נַעַר תָּדִיר. וְרָזָא דָא אוֹקִימְנָא, (משלי כ״ב:ו׳) חֲנֹךְ לַנַּעַר עַל פִּי דַּרְכּוֹ, לְאַנְהָגָא עָלְמִין כָּלְהוֹ. גַּם כִּי יַזְקִין לֹא יָסוּר מִמֶּנָּה, דְּהָא תָּדִיר אִשְׁתְּכַח בֵּיהּ וְאִתְהֲדַר נָעַר.</p>"],[9514012898,"<p>בַּחֲנוֹךָ אִתְכְּלֵיל דְּיוּקְנָא דְּעָלְמָא טְמִירָא. אִיהוּ כּוּרְסְיָיא דְמָארֵיהּ, עָבִיד שְׁלִיחָן בְּעָלְמָא. כַּד עָלְמָא בְּדִינָא, נְפַק וְאִיקְּרֵי מטטרו\"ן, רִבּוֹן עַל כָּל חַיָילִין עִילָּאִין. וְסָבָא אִיהוּ נָעַר. עָאל מֵעָלְמָא לְעָלְמָא, וְאִתְיַישְׁבָא רוּגְזָא.</p>"],[9514012899,"<p>דְּיוּקְנָא דָא אִתְפְּרַס בִּפְרִיסוּ כַּפּוּרְתָּא, וְאִתְצַיְירִין בֵּיהּ בְּהַהוּא פְּרִיסוּ תְּרֵין דִּיוּקְנִין, חַד דְּכַר, וְחַד נוּקְבָא. וְקָיְימָן תְּרֵי רַבְיָין עוּלֵמִין רְחִימִין, בִּרְחִימוּ דְּבִיקָאן דָּא בְּדָא.</p>"],[9514012900,"<p>וְרָזָא דָא בְּרֵאשִׁית בָּרָא אֱלֹהִים, פְּרִיסוּ כַּפּוּרְתָּא סְתִימָאָה. אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, תְּרֵין כְּרוּבִין קָיְימִין בִּדְבֵיקוּ דַּחֲבִיבוּתָא. שָׁמַיִם וָאָרֶץ לָא כְתִיב, אֶלָּא אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ, לְאַסְגָאָה תְּרֵין כְּרוּבִין כַּחֲדָא. כַּפֹּרֶת דָּא פְּרִיסָא לְגוֹ, בִּטְמִירוּ דְּהֵיכָלָא, וּבִתְרֵין סִטְרִין קָיְימִין תְּרֵין אִלֵּין.</p>"],[9514012901,"<p>בְּרֵאשִׁית סָלְקָא לְעֵילָא. רָזָא דִילֵיהּ, נָחֲתָא לְתַתָּא. כְּגַוְונָא דְּהַהוּא רָזָא דִבְרֵאשִׁית סָלְקָא לְעֵילָא, וְלָא אִתְרְשִׁים בִּרְשִׁימוּ, נָפְקָא רְשִׁימוּ לְתַתָּא, וְאִתְעֲבֵיד מִנֵּיהּ כַּפּוּרְתָּא עִילָּאָה, רְשִׁימָא בִּרְשִׁימִין תְּלָתָא. בְּרָזָא יהו\"ה אֱלֹהֵינ\"וּ יהו\"ה. מֵאִלֵּין תְּלַת, נָפְקוּ תְּלַת אָחֳרָנִין, וְאִינוּן שִׁית, וְהַיְינוּ בְּרִבִּי אֶלְעָזָר שִׁי\"ת.</p>"],[9514012902,"<p>אִתְפְּרַשׂ כַּפּוּרְתָּא דָא לִסְטַר דָּרוֹם וּמַעֲרָב, וְאַפֵּיק תְּרֵין כְּרוּבִים כַּחֲדָא, דְּכַר וְנוּקְבָא, דְּיִשְׁתַּכְּחוּן דָּא לָקֳבֵל דָּא. דָּרוֹם, אִיהוּ רֹאשׁ, כֹּהֵן נוֹטֵל בָּרֹאשׁ. וְאִיהוּ בֶּן דְּכַר. מַעֲרָב אִיהוּ נוּקְבָא, בַּת יְחִידָה, בַּת הָיְתָה לְאַבְרָהָם וַדַּאי. וְהַיְינוּ בְּרָזָא דָא, בְּרֵאשִׁית: ב\"ת רֹא\"שׁ. י' כַּפּוּרְתָּא, דְּלָא אִשְׁתְּמוֹדָע, עַד דְּאִתְפְּרַס בִּפְרִיסוּ, וְאַפֵּיק תְּרֵין אִלֵּין. כְּגַוְונָא דָא ה'. וְעַל דָּא. בַּת, בַּת רֹאשׁ, בַּת לְאַבְרָהָם. י' כַּפּוּרְתָּא לְאִתְפְּרָסָא.</p>"],[9514012903,"<p>אִתְהַדַּר כַּפּוּרְתָּא מִמַּעֲרָב לְצָפוֹן, וְאִתְפְּרַס בִּפְרִיסוּ. וְאִתְגַּלְיָיא דְּכַר, דְּאִתְאַחֵיד בְּסִטְרָא דְּכַפּוּרְתָּא. וְנוּקְבָא אִתְטַמְּרַת לְתַתָּא, וְאִתְעֲבִידַת בְּאֵשׁ דְּצָפוֹן. וְרָזָא דָא בְּרֵאשִׁית, בַּת אֵשׁ. י' כַּפּוּרְתָּא. י' פְּרִיסוּ דְּאִתְפְּרַס, וְאַחֲזֵי חַד, וְלָא תְּרֵין, דְּהָא נוּקְבָא אִתְכַּפְיָיא לְתַתָּא. וְאִי תֵימָא כּוֹלָּא חַד פְּרִיסוּ עִילָּאָה וְתַתָּאָה. הָכֵי הוּא. דְּלָא אִתְפְּרֵישׁ שְׁמָא דָא מִן דָּא, כֹּלָּא אִיהוּ אֱלֹהִים.</p>"],[9514012904,"<p>אִתְהַדַּר כַּפּוּרְתָּא מִמַּעֲרָב לְמִזְרָח, פָּרֵיס פְּרִיסוּ בִּתְרֵי סִטְרִין, בְּסִטְרָא דְמִזְרָח, וּבְסִטְרָא דְמַעֲרָב. כֵּיוָן דְּכַפּוּרְתָּא קָיְימָא בְּמִזְרָח וּמַעֲרָב, כְּדֵין חֶדְוָה אִשְׁתְּכַח, וְחִיבּוּרָא כִּדְקָא יָאוֹת, וְהַאי בַת, אִתְכְּלִילַת בְּעִיטְרָהָא כִּדְקָא יָאוֹת, וְקָיְימָא בְּאַשְׁלָמוּתָא. וּכְדֵין אִיהוּ בְּרָזָא דִילֵיהּ בְּרֵאשִׁית, בְּלָא פֵּירוּדָא כְּלָל.</p>"],[9514012905,"<p>וְלָקֳבֵל אִלֵּין תְּלַת זִימְנִין, סָלְקִין יִשְׂרָאֵל תְּלַת זִימְנִין לְמֵיחַג חַגַּיְיהוּ. בְּפֶסַח אִתְהַדַּר כַּפּוּרְתָּא בִּסְטַר דָּרוֹם וּמַעֲרָב, וּכְדֵין הַהִיא בַּת קָיְימָא בְּאַבְרָהָם, וְאִיהִי בַּ\"ת רֹא\"שׁ, וְתַמָּן הַלֵּל, וְלָאו הַלֵּל גָּמוּר, דְּהָא תְּרֵין כְּרוּבִין אִלֵּין, לָאו אִינוּן בְּאַשְׁלָמוּתָא כִּדְקָא יָאוֹת, דְּהָא יִשְׁמָעֵאל נָפִיק וּמְקַטְרֵג.</p>"],[9514012906,"<p>מִיּוֹמָא דְרֹאשׁ הַשָּׁנָה עַד יוֹמָא קַדְמָאָה דְּסוּכּוֹת, אִתְהַדַּר כַּפּוּרְתָּא מִצָּפוֹן לְמַעֲרָב, כְּדֵין הַהִיא בַּת אִתְכַּפְיָיא, וְקָיְימָא בֵּיהּ בְּיִצְחָק, וְלָא בְּחֶדְוָה, וְאִיהִי בַּ\"ת אֵ\"שׁ, וְאִינוּן לָאו בְּאַשְׁלָמוּתָא, וְעַל דָּא לֵית תַּמָּן הַלֵּילָא כְּלַל, דְּהָא עֵשָׂו נָפִיק וּמְקַטְרֵג. בְּסוּכּוֹת, סָלְקָא הַאי בַּת. וְאִישְׁתַּלִּימַת בֵּיהּ בְּיִצְחָק בְּחֶדְוָה, וּמִתְחַבְּרָן דָּא בְּדָא, וּכְדֵין הַלֵּל גָּמוּר, עַל דְּאִשְׁתְּכִיךְ רוּגְזָא, וְחַבְרוּתָא אִשְׁתַּכַּח.</p>"],[9514012907,"<p>בְּשָׁבוּעוֹת דְּאִקְּרֵי עֲצֶרֶת, אִתְהַדַּר כַּפּוּרְתָּא בִּסְטַר מִזְרָח וּמַעֲרָב, כְּדֵין שְׁלִימוּ אִשְׁתְּכַח, וַחֲבִיבוּ וּדְבֵיקוּתָא אִיהוּ בְּכָל סִטְרִין, וְחֶדְוָה דְּעִילָּאֵי וְתַתָּאֵי. וּכְדֵין (תהלים יטו) תּוֹרַת ה' תְּמִימָה מְשִׁיבַת נָפֶשׁ.</p>"],[9514012908,"<p>וּבִתְלַת זִמְנִין אִלֵּין, כַּפּוּרְתָּא אִתְהַדְּרַת בְּסִטְרָהָא, כִּדְקָא יָאוֹת, כַּפֻּרְתָּא דָּא אִתְפָּרְסָא לְעֵילָא, גּוֹ הַהוּא נְקוּדָה טְמִירָא, בִּנְהִירוּ קַדְמָאָה דְּאִתְפָּרְסָא. לְבָתַר אִתְפְּרָס בִּשְׁלִימוּ. וְשַׁרְיָיא עַל הַהוּא פְּרִיסוּ, כַּד אִתְחַפְיָין גַּדְפֵי כְּרוּבִים עַל הַאי כַּפֻּרְתָּא, בְּגִין לְאִתְחַפְיָיא כַּפֻּרְתָּא, וְלָא יְהֵא בְּאִתְגַּלְּיָיא.</p>"],[9514012909,"<p>כַפֹּרֶת. כַּפֹּרֶת כְּתִיב, דְּכַד אַתְיָא נְהִירוּ עִילָּאָה, אִינוּן כְּרוּבִים בַּטְשֵׁי בְּגַדְפַיְיהוּ, וְסָלְקִין לוֹן לְעֵילָא, וְאָמְרִין שִׁירָתָא מִסְּגִיאוּ דְּהַהוּא חֶדְוָה דְּהַהוּא נְהִירוּ.</p>"],[9514012910,"<p>כְגַוְונָא דָא לְתַתָּא, וְכַפּוּרְתָּא אִתְהַדַּר, וּמֵאִינוּן תְּלָתָא הֲווֹ כְּרוּבִים יָמִינָא וּשְׂמָאלָא. יָמִינָא שַׁרְיָא בֵּיהּ רוּחָא דִלְעֵילָא, מֵהַהוּא סִטְרָא. וּשְׂמָאלָא דְּהֲוָה בְּמַעֲרָב בְּאִתְהַדְּרוּתָא דְּכַפּוּרְתָּא, קָאִים לְגַבֵּיהּ בִּסְטַר שְׂמָאלָא, וְשַׁרְיָיא בֵּיהּ רוּחָא דְנוּקְבָא, וְאִתְחַבַּר דָּא בְּדָא בַּחֲבִיבוּ דִּדְכַר וְנוּקְבָא. וְכֵן לְכָל סִטְרִין בְּאִתְהַדְּרוּתָא דְכַפּוּרְתָּא. וּלְעוֹלָם תְּרֵין אִינוּן, דְּכַר וְנוּקְבָא, לְתַתָּא בְּהַאי עָלְמָא אִינוּן תְּרֵין וְלָא יַתִּיר.</p>"],[9514012911,"<p>וְאִי תֵימָא לְעֵילָא הוֹאִיל וְלָא אִצְטְרִיךְ דְּבֵקוּתָא בְּכַפּוּרְתָּא, אֵיךְ אִתְהַדַּר כַּפּוּרְתָּא. וַדַּאי בְּהַהוּא אִתְהַדְּרוּתָא, אִתְדַּבַּק דָּא בְּדָא, וְתָדִיר אִתְדַּבַּק בָּהּ.</p>"],[9514012912,"<p>כְגַוְונָא דִּכְרוּבִים אִינוּן לְעֵילָא, קָיְימִין עַל אָת וְנִיסָּא. וְהָא אוֹקִימְנָא רָזָא דִכְתִיב, (שמות כ״ה:כ׳) פּוֹרְשֵׂי כְנָפַיִם סוֹכְכִים, וְלָא כְתִיב פְּרוּשֵׂי כְנָפַיִם סְכוּכִים בְּכַנְפֵיהֶם, אֶלָּא עַל אָת וְנִיסָּא הֲווֹ קָיְימִין. זִמְנִין יְדִיעָן הֲווֹ סָלְקָן גַּדְפַיְיהוּ, וּפָרְשֵׂי לוֹן לְעֵילָא בְּכָל יוֹמָא וְיוֹמָא, וַהֲווּ מִתְהַדְּרָן וּמְחַפְיָין עַל כַּפּוּרְתָּא. וְעַל דָּא בְּאָת וְנִיסָּא הֲווֹ קָיְימִין.</p>"],[9514012913,"<p>בְּכָל אֲתַר דְּרוּחָא עִילָּאָה הֲוָה אָתֵי וְשַׁרְיָיא, וַדַּאי בְּהַהוּא אֲתַר דְּשַׁרְיָא, אִית בֵּיהּ מַמָּשׁוּ, וְקִיּוּמָא בְּאָת וְנִיסָּא. בַּר נָשׁ אִיהוּ מֵעַפְרָא, וְעַד לָא שְׁרָא עֲלֵיהּ נְצִיצוּ דְרוּחָא דִלְעֵילָא, לֵית בֵּיהּ מַמָּשׁוּ, כֵּיוָן דְּשַׁרְיָא עֲלֵיהּ, אִית בֵּיהּ מַמָּשׁוּ, וְקָיְימָא בְּקִיּוּמָא.</p>"],[9514012914,"<p>וְאִי תֵימָא דָא בִּלְחוֹדוֹי, תָּא חֲזֵי מֵחוּטְרָא דְאַהֲרֹן, דְּאִיהוּ אָעָא בְּלָא מַמָּשׁוּ כְּלַל, כֵּיוָן דְּשַׁדַּר בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא זְעִירוּ דְרוּחָא, קָאִים בְּקִיּוּמָא, וְאִתְעֲבֵיד לֵיהּ בְּרִיָּה וּמַמָּשׁוּ. וּמָה אָעָא דְּלָאו אוֹרְחֵיהּ בְּכָךְ, כֵּיוָן דְּשַׁדַּר בֵּיהּ קוּדְשָׁא בְּרִיךְ הוּא חַד זְעִירוּ דְרוּחָא, קָאִים בְּקִיּוּמָא, וַהֲוָה בֵּיהּ מַמָּשׁוּ. כְּרוּבִים דְּאִינוּן קְדוֹשִׁין, וְקָיְימִין בִּקְדוּשָׁה כְּגַוְונָא דִלְעֵילָא, עַל אַחַת כַּמָּה וְכַמָּה.</p>"],[9514012915,"<p>בְּכָל זִימְנָא דְּיִשְׂרָאֵל הֲווֹ זַכָּאִין, כְּרוּבִים הֲווֹ דְּבֵיקִין בִּדְבִיקוּ אַפִּין בְּאַפִּין, כֵּיוָן דַּהֲווֹ סָרְחָן, הֲווֹ מְהַדְּרָן אַפַּיְיהוּ דָּא מִן דָּא. מְנָא הֲווֹ יָדְעֵי, הָכָא אִתְפַּלְּגוּן עַמּוּדִין דְּעָלְמָא. אֲבָל בִּתְנָנָא דְּקוּרְבָּנָא, וּבְקוּרְבָּנָא עַל גַּבֵּי מַדְבְּחָא, וּבְכַהֲנָא כַּד בְּרִיךְ יָת עַמָּא. בְּאִלֵּין תְּלָתָא הֲווֹ יָדְעֵי, דְּהָא כְּרוּבִים מְהַדְּרִין אַנְפִּין דָּא מִן דָּא, וְקוּדְשָׁא בְּרִיךְ הוּא בָּעֵי תְּיוּבְתָּא דִבְנוֹי.</p>"],[9514012916,"<p>תְּנָנָא דְּקוּרְבָּנָא, כַּד הֲווֹ יִשְׂרָאֵל זַכָּאִין, תְּנָנָא הֲוָה סָלֵיק לְעֵילָא בְּאוֹרַח מֵישַׁר, כְּעִיטוּרָא דְּקוֹלְפִין, אִי לִסְטַר מִזְרָח, אִי לִסְטַר מַעֲרָב, אוֹ בְּכָל סְיָיפֵי עָלְמָא, בְּאוֹרַח מֵישַׁר הֲוָה סָלֵיק. וְכַד לָא סָטָא לְיָמִינָא וְלִשְׂמָאלָא, כְּדֵין רְעוּתָא קָיְימָא לְעֵילָא וְתַתָּא, וְקוּדְשָׁא בְּרִיךְ הוּא אִתְרְעֵי בְּעוֹבָדִין דְּיִשְׂרָאֵל בַּחֲבִיבוּ יַתִּיר.</p>"],[9514012917,"<p>בְּקָרְבָּנָא דְּעַל גַּבֵּי מַדְבְּחָא. כַּד הֲווֹ יִשְׂרָאֵל זַכָּאִין, הֲוָה מִתְחֲזֵי עַל גַּבֵּי אֶשָׁא דְמַדְבְּחָא דְּיוּקְנָא דְאַרְיֵה אָכִיל קוּרְבָּנָא עַל מַדְבְּחָא. וְכַד לָא הֲווֹ זַכָּאִין, הֲווֹ חָמָן דְּיוּקְנָא דְּכַלְבָא רְבִיעַ עַל מַדְבְּחָא.</p>"],[9514012918,"<p>כַהֲנָא כַּד בְּרִיךְ יַת עַמָּא, בְּשַׁעֲתָא דְּזָקֵיף יְדוֹי, כַּד הֲווֹ יִשְׂרָאֵל זַכָּאִין וְאִתְחַזּוּן לְבָרְכָא, יְדוֹי הֲווֹ זְקִיפִין בִּזְקִיפוּ, בְּלָא טוֹרַח כְּלַל, וְאִתְאֲרָמוּ בְּחֵידוּ וּבִרְעוּ. כְּדֵין שְׁכִינְתָּא שַׁרְיָיא עֲלַיְיהוּ, וְאִזְדַּקְּפָן אִינוּן מִגַּרְמַיְיהוּ, וּכְדֵין כַּהֲנָא הֲוָה יָדַע, דְּאִתְחַזּוּן יִשְׂרָאֵל לְבִרְכְּתָא, וּבָרֵיךְ לוֹן בִּרְעוּ דְּלִבָּא.</p>"],[9514012919,"<p>וְכַד יְדוֹי הֲווֹ יַקִּירִין וּבְטוֹרַח סַגֵּי אִזְדְּקָפוּ, וְלָא יָכֵיל לַאֲרָמָא לוֹן, אֶלָּא בְּרוֹב טוֹרַח. כְּדֵין הֲוָה יָדַע, דְּהָא שְׁכִינְתָּא לָא שַׁרְיָיא עַל יְדוֹי. וְיִשְׂרָאֵל לָא אִתְחַזּוּן לִבְרָכָא.</p>"],[9514012920,"<p>בְּגִין דִּבְשַׁעֲתָא דִּשְׁכִינְתָּא הֲוָה אַתְיָיא לְשָׁרְיָיא עַל יְדוֹי, כָּל אִינוּן אֶצְבְּעָן דְּאִינוּן בִּדְיוּקְנָא עִילָּאָה, הֲווֹ חָדָאן בְּחֵידוּ, לְקַבְּלָא לָהּ לִשְׁכִינְתָּא עֲלַיְיהוּ, וּפָרְחֵי לְאִזְדַּקְּפָא לְעֵילָא. כְּמָא דַּהֲווֹ חָדָאן כְּרוּבִין דְּהַאי עָלְמָא, וְכָּל שֶׁכֵּן לְעֵילָא, לְקַבְּלָא לָהּ לִשְׁכִינְתָּא עַל גַּבַּיְיהוּ.</p>"],[9514012921,"<p>וְרָזָא דָא, (שמות י״ז:י״ב) וִידֵי משֶׁה כְּבֵדִים. מַאי טַעְמָא, בְּגִין דְּהַהִיא שַׁעֲתָא יִשְׂרָאֵל לָא הֲווֹ זַכָּאִין. וִידוֹי דְמשֶׁה אִיתְיַיקָרוּ, וְלָא יָכֵיל לְזָקְפָא לוֹן לְעֵילָא. דִּכְתִיב לְעֵילָא, (שם) עַל רִיב בְּנֵי יִשְׂרָאֵל וְעַל נַסּוֹתָם אֶת ה'. וּכְדֵין וַיָּבֹא עֲמָלֵק, וְאִתְיַיקָרוּ יְדוֹי דְמשֶׁה, וְלָא יָכֵיל לְזָקְפָא לוֹן, עַד דְּקַבֵּיל עֲלֵיהּ עוֹנָשָׁא. דִּכְתִיב וַיִּקְחוּ אֶבֶן וְהָיָה כַּאֲשֶׁר יָרִים משֶׁה וְגו'. כְּגַוְונָא דָא לוּחֵי אַבְנַיָא, כְּגַוְונָא דְכַהֲנָא.</p>"],[9514012922,"<p>וְעַל דָּא, כְּרוּבִים בְּהַהוּא זִמְנָא דַּהֲווֹ יִשְׂרָאֵל זַכָּאִין, הֲווֹ אַנְפִּין בְּאַנְפִּין, מִתְדַּבְּקִין דָּא בְּדָא. וְכַד לָא הֲווֹ זַכָּאִין, הֲווֹ מְהַדְּרִין אַנְפַּיְיהוּ דָּא מִן דָּא. וְעַל רָזִין אִלֵּין, הֲווֹ יָדְעֵי, אִי יִשְׂרָאֵל זַכָּאִין, אִי לָא.</p>"],[9514012923,"<p>כְרוּבִים: רַבְיָין. וְכֹלָּא בְּרָזָא חַד קָיְימֵי, דִּכְתִיב (הושע י״א:א׳) כִּי נַעַר יִשְׂרָאֵל וָאוֹהֲבֵהוּ. וּבְגִין כָּךְ כֹּלָּא בְּחַדְתּוּתָא דְּסִיהֲרָא קָיְימָא, כְּמָה דְּאִתְחַדֵּי דָּא בְּחַדְתּוּתָא, הָכֵי אִיהוּ כֹּלָּא. וּבְגִין נַעַר, אִינוּן נְעָרִים. וְרָזָא דָא אֵשֶׁת נְעוּרִים, דְּקָיְימָא עַל תְּרֵין נְעָרִים, בְּחַדְתּוּתָא עִילָּאָה.</p>"],[9514012924,"<p>כְרוּבִים אַנְפֵּי רַבְרְבֵי, וְאַנְפֵּי זוּטְרֵי. וַדַּאי הָכֵי אִינוּן אַנְפִּין טְמִירִין לְעֵילָא, דְּלָא אִתְגַּלְּיָין. וּבְגִינַיְיהוּ, הֲוֵי חַדְתּוּתָא דְּסִיהֲרָא, וּמִלּוּי דִּילָהּ.</p>"],[9514012925,"<p>אַנְפֵּי זוּטְרֵי לְתַתָּא, כְּמָה דְאוֹקִימְנָא בְּכַפֹּרֶת, לְעֵילָא וְתַתָּא בְּרָזָא חָדָא קָיְימָא. אֵת הַשָּׁמַיִם וְאֶת הָאָרֶץ, אִינוּן רָזָא דִּתְרֵין כְּרוּבִים, חַד דְכַר, וְחַד נוּקְבָא, לְמֶהֱוֵי דְּבֵיקִין אִלֵּין בְּאִלֵּין בַּחֲבִיבוּתָא, כְּמָא דְּאִיתְּמָר. אֶת, לְאַסְגָּאָה עֵילָא וְתַתָּא כַּחֲדָא, לְמֶהֱוֵי רָזָא דִּכְרוּבִין כֹּלָּא בִּכְלָלָא חָדָא.</p>"],[9514012926,"<p>כְתִיב (תהילים ק׳:ב׳) עִבְדּוּ אֶת ה' בְּשִׂמְחָה, חֶדְוָותָא דִתְרֵין כְּרוּבִין. דְּהָא רַבְיָין, כָּל מַאן דְּשָׁארֵי בְּגַוַּיְיהוּ, אִתְהַדַּר אַנְפּוֹי כְּרֻבַיָיא, וְחָדֵי עִמְּהוֹן. וְרָזָא דָא, כֵּיוָן דְּשָׁארֵי עֲלַיְיהוּ, מַאן דְּשָׁארֵי, אִתְהַדַּר נַעַר, בְּחֵידוּ דְּכֹלָּא, וּבִרְעוּתָא, אַף עַל גַּב דְּאַתְיָיא בְּדִינָא עַל עָלְמָא, כֵּיוָן דְּשָׁארֵי עֲלַיְיהוּ, אִתְהַדַּר בְּחֶדְוָה, נַעַר קָטִיר בְּחֵידוּ. וְעָלְמָא אִתְהַדַּר בְּרַחֲמֵי.</p>"],[9514012927,"<p>מַאן דְּאִיהוּ בְּרוֹגְזָא, יֵיתוּן לְגַבֵּיהּ נַעַר, וְיִשְׁתַּכֵּךְ רוּגְזֵיהּ, וְיִתְהַדַּר בְּחֶדְוָה, וְשַׁוֵּי גַּרְמֵיהּ כְּרֻבַיָיא, וּכְדֵין כֹּלָּא בְּחֵידוּ. וְעַל רָזָא דָּא כְּתִיב, (הושע י״א:א׳) כִּי נַעַר יִשְׂרָאֵל וָאוֹהֲבֵהוּ, לֵית רְחִימוּ וַחֲבִיבוּ בַּר בְּרַבְיָיא.</p>"],[9514012928,"<p>כְתִיב (שמות ל״ג:י״א) וִיהוֹשֻׁעַ בִּן נוּן נַעַר לֹא יָמִישׁ. דְּהֲוָה קָאִים גּוֹ מַשְׁכְּנָא דְמשֶׁה, בְּגִין דְּהַהוּא אוֹהֶל, אוֹהֶל דְּמשֶׁה הֲוָה. וּבְשַׁעֲתָא דִּשְׁכִינְתָּא הֲוָה אַתְיָא, וְאַשְׁכַּח תַּמָּן לִיהוֹשֻׁעַ דְּאִיהוּ נַעַר, וּמִיָּד הֲוָה בְּחֵידוּ וּרְעוּ. דְּחֶדְוָה דִּיהוֹשֻׁעַ אַנְפּוֹי דְּסִיהֲרָא בְּכוֹלָּא, בְּכָל רָזִין דִּילֵיהּ הָכֵי הֲוָה.</p>"],[9514012929,"<p>כֵיוָן דְּמַשְׁכְּנָא אִתְבְּנֵי, לָא אִצְטְרִיךְ יְהוֹשֻׁעַ לְמֶהֱוֵי תַּמָּן, אֶלָּא כְּרוּבִים הֲווֹ תַּמָּן, וּמִשְׁתַּכְּחֵי בַּחֲבִיבוּ דָּא בְּדָא, אַנְפִּין בְּאַנְפִּין, כְּרֻבַיָיא בְּחֵידוּ. כֵּיוָן דְּשָׁארֵי עֲלַיְיהוּ מִיָּד כּוֹלָּא בְּחֵידוּ, וְדִינָא לָא אִשְׁתְּכַח כְּלָל. וּבְגִין דְּקוּדְשָׁא בְּרִיךְ הוּא רְעוּתֵיהּ בְּעַמָּא דְּיִשְׂרָאֵל, בָּעְיָין לְאַחֲזָאָה עוֹבָדָא לְתַתָּא, לְאִתְעָרָא רַחֲמֵי, וּלְאַעֲבָרָא דִינָא, דְּלָא יִשְׁלוֹט עֲלַיְיהוּ כְּלַל, וִיהוֹן תָּדִיר בְּחֶדְוָה עִמֵּיהּ. זַכָּאִין אִינוּן בְּעָלְמָא דֵין, וּבְעָלְמָא דְאָתֵי.</p>"],[9514012930,"<p>כְתִיב (שמואל א ג׳:א׳) וְהַנַּעַר שְׁמוּאֵל מְשָׁרֵת, כְּתִיב נַעַר, וּכְתִיב (תהילים צ״ט:ו׳) וּשְׁמוּאֵל בְּקוֹרְאֵי שְׁמוֹ. וְתָנִינָן, שָׁקוּל הָיָה שְׁמוּאֵל כְּנֶגֶד משֶׁה וְאַהֲרֹן. אִי שָׁקוּל אִיהוּ כְּמשֶׁה וְאַהֲרֹן, אַמַּאי כְּתִיב נַעַר, דְּהָא בְּכַמָּה דַרְגִּין אִינוּן, דְּלָא הֲוָה מָטָא אֲפִילּוּ לְדַרְגָא זְעִירָא דְמשֶׁה, כָּל שֶׁכֵּן לְמֶהֱוֵי שָׁקוּל כְּתַּרְוַויְיהוּ.</p>"],[9514012931,"<p>אֶלָּא הַאי קְרָא הָכֵי הוּא, (שם) משֶׁה וְאַהֲרֹן בְּכֹהֲנָיו, משֶׁה אִיהוּ נְבִיאָה מְהֵימְנָא עִילָּאָה עֲל כָּל שְׁאָר נְבִיאֵי. אַהֲרֹן בְּכֹהֲנָיו, אִיהוּ כַּהֲנָא עִילָּאָה עֲל כָּל כַּהֲנֵי עָלְמָא, דְּלָא הֲוָה כַּהֲנָא רַבָּא דְּסָלֵיק בְּדַרְגָא עִילָּאָה כְּאַהֲרֹן. זָכָה אַהֲרֹן לִכְהוּנָה וּנְבוּאָה, נָבִיא וְכֹהֵן. מַה דְּלָא זָכָה כַּהֲנַא אָחֳרָא. וְאִי תֵימָא, הָא זְכַרְיָה כֹּהֵן וְנָבִיא הָיָה, הַהִיא נְבוּאָה לְשַׁעֲתֵיהּ הֲוָה, דִּכְתִיב (דברי הימים כד) וְרוּחַ לָבְשָׁה אֶת זְכַרְיָה.</p>"],[9514012932,"<p>מַאי (שמות ל׳:י״ג) כָּל הָעוֹבֵר עַל הַפְּקוּדִים, אֶלָּא דָּא הוּא מַאן דְּעָבַר עַל פִּקּוּדִין דְּמָארֵיהּ, אִי בָּעֵי לְאִתְתַּקָּנָא קַמֵּי מָארֵיהּ, וְלָא יִשְׁלוֹט עֲלֵיהּ דִּינָא דִלְעֵילָא, זֶה יִתְּנוּ. זֶ\"ה בָּעֵי לְמִיתַּן, לְקָרְבָא לֵיהּ בְּזֹא\"ת, וּלְאַנְהָרָא לֵהּ בִּנְהִירוּ, בְּגִין דְּלָא תּוֹקֵיד עַלְמָא בְּשַׁלְהוֹבוֹי. בְּגִין דְּמַאן דְּעָבַר עַל פִּקּוּדִין דְּמָארֵיהּ, אַפְרֵיד זֶה מִזֹּאת, כְּדֵין בָּעֵי לְאַתְקָנָא לְהַהוּא אֲתַר, וּלְאֲרָמָא רֵישָׁא קַמֵּי דִינָא, וְלָא יִשְׁלוֹט דִּינָא עֲלֵיהּ.</p>"],[9514012933,"<p>זֶה יִתְּנוּ. תָּא חֲזֵי, בֵּי דִינָא דִּלְעֵילָא, לָא מַעֲנִישִׁין לֵיהּ לְבַּר נָשׁ עַד דְּאִיהוּ בַּר עֶשְׂרִין שְׁנִין. מַאי טַעְמָא, בְּגִין דְּהַהוּא זִמְנָא אִשְׁתַּלֵּים בִּתְרֵין חוּלָקִין, בְּחוּלָקָא דְקוּדְשָׁא בְּרִיךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל. וְעַל דָּא, אִי הַהוּא זִמְנָא עָבַר עַל פִּיקּוּדָא, לְמַאן בָּעֵי לְמֵיהַב, בְּאַתְרָא דְּחָב גַּבֵּיהּ, וּלְמַאן בָּעֵי לְאַמְשָׁכָא. הָדַר וַאֲמַר מַחֲצִית הַשֶּׁקֶל.</p>"],[9514012934,"<p>תָּא חֲזֵי, קוּדְשָׁא בְּרִיךְ הוּא וּכְנֶסֶת יִשְׂרָאֵל אִיקְרוּן אֶחָד. וְכַד כְּנֶסֶת יִשְׂרָאֵל בְּגָלוּתָא, לָא אִיקְּרֵי אֶחָד. וְעַל דָּא מַחֲצִית הַשֶּׁקֶל, דְּהוּא עֶשֶׂר גֵּרָה, רָזָא דְיו\"ד, בָּעֵי לְאַמְשָׁכָא וּלְאַנְהָרָא בְּאַתְרָא דְּפָגֵים.</p>"],[9514012935,"<p>וְהָא הוּא כּוֹפֶר נַפְשׁוֹ וַדַּאי, דְּהָא נֶפֶשׁ וא\"ו אִיהִי בֵּי דִינָא. בְּמַאי אִתְכַּפְּרָא וְאִסְתַּלֵּיק דִּינָא. בְּהַהוּא מַחֲצִית הַשֶּׁקֶל, וְדָא אִיהוּ טוֹב, דְּאַנְהַר לֵיהּ. וְכַד מִתְדַּבְּקִין תַּרְוַויְיהוּ כַּחֲדָא, טוֹב וְנֶפֶשׁ, כְּדֵין אִקְרֵי שֶׁקֶל הַקֹּדֶשׁ. וְאִיתְעַר כֶּסֶף יְמִינָא דְמַלְכָּא, לְגַבֵּי תְּרוּמַת ה'.</p>"],[9514012936,"<p>וְעַל דָּא בָּעָא משֶׁה בְּשַׁעֲתָא דְּדִינָא, וְעַתָּה יִגְדַּל נָא כֹּחַ אֲדֹנָ\"י. יו\"ד רַבָּתָא יִתְחַבַּר בַּהֲדָה, דְּאִקְּרֵי מַחֲצִית הַשֶּׁקֶל. וּבְאָן אֲתַר אִתְחַבַּר. בְּשֶׁקֶל הַקֹּדֶשׁ. וְכַד תַּרְוַויְיהוּ מִתְחַבְּרִין, כָּל אִינוּן בָּתֵּי דִינִין דְּבִתְרַע מַקְדְּשָׁא, מִסְתַּלְּקִין דְּלָא לְמֶעְבַּד דִּינָא, דְּהָא וַדַּאי כֹּפֶר נַפְשׁוֹ יָהַב.</p>"],[9514012937,"<p>תָּא חֲזֵי הַאי כּוּפְרָא, כְּדַאי הוּא לְכַפָּרָא עַל עֲשָׂרָה שְׁבָטִין, דְּזַבִּינוּ לְיוֹסֵף, וְאַפְרִידוּ זֶ\"ה מִזֹּא\"ת, וְעָבְרוּ עַל פִּקּוּדַיָיא דְּמָארֵיהוֹן. בְּגִין כָּךְ עֶשְׂרִים גֵּרָה הַשָּׁקֶל, לָקֳבֵיל הַהוּא דְּגָר בְּאַרְעָא נוּכְרָאָה, דְּאִסְתַּלַּק מֵאַרְעָא קַדִּישָׁא, וְנִמְכַּר בְּעֶשְׂרִים. וּבְנֵי יִשְׂרָאֵל לָא אֲרִימוּ רֵישָׁא מֵהַהוּא שַׁעֲתָא, בְּהַהוּא חוֹבָא. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְמשֶׁה, אִי אַתְּ בָּעֵי לַאֲרַמָאָה רֵישֵׁיהוֹן לְעֵילָא, זֶה יִתְּנוּ, כָּ\"ל.</p>"],[9514012938,"<p>תָּא חֲזֵי, הַהוּא צַדִּיק כָּל אִקְּרֵי, וּכְנֶסֶת יִשְׂרָאֵל עֲשִׂירָאָה דְּכָלְהוֹ אִתְכְּלִילַת בֵּיהּ אִתְקָרְבוּ דָּא בְּדָא, כְּדֵין שֶׁקֶל הַקֹּדֶשׁ אִקְּרוּן, בְּגִין דְּאִיהוּ פְּלַג גּוּפָא, וּכְּנֶסֶת יִשְׂרָאֵל פְּלַג גּוּפָא, אִתְחַבָּרוּ דָּא בְּדָא, גּוּפָא אִשְׁתְּלֵים.</p>"],[9514012939,"<p>וּתְרֵין עֲשַׂר שִׁבְטִין דִּתְחוֹת יַמָּא, יָנְקִין כָּל חַד מֵאֲתַר דִּילֵיהּ. הֲדָא הוּא דִכְתִיב, זֶה יִתְּנוּ. זֶ\"ה, חוּשְׁבַּן תְּרֵין עֲשַׂר, דְּאִתְדַּבְּקֵי סַחֲרָנֵי מַשְׁכְּנָא עִילָּאָה. וּבְהַהוּא זִמְנָא יְהֵא לוֹן נְשִׂיאוּת רֵישָׁא, מִשּׁוּם דְּאִתְדַּבַּק רֹאשׁ הַמַּטֶה בְּאַתְרֵיהּ הַהוּא דְנָטֵיר יו\"ד. וְכַד אָזַל לְעַלְמָא דְאָתֵי, אִתּוֹסַף בֵּיהּ יו\"ד, דִּכְתִיב (בראשית נ׳:כ״ו) וַיִּישָׂם בָּאָרוֹן בְּמִצְרָיִם.</p>"],[9514012940,"<p>וְעַל יְדוֹי דְּמשֶׁה דְּאִתְיַילֵיד בַּאֲדָר, אִסְתַּלַּק מִתַּמָּן, וַהֲוָה לוֹן לְיִשְׂרָאֵל נְשִׂיאַת רֹאשׁ. וּבְגִין כָּךְ בַּאֲדָר יָהֲבִין אִינוּן שְׁקָלִים, לַאֲרָמָא רֵישֵׁיהוֹן לְעֵילָא, וּלְקָרְבָא קִידּוּשִׁין דְּמַלְכָּא לְאַתְרַיְיהוּ, וְסִטְרָא דְּיָמִינָא אִתְעַר בְּעָלְמָא, וְסָמְכֵי מַשְׁכְּנָא אִתְקַיְּימוּ עַל תִּיקּוּנֵיהוֹן. וְאַתְיָא זֹאת בִּרְשִׁימוּ דְּצַדִּיק דְּהוּא יו\"ד, דְּאִיתְדַּבַּק בָּהּ בְּכָל קִידּוּשִׁין דִּלְעֵילָא, כַּד אִתְיְיהֵיב מַחֲצִית הַשֶּׁקֶל, דְּאִיהוּ מָעִין דְּכַסְפִּין, דְּאִתְקַשְּׁרוּ דָּא בְּדָא.</p>"],[9514012941,"<p>וְעַל דָּא קְטֹרֶת לְבַטָלָא דִּינָא, וּלְבַטָלָא מוֹתָנָא, בְּגִין דְּקָשִׁיר לָהּ בְּאַתְרָא דְּזֶה. וְתָּא חֲזֵי, קְטֹרֶת וְכָל קָרְבָּנִין דִּמְקָרְבִין, מֵהַאי מַחֲצִית הַשֶּׁקֶל אָתֵי, דְּיָהֵיב כָּל חַד וְחַד מִיִּשְׂרָאֵל, וּכְדֵין תְּרוּמַת ה' וַדַּאי.</p>"],[9514012942,"<p>תָּא חֲזֵי, כְּתִיב (משלי ט״ז:ל״א) עֲטֶרֶת תִּפְאֶרֶת שֵׂיבָה כו'. עֲטֶרֶת, דָּא תְּרוּמַת ה', דְּאִיהִי עֲטֶרֶת תִּפְאֶרֶת. בְּגִין דְּהָא תּוֹרָה שֶׁבְּעַל פֶּה, מְעַטְרָא לְתוֹרָה שֶׁבִּכְתַב, בְּגִין דְּאִיהִי אַתְרָא דְּאִתְגַּלְּיָיא, לְגִלוּיֵי סִתְרָהָא, וּלְפֵרוּשֵׁי תִּיקּוּנִין דִּילָהּ, עַל יְדָא דַּעֲטֶרֶת, דְּאִיהִי מַרְאָה, דְּכָלְהוֹ אִתְגַּלְּיָין בָּהּ. וְכִי תֵימָא הֵיאַךְ אִתְגַּלְּיָין בָּהּ. בְּהַהוּא אֲתַר דְּאִקְּרֵי דֶּרֶ\"ךְ צְדָקָ\"ה. וּמַאן אִיהוּ דֶּרֶךְ צְדָקָה. דָּא זֶה דְּאַנְהֵיר לָהּ. וּכְדֵין תִּמָּצֵ\"א וַדַּאי נְהִירוּ דְּתוֹרָה שֶׁבִּכְתָב.</p>"],[9514012943,"<p>וְעַל דָּא תְּרוּמַת ה' אִיקְּרֵי, תְּרוּמַת וַדַּאי, דְּאָרֵים דִּגְלֵיהּ עַל כּוֹלָּא, הַהוּא דִכְתִיב בֵּיהּ, (תהילים מ״ח:ב׳) גָּדוֹל ה' וּמְהֻלָּל מְאֹד בְּעִיר אֱלֹהֵינוּ. אֵימַת אִיהוּ גָּדוֹל וְאִתְעַטַר בְּעִטְרוֹי, בְּעִיר אֱלֹהֵינוּ. וּכְדֵין, נְהִירוּ דְּעַתִּיק יוֹמִין נָהֵיר בִּזְעֵיר אַנְפִין, וְאִתְעַטַר בְּגִין לְאִתְדַּבָּקָא בְּקַרְתָּא קַדִּישָׁא. הֲדָא הוּא דִכְתִיב, עֲטֶרֶת תִּפְאֶרֶת שֵׂיבָה בְּדֶרֶךְ צְדָקָה תִּמָּצֵא. וְנָגֵיד לְהַהוּא אַתְרָא דְּאִקְּרֵי צְדָקָה, וְאַנְהֵיר חִוָּורָא לְסוּמְקָא.</p>"],[9514012944,"<p>וְנָהֲרִין מִנֵּיהּ שִׁתִּין גִּבּוֹרִין, וּתְרֵין עֲשַׂר שִׁבְטִין. בְּגִין כָּךְ שִׁשִּׁים עִשָּׂרוֹן בִּכְלִי אֶחָד נִבְלָלִין, דְּכָלְהוֹ מִסִּטְרָא חָד. וּתְרֵין עֲשַׂר לָא אִתְכַּלְּלָן עִמְּהוֹן, דְּאִינוּן יַנְקִין נוֹפָא דְּאִילָנָא, הֲדָא הוּא דִכְתִיב זֶה יִתְּנוּ, וַדַּאי יִתְּנוּ לְכוֹלָּא, לְעַנְפֵי דְּסָחֳרָנֵי אִילָנָא. וְעַל דָּא כָּל אוּמִּין מִתְכַּפְּרִין בְּקָרְבָּנָא דְיִשְׂרָאֵל.</p>"],[9514012945,"<p>וְיִשְׂרָאֵל יָנְקִין בְּקַדְמִיתָא מֵהַאי אֲתַר דְּאִקְּרֵי סֶלַע. הַיְינוּ דִּכְתִיב (דברים ל״ב:י״ג) וַיְנִיקֵהוּ דְּבַשׁ מִסָּלַע. וּמַאי טַעְמָא דְּבַשׁ, בְּגִין דְּאִיהוּ תָּמָר, דִּכְתִיב (שיר השירים ז׳:ח׳) זֹאת קוֹמָתֵךְ דָּמְתָה לְתָמָר.</p>"],[9514012946,"<p>וּלְבָתַר, שֶׁמֶן מֵחַלְמִישׁ צוּר. דָּא אַתְרָא דִלְעֵילָא, אַתְרָא דְּיִצְחָק שָׁרֵי. אַף עַל גַּב דְּשֶׁמֶן מִסִּטְרָא דְאַבְרָהָם, כַּד יִשְׂרָאֵל מְכַשְׁרִין עוֹבָדַיְיהוּ, מְהַפְּכִין דִּינָא לְרַחֲמֵי וְדָא הוּא דַּאֲמַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וַיְנִיקֵהוּ דְּבַשׁ מִסָּלַע, דְּאִתְחַבְּרָן תָּמָר דְּכַר וְנוּקְבָא. וְשֶׁמֶן מֵחַלְמִישׁ צוּר, כּוּלְהוֹ דַּרְגִּין נַגְדִין שָׁמֶן, וַאֲפִילּוּ אֲתַר דְּאִיקְּרֵי צוּר. וְהַיְינוּ דִּכְתִיב, (דברים ל״ב:ד׳) הַצּוּר תָּמִים פָּעֳלוֹ. דְּאִתְהַדַּר צוּר לְמֶעְבַּד פָּעֳלוֹ דְּתָמִים. תָּמִים דָּא אַבְרָהָם, דִּכְתִיב (בראשית י״ז:א׳) הִתְהַלֶּךְ לְפָנַי וֶהְיֵה תָמִים. צוּר דָּא יִצְחָק, וְאוֹקְמוּהָ.</p>"],[9514012947,"<p>תָּא חֲזֵי, עַל דָּא תָּמַהּ משֶׁה וַאֲמַר, (במדבר כ׳:י׳) הֲמִן הַסֶּלַע הַזֶּה נוֹצִיא לָכֶם מָיִם. כֵּיוָן דְּאַתּוּן לָא אָזְלִין בְּאוֹרַח מֵישַׁר, וְלָא מְבַסְּמִין אַתְרָא. וְעַל דָּא יִשְׂרָאֵל עָבְדִין נִסּוּךְ הַמַּיִם בַּחַג, לְיָנְקָא הַאי מִזְבֵּחַ מִמַּיָּא דְּאַבְרָהָם, וּכְדֵין אִתְבָּרַךְ עָלְמָא.</p>"],[9514012948,"<p>וּבַּר נָשׁ כַּד אִיהוּ מְבָרֵךְ עַל מְזוֹנָא בְּכַסָּא, אִיבָּעֵי לֵיהּ לְמֵיהַב בֵּיהּ מַיָא, בְּבִרְכַּת הָאָרֶץ, לְבָרְכָא לְהַאי אֶרֶץ, דְּאִיקְּרֵי מִזְבֵּחַ, וְאִיקְּרֵי כּוֹס שֶׁל בְּרָכָה, דְּכָלְהוֹ בִּרְכָאן בֵּיהּ תַּלְיָין.</p>"],[9514012949,"<p>וְתָּא חֲזֵי, כַּד יִשְׂרָאֵל מַכְשְׁרָן עוֹבָדַיְיהוּ, הַאי מִזְבֵּחַ, שָׁלְטָא בְּסִטְרָא דְּיָמִינָא, וַהֲווּ חַזְיָין כְּחֵיזוּ אַרְיֵה רְבִיעַ עֲלֵיהּ, עַל קָרְבָּנָא, וְאָכֵיל לֵיהּ. וְעַל דָּא מַדְבְּחָא אִיקְּרֵי אֲרִיאֵל. (ישעיהו כ״ט:א׳) קִרְיַת חָנָה דָּוִד. וַדַּאי דְּחוּלָקֵיהּ דְּדָוִד הוּא, וְכָל יוֹמוֹי אִשְׁתַּדֵּל לְאַנְהָרָא לָהּ.</p>"],[9514012950,"<p>וְעַל דָּא (תהילים ט״ז:י״א) תּוֹדִיעֵנִי אוֹרַח חַיִּים. כְּמָה דְאַתְּ אָמֵר, (שמות ב) וַיֵּדַע אֱלֹהִים. אוֹרַח חַיִּים, וּמַאן הוּא, שׂוֹבַע שְׂמָחוֹת, הַהוּא דְּכָל שָׂבְעָא אִתְכְּלֵיל בֵּיהּ, וִיהַדַּר אַנְפּוֹי לָקֳבְלֵי פָנֶיךָ, דַּאֲנָא אָחִיד בְּהוֹן. וּכְדֵין נְעִימוֹת בִּימִינְךָ נֶצַח, דִּשְׂמָאלָא אִתְכְּלֵילַת בְּיָמִינָא, וְכַד אִתְכְּלֵילַת, אִתְהַדַּר צוּר לְמֶעְבַּד פָּעֳלוֹ דְּתָמִים, וְעַל דָּא זֶה יִתְּנוּ.</p>"],[9514012951,"<p>פְּתַח וַאֲמַר, (דברים ל״ג:י״ז) בְּכוֹר שׁוֹרוֹ, דָּא יוֹסֵף. הָדָר, דָּא יַעֲקֹב. דִּכְתִיב אֵלֶּה תּוֹלְדוֹת יַעֲקֹב יוֹסֵף. וּמְנָא לָן דְּאִקְּרֵי יַעֲקֹב הָדָר. דִּכְתִיב (בראשית ל״ו:ל״ט) וַיִּמְלֹךְ תַּחְתָּיו הֲדַר, וְאוֹקְמוּהָ בְּאִידְּרָא קַדִּישָׁא. וְקַרְנֵי רְאֵם קַרְנָיו, אֵלּוּ אַבְרָהָם וְיִצְחָק. בָּהֶם עַמִּים יְנַגַּח יַחְדָּיו. מַהוּ יַחְדָּיו, אֶלָּא כַּד כָּלְהוֹ אֲבָהָן כַּחֲדָא, לֵית דִּיקוּמוּן קַמַּיְיהוּ וּבְהַהוּא זִמְנָא, יִשְׂרָאֵל זָקְפִין רֵישָׁא. הֲדָא הוּא דִכְתִיב, כִּי תִשָּׂא.</p>"],[9514012952,"<p>וְתָּא חֲזֵי, כַּד נָפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, בְּסִיּוּעָא דַּאֲבָהָן נָפְקוּ, וַאֲרִימוּ רֵישָׁא. הֲדָא הוּא דִכְתִיב, (שמות י״ד:ח׳) וּבְנֵי יִשְׂרָאֵל יוֹצְאִים בְּיָד רָמָה. מַאן יָד רָמָה. דָּא אַבְרָהָם. יְדָא יָמִינָא, דְּבָעֵי לַאֲרָמָא לָהּ עַל שְׂמָאלָא.</p>"],[9514012953,"<p>וּמַה אַבְרָהָם, עָבַד לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא נוּקְמִין בְּלֵילְיָא, אוּף יִשְׂרָאֵל בְּיַד רָמָה נָפְקִין, וְסִיּוּעָא דִילֵיהּ נָקְטוּ. וְנָטְרוּ יַד דִּילֵיהּ, דְּאוֹמֵי לַאֲבִימֶלֶךְ. וְעַל דָּא לְנָטְרָא הַהוּא יַד רָמָה (שם יג) וְלֹא נָחָם אֱלֹהִים דֶּרֶךְ אֶרֶץ פְּלִשְׁתִּים.</p>"],[9514012954,"<p>וּמָנוּ שֶׁבַע שְׁבוּעִין מִתַּתָּא לְעֵילָא לְסָלְקָא לְאַתְרֵיהּ, וּלְקַבְּלָא חֵירוּת מֵאִימָּא עִילָּאָה. וְכַד אִשְׁתְּלִימוּ, נָחֲתָא אוֹרַיְיתָא, וּפְתִיחוּ דִּילָהּ בְּאַבְרָהָם, אָנֹכִי לְקִבְלֵיהּ. לֹא יִהְיֶה, לְקִבְלֵיהּ דְּיִצְחָק.</p>"],[9514012955,"<p>וְתָּא חֲזֵי, כַּד יְהֵיב קוּדְשָׁא בְּרִיךְ הוּא אוֹרַיְיתָא לְיִשְׂרָאֵל, רָשִׁים לָהּ בְּרָזָא דִּשְׁמָא קַדִּישָׁא, וַאֲמַר (שם כ) אָנֹכִי ה' אֱלֹהֶיךָ, בְּרָזָא דְחֶסֶד דְּאַבְרָהָם אָחִיד בָּהּ, וּלְקִבְלֵיהּ מִצְוֹת עֲשֵׂה. וְרָזָא דָא, תַּפְקֵידְתָּא קַמַּיְיתָא דְּפַקֵּיד קוּדְשָׁא בְּרִיךְ הוּא לְאַבְרָהָם, מִצְוַת עֲשֵׂה הֲוָה. דִּכְתִיב, (בראשית י״ב:א׳) לֶךְ לְךָ מֵאַרְצְךָ. וּבְגִין כָּךְ מִצְוֹת עֲשֵׂה רמ\"ח, כְּחוּשְׁבַּן אַבְרָהָם.</p>"],[9514012956,"<p>(שמות כ׳:ג׳) לֹא יִהְיֶה לְךָ אֱלֹהִים אֲחֵרִים. בְּרָזָא דִגְבוּרָה, דְאָחִיד בָּהּ יִצְחָק. דְּכָל אִינוּן אֱלֹהִים אֲחֵרִים, וְאִינוּן סָרְכִין מְמַנָּן, מִסִּטְרֵיהּ יָנְקִין. וְכֵן עֵשָׂו, וְכָל אִינוּן מְמַנָּן דִּילֵיהּ. דְהָא יִצְחָק בְּמִצְוַת לֹא תַּעֲשֶׂה אָחֵיד, וְתַפְקֵידְתָּא קַמַּיְיתָא דִילֵיהּ, מִצְוַת לֹא תַעֲשֶׂה הֲוָה, דִּכְתִיב (בראשית כ״ו:ב׳) אַל תֵּרֵד מִצְרַיְמָה. וּמִצְוַת לֹא תַּעֲשֶׂה מִסִּטְרָא דְדִינָא אָתֵי, דְּהָא מַעֲנִישִׁין לֵיהּ לְבַר נָשׁ כַּד עָבַר עֲלָהּ.</p>"],[9514012957,"<p>וּבְגִין כָּךְ, חוּשְׁבַּן מִצְוַת לֹא תַעֲשֶׂה, בְּרָזָא דְדַרְגָא דִּילֵיהּ, בְּרָזָא דְּשס\"ה לָקֳבֵיל יוֹמִין דְּשִׁמְשָׁא, דְּנָהֵיר מִסִּטְרָא דִגְבוּרָה. הֲדָא הוּא דִכְתִיב, (שופטים ה׳:ל״א) כְּצֵאת הַשֶּׁמֶשׁ בִּגְבוּרָתוֹ.</p>"]]});
